# non-PMA sells, but must not stamp skip/debug timers or reset PMA/GF+ timing.
PMA_GF_PLUS_SKIP_MUTATION_CONTEXT = threading.local()

def set_pma_gf_plus_skip_mutation_allowed(allowed):
    try:
        PMA_GF_PLUS_SKIP_MUTATION_CONTEXT.allowed = bool(allowed)
    except Exception:
        pass

def pma_gf_plus_skip_mutation_allowed():
    try:
        return bool(getattr(PMA_GF_PLUS_SKIP_MUTATION_CONTEXT, "allowed", True))
    except Exception:
        return True
