def load_env_file(filename=".env"):
    env_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), filename)

    if not os.path.exists(env_path):
        return

    with open(env_path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()

            if not line or line.startswith("#"):
                continue

            if "=" not in line:
                continue

            key, value = line.split("=", 1)
            key = key.strip()
            value = value.strip().strip('"').strip("'")

            # Shell/exported values must win over .env.  This matters on
            # Pydroid3 when LBANK_CA_BUNDLE / SSL_CERT_FILE are exported
            # just before launching the bot; an old .env entry could otherwise
            # silently replace the combined mhr-cfw CA bundle and cause
            # CERTIFICATE_VERIFY_FAILED through the local SOCKS proxy.
            if key not in os.environ:
                os.environ[key] = value


load_env_file()


def _env_float(name, default):
    value = os.getenv(name)
    if value is None or str(value).strip() == "":
        return default
    try:
        parsed = float(str(value).strip())
        return parsed if math.isfinite(parsed) else default
    except Exception:
        return default


def _env_int(name, default):
    value = os.getenv(name)
    if value is None or str(value).strip() == "":
        return default
    try:
        return int(float(str(value).strip()))
    except Exception:
        return default


def _env_text(name, default=""):
    value = os.getenv(name)
    if value is None:
        return default
    return str(value).strip()


