# V2: Live market-breadth confirmation boost.
# Defaults above stay unchanged. During each scan, if the fetched market rows show
# at least MARKET_BREADTH_CONFIRM_BOOST_MIN_UNIQUE_COINS unique coin(s) with
# 24h change >= MARKET_BREADTH_CONFIRM_BOOST_MIN_24H_PCT, the BUY-1M
# pending-buy / buy confirmation targets are raised to the boosted values below.
MARKET_BREADTH_CONFIRM_BOOST_MIN_24H_PCT = 200.0
MARKET_BREADTH_CONFIRM_BOOST_MIN_UNIQUE_COINS = 1
MARKET_BREADTH_CONFIRM_BOOST_PENDING_BUY_CONFIRM_SCANS = 2
MARKET_BREADTH_CONFIRM_BOOST_BUY_CONFIRM_SCANS = 5


def market_breadth_confirmation_boost_active(unique_count):
    try:
        unique_count = int(unique_count or 0)
    except Exception:
        unique_count = 0
    try:
        min_unique = int(MARKET_BREADTH_CONFIRM_BOOST_MIN_UNIQUE_COINS)
    except Exception:
        min_unique = 1
    return unique_count >= max(1, min_unique)


def resolve_buy_confirmation_scans(context=None):
    context = context if isinstance(context, dict) else {}

    unique_count = context.get("market_confirm_boost_unique_count")
    if unique_count is None:
        unique_count = context.get("market_30pct_24h_unique_count")

    boost_active = market_breadth_confirmation_boost_active(unique_count)
    if boost_active:
        return (
            int(MARKET_BREADTH_CONFIRM_BOOST_PENDING_BUY_CONFIRM_SCANS),
            int(MARKET_BREADTH_CONFIRM_BOOST_BUY_CONFIRM_SCANS),
            True,
        )

    return (
        int(PENDING_BUY_CONFIRM_SCANS),
        int(BUY_CONFIRM_SCANS),
        False,
    )




# In pumpbox mode, pending-buy is an internal pre-BUY state.  Do not send
# user-facing "احتمال خرید هنگام پامپ" Bale alerts unless explicitly enabled.
BALE_SEND_PUMPBOX_PENDING_BUY_EVENTS = False


def should_emit_pending_buy_event_for_pumpbox_mode():
    return (not bool(ENABLE_PUMPBOX_GATE)) or bool(BALE_SEND_PUMPBOX_PENDING_BUY_EVENTS)


def candidate_market_type_name(candidate=None):
    """Return the LBank quote currency for a candidate row."""
    if not isinstance(candidate, dict):
        return "USDT"

    for key in ("market_type", "quote_currency", "display_quote_currency", "symbol_udf", "symbol", "raw_symbol"):
        value = candidate.get(key)
        if value is None:
            continue
        try:
            normalized = normalize_quote_currency(value)
        except Exception:
            normalized = str(value or "").strip().upper()
        if normalized == "USDT" or str(value or "").strip().upper().replace("/", "_").replace("-", "_").endswith("USDT"):
            return "USDT"

    return "USDT"


def is_usdt_market_symbol(candidate=None):
    return candidate_market_type_name(candidate) == "USDT"


def should_disable_usdt_pending_buy_buys(candidate=None, direct_overlap=False):
    if not is_usdt_market_symbol(candidate):
        return False
    if direct_overlap and bool(DISABLE_USDT_DIRECT_BUY_OVERLAP_BUYS):
        return True
    return bool(DISABLE_USDT_PENDING_BUY_BUYS)


def should_disable_usdt_shadow_pending_buy_buys(candidate=None):
    return bool(is_usdt_market_symbol(candidate) and DISABLE_USDT_SHADOW_PENDING_BUY_BUYS)


def should_skip_usdt_market_buys(candidate=None):
    return bool(SKIP_USDT_MARKET_BUYS and is_usdt_market_symbol(candidate))


def should_include_market_row_for_buy_scan(row, states=None):
    """Keep active USDT positions manageable while blocking new USDT buy setups."""
    if not should_skip_usdt_market_buys(row):
        return True

    symbol = str((row or {}).get("symbol_udf") or "").strip().upper()
    state = (states or {}).get(symbol) if isinstance(states, dict) else None
    stage = str((state or {}).get("stage") or "idle").strip().lower()

    # Existing active positions still need BUY-1M/FULL scans for sells and status.
    return stage in {"buy", "pumped"}


def clear_usdt_prebuy_state_if_needed(state, candidate=None):
    if not isinstance(state, dict) or not should_skip_usdt_market_buys(candidate):
        return False

    stage = str(state.get("stage") or "idle").strip().lower()
    if stage in {"buy", "pumped"}:
        return False

    reset_state_to_idle(state, keep_cooldown=True)
    clear_pumpbox_fields(state)
    clear_all_exact_2h_sandbox_fields(state)
    clear_pending_buy_extension_window(state, "pending_buy")
    clear_pending_buy_extension_window(state, "shadow_pending_buy")
    set_state_scan_counter(state, "pending_buy_scan_count", 0, reset_reason="USDT market buys skipped")
    set_state_scan_counter(state, "shadow_pending_buy_scan_count", 0, reset_reason="USDT market buys skipped")
    return True


def pending_sell_confirm_scans_for_gain(peak_gain_pct=None):
    try:
        default_scans = max(1, int(PENDING_SELL_CONFIRM_SCANS))
    except Exception:
        default_scans = 4

    try:
        gain_value = float(peak_gain_pct)
    except Exception:
        gain_value = None

    try:
        trigger_pct = float(PENDING_SELL_HIGH_GAIN_TRIGGER_PCT)
    except Exception:
        trigger_pct = 8.0

    if gain_value is not None and gain_value >= trigger_pct:
        try:
            return max(1, int(PENDING_SELL_HIGH_GAIN_CONFIRM_SCANS))
        except Exception:
            return 2

    return default_scans


def pending_sell_confirm_seconds_for_gain(peak_gain_pct=None):
    """Return fib sell-zone confirmation duration in real seconds.

    The legacy config names still say "scans", but after BUY-1M scans became
    faster than one minute these values represent real minutes. This keeps
    PENDING_SELL_CONFIRM_SCANS=4 equivalent to about four real minutes rather
    than four fast 9.6-second scans.
    """
    try:
        confirm_units = max(1.0, float(pending_sell_confirm_scans_for_gain(peak_gain_pct)))
    except Exception:
        confirm_units = 4.0

    try:
        seconds_per_unit = max(1.0, float(PENDING_SELL_CONFIRM_SECONDS_PER_UNIT))
    except Exception:
        seconds_per_unit = 60.0

    return int(max(1, round(confirm_units * seconds_per_unit)))


def sell_zone_confirmation_timing_status(
    state,
    scan_dt=None,
    peak_gain_pct=None,
    confirm_seconds_override=None,
    confirm_units_override=None,
):
    if scan_dt is None:
        scan_dt = get_tehran_now()

    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    pending_since_ts = ts_to_int((state or {}).get("sell_zone_pending_since_ts") if isinstance(state, dict) else None)

    if confirm_seconds_override is not None:
        try:
            confirm_seconds = max(1, int(round(float(confirm_seconds_override))))
        except Exception:
            confirm_seconds = pending_sell_confirm_seconds_for_gain(peak_gain_pct)
        if confirm_units_override is not None:
            try:
                confirm_units = max(0.0, float(confirm_units_override))
            except Exception:
                confirm_units = confirm_seconds / 60.0
        else:
            confirm_units = confirm_seconds / 60.0
    else:
        confirm_units = pending_sell_confirm_scans_for_gain(peak_gain_pct)
        confirm_seconds = pending_sell_confirm_seconds_for_gain(peak_gain_pct)

    elapsed_seconds = None
    if current_scan_ts is not None and pending_since_ts is not None:
        elapsed_seconds = max(0, int(current_scan_ts - pending_since_ts))

    return {
        "pending_since_ts": pending_since_ts,
        "current_scan_ts": current_scan_ts,
        "elapsed_seconds": elapsed_seconds,
        "elapsed_minutes": (elapsed_seconds / 60.0) if elapsed_seconds is not None else None,
        "confirm_units": confirm_units,
        "confirm_seconds": confirm_seconds,
        "confirm_minutes": confirm_seconds / 60.0,
        "confirmed": elapsed_seconds is not None and elapsed_seconds >= confirm_seconds,
    }


def best_peak_gain_pct_from_entry(entry_price, current_price=None, live_candle=None, fib_top=None):
    entry_price = _safe_positive_float(entry_price)
    if entry_price in (None, 0, 0.0):
        return None

    prices = []
    for value in (current_price, fib_top):
        value = _safe_positive_float(value)
        if value is not None:
            prices.append(value)

    if isinstance(live_candle, dict):
        for key in ("h", "body_top", "c"):
            value = _safe_positive_float(live_candle.get(key))
            if value is not None:
                prices.append(value)

    if not prices:
        return None

    return pct_change(entry_price, max(prices))


