BALE_ADMIN_CHAT_ID = "808704022"
SUBSCRIBERS_FILE = "bale_subscribers.json"
SUBSCRIBER_STATE_LOCK = threading.Lock()


def get_subscribers_file_path():
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), SUBSCRIBERS_FILE)


def _parse_access_dt(value):
    if not value:
        return None
    try:
        return datetime.strptime(str(value), "%Y-%m-%d %H:%M:%S")
    except Exception:
        return None


def _format_access_dt(value):
    if value is None:
        return None
    try:
        return value.strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return None


def _resolve_nobit_access_provider():
    """Return an external subscriber-state provider, never this module itself.

    The LBank script can run as __main__ or be imported as signaler_lbank.  In
    those cases the old compatibility lookup would resolve back to this same
    module and load_subscriber_state()/save_subscriber_state() would call
    themselves forever, usually when a Bale message snapshot was persisted.
    """
    for module_name in ("__main__", "lbank", "signaler_lbank", "nobit"):
        mod = sys.modules.get(module_name)
        if not mod:
            continue

        load_func = getattr(mod, "load_subscriber_state", None)
        save_func = getattr(mod, "save_subscriber_state", None)
        if not callable(load_func) or not callable(save_func):
            continue

        # Skip self-provider recursion when this standalone script is running
        # as __main__ or imported under its compatibility module name.
        if load_func is load_subscriber_state or save_func is save_subscriber_state:
            continue

        return mod
    return None


def get_default_subscriber_state():
    return {
        "schema_version": 1,
        "next_order_id": 1,
        "users": {},
        "last_messages": {
            "pump_radar": {"text": None, "generated_at": None, "meta": {}},
            "strategy": {"text": None, "generated_at": None, "meta": {}},
        },
    }


def normalize_subscriber_state(state):
    if not isinstance(state, dict):
        state = {}
    base = get_default_subscriber_state()
    base.update({k: v for k, v in state.items() if k in base})
    if not isinstance(base.get("users"), dict):
        base["users"] = {}
    if not isinstance(base.get("last_messages"), dict):
        base["last_messages"] = {}
    for key in ("pump_radar", "strategy"):
        item = base["last_messages"].get(key)
        if not isinstance(item, dict):
            item = {}
        base["last_messages"][key] = {
            "text": item.get("text"),
            "generated_at": item.get("generated_at"),
            "meta": item.get("meta") if isinstance(item.get("meta"), dict) else {},
        }
    return base


def load_subscriber_state():
    provider = _resolve_nobit_access_provider()
    if provider is not None:
        return provider.load_subscriber_state()
    path = get_subscribers_file_path()
    if not os.path.exists(path):
        return get_default_subscriber_state()
    with SUBSCRIBER_STATE_LOCK:
        try:
            with open(path, "r", encoding="utf-8") as fh:
                return normalize_subscriber_state(json.load(fh))
        except Exception:
            return get_default_subscriber_state()


def save_subscriber_state(state):
    provider = _resolve_nobit_access_provider()
    if provider is not None:
        provider.save_subscriber_state(state)
        return
    path = get_subscribers_file_path()
    tmp_path = path + ".tmp"
    with SUBSCRIBER_STATE_LOCK:
        with open(tmp_path, "w", encoding="utf-8") as fh:
            json.dump(normalize_subscriber_state(state), fh, ensure_ascii=False, indent=2)
        os.replace(tmp_path, path)


def get_last_subscription_end_dt(user):
    latest = None
    for entry in user.get("subscriptions", []):
        if not isinstance(entry, dict):
            continue
        end_dt = _parse_access_dt(entry.get("end_at"))
        if end_dt is None:
            continue
        if latest is None or end_dt > latest:
            latest = end_dt
    return latest


def get_user_access_snapshot_from_record(user, now_dt=None):
    provider = _resolve_nobit_access_provider()
    if provider is not None and hasattr(provider, "get_user_access_snapshot_from_record"):
        try:
            return provider.get_user_access_snapshot_from_record(user, now_dt=now_dt)
        except Exception:
            pass
    if now_dt is None:
        now_dt = get_tehran_now()
    if not isinstance(user, dict):
        return {"active": False, "reason": "missing", "stage": "missing", "expires_at": None}
    chat_id = str(user.get("chat_id") or "")
    if chat_id == BALE_ADMIN_CHAT_ID:
        return {"active": True, "reason": "admin", "stage": "admin", "expires_at": None}
    free_trial = user.get("free_trial") if isinstance(user.get("free_trial"), dict) else {}
    free_expires_dt = _parse_access_dt(free_trial.get("expires_at"))
    subscription_end_dt = get_last_subscription_end_dt(user)
    phone_number = user.get("phone_number")
    if subscription_end_dt is not None and subscription_end_dt > now_dt:
        return {"active": True, "reason": "subscription_active", "stage": "subscribed", "expires_at": subscription_end_dt}
    if free_expires_dt is not None and free_expires_dt > now_dt:
        return {"active": True, "reason": "free_trial_active", "stage": "free", "expires_at": free_expires_dt}
    if not phone_number:
        return {"active": False, "reason": "awaiting_phone", "stage": "awaiting_phone", "expires_at": None}
    if subscription_end_dt is not None and subscription_end_dt <= now_dt:
        return {"active": False, "reason": "subscription_expired", "stage": "locked", "expires_at": subscription_end_dt}
    if free_expires_dt is not None and free_expires_dt <= now_dt:
        return {"active": False, "reason": "free_trial_expired", "stage": "locked", "expires_at": free_expires_dt}
    return {"active": False, "reason": "no_access", "stage": "locked", "expires_at": None}


def get_active_broadcast_chat_ids(now_dt=None, include_admin=True):
    if now_dt is None:
        now_dt = get_tehran_now()
    state = load_subscriber_state()
    chat_ids = []
    if include_admin:
        chat_ids.append(BALE_ADMIN_CHAT_ID)
    for user in state.get("users", {}).values():
        access = get_user_access_snapshot_from_record(user, now_dt=now_dt)
        if not access.get("active"):
            continue
        chat_id = str(user.get("chat_id") or "").strip()
        if chat_id and chat_id not in chat_ids:
            chat_ids.append(chat_id)
    return chat_ids


def persist_last_bot_message_snapshot(message_key, text, generated_at=None, meta=None):
    if generated_at is None:
        generated_at = get_tehran_now()
    state = load_subscriber_state()
    last_messages = state.setdefault("last_messages", {})
    current = last_messages.get(message_key)
    if not isinstance(current, dict):
        current = {}
    current["text"] = str(text or "").strip() or None
    current["generated_at"] = _format_access_dt(generated_at)
    current["meta"] = meta if isinstance(meta, dict) else {}
    last_messages[message_key] = current
    save_subscriber_state(state)


