HTTP_BACKOFF_CAP_SECONDS = 4.0

# Per-scan OHLC prefetch context. Analysis reads OHLC from this in-memory
# context after the bounded prefetch phase, so slow symbols cannot block analysis.
OHLC_PREFETCH_LOCAL = threading.local()
OHLC_PREFETCH_MISSING = object()
OHLC_PREFETCH_HTTP_LOG_LOCAL = threading.local()

# v84: Per-scan delivery/dedupe state cache. This avoids repeatedly re-reading
# and re-normalizing the event-message and pumping sent ledgers during one scan.
# Save functions still write through to disk, preserving existing dedupe semantics.
SCAN_EVENT_DEDUPE_LOCAL = threading.local()


def _get_scan_event_dedupe_context():
    context = getattr(SCAN_EVENT_DEDUPE_LOCAL, "context", None)
    return context if isinstance(context, dict) and context.get("enabled") else None


def set_scan_event_dedupe_context(scan_dt=None):
    SCAN_EVENT_DEDUPE_LOCAL.context = {
        "enabled": True,
        "scan_dt": scan_dt,
        "event_message_state": None,
        "pumping_event_state": None,
    }


def clear_scan_event_dedupe_context():
    SCAN_EVENT_DEDUPE_LOCAL.context = None


def _record_suppressed_ohlc_prefetch_http_warning(url, reason):
    collector = getattr(OHLC_PREFETCH_HTTP_LOG_LOCAL, "collector", None)
    if not isinstance(collector, dict):
        return False

    lock = collector.get("lock")
    if lock is None:
        collector["count"] = int(collector.get("count", 0)) + 1
        return True

    with lock:
        collector["count"] = int(collector.get("count", 0)) + 1
    return True


def _set_ohlc_prefetch_http_warning_collector(collector):
    old = getattr(OHLC_PREFETCH_HTTP_LOG_LOCAL, "collector", None)
    if collector is None:
        if hasattr(OHLC_PREFETCH_HTTP_LOG_LOCAL, "collector"):
            delattr(OHLC_PREFETCH_HTTP_LOG_LOCAL, "collector")
    else:
        OHLC_PREFETCH_HTTP_LOG_LOCAL.collector = collector
    return old


def _restore_ohlc_prefetch_http_warning_collector(old_collector):
    if old_collector is None:
        if hasattr(OHLC_PREFETCH_HTTP_LOG_LOCAL, "collector"):
            delattr(OHLC_PREFETCH_HTTP_LOG_LOCAL, "collector")
    else:
        OHLC_PREFETCH_HTTP_LOG_LOCAL.collector = old_collector

