def color_pct(pct):
    if pct is None:
        return f"{COL_NEU}-{RESET}"
    if pct > 0:
        return f"{COL_POS}{pct:+.2f}%{RESET}"
    if pct < 0:
        return f"{COL_NEG}{pct:+.2f}%{RESET}"
    return f"{COL_NEU}{pct:+.2f}%{RESET}"


def plain_pct(pct):
    if pct is None:
        return "-"
    return f"{pct:+.2f}%"


def plain_pct_summary(pct):
    if pct is None:
        return "-"
    if pct > 0:
        return f"+{pct:.2f}%"
    if pct < 0:
        return f"-{abs(pct):.2f}%"
    return "0.00%"


def plain_pct_summary_ltr(pct):
    summary_text = plain_pct_summary(pct)
    if summary_text == "-":
        return summary_text
    return f"\u2066{summary_text}\u2069"


def format_report_window_label(total_seconds):
    try:
        total_seconds = int(max(0, round(float(total_seconds))))
    except Exception:
        total_seconds = 0
    if total_seconds <= 0:
        return "0m"
    if total_seconds % 3600 == 0 and total_seconds < (48 * 3600):
        return f"{total_seconds // 3600}h"
    if total_seconds % 60 == 0 and total_seconds < 3600:
        return f"{total_seconds // 60}m"
    return format_duration_compact(total_seconds)


def format_report_window_label_fa(total_seconds):
    try:
        total_seconds = int(max(0, round(float(total_seconds))))
    except Exception:
        total_seconds = 0

    if total_seconds <= 0:
        return "اخیر"
    if total_seconds % (24 * 3600) == 0:
        days = total_seconds // (24 * 3600)
        return "اخیر"
    if total_seconds % 3600 == 0:
        hours = total_seconds // 3600
        return "اخیر"
    if total_seconds % 60 == 0:
        minutes = total_seconds // 60
        return "اخیر"
    return "اخیر"


