def scan_label_to_log_path(scan_label=None):
    label = str(scan_label or "FULL").strip().upper()
    if label in {"BUY-1M", "BUY-1M-SUMMARY"}:
        return get_buy_signal_log_path()
    return get_log_path()


def ensure_scan_log_files_exist():
    for path in (get_log_path(), get_buy_signal_log_path()):
        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            if not os.path.exists(path):
                with open(path, "a", encoding="utf-8"):
                    pass
        except Exception as exc:
            print(f"{COL_WARN}[LOG]{RESET} create failed for {path}: {exc}")


def reset_buy_signal_log_stats(day_key=None):
    global BUY_SIGNAL_LOG_STATS
    BUY_SIGNAL_LOG_STATS = {
        "day_key": day_key,
        "today_total": 0,
        "today_passed": 0,
        "windows": {},
        "last_summary_window_key": None,
    }


def _ensure_buy_signal_log_stats_day(scan_dt=None):
    if scan_dt is None:
        scan_dt = get_tehran_now()
    day_key = scan_dt.strftime("%Y-%m-%d") if isinstance(scan_dt, datetime) else None
    if BUY_SIGNAL_LOG_STATS.get("day_key") != day_key:
        reset_buy_signal_log_stats(day_key=day_key)
    return day_key


def record_buy_signal_log_stats(scan_dt, passed):
    if not isinstance(scan_dt, datetime):
        return
    with BUY_SIGNAL_LOG_STATS_LOCK:
        _ensure_buy_signal_log_stats_day(scan_dt)
        BUY_SIGNAL_LOG_STATS["today_total"] += 1
        if passed:
            BUY_SIGNAL_LOG_STATS["today_passed"] += 1
        window_key = interval_slot_key(scan_dt, BUY_SIGNAL_SUMMARY_INTERVAL_MINUTES)
        window = BUY_SIGNAL_LOG_STATS["windows"].setdefault(window_key, {
            "window_start_dt": floor_to_interval(scan_dt, BUY_SIGNAL_SUMMARY_INTERVAL_MINUTES),
            "passed": 0,
            "total": 0,
        })
        window["total"] += 1
        if passed:
            window["passed"] += 1


def collect_buy_signal_log_summary(scan_dt=None, summary_interval_minutes=BUY_SIGNAL_SUMMARY_INTERVAL_MINUTES):
    if scan_dt is None:
        scan_dt = get_tehran_now()
    window_start_dt = floor_to_interval(scan_dt, summary_interval_minutes)
    window_key = interval_slot_key(scan_dt, summary_interval_minutes)
    with BUY_SIGNAL_LOG_STATS_LOCK:
        _ensure_buy_signal_log_stats_day(scan_dt)
        window = BUY_SIGNAL_LOG_STATS.get("windows", {}).get(window_key, {})
        return {
            "window_start_dt": window_start_dt,
            "window_key": window_key,
            "today_passed": int(BUY_SIGNAL_LOG_STATS.get("today_passed", 0) or 0),
            "today_total": int(BUY_SIGNAL_LOG_STATS.get("today_total", 0) or 0),
            "this_window_passed": int(window.get("passed", 0) or 0),
            "this_window_total": int(window.get("total", 0) or 0),
            "summary_already_logged": BUY_SIGNAL_LOG_STATS.get("last_summary_window_key") == window_key,
        }


def mark_buy_signal_summary_logged(window_key):
    with BUY_SIGNAL_LOG_STATS_LOCK:
        BUY_SIGNAL_LOG_STATS["last_summary_window_key"] = window_key


def scan_logs_disabled(scan_label=None):
    """Return True only for suppressible fast-scan file logs.

    DISABLE_SCAN_LOGS intentionally does not disable FULL 5-minute logs or
    printed exception/error output. It only suppresses the noisy BUY-1M log file
    blocks and BUY-1M summary blocks.
    """
    try:
        disabled = bool(DISABLE_SCAN_LOGS)
    except Exception:
        disabled = False

    if not disabled:
        return False

    label = str(scan_label or "").strip().upper()
    return label in {"BUY-1M", "BUY-1M-SUMMARY"}

def debug_output_disabled():
    """Return True when verbose scan debug/details should be omitted from output.

    This is intentionally output-only. The strategy still calculates the same
    fields, and the always-needed timing lines (OHLC prefetch and scan-finished)
    are printed by their own code paths.
    """
    try:
        return bool(DISABLE_DEBUG_OUTPUT)
    except Exception:
        return False


def enqueue_log_write(text, scan_label="FULL", scan_dt=None, path=None):
    if scan_logs_disabled(scan_label):
        return
    ensure_scan_log_files_exist()
    target_path = path or scan_label_to_log_path(scan_label)
    LOG_WRITE_QUEUE.put({
        "path": target_path,
        "text": str(text or ""),
        "scan_label": str(scan_label or "FULL"),
        "scan_dt": scan_dt,
    })


def log_write_worker_loop():
    ensure_scan_log_files_exist()
    while True:
        job = LOG_WRITE_QUEUE.get()
        try:
            path = str(job.get("path") or "").strip()
            text = str(job.get("text") or "")
            scan_label = str(job.get("scan_label") or "FULL")
            scan_dt = job.get("scan_dt")
            if not path:
                continue
            with open(path, "a", encoding="utf-8") as fh:
                fh.write(text)
            prune_log_file(
                scan_dt,
                retention_hours=LOG_RETENTION_HOURS,
                keep_last_scans=LOG_KEEP_LAST_SCANS,
                scan_label=scan_label,
                path=path,
            )
        except Exception as exc:
            print(f"{COL_WARN}[LOG]{RESET} write failed: {exc}")
        finally:
            LOG_WRITE_QUEUE.task_done()


def ensure_log_write_worker_started():
    global LOG_WRITE_WORKER_STARTED, LOG_WRITE_WORKER_THREAD
    thread = LOG_WRITE_WORKER_THREAD
    if LOG_WRITE_WORKER_STARTED and thread is not None and thread.is_alive():
        return thread
    with LOG_WRITE_WORKER_LOCK:
        thread = LOG_WRITE_WORKER_THREAD
        if LOG_WRITE_WORKER_STARTED and thread is not None and thread.is_alive():
            return thread
        thread = threading.Thread(
            target=log_write_worker_loop,
            name="log-write-worker",
            daemon=True,
        )
        thread.start()
        LOG_WRITE_WORKER_THREAD = thread
        LOG_WRITE_WORKER_STARTED = True
        return thread


