def get_script_dir():
    return os.path.dirname(os.path.abspath(__file__))


def get_pumping_event_sent_path():
    return os.path.join(get_script_dir(), PUMPING_EVENT_SENT_FILE)


def _pumping_event_window_start(scan_dt=None):
    if scan_dt is None:
        scan_dt = get_tehran_now()
    anchor = scan_dt.replace(hour=DAILY_PNL_REPLAY_HOUR, minute=DAILY_PNL_REPLAY_MINUTE, second=0, microsecond=0)
    if scan_dt < anchor:
        anchor -= timedelta(days=1)
    return anchor


def _pumping_event_window_key(scan_dt=None):
    return _pumping_event_window_start(scan_dt).strftime("%Y-%m-%d %H:%M:%S")


def _load_pumping_event_sent_state_from_disk(scan_dt=None):
    # v59: keep pumping-message memory live-candle scoped instead of daily/24h-window scoped.
    # Older files that still have window_start are accepted, but window_start no longer suppresses
    # future live-candle PMA/GF+ pumping messages.
    default_state = {"sent": {}, "updated_at": None}
    path = get_pumping_event_sent_path()
    if not os.path.exists(path):
        return default_state
    try:
        with open(path, "r", encoding="utf-8") as fh:
            state = json.load(fh)
    except Exception:
        return default_state
    if not isinstance(state, dict):
        return default_state
    sent = state.get("sent") if isinstance(state.get("sent"), dict) else {}
    state = dict(state)
    state["sent"] = sent
    if "updated_at" not in state:
        state["updated_at"] = None
    return state


def load_pumping_event_sent_state(scan_dt=None):
    context = _get_scan_event_dedupe_context()
    if context is not None:
        cached_state = context.get("pumping_event_state")
        if isinstance(cached_state, dict):
            return cached_state
        cached_state = _load_pumping_event_sent_state_from_disk(scan_dt=scan_dt)
        context["pumping_event_state"] = cached_state
        return cached_state
    return _load_pumping_event_sent_state_from_disk(scan_dt=scan_dt)


def save_pumping_event_sent_state(state):
    path = get_pumping_event_sent_path()
    tmp_path = path + ".tmp"
    if not isinstance(state, dict):
        state = {"sent": {}, "updated_at": None}
    state["updated_at"] = get_tehran_now().strftime("%Y-%m-%d %H:%M:%S")
    with open(tmp_path, "w", encoding="utf-8") as fh:
        json.dump(state, fh, ensure_ascii=False, indent=2)
    os.replace(tmp_path, path)
    context = _get_scan_event_dedupe_context()
    if context is not None:
        context["pumping_event_state"] = state


def _pumping_event_state_for_mutation(scan_dt=None):
    # v95: mirror event-message atomicity for pumping marks.  Mutation paths
    # must not edit the scan-cached pumping ledger before write-through save
    # succeeds; otherwise a disk/write failure can poison same-scan dedupe with
    # a pumping mark that was never persisted.
    state = load_pumping_event_sent_state(scan_dt=scan_dt)
    if not isinstance(state, dict):
        return {"sent": {}, "updated_at": None}
    try:
        cloned = copy.deepcopy(state)
    except Exception:
        cloned = dict(state)
        sent = cloned.get("sent") if isinstance(cloned.get("sent"), dict) else {}
        cloned["sent"] = dict(sent)
    if not isinstance(cloned.get("sent"), dict):
        cloned["sent"] = {}
    if "updated_at" not in cloned:
        cloned["updated_at"] = None
    return cloned


def was_pumping_event_sent_for_base(base_symbol, scan_dt=None, live_candle_ts=None, live_pma=None):
    normalized_base = str(base_symbol or "").strip().upper()
    if not normalized_base:
        return False

    current_live_ts = ts_to_int(live_candle_ts)
    state = load_pumping_event_sent_state(scan_dt=scan_dt)
    sent = state.setdefault("sent", {})
    payload = sent.get(normalized_base)
    if not isinstance(payload, dict):
        return False

    stored_live_ts = ts_to_int(payload.get("live_candle_ts") or payload.get("candle_ts") or payload.get("candle_unix_ts"))

    # v59: once a new live candle exists, the old sent marker must not block the next PMA/GF+ live cross.
    if current_live_ts is not None and stored_live_ts is not None and stored_live_ts != current_live_ts:
        mutation_state = _pumping_event_state_for_mutation(scan_dt=scan_dt)
        mutation_sent = mutation_state.setdefault("sent", {})
        mutation_sent.pop(normalized_base, None)
        try:
            save_pumping_event_sent_state(mutation_state)
        except Exception:
            pass
        return False

    return bool(current_live_ts is not None and stored_live_ts is not None and stored_live_ts == current_live_ts)


def mark_pumping_event_sent_for_base(
    base_symbol,
    preferred_symbol=None,
    scan_dt=None,
    change_24h_pct=None,
    live_candle_ts=None,
    live_pma=None,
    gf_plus=None,
    pma_gf_plus_offset=None,
):
    normalized_base = str(base_symbol or "").strip().upper()
    if not normalized_base:
        return
    state = _pumping_event_state_for_mutation(scan_dt=scan_dt)
    sent = state.setdefault("sent", {})
    sent[normalized_base] = {
        "sent_at": (scan_dt or get_tehran_now()).strftime("%Y-%m-%d %H:%M:%S"),
        "preferred_symbol": str(preferred_symbol or "").strip().upper() or None,
        "change_24h_pct": float(change_24h_pct) if change_24h_pct is not None else None,
        "live_candle_ts": ts_to_int(live_candle_ts),
        "live_pma": float(live_pma) if live_pma is not None else None,
        "gf_plus": float(gf_plus) if gf_plus is not None else None,
        "pma_gf_plus_offset": float(pma_gf_plus_offset) if pma_gf_plus_offset is not None else None,
    }
    save_pumping_event_sent_state(state)


def pumping_display_preference_key(item):
    row = (item or {}).get("row") or {}
    market_type = str(row.get("market_type") or market_type_from_symbol(row.get("symbol_udf")) or "").strip().upper()
    try:
        change_24h_pct = float(row.get("change_24h_pct", 0.0) or 0.0)
    except Exception:
        change_24h_pct = 0.0
    return (0 if market_type == "USDT" else 1, -change_24h_pct, str(row.get("symbol_udf") or ""))


def get_event_message_sent_path():
    return os.path.join(get_script_dir(), EVENT_MESSAGE_SENT_FILE)


def _json_safe_event_debug_value(value):
    """Return a JSON-safe copy for event_message_sent debug snapshots."""
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, list):
        return [_json_safe_event_debug_value(item) for item in value]
    if isinstance(value, tuple):
        return [_json_safe_event_debug_value(item) for item in value]
    if isinstance(value, dict):
        return {str(k): _json_safe_event_debug_value(v) for k, v in value.items()}
    try:
        json.dumps(value, ensure_ascii=False)
        return value
    except Exception:
        return str(value)


def _truncate_event_message_text(value, max_chars=None):
    if value is None:
        return None
    text = str(value)
    try:
        max_len = int(max_chars if max_chars is not None else EVENT_MESSAGE_SUMMARY_REASON_MAX_CHARS)
    except Exception:
        max_len = 260
    if max_len <= 0 or len(text) <= max_len:
        return text
    return text[: max_len - 1].rstrip() + "…"


def _compact_event_message_list_summary(value):
    try:
        items = list(value)
    except Exception:
        return {"count": 0}
    summary = {"count": len(items)}
    if not items:
        return summary

    ts_values = []
    pnl_values = []
    price_values = []
    non_flat_count = 0
    for item in items:
        if not isinstance(item, dict):
            continue
        item_ts = ts_to_int(item.get("ts") or item.get("timestamp"))
        if item_ts is not None:
            ts_values.append(item_ts)
        pnl = _safe_finite_float(item.get("pnl_pct"))
        if pnl is not None:
            pnl_values.append(pnl)
        price = _safe_positive_float(item.get("price"))
        if price is not None:
            price_values.append(price)
        if bool(item.get("non_flat")):
            non_flat_count += 1
    if ts_values:
        summary["first_ts"] = min(ts_values)
        summary["last_ts"] = max(ts_values)
    if pnl_values:
        summary["first_pnl_pct"] = pnl_values[0]
        summary["last_pnl_pct"] = pnl_values[-1]
        summary["min_pnl_pct"] = min(pnl_values)
        summary["max_pnl_pct"] = max(pnl_values)
    if price_values:
        summary["first_price"] = price_values[0]
        summary["last_price"] = price_values[-1]
        summary["min_price"] = min(price_values)
        summary["max_price"] = max(price_values)
    if non_flat_count:
        summary["non_flat_count"] = non_flat_count
    return summary


def _event_message_safe_storage_value(key, value):
    key_text = str(key or "")
    if isinstance(value, str) and (key_text == "reason" or key_text.endswith("_reason")):
        return _truncate_event_message_text(value)
    if isinstance(value, (list, tuple)):
        # Do not store debug/sample arrays in event_message_sent.json. They are
        # runtime state only; the event ledger only needs a compact audit summary.
        return _compact_event_message_list_summary(value)
    if isinstance(value, dict):
        return _json_safe_event_debug_value(value)
    return _json_safe_event_debug_value(value)

