        "pma", "gf_plus", "offset", "force_buy_line_kind", "force_buy_line_source", "force_buy_line_value",
        "entry_pma_flat_neutral", "latest_closed_candle_ts", "latest_closed_candle_body_pct",
        "above_since_ts", "elapsed_seconds",
        "upper_predict_gate_enabled", "upper_predict_gate_passed", "upper_predict_gate_reason",
        "upper_predict_line", "upper_predict_add", "upper_predict_since_ts", "upper_predict_elapsed_seconds",
        "closed_pma_above_upper_predict_required", "closed_pma_above_upper_predict_passed",
        "closed_pma_above_upper_predict_reason", "closed_pma_upper_predict",
        "setup_source", "setup_reason", "setup_line",
        "closed_pma_floor_required", "closed_pma_floor_passed", "closed_pma_floor_threshold", "closed_pma_floor_reason",
        "pre_entry_df0_guard_enabled", "pre_entry_df0_guard_passed", "pre_entry_df0_guard_reason", "pre_entry_df0",
        "reentry_gate_enabled", "reentry_gate_passed", "reentry_gate_blocked", "reentry_gate_reason",
        "quality_gate_enabled", "quality_gate_passed", "quality_gate_reason",
        "quality_price_sample_count", "quality_price_positive_sample_count", "quality_price_negative_sample_count",
        "quality_price_flat_sample_count", "quality_price_non_flat_sample_count", "quality_price_min_non_flat_sample_count",
        "quality_price_positive_sample_ratio", "quality_price_avg_expansion_pct",
        "quality_price_split_gate_enabled", "quality_price_split_passed", "quality_price_split_source",
        "quality_price_split_balance_ratio", "quality_price_split_combined_avg_pct",
        "quality_price_split_first_non_flat_count", "quality_price_split_second_non_flat_count",
        "oma_filter_enabled", "oma_filter_passed", "oma_filter_reason", "oma_value", "oma_prev_value", "oma_delta",
        "oma_sample_count", "oma_positive_delta_count", "oma_negative_delta_count", "oma_flat_delta_count",
        "oma_non_flat_delta_count", "oma_min_non_flat_delta_count", "oma_positive_delta_ratio",
        "final_survival_gate_enabled", "final_survival_gate_passed", "final_survival_gate_reason",
        "breakout_force_buy_enabled", "breakout_force_buy_passed", "breakout_force_buy_reason",
        "closed_pma_gf_plus_direct_force_enabled", "closed_pma_gf_plus_direct_force_passed",
