def _market_priority_for_filter(row):
    market_type = str((row or {}).get("market_type") or market_type_from_symbol((row or {}).get("symbol_udf")) or "").strip().upper()
    if market_type == "USDT":
        return 0
    return 1


def select_candidates(all_markets):
    filtered = [
        m for m in (all_markets or [])
        if (
            isinstance(m, dict)
            and MIN_DAYCHANGE_PCT <= float(m.get("change_24h_pct", 0.0) or 0.0) <= MAX_DAYCHANGE_PCT
        )
    ]
    # Keep the top LBank USDT markets by 24h change within the configured 24h-change band, capped by MAX_CANDIDATES.
    filtered.sort(key=lambda m: (
        -float(m.get("change_24h_pct", 0.0) or 0.0),
        _market_priority_for_filter(m),
        str(m.get("symbol_udf") or ""),
    ))
    return filtered[:MAX_CANDIDATES]


def _normalize_ohlc_request_key(symbol, resolution="30", countback=OHLC_FETCH_COUNT):
    symbol = normalize_nobitex_udf_symbol(symbol)
    if not symbol:
        return None

    resolution = str(resolution)
    if resolution not in VALID_NOBITEX_OHLC_RESOLUTIONS:
        return None

    try:
        countback = int(countback)
    except Exception:
        return None

    if countback <= 0:
        return None

    countback = min(countback, MAX_NOBITEX_OHLC_COUNTBACK)
    return (symbol, resolution, countback)


CACHE_4H_LOCK = threading.Lock()


def _hourly_4h_cache_key(scan_dt=None):
    if not isinstance(scan_dt, datetime):
        scan_dt = get_tehran_now()
    return scan_dt.replace(minute=0, second=0, microsecond=0).strftime("%Y-%m-%d %H:00:00")


def _ensure_4h_cache_hour(scan_dt=None):
    hour_key = _hourly_4h_cache_key(scan_dt)
    with CACHE_4H_LOCK:
        if CACHE_4H.get("_hour_key") != hour_key:
            CACHE_4H.clear()
            CACHE_4H["_hour_key"] = hour_key
            CACHE_4H["data"] = {}
        elif not isinstance(CACHE_4H.get("data"), dict):
            CACHE_4H["data"] = {}
    return hour_key


def _get_4h_cached_ohlc_by_key(key, scan_dt=None):
    if key is None:
        return False, None
    symbol, resolution, countback = key
    if str(resolution) != "240":
        return False, None
    hour_key = _ensure_4h_cache_hour(scan_dt)
    with CACHE_4H_LOCK:
        if CACHE_4H.get("_hour_key") != hour_key:
            return False, None
        data = CACHE_4H.get("data") if isinstance(CACHE_4H.get("data"), dict) else {}
        if key in data:
            return True, data.get(key)
    return False, None


def _store_4h_cached_ohlc_by_key(key, value, scan_dt=None):
    if key is None or not value:
        return False
    symbol, resolution, countback = key
    if str(resolution) != "240":
        return False
    hour_key = _ensure_4h_cache_hour(scan_dt)
    with CACHE_4H_LOCK:
        if CACHE_4H.get("_hour_key") != hour_key:
            CACHE_4H.clear()
            CACHE_4H["_hour_key"] = hour_key
            CACHE_4H["data"] = {}
        CACHE_4H.setdefault("data", {})[key] = value
    return True


def _get_scan_ohlc_prefetch_context():
    context = getattr(OHLC_PREFETCH_LOCAL, "context", None)
    return context if isinstance(context, dict) and context.get("enabled") else None


def set_scan_ohlc_prefetch_context(context):
    OHLC_PREFETCH_LOCAL.context = context if isinstance(context, dict) else None


def clear_scan_ohlc_prefetch_context():
    OHLC_PREFETCH_LOCAL.context = None


def clear_scan_4h_cache(scan_dt=None):
    _ensure_4h_cache_hour(scan_dt)
    return None


def _lookup_prefetched_ohlc(symbol, resolution="30", countback=OHLC_FETCH_COUNT):
    context = _get_scan_ohlc_prefetch_context()
    if not context:
        return OHLC_PREFETCH_MISSING

    key = _normalize_ohlc_request_key(symbol, resolution=resolution, countback=countback)
    if key is None:
        return None

    data = context.get("data") if isinstance(context.get("data"), dict) else {}
    if key in data:
        return data.get(key)

    scan_hour_dt = context.get("scan_dt") if isinstance(context.get("scan_dt"), datetime) else None
    cached_hit, cached_data = _get_4h_cached_ohlc_by_key(key, scan_hour_dt)
    if cached_hit:
        return cached_data

    # Strict mode means analysis must not perform new OHLC network calls after
    # the bounded prefetch window. Missing prefetch result => missing OHLC.
    if context.get("strict", OHLC_PREFETCH_STRICT):
        return None

    return OHLC_PREFETCH_MISSING


def lbank_kline_type_from_resolution(resolution):
    key = str(resolution or "30").strip().upper()
    return LBANK_KLINE_TYPE_BY_RESOLUTION.get(key)


def lbank_kline_interval_seconds(resolution):
    key = str(resolution or "30").strip().upper()
    try:
        return int(LBANK_KLINE_INTERVAL_SECONDS.get(key) or 30 * 60)
    except Exception:
        return 30 * 60


def _convert_lbank_kline_payload_to_udf(payload):
    rows = _lbank_data_list(payload)
    if not rows:
        return {"s": "no_data", "t": [], "o": [], "h": [], "l": [], "c": [], "v": []}

    candles = []
    for row in rows:
        if not isinstance(row, (list, tuple)) or len(row) < 6:
            continue
        try:
            ts = int(float(row[0]))
            o = float(row[1])
            h = float(row[2])
            l = float(row[3])
            c = float(row[4])
            v = float(row[5])
        except Exception:
            continue
        candles.append((ts, o, h, l, c, v))

    candles.sort(key=lambda item: item[0])
    if not candles:
        return {"s": "no_data", "t": [], "o": [], "h": [], "l": [], "c": [], "v": []}

    return {
        "s": "ok",
        "t": [item[0] for item in candles],
        "o": [item[1] for item in candles],
        "h": [item[2] for item in candles],
        "l": [item[3] for item in candles],
        "c": [item[4] for item in candles],
        "v": [item[5] for item in candles],
    }


def fetch_ohlc_direct(symbol, resolution="30", countback=OHLC_FETCH_COUNT, to_ts=None, timeout=None, retries=None):
    key = _normalize_ohlc_request_key(symbol, resolution=resolution, countback=countback)
    if key is None:
        return None

    symbol, resolution, countback = key
    lbank_symbol = lbank_api_symbol(symbol)
    kline_type = lbank_kline_type_from_resolution(resolution)
    if not lbank_symbol or not kline_type:
        return None

    if to_ts is None:
        to_ts = int(time.time())

    interval_seconds = lbank_kline_interval_seconds(resolution)
    try:
        start_ts = int(to_ts) - (int(countback) * int(interval_seconds))
    except Exception:
        start_ts = int(time.time()) - (int(countback) * int(interval_seconds))
    start_ts = max(0, start_ts)

    params = {
        "symbol": lbank_symbol,
        "size": str(int(countback)),
        "type": kline_type,
        "time": str(int(start_ts)),
    }

    if timeout is None:
        timeout = HTTP_TIMEOUT
    if retries is None:
        retries = RETRY_COUNT

    data = http_get_json("/v2/kline.do", params=params, timeout=timeout, retries=retries)
    if not data:
        return None

    converted = _convert_lbank_kline_payload_to_udf(data)
    if converted.get("s") == "ok" and int(to_ts or 0) > 0:
        max_ts = int(to_ts) + int(interval_seconds)
        keep_indices = [i for i, ts in enumerate(converted.get("t") or []) if int(ts) <= max_ts]
        if len(keep_indices) != len(converted.get("t") or []):
            converted = {
                "s": "ok",
                "t": [converted["t"][i] for i in keep_indices],
                "o": [converted["o"][i] for i in keep_indices],
                "h": [converted["h"][i] for i in keep_indices],
                "l": [converted["l"][i] for i in keep_indices],
                "c": [converted["c"][i] for i in keep_indices],
                "v": [converted["v"][i] for i in keep_indices],
            }
        if converted.get("t"):
            for field in ("t", "o", "h", "l", "c", "v"):
                converted[field] = converted[field][-int(countback):]
        else:
            converted = {"s": "no_data", "t": [], "o": [], "h": [], "l": [], "c": [], "v": []}

    return converted


def fetch_ohlc(
    symbol,
    resolution="30",
    countback=OHLC_FETCH_COUNT,
    to_ts=None,
    allow_live_fallback=False,
    live_timeout=None,
    live_retries=None,
):
    # Analyzer must never do a per-symbol live redo after strict prefetch.
    # The only extra network attempt is the failed-key retry inside
    # prefetch_ohlc_for_scan(). Compatibility args are intentionally ignored.
    prefetched = _lookup_prefetched_ohlc(symbol, resolution=resolution, countback=countback)

    if prefetched is not OHLC_PREFETCH_MISSING:
        return prefetched

    key = _normalize_ohlc_request_key(symbol, resolution=resolution, countback=countback)
    cached_hit, cached_data = _get_4h_cached_ohlc_by_key(key)
    if cached_hit:
        return cached_data

    direct_data = fetch_ohlc_with_closed_30m_cache(symbol, resolution=resolution, countback=countback, to_ts=to_ts)
    if direct_data:
        _store_4h_cached_ohlc_by_key(key, direct_data)
    return direct_data


def build_ohlc_prefetch_plan(scan_universe):
    plan = []
    seen = set()

    try:
        max_plan_items = max(1, int(OHLC_PREFETCH_MAX_PLAN_ITEMS))
    except Exception:
        max_plan_items = 240

    for candidate in scan_universe or []:
        if not isinstance(candidate, dict):
            continue
        symbol = candidate.get("symbol_udf")
        for resolution, countback in (("30", OHLC_FETCH_COUNT), ("240", CANDLE_4H_FETCH)):
            key = _normalize_ohlc_request_key(symbol, resolution=resolution, countback=countback)
            if key is None or key in seen:
                continue
            if str(resolution) == "240":
                cached_hit, _cached_data = _get_4h_cached_ohlc_by_key(key)
                if cached_hit:
                    continue
            seen.add(key)
            plan.append(key)
            if len(plan) >= max_plan_items:
                return plan

    return plan


def prefetch_ohlc_for_scan(scan_universe, scan_dt, scan_label=None):
    _ensure_4h_cache_hour(scan_dt)
    plan = build_ohlc_prefetch_plan(scan_universe)
    started_mono = time.monotonic()
    data = {}

    if not plan:
        return {
            "enabled": True,
            "strict": OHLC_PREFETCH_STRICT,
            "data": data,
            "scan_dt": scan_dt,
            "planned": 0,
            "fetched": 0,
            "failed": 0,
            "cancelled": 0,
            "retried_failed": 0,
            "duration": 0.0,
            "request_gap_seconds": OHLC_PREFETCH_REQUEST_GAP_SECONDS,
            "failed_retry_count": OHLC_PREFETCH_FAILED_RETRY_COUNT,
        }

    try:
        budget_seconds = max(0.1, float(OHLC_PREFETCH_BUDGET_SECONDS))
    except Exception:
        budget_seconds = 60.0

    try:
        request_timeout = max(0.1, float(OHLC_PREFETCH_REQUEST_TIMEOUT))
    except Exception:
        request_timeout = 0.2

    try:
        first_request_timeout = max(request_timeout, float(OHLC_PREFETCH_FIRST_REQUEST_TIMEOUT))
    except Exception:
        first_request_timeout = 7.0

    try:
        request_gap_seconds = max(0.0, float(OHLC_PREFETCH_REQUEST_GAP_SECONDS))
    except Exception:
        request_gap_seconds = 0.02

    try:
        worker_count = max(1, int(OHLC_PREFETCH_WORKERS))
    except Exception:
        worker_count = 7
    worker_count = min(worker_count, len(plan))

    try:
        failed_retry_count = max(0, int(OHLC_PREFETCH_FAILED_RETRY_COUNT))
    except Exception:
        failed_retry_count = 1

    to_ts = int(scan_dt.timestamp()) if isinstance(scan_dt, datetime) else int(time.time())
    deadline_mono = started_mono + budget_seconds
    request_start_lock = threading.Lock()
    next_request_start_mono = [started_mono]
    cancelled_keys = set()
    http_warning_collector = {"count": 0, "lock": threading.Lock()}

    def wait_for_prefetch_request_slot():
        if request_gap_seconds <= 0:
            return time.monotonic() <= deadline_mono

        with request_start_lock:
            now_mono = time.monotonic()
            scheduled_mono = max(now_mono, next_request_start_mono[0])
            if scheduled_mono > deadline_mono:
                return False
            next_request_start_mono[0] = scheduled_mono + request_gap_seconds

        sleep_seconds = scheduled_mono - time.monotonic()
        if sleep_seconds > 0:
            time.sleep(min(sleep_seconds, max(0.0, deadline_mono - time.monotonic())))

        return time.monotonic() <= deadline_mono

    def fetch_one(key, retry_count=0):
        if not wait_for_prefetch_request_slot():
            return key, None

        symbol, resolution, countback = key
        timeout_for_this_request = (
            request_timeout
            if native_http_connection_exists_for_base_url()
            else first_request_timeout
        )
        old_collector = _set_ohlc_prefetch_http_warning_collector(http_warning_collector)
        try:
            return key, fetch_ohlc_with_closed_30m_cache(
                symbol,
                resolution=resolution,
                countback=countback,
                to_ts=to_ts,
                timeout=timeout_for_this_request,
                retries=retry_count,
            )
        finally:
            _restore_ohlc_prefetch_http_warning_collector(old_collector)

    def run_prefetch_batch(batch_keys, retry_count, timeout_seconds):
        if not batch_keys or timeout_seconds <= 0:
            return set()

        batch_worker_count = min(worker_count, len(batch_keys))
        failed_keys = set()
        executor = concurrent.futures.ThreadPoolExecutor(
            max_workers=batch_worker_count,
            thread_name_prefix="ohlc-prefetch",
        )
        futures = {executor.submit(fetch_one, key, retry_count): key for key in batch_keys}

        try:
            done, not_done = concurrent.futures.wait(
                futures.keys(),
                timeout=timeout_seconds,
                return_when=concurrent.futures.ALL_COMPLETED,
            )

            for future in done:
                key = futures.get(future)
                try:
                    returned_key, ohlc_data = future.result()
                    returned_key = returned_key or key
                    if returned_key is not None and ohlc_data:
                        data[returned_key] = ohlc_data
                    elif key is not None:
                        failed_keys.add(key)
                except Exception:
                    if key is not None:
                        failed_keys.add(key)

            for future in not_done:
                key = futures.get(future)
                if key is not None:
                    cancelled_keys.add(key)
                future.cancel()

        finally:
            try:
                executor.shutdown(wait=False, cancel_futures=True)
            except TypeError:
                executor.shutdown(wait=False)

        return failed_keys

    first_failed_keys = run_prefetch_batch(plan, retry_count=0, timeout_seconds=budget_seconds)
    retry_keys = [key for key in plan if key in first_failed_keys and key not in data and key not in cancelled_keys]
    retried_failed = 0

    remaining_seconds = max(0.0, deadline_mono - time.monotonic())
    if failed_retry_count > 0 and retry_keys and remaining_seconds > 0:
        retried_failed = len(retry_keys)
        run_prefetch_batch(retry_keys, retry_count=failed_retry_count, timeout_seconds=remaining_seconds)

    for key, value in list(data.items()):
        _store_4h_cached_ohlc_by_key(key, value, scan_dt)

    cancelled = len(cancelled_keys)
    failed = sum(1 for key in plan if key not in data and key not in cancelled_keys)
    duration = time.monotonic() - started_mono
    suppressed_http_warnings = int(http_warning_collector.get("count", 0))
    suppressed_suffix = (
        f" http_warn_suppressed={suppressed_http_warnings}"
        if suppressed_http_warnings > 0
        else ""
    )
    print(
        f"{COL_INFO}[OHLC-PREFETCH]{RESET} {scan_label or '-'} "
        f"planned={len(plan)} fetched={len(data)} failed={failed} "
        f"cancelled={cancelled} retried_failed={retried_failed} duration={duration:.1f}s "
        f"budget={budget_seconds:.1f}s request_timeout={request_timeout:.1f}s "
        f"first_request_timeout={first_request_timeout:.1f}s "
        f"request_gap={request_gap_seconds:.2f}s retry_failed={failed_retry_count}"
        f"{suppressed_suffix}"
    )

    return {
        "enabled": True,
        "strict": OHLC_PREFETCH_STRICT,
        "data": data,
        "scan_dt": scan_dt,
        "planned": len(plan),
        "fetched": len(data),
        "failed": failed,
        "cancelled": cancelled,
        "retried_failed": retried_failed,
        "duration": duration,
        "request_timeout": request_timeout,
        "first_request_timeout": first_request_timeout,
        "request_gap_seconds": request_gap_seconds,
        "failed_retry_count": failed_retry_count,
        "http_warn_suppressed": suppressed_http_warnings,
    }

def _safe_positive_float(value):
    try:
        value = float(value)
    except Exception:
        return None
    if not math.isfinite(value) or value <= 0:
        return None
    return value





def _safe_non_negative_int(value, default=0, max_value=None):
    try:
        if value is None:
            return int(default or 0)
        numeric = float(value)
        if not math.isfinite(numeric):
            return int(default or 0)
        result = int(numeric)
    except Exception:
        return int(default or 0)
    if result < 0:
        result = 0
    if max_value is not None:
        try:
            max_int = int(max_value)
            if max_int >= 0 and result > max_int:
                result = max_int
        except Exception:
            pass
    return result


def _safe_non_negative_float(value):
    try:
        value = float(value)
    except Exception:
        return None
    if not math.isfinite(value) or value < 0:
        return None
    return value



def _safe_int_timestamp(value):
    try:
        value = int(float(value))
    except Exception:
        return None
    return value if value > 0 else None



def _latest_closed_candle_start_ts(timeframe_seconds, now_ts=None):
    if now_ts is None:
        now_ts = int(time.time())
    try:
        now_ts = int(now_ts)
        timeframe_seconds = int(timeframe_seconds)
    except Exception:
        return None
    if now_ts <= 0 or timeframe_seconds <= 0:
        return None
    slot_index = (now_ts // timeframe_seconds) - 1
    if slot_index < 0:
        return None
    return slot_index * timeframe_seconds




def _closed_30m_cache_enabled():
    try:
        return bool(ENABLE_CLOSED_30M_OHLC_CACHE)
    except Exception:
        return False


def _is_closed_30m_cache_key(key):
    if key is None:
        return False
    try:
        _symbol, resolution, countback = key
    except Exception:
        return False
    try:
        countback = int(countback)
    except Exception:
        return False
    return str(resolution) == "30" and countback >= STRATEGY_MIN_CLOSED_CANDLES


def _ohlc_rows_from_payload(ohlc):
    if not isinstance(ohlc, dict) or ohlc.get("s") == "no_data":
        return []

    t = ohlc.get("t") or []
    o = ohlc.get("o") or []
    h = ohlc.get("h") or []
    l = ohlc.get("l") or []
    c = ohlc.get("c") or []
    v = ohlc.get("v") or []

    rows = []
    for idx in range(len(t)):
        ts = _safe_int_timestamp(t[idx])
        if ts is None:
            continue
        rows.append({
            "t": int(ts),
            "o": o[idx] if idx < len(o) else None,
            "h": h[idx] if idx < len(h) else None,
            "l": l[idx] if idx < len(l) else None,
            "c": c[idx] if idx < len(c) else None,
            "v": v[idx] if idx < len(v) else None,
        })
    return rows


def _ohlc_payload_from_rows(rows):
    rows = sorted(
        (row for row in (rows or []) if isinstance(row, dict) and row.get("t") is not None),
        key=lambda row: int(row.get("t")),
    )
    return {
        "s": "ok",
        "t": [int(row.get("t")) for row in rows],
        "o": [row.get("o") for row in rows],
        "h": [row.get("h") for row in rows],
        "l": [row.get("l") for row in rows],
        "c": [row.get("c") for row in rows],
        "v": [row.get("v") for row in rows],
    }


def _closed_30m_cache_signature(rows):
    signature = []
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        signature.append((
            int(row.get("t")),
            str(row.get("o")),
            str(row.get("h")),
            str(row.get("l")),
            str(row.get("c")),
            str(row.get("v")),
        ))
    return tuple(signature)


def _closed_30m_expected_latest_closed_ts(now_ts=None, timeframe_seconds=1800):
    return _latest_closed_candle_start_ts(timeframe_seconds, now_ts=now_ts)


def _closed_30m_next_difference_ts(latest_closed_ts, now_ts=None, timeframe_seconds=1800):
    """Return the moment when the cached closed-30m set can first differ.

    Candle timestamps are candle-start timestamps. A candle with start T becomes
    the latest closed candle only after T + timeframe, and it remains the latest
    closed candle until the next candle closes at T + 2 * timeframe. Therefore a
    cache whose latest closed candle is T is valid only while the expected latest
    closed candle for the current scan is still T.

    This intentionally avoids modulo-based renewal. Once the expected latest
    closed candle advances, an old cache entry must expire and cannot be
    resurrected for another 30m cycle.
    """
    try:
        latest_closed_ts = int(latest_closed_ts)
        timeframe_seconds = int(timeframe_seconds)
        now_ts = int(now_ts if now_ts is not None else time.time())
    except Exception:
        return None

    if latest_closed_ts <= 0 or timeframe_seconds <= 0 or now_ts <= 0:
        return None

    expected_latest_closed_ts = _closed_30m_expected_latest_closed_ts(
        now_ts=now_ts,
        timeframe_seconds=timeframe_seconds,
    )
    if expected_latest_closed_ts is None:
        return None

    # Stale cache: the scan already expects a newer closed candle.
    if latest_closed_ts < expected_latest_closed_ts:
        return now_ts

    # Future/misaligned cache: do not trust it.
    if latest_closed_ts > expected_latest_closed_ts:
        return None

    return int(latest_closed_ts) + (2 * int(timeframe_seconds))


def _closed_30m_cache_seconds_remaining(entry, now_ts=None, timeframe_seconds=1800):
    if not isinstance(entry, dict):
        return 0
    try:
        latest_closed_ts = int(entry.get("latest_closed_ts") or 0)
        now_ts = int(now_ts if now_ts is not None else time.time())
        timeframe_seconds = int(timeframe_seconds)
    except Exception:
        return 0

    expected_latest_closed_ts = _closed_30m_expected_latest_closed_ts(
        now_ts=now_ts,
        timeframe_seconds=timeframe_seconds,
    )
    if expected_latest_closed_ts is None or latest_closed_ts != expected_latest_closed_ts:
        return 0

    try:
        valid_until_ts = int(entry.get("valid_until_ts") or 0)
    except Exception:
        valid_until_ts = 0

    if valid_until_ts <= 0:
        valid_until_ts = _closed_30m_next_difference_ts(
            latest_closed_ts,
            now_ts=now_ts,
            timeframe_seconds=timeframe_seconds,
        ) or 0

    if valid_until_ts <= now_ts:
        return 0

    return max(0, int(valid_until_ts) - int(now_ts))


CACHE_30M_CLOSED_LOCK = threading.Lock()


def _get_30m_closed_cached_payload_by_key(key, scan_dt=None):
    if not _closed_30m_cache_enabled() or not _is_closed_30m_cache_key(key):
        return False, None, None

    try:
        now_ts = int(scan_dt.timestamp()) if isinstance(scan_dt, datetime) else int(time.time())
    except Exception:
        now_ts = int(time.time())

    with CACHE_30M_CLOSED_LOCK:
        entry = CACHE_30M_CLOSED.get(key)
        if not isinstance(entry, dict):
            return False, None, None

        seconds_remaining = _closed_30m_cache_seconds_remaining(entry, now_ts=now_ts, timeframe_seconds=1800)
        if seconds_remaining <= 0:
            CACHE_30M_CLOSED.pop(key, None)
            return False, None, None

        next_difference_ts = now_ts + seconds_remaining
        entry["valid_until_ts"] = next_difference_ts
        entry["seconds_until_next_closed_difference"] = seconds_remaining

        payload = entry.get("closed_ohlc")
        if not isinstance(payload, dict):
            CACHE_30M_CLOSED.pop(key, None)
            return False, None, None

        return True, payload, dict(entry)


def _store_30m_closed_cache_by_key(key, ohlc, scan_dt=None):
    if not _closed_30m_cache_enabled() or not _is_closed_30m_cache_key(key):
        return False
    if not isinstance(ohlc, dict) or ohlc.get("s") == "no_data":
        return False

    try:
        now_ts = int(scan_dt.timestamp()) if isinstance(scan_dt, datetime) else int(time.time())
    except Exception:
        now_ts = int(time.time())

    latest_expected_closed_ts = _latest_closed_candle_start_ts(1800, now_ts=now_ts)
    if latest_expected_closed_ts is None:
        return False

    rows = _ohlc_rows_from_payload(ohlc)
    closed_rows = [row for row in rows if int(row.get("t")) <= latest_expected_closed_ts]
    if not closed_rows:
        return False

    closed_rows.sort(key=lambda row: int(row.get("t")))
    try:
        _symbol, _resolution, countback = key
        countback = int(countback)
    except Exception:
        countback = OHLC_FETCH_COUNT
    closed_rows = closed_rows[-max(1, countback):]

    latest_closed_ts = int(closed_rows[-1].get("t"))
    if latest_closed_ts != int(latest_expected_closed_ts):
        # The exchange/API has not returned the latest expected closed 30m candle yet.
        # Do not cache stale history; force a fresh full fetch on the next scan.
        return False

    valid_until_ts = _closed_30m_next_difference_ts(latest_closed_ts, now_ts=now_ts, timeframe_seconds=1800)
    if valid_until_ts is None or valid_until_ts <= now_ts:
        return False
    seconds_until_next_closed_difference = max(0, int(valid_until_ts) - int(now_ts))

    signature = _closed_30m_cache_signature(closed_rows)
    closed_payload = _ohlc_payload_from_rows(closed_rows)

    with CACHE_30M_CLOSED_LOCK:
        previous = CACHE_30M_CLOSED.get(key) if isinstance(CACHE_30M_CLOSED.get(key), dict) else {}
        CACHE_30M_CLOSED[key] = {
            "closed_ohlc": closed_payload,
            "latest_closed_ts": latest_closed_ts,
            "valid_until_ts": valid_until_ts,
            "seconds_until_next_closed_difference": seconds_until_next_closed_difference,
            "stored_at_ts": now_ts,
            "signature": signature,
            "unchanged_from_previous": previous.get("signature") == signature if previous else False,
        }
    return True


def _merge_cached_closed_30m_with_live_ohlc(cached_closed_ohlc, live_ohlc, scan_dt=None, countback=OHLC_FETCH_COUNT, cache_entry=None):
    if not isinstance(cached_closed_ohlc, dict):
        return live_ohlc

    try:
        now_ts = int(scan_dt.timestamp()) if isinstance(scan_dt, datetime) else int(time.time())
    except Exception:
        now_ts = int(time.time())

    latest_expected_closed_ts = _closed_30m_expected_latest_closed_ts(now_ts=now_ts, timeframe_seconds=1800)
    if latest_expected_closed_ts is None:
        return live_ohlc if isinstance(live_ohlc, dict) else cached_closed_ohlc

    try:
        cached_latest_closed_ts = int((cache_entry or {}).get("latest_closed_ts") or 0)
    except Exception:
        cached_latest_closed_ts = 0

    cached_rows = _ohlc_rows_from_payload(cached_closed_ohlc)
    if cached_latest_closed_ts <= 0 and cached_rows:
        try:
            cached_latest_closed_ts = max(int(row.get("t")) for row in cached_rows if row.get("t") is not None)
        except Exception:
            cached_latest_closed_ts = 0

    # If the cached history is not for the latest expected closed candle, never
    # merge it with a small live fetch. The caller should do a full fetch instead.
    if cached_latest_closed_ts != int(latest_expected_closed_ts):
        return live_ohlc if isinstance(live_ohlc, dict) else cached_closed_ohlc

    rows_by_ts = {}
    for row in cached_rows:
        try:
            row_ts = int(row.get("t"))
        except Exception:
            continue
        if row_ts <= cached_latest_closed_ts:
            rows_by_ts[row_ts] = row

    if isinstance(live_ohlc, dict) and live_ohlc.get("s") != "no_data":
        for row in _ohlc_rows_from_payload(live_ohlc):
            try:
                row_ts = int(row.get("t"))
            except Exception:
                continue
            # Keep the current forming candle fresh. If the API unexpectedly
            # returns a newer closed candle, include it in the returned payload
            # instead of hiding it, but the cache itself will refresh on expiry.
            if row_ts > cached_latest_closed_ts:
                rows_by_ts[row_ts] = row

    try:
        countback = int(countback)
    except Exception:
        countback = OHLC_FETCH_COUNT

    rows = sorted(rows_by_ts.values(), key=lambda row: int(row.get("t")))
    if not rows:
        return live_ohlc if isinstance(live_ohlc, dict) else cached_closed_ohlc

    # Keep enough closed history plus any returned forming/newer rows.
    rows = rows[-max(1, countback + int(CLOSED_30M_LIVE_FETCH_COUNTBACK)):] 
    return _ohlc_payload_from_rows(rows)


def fetch_ohlc_with_closed_30m_cache(symbol, resolution="30", countback=OHLC_FETCH_COUNT, to_ts=None, timeout=None, retries=None):
    key = _normalize_ohlc_request_key(symbol, resolution=resolution, countback=countback)
    if key is None:
        return None

    if str(resolution) != "30" or not _closed_30m_cache_enabled() or not _is_closed_30m_cache_key(key):
        data = fetch_ohlc_direct(symbol, resolution=resolution, countback=countback, to_ts=to_ts, timeout=timeout, retries=retries)
        if str(resolution) == "30" and data:
            _store_30m_closed_cache_by_key(key, data, datetime.fromtimestamp(int(to_ts)) if to_ts else None)
        return data

    scan_dt = datetime.fromtimestamp(int(to_ts)) if to_ts else None
    cached_hit, cached_closed_ohlc, _cache_entry = _get_30m_closed_cached_payload_by_key(key, scan_dt=scan_dt)
    if cached_hit:
        try:
            live_countback = max(2, int(CLOSED_30M_LIVE_FETCH_COUNTBACK))
        except Exception:
            live_countback = 4
        live_ohlc = fetch_ohlc_direct(
            symbol,
            resolution=resolution,
            countback=live_countback,
            to_ts=to_ts,
            timeout=timeout,
            retries=retries,
        )
        return _merge_cached_closed_30m_with_live_ohlc(
            cached_closed_ohlc,
            live_ohlc,
            scan_dt=scan_dt,
            countback=countback,
            cache_entry=_cache_entry,
        )

    data = fetch_ohlc_direct(symbol, resolution=resolution, countback=countback, to_ts=to_ts, timeout=timeout, retries=retries)
    if data:
        _store_30m_closed_cache_by_key(key, data, scan_dt=scan_dt)
    return data



def _price_seed_from_raw_slot(raw_row):
    if not isinstance(raw_row, dict):
        return None
    for key in ("c", "o", "h", "l"):
        price = raw_row.get(key)
        if price is not None and price > 0:
            return price
    return None



def _normalize_slot_row(ts, raw_row, prev_close=None, next_seed_price=None):
    raw_row = raw_row if isinstance(raw_row, dict) else {}

    open_p = raw_row.get("o")
    high_p = raw_row.get("h")
    low_p = raw_row.get("l")
    close_p = raw_row.get("c")
    vol = raw_row.get("v")

    price_candidates = [price for price in (open_p, high_p, low_p, close_p) if price is not None and price > 0]
    fallback_price = None
    for candidate_price in (close_p, open_p, low_p, high_p, prev_close, next_seed_price):
        if candidate_price is not None and candidate_price > 0:
            fallback_price = candidate_price
            break

    if fallback_price is None:
        return None

    if open_p is None:
        open_p = close_p if close_p is not None else fallback_price
    if close_p is None:
        close_p = open_p if open_p is not None else fallback_price

    if open_p is None or close_p is None or open_p <= 0 or close_p <= 0:
        return None

    range_prices = [price for price in price_candidates + [open_p, close_p] if price is not None and price > 0]
    if not range_prices:
        return None

    high_p = max(range_prices)
    low_p = min(range_prices)

    full_price_set_valid = (
        raw_row.get("o") is not None and
        raw_row.get("h") is not None and
        raw_row.get("l") is not None and
        raw_row.get("c") is not None and
        raw_row["h"] >= raw_row["l"] and
        raw_row["h"] >= max(raw_row["o"], raw_row["c"], raw_row["l"]) and
        raw_row["l"] <= min(raw_row["o"], raw_row["c"], raw_row["h"])
    )

    placeholder_reason = None
    if not full_price_set_valid:
        placeholder_reason = "repaired"
    elif raw_row.get("v") is None:
        placeholder_reason = "volume_repaired"

    return {
        "t": int(ts),
        "o": float(open_p),
        "h": float(high_p),
        "l": float(low_p),
        "c": float(close_p),
        "v": float(vol) if vol is not None else 0.0,
        "is_placeholder": bool(placeholder_reason),
        "placeholder_reason": placeholder_reason,
    }



def extract_closed_candles(ohlc, timeframe_seconds=1800, now_ts=None, expected_count=None, fill_missing=True, seed_price=None):
    if not ohlc:
        return []

    latest_closed_ts = _latest_closed_candle_start_ts(timeframe_seconds, now_ts=now_ts)
    if latest_closed_ts is None:
        return []

    if ohlc.get("s") == "no_data":
        if not fill_missing:
            return []
        try:
            expected_count = max(1, int(expected_count)) if expected_count is not None else None
        except Exception:
            expected_count = None
        seed_price = _safe_positive_float(seed_price)
        if not expected_count or seed_price is None:
            return []
        start_ts = latest_closed_ts - ((expected_count - 1) * int(timeframe_seconds))
        return [{
            "t": int(ts),
            "o": float(seed_price),
            "h": float(seed_price),
            "l": float(seed_price),
            "c": float(seed_price),
            "v": 0.0,
            "is_placeholder": True,
            "placeholder_reason": "no_data_fill",
        } for ts in range(int(start_ts), int(latest_closed_ts) + 1, int(timeframe_seconds))]

    t = ohlc.get("t") or []
    o = ohlc.get("o") or []
    h = ohlc.get("h") or []
    l = ohlc.get("l") or []
    c = ohlc.get("c") or []
    v = ohlc.get("v") or []

    raw_rows_by_ts = {}
    seen_ts = set()

    for idx in range(len(t)):
        ts = _safe_int_timestamp(t[idx])
        if ts is None or ts in seen_ts or ts > latest_closed_ts:
            continue

        seen_ts.add(ts)
        raw_rows_by_ts[ts] = {
            "o": _safe_positive_float(o[idx]) if idx < len(o) else None,
            "h": _safe_positive_float(h[idx]) if idx < len(h) else None,
            "l": _safe_positive_float(l[idx]) if idx < len(l) else None,
            "c": _safe_positive_float(c[idx]) if idx < len(c) else None,
            "v": _safe_non_negative_float(v[idx]) if idx < len(v) else None,
        }

    if not raw_rows_by_ts:
        if not fill_missing:
            return []
        try:
            expected_count = max(1, int(expected_count)) if expected_count is not None else None
        except Exception:
            expected_count = None
        seed_price = _safe_positive_float(seed_price)
        if not expected_count or seed_price is None:
            return []
        start_ts = latest_closed_ts - ((expected_count - 1) * int(timeframe_seconds))
        return [{
            "t": int(ts),
            "o": float(seed_price),
            "h": float(seed_price),
            "l": float(seed_price),
            "c": float(seed_price),
            "v": 0.0,
            "is_placeholder": True,
            "placeholder_reason": "empty_window_fill",
        } for ts in range(int(start_ts), int(latest_closed_ts) + 1, int(timeframe_seconds))]

    if fill_missing:
        if expected_count is not None:
            try:
                expected_count = max(1, int(expected_count))
            except Exception:
                expected_count = None
        if expected_count:
            start_ts = latest_closed_ts - ((expected_count - 1) * int(timeframe_seconds))
        else:
            start_ts = min(raw_rows_by_ts)
        end_ts = latest_closed_ts
        target_timestamps = list(range(int(start_ts), int(end_ts) + 1, int(timeframe_seconds)))
        if expected_count and not any(ts in raw_rows_by_ts for ts in target_timestamps):
            seed_price = _safe_positive_float(seed_price)
            if seed_price is not None:
                return [{
                    "t": int(ts),
                    "o": float(seed_price),
                    "h": float(seed_price),
                    "l": float(seed_price),
                    "c": float(seed_price),
                    "v": 0.0,
                    "is_placeholder": True,
                    "placeholder_reason": "stale_window_fill",
                } for ts in target_timestamps]
    else:
        target_timestamps = sorted(raw_rows_by_ts)

    slot_seed_by_ts = {ts: _price_seed_from_raw_slot(raw_rows_by_ts.get(ts)) for ts in target_timestamps}
    next_seed_price = None
    next_seed_by_ts = {}
    for ts in reversed(target_timestamps):
        seed_price = slot_seed_by_ts.get(ts)
        if seed_price is not None:
            next_seed_price = seed_price
        next_seed_by_ts[ts] = next_seed_price

    candles = []
    prev_close = None

    for ts in target_timestamps:
        raw_row = raw_rows_by_ts.get(ts)
        candle = _normalize_slot_row(
            ts,
            raw_row,
            prev_close=prev_close,
            next_seed_price=next_seed_by_ts.get(ts),
        )
        if candle is None:
            continue

        if raw_row is None:
            candle["is_placeholder"] = True
            candle["placeholder_reason"] = "gap_fill"

        candles.append(candle)
        prev_close = candle["c"]

    candles.sort(key=lambda row: row["t"])
    return candles



def extract_current_forming_candle(ohlc, timeframe_seconds=1800, now_ts=None, fallback_price=None):
    """Return the current/live forming candle for the active timeframe.

    LBank REST kline responses may contain only completed candles.  The old
    LBank port treated the absence of a current-slot row as "no live candle",
    which caused BUY-1M PMA/GF+ diagnostics to stop before they could populate
    pma_gf_plus_force_buy_* fields.  Nobitex often supplies a usable live row,
    so the same strategy logic looked healthy there.

    This function keeps the old behavior when a current-slot/future row exists.
    When no current-slot row exists, it synthesizes a conservative live candle
    from the latest closed candle and the already-fetched ticker/current price
    (fallback_price).  This is an API-adapter fix only: no PMA/GF+ thresholds,
    offsets, gates, or buy/sell strategy rules are changed.
    """
    if not ohlc or ohlc.get("s") == "no_data":
        return None

    latest_closed_ts = _latest_closed_candle_start_ts(timeframe_seconds, now_ts=now_ts)
    if latest_closed_ts is None:
        return None

    try:
        timeframe_seconds = int(timeframe_seconds)
        current_slot_ts = (int(now_ts if now_ts is not None else time.time()) // timeframe_seconds) * timeframe_seconds
    except Exception:
        current_slot_ts = int(latest_closed_ts) + int(timeframe_seconds or 1800)

    t = ohlc.get("t") or []
    o = ohlc.get("o") or []
    h = ohlc.get("h") or []
    l = ohlc.get("l") or []
    c = ohlc.get("c") or []
    v = ohlc.get("v") or []

    future_rows = []
    latest_closed_rows = []
    for idx in range(len(t)):
        ts = _safe_int_timestamp(t[idx])
        if ts is None:
            continue
        if latest_closed_ts < ts <= current_slot_ts:
            future_rows.append((ts, idx))
        elif ts <= latest_closed_ts:
            latest_closed_rows.append((ts, idx))

    if future_rows:
        current_ts, idx = max(future_rows, key=lambda item: item[0])
        raw_row = {
            "o": _safe_positive_float(o[idx]) if idx < len(o) else None,
            "h": _safe_positive_float(h[idx]) if idx < len(h) else None,
            "l": _safe_positive_float(l[idx]) if idx < len(l) else None,
            "c": _safe_positive_float(c[idx]) if idx < len(c) else None,
            "v": _safe_non_negative_float(v[idx]) if idx < len(v) else None,
        }

        if fallback_price is not None:
            fallback_price = _safe_positive_float(fallback_price)
            if fallback_price is not None:
                raw_row["c"] = fallback_price
                # Keep the live price inside the reported range if the exchange
                # sends an unfinished candle but ticker is fresher than the REST row.
                if raw_row.get("h") is not None:
                    raw_row["h"] = max(raw_row["h"], fallback_price)
                if raw_row.get("l") is not None:
                    raw_row["l"] = min(raw_row["l"], fallback_price)

        candle = _normalize_slot_row(current_ts, raw_row)
        if candle is None:
            return None

        candle["is_green"] = candle["c"] > candle["o"]
        candle["is_red"] = candle["c"] < candle["o"]
        candle["body_size_abs"] = abs(candle["c"] - candle["o"])
        candle["body_size_pct"] = abs(pct_change(candle["o"], candle["c"])) if candle.get("o") else None
        candle["synthetic_live"] = False
        candle["live_candle_source"] = "ohlc_current_slot"
        return candle

    # LBank REST fallback:
    # If /kline only returned completed candles, create the current forming
    # candle from the latest completed candle close and the ticker/latest price.
    # This restores the data shape that the PMA/GF+ pipeline expects.
    fallback_price = _safe_positive_float(fallback_price)
    if fallback_price is None:
        return None
    if not latest_closed_rows:
        return None

    latest_ts, latest_idx = max(latest_closed_rows, key=lambda item: item[0])
    latest_close = _safe_positive_float(c[latest_idx]) if latest_idx < len(c) else None
    latest_open = _safe_positive_float(o[latest_idx]) if latest_idx < len(o) else None
    seed_open = latest_close or latest_open or fallback_price
    if seed_open is None or seed_open <= 0:
        return None

    raw_row = {
        "o": seed_open,
        "h": max(seed_open, fallback_price),
        "l": min(seed_open, fallback_price),
        "c": fallback_price,
        "v": 0.0,
    }
    candle = _normalize_slot_row(current_slot_ts, raw_row, prev_close=seed_open, next_seed_price=fallback_price)
    if candle is None:
        return None

    candle["is_green"] = candle["c"] > candle["o"]
    candle["is_red"] = candle["c"] < candle["o"]
    candle["body_size_abs"] = abs(candle["c"] - candle["o"])
    candle["body_size_pct"] = abs(pct_change(candle["o"], candle["c"])) if candle.get("o") else None
    candle["synthetic_live"] = True
    candle["live_candle_source"] = "synthetic_from_lbank_rest_closed_candle_and_ticker"
    candle["synthetic_base_closed_ts"] = int(latest_ts)
    candle["synthetic_base_close"] = float(seed_open)
    candle["synthetic_fallback_price"] = float(fallback_price)
    return candle




def evaluate_current_red_entry_skip(prev_closed_candle, current_forming_candle, min_ratio=ENTRY_RED_CANDLE_SKIP_RATIO):
    result = {
        "blocked": False,
        "ratio": None,
        "current_body_abs": None,
        "prev_body_abs": None,
        "current_candle_ts": current_forming_candle.get("t") if isinstance(current_forming_candle, dict) else None,
        "current_open": current_forming_candle.get("o") if isinstance(current_forming_candle, dict) else None,
        "current_price": current_forming_candle.get("c") if isinstance(current_forming_candle, dict) else None,
    }

    if not isinstance(prev_closed_candle, dict) or not isinstance(current_forming_candle, dict):
        return result

    try:
        prev_body_abs = abs(float(prev_closed_candle.get("c")) - float(prev_closed_candle.get("o")))
        current_body_abs = abs(float(current_forming_candle.get("c")) - float(current_forming_candle.get("o")))
    except Exception:
        return result

    result["current_body_abs"] = current_body_abs
    result["prev_body_abs"] = prev_body_abs

    if prev_body_abs <= 0:
        return result
    if not bool(current_forming_candle.get("is_red")):
        return result

    ratio = current_body_abs / prev_body_abs
    result["ratio"] = ratio
    if ratio >= float(min_ratio):
        result["blocked"] = True
        result["reason"] = (
            "forming candle is red and its body reached at least "
            f"{min_ratio * 100.0:.0f}% of previous closed candle body"
        )

    return result



def evaluate_closed_entry_skip(prev_closed_candle, latest_closed_candle, flat_change_pct=ENTRY_CLOSED_FLAT_CHANGE_PCT):
    result = {
        "blocked": False,
        "reason": None,
        "closed_candle_ts": latest_closed_candle.get("t") if isinstance(latest_closed_candle, dict) else None,
        "latest_open": latest_closed_candle.get("o") if isinstance(latest_closed_candle, dict) else None,
        "latest_close": latest_closed_candle.get("c") if isinstance(latest_closed_candle, dict) else None,
        "latest_vs_prev_pct": None,
        "latest_is_red": False,
        "latest_is_placeholder": bool(latest_closed_candle.get("is_placeholder")) if isinstance(latest_closed_candle, dict) else False,
        "latest_red_tolerated": False,
    }

    if not isinstance(prev_closed_candle, dict) or not isinstance(latest_closed_candle, dict):
        return result

    try:
        prev_close = float(prev_closed_candle.get("c"))
        latest_open = float(latest_closed_candle.get("o"))
        latest_close = float(latest_closed_candle.get("c"))
    except Exception:
        return result

    if prev_close <= 0:
        return result

    latest_vs_prev_pct = pct_change(prev_close, latest_close)
    latest_is_red = latest_close < prev_close
    prev_is_green = bool(prev_closed_candle.get("is_green"))
    latest_red_tolerated = bool(latest_is_red and prev_is_green and latest_vs_prev_pct > -1.0)

    result["latest_open"] = latest_open
    result["latest_close"] = latest_close
    result["latest_vs_prev_pct"] = latest_vs_prev_pct
    result["latest_is_red"] = latest_is_red
    result["latest_red_tolerated"] = latest_red_tolerated

    if latest_is_red and not latest_red_tolerated:
        result["blocked"] = True
        result["reason"] = "latest closed red candle closed -1.00% or more below previous closed green candle"
        return result

    if abs(latest_vs_prev_pct) <= float(flat_change_pct):
        result["blocked"] = True
        result["reason"] = (
            "latest closed candle is flat within "
            f"±{float(flat_change_pct):.2f}% of previous closed candle"
        )
        if result["latest_is_placeholder"]:
            result["reason"] += " (placeholder-filled candle)"

    return result



def pct_change(start, end):
    if start is None or end is None or start == 0:
        return 0.0
    return ((end - start) / start) * 100.0


def sma(closes, period):
    if len(closes) < period:
        return None
    return sum(closes[-period:]) / period


def sma_at(closes, end_index, period):
    start_index = end_index - period + 1
    if start_index < 0:
        return None
    window = closes[start_index:end_index + 1]
    if len(window) < period:
        return None
    return sum(window) / period


def mean_value(values):
    if not values:
        return 0.0
    return sum(values) / len(values)


def std_dev_population(values):
    if not values:
        return 0.0
    mean_val = mean_value(values)
    variance = sum((x - mean_val) ** 2 for x in values) / len(values)
    return math.sqrt(variance)



def pine_30m_tehran_day_key_from_ts(ts):
    ts = ts_to_int(ts)
    if ts is None:
        return None
    try:
        # Match the bot's Tehran-oriented time model while using LBank 30m
        # Unix candle timestamps. No TradingView UI/session data is needed.
        return (datetime.utcfromtimestamp(ts) + timedelta(hours=3, minutes=30)).strftime("%Y-%m-%d")
    except Exception:
        return None


def pine_30m_scan_day_key(scan_dt=None):
    if isinstance(scan_dt, datetime):
        return scan_dt.strftime("%Y-%m-%d")
    return get_tehran_now().strftime("%Y-%m-%d")


def pine_30m_candle_price(candle, key):
    if not isinstance(candle, dict):
        return None
    return _safe_positive_float(candle.get(key))


def pine_30m_candle_volume_value(candle):
    if not isinstance(candle, dict):
        return 0.0
    volume_value = _safe_non_negative_float(candle.get("v"))
    if volume_value is None:
        volume_value = 0.0
    if bool(PINE_30M_USE_QUOTE_VOLUME):
        close_price = pine_30m_candle_price(candle, "c")
        if close_price is None:
            return 0.0
        return volume_value * close_price
    return volume_value


def pine_30m_ordered_candles(candles, live_candle=None):
    rows = []
    seen = set()
    for candle in list(candles or []):
        if not isinstance(candle, dict):
            continue
        ts = ts_to_int(candle.get("t"))
        if ts is None:
            continue
        rows.append(dict(candle))
        seen.add(ts)
    if isinstance(live_candle, dict):
        live_ts = ts_to_int(live_candle.get("t"))
        if live_ts is not None:
            live_row = dict(live_candle)
            # V21: do not replace an existing OHLC row with another row that has
            # the same timestamp.  The earlier V20 defensive same-timestamp
            # replacement is intentionally reverted because it could choose the
            # wrong row and create hard-to-debug PMA flicker.
            if live_ts not in seen:
                rows.append(live_row)
    rows.sort(key=lambda c: ts_to_int(c.get("t")) or 0)
    return rows


def pine_30m_polarity_for_candle(candle, prev_intrabar_close=None, prev_intrabar_polarity=1):
    open_price = pine_30m_candle_price(candle, "o")
    close_price = pine_30m_candle_price(candle, "c")
    if open_price is None or close_price is None:
        return int(prev_intrabar_polarity or 1)
    if close_price > open_price:
        return 1
    if close_price < open_price:
        return -1
    if prev_intrabar_close is not None:
        if close_price > prev_intrabar_close:
            return 1
        if close_price < prev_intrabar_close:
            return -1
    return int(prev_intrabar_polarity or 1)


def pine_30m_build_daily_price_buckets(candles, scan_dt=None):
    current_day_key = pine_30m_scan_day_key(scan_dt)
    buckets = {}
    for candle in list(candles or []):
        if not isinstance(candle, dict):
            continue
        day_key = pine_30m_tehran_day_key_from_ts(candle.get("t"))
        if not day_key:
            continue
        bucket = buckets.setdefault(day_key, {"candles": []})
        bucket["candles"].append(candle)
    for bucket in buckets.values():
        bucket["candles"].sort(key=lambda c: ts_to_int(c.get("t")) or 0)
        first_candle = bucket["candles"][0] if bucket["candles"] else None
        last_candle = bucket["candles"][-1] if bucket["candles"] else None
        bucket["open"] = pine_30m_candle_price(first_candle, "o")
        bucket["close"] = pine_30m_candle_price(last_candle, "c")
    closed_day_keys = sorted(day_key for day_key in buckets if day_key < current_day_key)
    return buckets, closed_day_keys


def pine_30m_simulate_cvd_rotation(candles, live_candle=None):
    # Mirrors the Pine script's state-machine order: classify/add the current
    # intrabar first, then rotate B0/S0 on a new daily boundary. This preserves
    # the Pine math exactly instead of rewriting it as a separate daily grouper.
    acc_buy = 0.0
    acc_sell = 0.0
    b_values = [0.0, 0.0, 0.0, 0.0]
    s_values = [0.0, 0.0, 0.0, 0.0]
    prev_intrabar_close = None
    prev_intrabar_polarity = 1
    prev_day_key = None

    for candle in pine_30m_ordered_candles(candles, live_candle=live_candle):
        day_key = pine_30m_tehran_day_key_from_ts(candle.get("t"))
        if not day_key:
            continue
        new_day = prev_day_key is not None and day_key != prev_day_key
        polarity = pine_30m_polarity_for_candle(
            candle,
            prev_intrabar_close=prev_intrabar_close,
            prev_intrabar_polarity=prev_intrabar_polarity,
        )
        vol_used = pine_30m_candle_volume_value(candle)
        if polarity == 1:
            acc_buy += vol_used
        else:
            acc_sell += vol_used

        close_price = pine_30m_candle_price(candle, "c")
        if close_price is not None:
            prev_intrabar_close = close_price
        prev_intrabar_polarity = polarity

        if new_day:
            b_values = [acc_buy, b_values[0], b_values[1], b_values[2]]
            s_values = [acc_sell, s_values[0], s_values[1], s_values[2]]
            acc_buy = 0.0
            acc_sell = 0.0
            prev_intrabar_close = None
            prev_intrabar_polarity = 1
        prev_day_key = day_key

    return b_values, s_values


def pine_30m_calc_gf_ratio10_df(close_price, open_price, buy_volume, sell_volume):
    eps = float(PINE_30M_EPS)
    golden = float(PINE_30M_GOLDEN)
    buy_volume = float(buy_volume or 0.0)
    sell_volume = float(sell_volume or 0.0)
    close_price = _safe_positive_float(close_price)
    open_price = _safe_positive_float(open_price)
    if close_price is None or open_price is None:
        return 0.0, 0.0, 0.0

    total = buy_volume + sell_volume
    p_buy = buy_volume / total if total > eps else 0.0
    p_sell = sell_volume / total if total > eps else 0.0

    if p_buy >= p_sell:
        weighted_close = p_buy * close_price
        weighted_open = p_sell * open_price
    else:
        weighted_close = p_sell * close_price
        weighted_open = p_buy * open_price

    gf_raw = (weighted_close / weighted_open) if weighted_open > eps else 0.0
    min_bs = max(min(buy_volume, sell_volume), eps)
    max_bs = max(buy_volume, sell_volume)
    raw_ratio = max_bs / min_bs
    try:
        ratio_cap = float(PINE_30M_RATIO_CAP)
    except Exception:
        ratio_cap = 8.0
    # v58: keep flat candles included, but cap GF itself with the same 8.0
    # imbalance cap used by ratio10/DF. This prevents one tiny minority-volume
    # daily bucket from inflating GF+ far above the real daily move.
    gf = min(gf_raw, ratio_cap) if ratio_cap > 0 else gf_raw
    ratio = min(raw_ratio, ratio_cap)
    ratio10 = ratio
    df = ratio10 * golden
    return gf, ratio10, df


def pine_30m_pma_from_series(candle_series, length=None):
    try:
        length = max(1, int(length if length is not None else PINE_30M_PMA_LENGTH))
    except Exception:
        length = 1
    pct_changes = []
    for candle in candle_series or []:
        open_price = pine_30m_candle_price(candle, "o")
        close_price = pine_30m_candle_price(candle, "c")
        if open_price is None or close_price is None:
            continue
        pct_changes.append(((close_price - open_price) / max(open_price, float(PINE_30M_EPS))) * 100.0)
    if len(pct_changes) < length:
        return None
    return sum(pct_changes[-length:]) / length




def pine_30m_pma_flat_neutral_status(candle_series, length=None):
    """Classify a computed PMA value as flat/neutral when its source candles are flat.

    V20 keeps pma_available=True and keeps the numeric PMA value, but adds an
    explicit neutral flag so a 0.000000 PMA from a flat/stale OHLC row cannot be
    treated as a real bearish live-PMA sell signal. Flat still means flat: it is
    not positive and not negative.
    """
    try:
        length = max(1, int(length if length is not None else PINE_30M_PMA_LENGTH))
    except Exception:
        length = 1
    try:
        threshold = abs(float(globals().get("PINE_30M_PMA_FLAT_NEUTRAL_THRESHOLD_PCT", 0.01)))
    except Exception:
        threshold = 0.01
    enabled = bool(globals().get("PINE_30M_PMA_MARK_FLAT_NEUTRAL", True))
    rows = [c for c in list(candle_series or []) if isinstance(c, dict)]
    rows = rows[-length:] if length > 0 else rows
    sample_changes = []
    candle_ts = []
    for candle in rows:
        open_price = pine_30m_candle_price(candle, "o")
        close_price = pine_30m_candle_price(candle, "c")
        if open_price is None or close_price is None:
            continue
        change = ((close_price - open_price) / max(open_price, float(PINE_30M_EPS))) * 100.0
        sample_changes.append(change)
        candle_ts.append(ts_to_int(candle.get("t")))
    pma_value = sum(sample_changes[-length:]) / length if len(sample_changes) >= length else None
    flat_samples = [value for value in sample_changes[-length:] if abs(value) <= threshold]
    flat_neutral = bool(enabled and pma_value is not None and len(sample_changes) >= length and abs(pma_value) <= threshold and len(flat_samples) == length)
    return {
        "enabled": enabled,
        "flat_neutral": flat_neutral,
        "threshold_pct": threshold,
        "pma": pma_value,
        "sample_changes_pct": sample_changes[-length:],
        "sample_count": len(sample_changes[-length:]),
        "required_length": length,
        "candle_ts": candle_ts[-length:],
        "reason": "flat_neutral_pma" if flat_neutral else "not_flat_neutral",
    }


def pine_30m_pma_guard_add():
    try:
        return float(PINE_30M_PMA_GUARD_ADD)
    except Exception:
        return 0.0


def pine_30m_required_pma_guard_line():
    try:
        middle = float(PINE_30M_MIDDLE_LINE)
    except Exception:
        middle = 0.0
    return middle + pine_30m_pma_guard_add()


def pine_30m_confirm_guard_line_from_status(status):
    mode = str(globals().get("PINE_30M_CONFIRM_GUARD_LINE_MODE", "middle_plus_add") or "middle_plus_add").strip().lower()
    if mode in {"predict_upper", "upper_predict", "predict"}:
        try:
            value = float((status or {}).get("predict_upper"))
            if math.isfinite(value):
                return value, "predict_upper"
        except Exception:
            return None, "predict_upper"
    return pine_30m_required_pma_guard_line(), "middle_plus_add"


def pine_30m_pma_is_above_guard_line(pma, required_line):
    try:
        pma_value = float(pma)
        line_value = float(required_line)
    except Exception:
        return False
    if not math.isfinite(pma_value) or not math.isfinite(line_value):
        return False
    return pma_value > line_value


def resolve_pine_30m_source_candles(candidate=None, fallback_candles=None):
    """Return the full OHLCV candle history for the Pine daily system.

    Strategy calculations intentionally keep using their trimmed 144-candle
    window. The Pine daily B/S/GF/Vibration system needs more history, so it
    reads the full prefetched OHLCV list saved on the candidate before trimming.
    """
    if isinstance(candidate, dict):
        source_candles = candidate.get("pine_30m_source_candles")
        if isinstance(source_candles, list) and source_candles:
            return source_candles
    return fallback_candles


def compute_pine_30m_system_status(candles, live_candle=None, scan_dt=None):
    status = {
        "available": False,
        "reason": None,
        "pma": None,
        "pma_available": False,
        "pma_flat_neutral": False,
        "pma_flat_neutral_reason": None,
        "pma_flat_neutral_threshold_pct": None,
        "pma_sample_changes_pct": [],
        "prev_pma": None,
        "prev_pma_flat_neutral": False,
        "prev_pma_candle_open": None,
        "prev_pma_candle_close": None,
        "prev_pma_candle_body_pct": None,
        "prev_pma_candle_flat_body": False,
        "prev_pma_candle_flat_body_threshold_pct": None,
        "prev_prev_pma": None,
        "scan_ts": None,
        "current_slot_ts": None,
        "live_candle_ts": None,
        "live_candle_current_slot_ok": False,
        "live_candle_missing_current_slot": False,
        "live_candle_stale_for_scan": False,
        "live_candle_future_for_scan": False,
        "pma_series_last_ts": None,
        "pma_series_last_ts_matches_current_slot": False,
        "middle_line": float(PINE_30M_MIDDLE_LINE),
        "pma_guard_add": pine_30m_pma_guard_add(),
        "pma_guard_line_mode": str(globals().get("PINE_30M_CONFIRM_GUARD_LINE_MODE", "middle_plus_add") or "middle_plus_add"),
        "pma_guard_line_source": None,
        "pma_required_line": None,
        "pma_above_required_line": False,
        "pma_below_middle": False,
        "pma_below_required_line": False,
        "guard_enabled": bool(ENABLE_PINE_30M_CONFIRM_GUARD),
        "guard_blocked": False,
        "use_quote_volume": bool(PINE_30M_USE_QUOTE_VOLUME),
        "pma_length": int(PINE_30M_PMA_LENGTH),
        "ratio_cap": float(PINE_30M_RATIO_CAP),
        "vibration_mult": float(PINE_30M_VIBRATION_MULT),
    }

    ordered_closed = pine_30m_ordered_candles(candles)
    status["source_closed_candle_count"] = len(ordered_closed)
    if not ordered_closed:
        status["reason"] = "no closed 30m candles available"
        status["guard_blocked"] = bool(status.get("guard_enabled"))
        status["pma_below_required_line"] = True
        return status

    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    try:
        timeframe_seconds = int(globals().get("PINE_30M_TIMEFRAME_SECONDS", 30 * 60) or (30 * 60))
    except Exception:
        timeframe_seconds = 30 * 60
    current_slot_ts = None
    if scan_ts is not None and timeframe_seconds > 0:
        try:
            current_slot_ts = (int(scan_ts) // int(timeframe_seconds)) * int(timeframe_seconds)
        except Exception:
            current_slot_ts = None
    live_candle_ts = ts_to_int((live_candle or {}).get("t")) if isinstance(live_candle, dict) else None
    live_current_slot_ok = bool(live_candle_ts is not None and current_slot_ts is not None and live_candle_ts == current_slot_ts)
    live_missing_current_slot = bool(current_slot_ts is not None and (live_candle_ts is None or live_candle_ts < current_slot_ts))
    live_stale_for_scan = bool(live_candle_ts is not None and current_slot_ts is not None and live_candle_ts < current_slot_ts)
    live_future_for_scan = bool(live_candle_ts is not None and current_slot_ts is not None and live_candle_ts > current_slot_ts)
    status["scan_ts"] = scan_ts
    status["current_slot_ts"] = current_slot_ts
    status["live_candle_ts"] = live_candle_ts
    status["live_candle_current_slot_ok"] = live_current_slot_ok
    status["live_candle_missing_current_slot"] = live_missing_current_slot
    status["live_candle_stale_for_scan"] = live_stale_for_scan
    status["live_candle_future_for_scan"] = live_future_for_scan

    current_series = pine_30m_ordered_candles(candles, live_candle=live_candle)
    status["pma_series_last_ts"] = ts_to_int((current_series[-1] or {}).get("t")) if current_series else None
    status["pma_series_last_ts_matches_current_slot"] = bool(status.get("pma_series_last_ts") is not None and current_slot_ts is not None and status.get("pma_series_last_ts") == current_slot_ts)
    status["pma"] = pine_30m_pma_from_series(current_series, length=PINE_30M_PMA_LENGTH)
    status["prev_pma"] = pine_30m_pma_from_series(ordered_closed, length=PINE_30M_PMA_LENGTH)
    status["prev_prev_pma"] = pine_30m_pma_from_series(ordered_closed[:-1], length=PINE_30M_PMA_LENGTH) if len(ordered_closed) > 1 else None
    pma_flat_status = pine_30m_pma_flat_neutral_status(current_series, length=PINE_30M_PMA_LENGTH)
    prev_pma_flat_status = pine_30m_pma_flat_neutral_status(ordered_closed, length=PINE_30M_PMA_LENGTH)
    status["pma_flat_neutral"] = bool(pma_flat_status.get("flat_neutral"))
    status["pma_flat_neutral_reason"] = pma_flat_status.get("reason")
    status["pma_flat_neutral_threshold_pct"] = pma_flat_status.get("threshold_pct")
    status["pma_sample_changes_pct"] = pma_flat_status.get("sample_changes_pct")
    status["pma_flat_neutral_status"] = pma_flat_status
    status["prev_pma_flat_neutral"] = bool(prev_pma_flat_status.get("flat_neutral"))
    status["prev_pma_flat_neutral_status"] = prev_pma_flat_status
    latest_closed_pma_candle = ordered_closed[-1] if ordered_closed else None
    prev_prev_pma_candle = ordered_closed[-2] if len(ordered_closed) > 1 else None
    try:
        _prev_pma_candle_flat_threshold = abs(float(globals().get("PMA_GF_PLUS_FORCE_BUY_LATEST_CLOSED_FLAT_CANDLE_THRESHOLD_PCT", 0.01)))
    except Exception:
        _prev_pma_candle_flat_threshold = 0.01
    status["prev_pma_candle_flat_body_threshold_pct"] = _prev_pma_candle_flat_threshold
    if isinstance(latest_closed_pma_candle, dict):
        _prev_pma_candle_open = pine_30m_candle_price(latest_closed_pma_candle, "o")
        _prev_pma_candle_close = pine_30m_candle_price(latest_closed_pma_candle, "c")
        status["prev_pma_candle_open"] = _prev_pma_candle_open
        status["prev_pma_candle_close"] = _prev_pma_candle_close
        if _prev_pma_candle_open is not None and _prev_pma_candle_close is not None and _prev_pma_candle_open > 0:
            _prev_pma_candle_body_pct = pct_change(_prev_pma_candle_open, _prev_pma_candle_close)
            status["prev_pma_candle_body_pct"] = _prev_pma_candle_body_pct
            status["prev_pma_candle_flat_body"] = bool(abs(_prev_pma_candle_body_pct) <= _prev_pma_candle_flat_threshold)
    status["prev_pma_candle_ts"] = ts_to_int((latest_closed_pma_candle or {}).get("t")) if isinstance(latest_closed_pma_candle, dict) else None
    status["prev_pma_candle_close_ts"] = (status["prev_pma_candle_ts"] + int(PINE_30M_TIMEFRAME_SECONDS)) if status.get("prev_pma_candle_ts") is not None else None
    status["prev_prev_pma_candle_ts"] = ts_to_int((prev_prev_pma_candle or {}).get("t")) if isinstance(prev_prev_pma_candle, dict) else None
    status["prev_prev_pma_candle_close_ts"] = (status["prev_prev_pma_candle_ts"] + int(PINE_30M_TIMEFRAME_SECONDS)) if status.get("prev_prev_pma_candle_ts") is not None else None
    status["pma_available"] = status["pma"] is not None
    if status["pma"] is not None:
        middle_line = float(status.get("middle_line") if status.get("middle_line") is not None else PINE_30M_MIDDLE_LINE)
        status["pma_below_middle"] = status["pma"] < middle_line
    else:
        status["reason"] = "no Pine 30m PMA data available"
        status["pma_below_required_line"] = True
        status["guard_blocked"] = bool(status.get("guard_enabled"))

    buckets, closed_day_keys = pine_30m_build_daily_price_buckets(ordered_closed, scan_dt=scan_dt)
    required_days = max(1, int(PINE_30M_REQUIRED_CLOSED_DAYS))
    status["closed_day_count"] = len(closed_day_keys)
    status["required_closed_day_count"] = required_days
    if len(closed_day_keys) < required_days:
        status["reason"] = f"need {required_days} closed 30m daily buckets for full Pine daily system; got {len(closed_day_keys)}"
        status["pma_below_required_line"] = True
        status["guard_blocked"] = bool(status.get("guard_enabled"))
        return status

    selected_day_keys = list(reversed(closed_day_keys[-required_days:]))
    b_values, s_values = pine_30m_simulate_cvd_rotation(ordered_closed, live_candle=live_candle)

    gf_values = []
    ratio_values = []
    df_values = []
    day_payloads = []

    for idx, day_key in enumerate(selected_day_keys):
        bucket = buckets.get(day_key) or {}
        buy_volume = b_values[idx] if idx < len(b_values) else 0.0
        sell_volume = s_values[idx] if idx < len(s_values) else 0.0
        gf, ratio10, df = pine_30m_calc_gf_ratio10_df(
            bucket.get("close"),
            bucket.get("open"),
            buy_volume,
            sell_volume,
        )
        gf_values.append(gf)
        ratio_values.append(ratio10)
        df_values.append(df)
        day_payloads.append({
            "day_key": day_key,
            "open": bucket.get("open"),
            "close": bucket.get("close"),
            "buy": buy_volume,
            "sell": sell_volume,
            "gf": gf,
            "ratio10": ratio10,
            "df": df,
        })

    gf_sum = (((gf_values[0] + gf_values[1] + gf_values[2]) / 6.0) * 3.69) if len(gf_values) >= 3 else 0.0
    delta_sum = (((ratio_values[0] + ratio_values[1] + ratio_values[2]) / 6.0) * float(PINE_30M_GOLDEN)) if len(ratio_values) >= 3 else 0.0
    vibration_raw = ((gf_sum / delta_sum) / float(PINE_30M_GOLDEN)) if delta_sum > float(PINE_30M_EPS) else 0.0
    vibration = vibration_raw * float(PINE_30M_VIBRATION_MULT)

    status.update({
        "available": True,
        "reason": None,
        "days": day_payloads,
        "selected_day_keys": selected_day_keys,
        "B0": b_values[0],
        "S0": s_values[0],
        "B1": b_values[1],
        "S1": s_values[1],
        "B2": b_values[2],
        "S2": s_values[2],
        "B3": b_values[3],
        "S3": s_values[3],
        "GF0": gf_values[0],
        "GF1": gf_values[1],
        "GF2": gf_values[2],
        "GF3": gf_values[3] if len(gf_values) > 3 else None,
        "ratio10_0": ratio_values[0],
        "ratio10_1": ratio_values[1],
        "ratio10_2": ratio_values[2],
        "ratio10_3": ratio_values[3] if len(ratio_values) > 3 else None,
        "DF0": df_values[0],
        "DF1": df_values[1],
        "DF2": df_values[2],
        "DF3": df_values[3] if len(df_values) > 3 else None,
        "GF_sum": gf_sum,
        "Delta_sum": delta_sum,
        "vibration_raw": vibration_raw,
        "vibration": vibration,
        "vib_pos": vibration,
        "vib_neg": -vibration,
        "GF_pos": gf_sum,
        "GF_neg": -gf_sum,
        "predict_upper": delta_sum,
        "predict_lower": -delta_sum,
    })
    required_line, required_source = pine_30m_confirm_guard_line_from_status(status)
    status["pma_required_line"] = required_line
    status["pma_guard_line_source"] = required_source
    status["live_pma_above_required_line"] = False
    status["latest_closed_pma_above_required_line"] = False
    status["pma_guard_eval_pma"] = None
    status["pma_guard_eval_source"] = None
    if required_line is not None:
        status["live_pma_above_required_line"] = pine_30m_pma_is_above_guard_line(status.get("pma"), required_line)
        status["latest_closed_pma_above_required_line"] = pine_30m_pma_is_above_guard_line(status.get("prev_pma"), required_line)

    # V3/V5: Predict Upper is a closed-candle confirmation guard. A live PMA
    # cross still appears in debug fields, but normal confirmations must wait
    # until the latest CLOSED PMA is above Predict Upper. The PMA/GF+ force-BUY
    # rule is the only bypass for this closed-Predict-Upper requirement.
    eval_pma = status.get("pma")
    eval_source = "live_pma"
    if str(required_source or "").strip().lower() == "predict_upper":
        eval_pma = status.get("prev_pma")
        eval_source = "latest_closed_pma"
    status["pma_guard_eval_pma"] = eval_pma
    status["pma_guard_eval_source"] = eval_source

    if eval_pma is not None and required_line is not None:
        status["pma_above_required_line"] = pine_30m_pma_is_above_guard_line(eval_pma, required_line)
        status["pma_below_required_line"] = not bool(status["pma_above_required_line"])
        status["guard_blocked"] = bool(status.get("guard_enabled") and status["pma_below_required_line"])
    else:
        status["pma_above_required_line"] = False
        status["pma_below_required_line"] = True
        status["guard_blocked"] = bool(status.get("guard_enabled"))

    prev_prev_pma_for_df0 = _safe_finite_float(status.get("prev_prev_pma"))
    latest_closed_pma_for_df0 = _safe_finite_float(status.get("prev_pma"))
    df0_for_downcross = _safe_finite_float(status.get("DF0"))
    closed_pma_was_above_df0 = bool(
        prev_prev_pma_for_df0 is not None and
        df0_for_downcross is not None and
        (prev_prev_pma_for_df0 > df0_for_downcross if bool(PINE_30M_DF0_FORCE_SELL_STRICT_ABOVE) else prev_prev_pma_for_df0 >= df0_for_downcross)
    )
    closed_pma_now_below_df0 = bool(
        latest_closed_pma_for_df0 is not None and
        df0_for_downcross is not None and
        (latest_closed_pma_for_df0 < df0_for_downcross if bool(PINE_30M_DF0_FORCE_SELL_STRICT_BELOW) else latest_closed_pma_for_df0 <= df0_for_downcross)
    )
    closed_pma_df0_downcross = bool(closed_pma_was_above_df0 and closed_pma_now_below_df0)
    pma_df0_downcross_buy_blocked = bool(
        BLOCK_BUY_AFTER_CLOSED_PMA_DF0_DOWNCROSS_UNTIL_PREDICT_UPPER and
        (not bool(globals().get("ONLY_ALLOW_PMA_GF_PLUS_FORCE_BUYS", False))) and
        closed_pma_df0_downcross and
        not bool(status.get("pma_above_required_line"))
    )
    status["prev_closed_pma_above_DF0"] = closed_pma_was_above_df0
    status["latest_closed_pma_below_DF0"] = closed_pma_now_below_df0
    status["closed_pma_DF0_downcross"] = closed_pma_df0_downcross
    status["pma_df0_downcross_buy_blocked"] = pma_df0_downcross_buy_blocked
    status["pma_df0_downcross_buy_block_reason"] = (
        f"buy blocked: latest CLOSED Pine 30m PMA crossed below DF0 "
        f"(previous closed PMA {prev_prev_pma_for_df0:.6f} > DF0 {df0_for_downcross:.6f}; "
        f"latest closed PMA {latest_closed_pma_for_df0:.6f} < DF0 {df0_for_downcross:.6f}) "
        f"and live PMA is not above Predict Upper {float(status.get('pma_required_line')):.6f}"
        if pma_df0_downcross_buy_blocked and status.get("pma_required_line") is not None
        else None
    )
    if pma_df0_downcross_buy_blocked:
        status["guard_blocked"] = True
        if status.get("reason") is None:
            status["reason"] = status.get("pma_df0_downcross_buy_block_reason")

    pma = status.get("pma")
    prev_pma = status.get("prev_pma")
    if pma is not None and prev_pma is not None:
        status["long_signal"] = prev_pma <= vibration and pma > vibration
        status["short_signal"] = prev_pma >= -vibration and pma < -vibration
    else:
        status["long_signal"] = False
        status["short_signal"] = False
    return status


