def pine_30m_guard_note(prefix, pine_status):
    pma = pine_status.get("pma") if isinstance(pine_status, dict) else None
    middle = pine_status.get("middle_line") if isinstance(pine_status, dict) else PINE_30M_MIDDLE_LINE
    guard_add = pine_status.get("pma_guard_add") if isinstance(pine_status, dict) else PINE_30M_PMA_GUARD_ADD
    required_line = pine_status.get("pma_required_line") if isinstance(pine_status, dict) else pine_30m_required_pma_guard_line()
    source = str((pine_status or {}).get("pma_guard_line_source") or (pine_status or {}).get("pma_guard_line_mode") or "middle_plus_add") if isinstance(pine_status, dict) else "middle_plus_add"
    if isinstance(pine_status, dict) and bool(pine_status.get("pma_df0_downcross_buy_blocked")):
        return str(pine_status.get("pma_df0_downcross_buy_block_reason") or "buy blocked: latest CLOSED Pine 30m PMA crossed below DF0 and live PMA is not above Predict Upper")
    if pma is None:
        reason = pine_status.get("reason") if isinstance(pine_status, dict) else None
        if reason:
            return f"{prefix} confirmation scan ignored by Pine 30m PMA guard: {reason}"
        return f"{prefix} confirmation scan ignored by Pine 30m PMA guard: no PMA data available"
    if required_line is None:
        reason = pine_status.get("reason") if isinstance(pine_status, dict) else None
        if reason:
            return f"{prefix} confirmation scan ignored by Pine 30m PMA guard: {reason}"
        return f"{prefix} confirmation scan ignored by Pine 30m PMA guard: required guard line unavailable"
    if source == "predict_upper":
        return (
            f"{prefix} confirmation scan ignored because Pine 30m PMA={pma:.6f} is not above "
            f"Predict Upper {float(required_line):.6f}"
        )
    return (
        f"{prefix} confirmation scan ignored because Pine 30m PMA={pma:.6f} is not above "
        f"required line {float(required_line):.6f} "
        f"(middle {float(middle):.6f} + guard {float(guard_add):.6f})"
    )


def compute_4h_change_pct_from_240m_ohlc(ohlc_4h, now_ts=None):
    """
    Compute the official last closed 4h candle percent from LBank hour4 OHLC.

    This uses the raw 240m candle open and close returned by LBank. It does
    not rebuild a rolling 4h value from 30m closes.
    """
    if not isinstance(ohlc_4h, dict):
        return 0.0

    if now_ts is None:
        now_ts = int(time.time())
    else:
        now_ts = _safe_int_timestamp(now_ts) or int(time.time())

    timeframe_seconds = 4 * 60 * 60
    t_values = ohlc_4h.get("t") or []
    o_values = ohlc_4h.get("o") or []
    c_values = ohlc_4h.get("c") or []

    latest_closed = None

    for idx, raw_ts in enumerate(t_values):
        candle_start = _safe_int_timestamp(raw_ts)
        if candle_start is None:
            continue

        candle_end = candle_start + timeframe_seconds
        if candle_end > now_ts:
            continue

        try:
            open_price = float(o_values[idx])
            close_price = float(c_values[idx])
        except Exception:
            continue

        if open_price <= 0 or close_price <= 0:
            continue

        if latest_closed is None or candle_start > latest_closed[0]:
            latest_closed = (candle_start, open_price, close_price)

    if latest_closed is None:
        return 0.0

    _, open_price, close_price = latest_closed
    return pct_change(open_price, close_price)


def compute_pump_metrics(candles, change_pct, pct_4h):
    min_needed_30m = CANDLE_30M_PREV_FOR_AVG + 1
    closes = [c.get("c") for c in candles if c.get("c") is not None]

    if len(closes) < min_needed_30m:
        return {
            "last_30m_pct": 0.0,
            "avg_prev_30m_pct": 0.0,
            "last_vs_avg_pct": 0.0,
            "z_score": 0.0,
            "4h_pct": pct_4h or 0.0,
            "is_pump": False,
            "recent_pump_diff_pct": -9999.0,
            "is_recent_pump": False,
        }

    prev_closes = closes[-min_needed_30m:-1]
    last_close = closes[-1]

    avg_prev = sum(prev_closes) / len(prev_closes) if prev_closes else last_close
    last_vs_avg_pct = pct_change(avg_prev, last_close)

    if len(prev_closes) > 1:
        try:
            stdev_prev = statistics.stdev(prev_closes)
        except statistics.StatisticsError:
            stdev_prev = 0.0
    else:
        stdev_prev = 0.0

    if stdev_prev > 0:
        z_score = (last_close - avg_prev) / stdev_prev
    else:
        z_score = 99.0 if last_close > avg_prev else 0.0

    pct_4h = pct_4h or 0.0

    if pct_4h == 0.0:
        is_pump = (last_vs_avg_pct >= PUMP_ALT_30M_PCT) and (z_score >= MIN_Z_SCORE)
    else:
        is_pump = (
            last_vs_avg_pct >= PUMP_MIN_30M_LAST_VS_AVG_PCT and
            pct_4h >= PUMP_MIN_4H_PCT and
            z_score >= MIN_Z_SCORE
        )

    recent_pump_diff_pct = abs(change_pct - last_vs_avg_pct)

    is_recent_pump = (
        last_vs_avg_pct >= RECENT_PUMP_DIFF_PCT and
        change_pct > 0 and
        recent_pump_diff_pct >= RECENT_PUMP_DIFF_PCT
    )

    last_30m_pct = pct_change(prev_closes[-1], last_close) if prev_closes else 0.0
    avg_prev_30m_pct = mean_value([pct_change(prev_closes[idx - 1], prev_closes[idx]) for idx in range(1, len(prev_closes))]) if len(prev_closes) >= 2 else 0.0

    return {
        "last_30m_pct": last_30m_pct,
        "avg_prev_30m_pct": avg_prev_30m_pct,
        "last_vs_avg_pct": last_vs_avg_pct,
        "z_score": z_score,
        "4h_pct": pct_4h,
        "is_pump": is_pump,
        "recent_pump_diff_pct": recent_pump_diff_pct,
        "is_recent_pump": is_recent_pump,
    }


def compute_recent_window_rise_pct(candles, window_hours=WATCH_RECENT_PUMP_WINDOW_HOURS, recent_hours=WATCH_RECENT_PUMP_LOOKBACK_HOURS):
    window_candles = max(1, int((window_hours * 60) / 30))
    recent_candles = max(window_candles + 1, int((recent_hours * 60) / 30))

    if len(candles) < window_candles + 1:
        return {
            "blocked": False,
            "max_rise_pct": None,
            "from_ts": None,
            "to_ts": None,
        }

    start_end_idx = max(window_candles, len(candles) - recent_candles)
    max_rise_pct = None
    max_from_ts = None
    max_to_ts = None

    for end_idx in range(start_end_idx, len(candles)):
        start_idx = end_idx - window_candles
        rise_pct = pct_change(candles[start_idx]["c"], candles[end_idx]["c"])
        if max_rise_pct is None or rise_pct > max_rise_pct:
            max_rise_pct = rise_pct
            max_from_ts = candles[start_idx]["t"]
            max_to_ts = candles[end_idx]["t"]

    return {
        "blocked": bool(max_rise_pct is not None and max_rise_pct > WATCH_RECENT_PUMP_THRESHOLD_PCT),
        "max_rise_pct": max_rise_pct,
        "from_ts": max_from_ts,
        "to_ts": max_to_ts,
    }


def recent_pump_block_note(stage_name):
    stage_label = str(stage_name or "signal").replace("_", " ")
    return (
        f"{stage_label} blocked: recent {WATCH_RECENT_PUMP_WINDOW_HOURS}h rise inside last "
        f"{WATCH_RECENT_PUMP_LOOKBACK_HOURS}h exceeded {WATCH_RECENT_PUMP_THRESHOLD_PCT:.2f}%"
    )


def enrich_candles_with_mas(candles):
    closes = [x["c"] for x in candles]
    enriched = []
    for idx, candle in enumerate(candles):
        row = dict(candle)
        row["idx"] = idx
        row["is_green"] = row["c"] > row["o"]
        row["body_bottom"] = min(row["o"], row["c"])
        row["body_top"] = max(row["o"], row["c"])
        row["sma3"] = sma_at(closes, idx, 3)
        row["sma7"] = sma_at(closes, idx, 7)
        row["sma18"] = sma_at(closes, idx, 18)
        row["gap_close_3_pct"] = pct_change(row["sma3"], row["c"]) if row["sma3"] else None
        row["gap_3_7_pct"] = pct_change(row["sma7"], row["sma3"]) if row["sma7"] else None
        row["gap_7_18_pct"] = pct_change(row["sma18"], row["sma7"]) if row["sma18"] else None
        row["body_bottom_to_3_pct"] = pct_change(row["sma3"], row["body_bottom"]) if row["sma3"] else None
        row["body_bottom_to_7_pct"] = pct_change(row["sma7"], row["body_bottom"]) if row["sma7"] else None
        row["body_bottom_to_18_pct"] = pct_change(row["sma18"], row["body_bottom"]) if row["sma18"] else None
        enriched.append(row)
    return enriched


def candle_touches_ma(candle, ma_value, tolerance_pct=MA_TOUCH_TOLERANCE_PCT):
    if candle is None or ma_value is None or ma_value <= 0:
        return False

    if candle["l"] <= ma_value <= candle["h"]:
        return True

    close_gap = abs(pct_change(ma_value, candle["c"]))
    open_gap = abs(pct_change(ma_value, candle["o"]))
    low_gap = abs(pct_change(ma_value, candle["l"]))
    high_gap = abs(pct_change(ma_value, candle["h"]))

    return min(close_gap, open_gap, low_gap, high_gap) <= tolerance_pct


def format_body_sit_tolerance_label(tolerance_pct, both_sides=True):
    if both_sides:
        return f"±{tolerance_pct:.3f}%"
    return f"+{tolerance_pct:.3f}% above MA only"


def candle_body_bottom_sets_on_ma(candle, ma_value, tolerance_pct=BODY_SIT_TOLERANCE_PCT, both_sides=BODY_SIT_TOLERANCE_BOTH_SIDES):
    if candle is None or ma_value is None or ma_value <= 0:
        return False

    body_bottom = candle.get("body_bottom")
    if body_bottom is None:
        body_bottom = min(candle["o"], candle["c"])

    distance_pct = pct_change(ma_value, body_bottom)
    if distance_pct is None:
        return False

    if both_sides:
        return abs(distance_pct) <= tolerance_pct

    return 0 <= distance_pct <= tolerance_pct


def sma3_vs_sma7_threshold_ok(gap_3_7_pct, min_pct):
    return gap_3_7_pct is not None and gap_3_7_pct >= min_pct


def format_sma3_sma7_threshold_label(min_pct):
    try:
        min_pct = float(min_pct)
    except Exception:
        return "SMA3/SMA7 threshold unavailable"

    if min_pct >= 0:
        return f"SMA3 >= SMA7 by at least {min_pct:.3f}%"

    return f"SMA3 >= SMA7 or within {abs(min_pct):.3f}% below SMA7"


def is_watch_candle(candle, tolerance_pct=WATCH_BODY_SIT_TOLERANCE_PCT, both_sides=WATCH_BODY_SIT_TOLERANCE_BOTH_SIDES):
    if candle is None:
        return False

    return (
        candle["is_green"] and
        candle_body_bottom_sets_on_ma(candle, candle.get("sma18"), tolerance_pct=tolerance_pct, both_sides=both_sides) and
        candle.get("sma3") is not None and candle.get("sma7") is not None and candle.get("sma18") is not None and
        candle["sma7"] > candle["sma18"] and
        sma3_vs_sma7_threshold_ok(candle.get("gap_3_7_pct"), WATCH_SMA3_SMA7_MIN_PCT) and
        (candle.get("gap_7_18_pct") is not None and candle["gap_7_18_pct"] >= WATCH_MIN_7_OVER_18_PCT)
    )


def is_possible_buy_candle(candle, tolerance_pct=POSSIBLE_BUY_BODY_SIT_TOLERANCE_PCT, both_sides=POSSIBLE_BUY_BODY_SIT_TOLERANCE_BOTH_SIDES):
    if candle is None:
        return False

    return (
        candle["is_green"] and
        candle_body_bottom_sets_on_ma(candle, candle.get("sma7"), tolerance_pct=tolerance_pct, both_sides=both_sides) and
        candle.get("sma3") is not None and candle.get("sma7") is not None and candle.get("sma18") is not None and
        candle["sma7"] > candle["sma18"] and
        sma3_vs_sma7_threshold_ok(candle.get("gap_3_7_pct"), SMA3_SMA7_MIN_PCT) and
        (candle.get("gap_7_18_pct") is not None and candle["gap_7_18_pct"] >= RULE2_MIN_7_OVER_18_PCT)
    )


def is_non_flat_candle(candle, flat_change_pct=BUY_WINDOW_FLAT_CHANGE_PCT):
    if not isinstance(candle, dict):
        return False

    try:
        open_price = float(candle.get("o"))
        close_price = float(candle.get("c"))
    except Exception:
        return False

    if open_price <= 0:
        return False

    return abs(pct_change(open_price, close_price)) > float(flat_change_pct)



def candle_is_above_sma7(candle):
    if not isinstance(candle, dict):
        return False

    return (
        candle.get("sma7") is not None and
        candle.get("body_bottom") is not None and
        candle["body_bottom"] >= candle["sma7"]
    )


def last_n_candles_all_above_sma7(candles, end_idx, count):
    if not candles:
        return False

    try:
        end_idx = int(end_idx)
        count = max(1, int(count))
    except Exception:
        return False

    start_idx = end_idx - count + 1
    if start_idx < 0 or end_idx >= len(candles):
        return False

    return all(candle_is_above_sma7(candle) for candle in candles[start_idx:end_idx + 1])


def closed_candles_and_live_above_sma7(candles, end_idx, closed_count, live_candle):
    if not candles or not candle_is_above_sma7(live_candle):
        return False

    try:
        end_idx = int(end_idx)
        closed_count = max(1, int(closed_count))
    except Exception:
        return False

    start_idx = end_idx - closed_count + 1
    if start_idx < 0 or end_idx >= len(candles):
        return False

    return all(candle_is_above_sma7(candle) for candle in candles[start_idx:end_idx + 1])


def candle_body_reference(candle):
    if not isinstance(candle, dict):
        return None

    body_top = candle.get("body_top")
    body_bottom = candle.get("body_bottom")
    if body_top is None or body_bottom is None:
        try:
            open_price = float(candle.get("o"))
            close_price = float(candle.get("c"))
        except Exception:
            return None
        body_top = max(open_price, close_price)
        body_bottom = min(open_price, close_price)

    if bool(candle.get("is_green")):
        return float(body_top)
    if bool(candle.get("is_red")):
        return float(body_bottom)
    return None


def current_candle_age_minutes(current_forming_candle, scan_dt=None):
    current_ts = ts_to_int((current_forming_candle or {}).get("t"))
    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if current_ts is None or scan_ts is None or scan_ts < current_ts:
        return None
    return max(0.0, (scan_ts - current_ts) / 60.0)


def is_live_candle_in_last_minutes(current_forming_candle, scan_dt=None, last_minutes=7, candle_minutes=30):
    age_minutes = current_candle_age_minutes(current_forming_candle, scan_dt=scan_dt)
    if age_minutes is None:
        return False

    try:
        last_minutes = max(0.0, float(last_minutes))
    except Exception:
        last_minutes = 0.0

    try:
        candle_minutes = max(0.0, float(candle_minutes))
    except Exception:
        candle_minutes = 30.0

    return age_minutes >= max(0.0, candle_minutes - last_minutes)


def breakout_early_confirm_threshold_price(live_breakout_threshold):
    breakout_threshold = _safe_positive_float(live_breakout_threshold)
    if breakout_threshold is None:
        return None
    return breakout_threshold * (1.0 + (BUY_BREAKOUT_EARLY_CONFIRM_EXTRA_PCT / 100.0))


def evaluate_exact_two_hour_buy_window(candles, live_candle=None, flat_change_pct=BUY_WINDOW_FLAT_CHANGE_PCT):
    window_candles = BUY_WINDOW_EXACT_CANDLES
    result = {
        "matched": False,
        "window_hours": BUY_WINDOW_EXACT_HOURS,
        "window_candles": window_candles,
        "green_count": 0,
        "not_flat_count": 0,
        "all_above_sma7": False,
        "latest_sma3_above_sma7": False,
        "latest_gap_7_18_ok": False,
        "has_placeholder": False,
        "window": [],
    }

    if not candles or len(candles) < window_candles:
        return result

    window = list(candles[-window_candles:])
    result["window"] = window
    result["has_placeholder"] = any(bool(candle.get("is_placeholder")) for candle in window)
    result["green_count"] = sum(1 for candle in window if bool(candle.get("is_green")))
    result["not_flat_count"] = sum(1 for candle in window if is_non_flat_candle(candle, flat_change_pct=flat_change_pct))
    result["all_above_sma7"] = closed_candles_and_live_above_sma7(
        window,
        len(window) - 1,
        BUY_WINDOW_ABOVE_SMA7_REQUIRED_CLOSED_CANDLES,
        live_candle,
    )

    latest = window[-1]
    # V2: stack/gap guards are intentionally disabled for this path; the live
    # candle SMA18/SMA3 gate handles the current 18-SMA requirement.
    result["latest_sma3_above_sma7"] = True
    result["latest_gap_7_18_ok"] = True

    result["matched"] = (
        not result["has_placeholder"] and
        result["latest_sma3_above_sma7"] and
        result["latest_gap_7_18_ok"] and
        result["green_count"] >= BUY_WINDOW_MIN_GREEN_COUNT and
        result["not_flat_count"] >= BUY_WINDOW_MIN_NOT_FLAT_COUNT and
        result["all_above_sma7"]
    )
    return result



def find_latest_possible_buy_candle(candles, start_idx=0, live_candle=None):
    if not candles:
        return None

    found = None
    start_idx = max(0, int(start_idx or 0))
    for idx in range(start_idx, len(candles)):
        candle = candles[idx]
        if (
            is_possible_buy_candle(
                candle,
                tolerance_pct=POSSIBLE_BUY_BODY_SIT_TOLERANCE_PCT,
                both_sides=POSSIBLE_BUY_BODY_SIT_TOLERANCE_BOTH_SIDES,
            )
            and closed_candles_and_live_above_sma7(
                candles,
                idx,
                POSSIBLE_BUY_ABOVE_SMA7_REQUIRED_CLOSED_CANDLES,
                live_candle,
            )
        ):
            found = candle
    return found


def find_latest_watch_candle(candles, start_idx=0):
    if not candles:
        return None

    found = None
    start_idx = max(0, int(start_idx or 0))
    for candle in candles[start_idx:]:
        if is_watch_candle(candle, tolerance_pct=WATCH_BODY_SIT_TOLERANCE_PCT, both_sides=WATCH_BODY_SIT_TOLERANCE_BOTH_SIDES):
            found = candle
    return found


def find_candle_index_by_ts(candles, ts_value):
    for idx, candle in enumerate(candles):
        if candle["t"] == ts_value:
            return idx
    return None


def find_first_candle_index_at_or_after_ts(candles, ts_value):
    if ts_value is None:
        return None
    try:
        ts_value = int(ts_value)
    except Exception:
        return None

    for idx, candle in enumerate(candles or []):
        if candle.get("t") is not None and int(candle["t"]) >= ts_value:
            return idx
    return None


def recent_candles_by_hours(candles, hours, anchor_ts=None):
    if not candles:
        return []

    try:
        window_seconds = max(0, int(round(float(hours) * 3600.0)))
    except Exception:
        window_seconds = 0

    if anchor_ts is None:
        anchor_ts = candles[-1].get("t")

    anchor_ts = ts_to_int(anchor_ts)
    if anchor_ts is None or window_seconds <= 0:
        return list(candles)

    cutoff_ts = anchor_ts - window_seconds
    return [candle for candle in candles if ts_to_int(candle.get("t")) is not None and int(candle["t"]) >= cutoff_ts]


def append_strategy_note(existing_note, extra_note):
    existing_note = (existing_note or "").strip()
    extra_note = (extra_note or "").strip()

    if not existing_note:
        return extra_note
    if not extra_note:
        return existing_note
    return f"{existing_note} | {extra_note}"


def is_fib_sell_zone_sell_reason(reason=None, extra_event_fields=None):
    text = str(reason or "").strip().lower()
    if "fib" in text and ("sell" in text or "zone" in text or "bottom" in text or "retracement" in text):
        return True
    if isinstance(extra_event_fields, dict):
        if extra_event_fields.get("sell_zone_threshold_price") is not None:
            return True
        if extra_event_fields.get("fib_sell_zone_peak_gate_allowed") is not None:
            return True
        if extra_event_fields.get("below_fib_bottom") is not None or extra_event_fields.get("below_floor") is not None:
            return True
    return False


def same_live_candle_fib_sell_rebuy_block_status(state, live_candle=None, scan_dt=None):
    if not bool(BLOCK_REBUY_AFTER_FIB_SELL_SAME_LIVE_CANDLE):
        return {"blocked": False}
    if not isinstance(state, dict):
        return {"blocked": False}
    live_candle_ts = ts_to_int((live_candle or {}).get("t")) if isinstance(live_candle, dict) else None
    last_fib_sell_live_candle_ts = ts_to_int(state.get("last_fib_sell_live_candle_ts"))
    if live_candle_ts is None or last_fib_sell_live_candle_ts is None:
        return {"blocked": False, "live_candle_ts": live_candle_ts, "last_fib_sell_live_candle_ts": last_fib_sell_live_candle_ts}
    blocked = bool(live_candle_ts == last_fib_sell_live_candle_ts)
    return {
        "blocked": blocked,
        "live_candle_ts": live_candle_ts,
        "last_fib_sell_live_candle_ts": last_fib_sell_live_candle_ts,
        "last_fib_sell_scan_ts": ts_to_int(state.get("last_fib_sell_scan_ts")),
        "last_fib_sell_price": state.get("last_fib_sell_price"),
        "last_fib_sell_reason": state.get("last_fib_sell_reason"),
        "reason": (
            "buy blocked: previous sell on this same live candle was a fib sell-zone/fib-bottom sell"
            if blocked else ""
        ),
    }


def pine_30m_df0_downcross_buy_block_status(pine_status):
    if not isinstance(pine_status, dict) or not bool(BLOCK_BUY_AFTER_CLOSED_PMA_DF0_DOWNCROSS_UNTIL_PREDICT_UPPER):
        return {"blocked": False}
    return {
        "blocked": bool(pine_status.get("pma_df0_downcross_buy_blocked")),
        "reason": pine_status.get("pma_df0_downcross_buy_block_reason") or "",
        "prev_prev_pma": pine_status.get("prev_prev_pma"),
        "prev_pma": pine_status.get("prev_pma"),
        "DF0": pine_status.get("DF0"),
        "predict_upper": pine_status.get("predict_upper"),
        "pma": pine_status.get("pma"),
    }


def active_buy_peak_pnl_pct_for_sell_cooldown(state):
    if not isinstance(state, dict):
        return None

    active_entry_price, active_entry_ts = resolve_active_buy_real_entry_anchor(state)
    active_entry_price = _safe_positive_float(active_entry_price)
    active_entry_ts = ts_to_int(active_entry_ts)

    try:
        max_valid_peak_pct = float(HIGH_PEAK_SELL_COOLDOWN_MAX_VALID_PEAK_PCT)
    except Exception:
        max_valid_peak_pct = 100.0
    if max_valid_peak_pct <= 0:
        max_valid_peak_pct = 100.0

    invalid_keys = []

    def valid_peak_candidate(value_key, price_key=None, entry_price_key=None, entry_ts_key=None, scan_ts_key=None):
        try:
            raw_value = state.get(value_key)
        except Exception:
            raw_value = None
        try:
            value = float(raw_value) if raw_value is not None else None
        except Exception:
            return None
        if value is None or not math.isfinite(value):
            return None
        if value > max_valid_peak_pct:
            invalid_keys.append(value_key)
            return None

        candidate_entry_price = _safe_positive_float(state.get(entry_price_key)) if entry_price_key else None
        if (
            candidate_entry_price is not None and
            active_entry_price is not None and
            not math.isclose(candidate_entry_price, active_entry_price, rel_tol=1e-9, abs_tol=1e-9)
        ):
            invalid_keys.append(value_key)
            return None

        candidate_entry_ts = ts_to_int(state.get(entry_ts_key)) if entry_ts_key else None
        if candidate_entry_ts is not None and active_entry_ts is not None and candidate_entry_ts != active_entry_ts:
            invalid_keys.append(value_key)
            return None

        scan_ts = ts_to_int(state.get(scan_ts_key)) if scan_ts_key else None
        if scan_ts is not None and active_entry_ts is not None and scan_ts < active_entry_ts:
            invalid_keys.append(value_key)
            return None

        peak_price = _safe_positive_float(state.get(price_key)) if price_key else None
        if peak_price is not None and active_entry_price not in (None, 0, 0.0):
            computed_value = pct_change(active_entry_price, peak_price)
            if computed_value is None or not math.isfinite(computed_value):
                invalid_keys.append(value_key)
                return None
            if computed_value > max_valid_peak_pct:
                invalid_keys.append(value_key)
                return None
            if abs(computed_value - value) > max(0.10, abs(computed_value) * 0.05):
                # Prefer the entry/price-consistent value when the stored percent
                # drifted, but do not allow impossible/stale cross-entry peaks.
                value = computed_value

        # The secondary trackers have no explicit entry identity in older state.
        # Require their peak price to validate against the active real entry so
        # stale/cross-symbol percentages cannot create fake high-peak cooldowns.
        if price_key and peak_price is None and value_key != "active_buy_peak_pnl_pct":
            invalid_keys.append(value_key)
            return None

        return value

    candidates = []
    for value in (
        valid_peak_candidate(
            "active_buy_peak_pnl_pct",
            price_key="active_buy_peak_price",
            entry_price_key="active_buy_peak_entry_price",
            entry_ts_key="active_buy_peak_entry_ts",
            scan_ts_key="active_buy_peak_scan_ts",
        ),
        valid_peak_candidate(
            "active_buy_min_progress_peak_pnl_pct",
            price_key="active_buy_min_progress_peak_price",
            scan_ts_key="active_buy_min_progress_peak_scan_ts",
        ),
        valid_peak_candidate(
            "active_buy_profit_pullback_peak_pnl_pct",
            price_key="active_buy_profit_pullback_peak_price",
        ),
    ):
        if value is not None:
            candidates.append(value)

    for key in set(invalid_keys):
        try:
            state[key] = None
        except Exception:
            pass

    if not candidates:
        return None
    return max(candidates)


def high_peak_sell_cooldown_status(state):
    peak_pnl_pct = active_buy_peak_pnl_pct_for_sell_cooldown(state)
    try:
        threshold_pct = float(HIGH_PEAK_SELL_COOLDOWN_TRIGGER_PCT)
    except Exception:
        threshold_pct = 3.8
    try:
        enabled = bool(HIGH_PEAK_SELL_COOLDOWN_ENABLED)
    except Exception:
        enabled = True
    triggered = bool(enabled and peak_pnl_pct is not None and float(peak_pnl_pct) > threshold_pct)
    return {
        "triggered": triggered,
        "peak_pnl_pct": peak_pnl_pct,
        "threshold_pct": threshold_pct,
    }


def is_high_peak_sell_cooldown_kind(kind):
    return "high_peak" in str(kind or "").strip().lower()


def high_peak_sell_cooldown_duration_seconds():
    try:
        hours = float(HIGH_PEAK_SELL_COOLDOWN_HOURS)
    except Exception:
        hours = 2.0 / 60.0
    return int(max(0, round(hours * 3600)))


def pending_buy_sell_cooldown_until_ts(scan_dt):
    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if scan_ts is None:
        return None
    cooldown_seconds = int(SELL_COOLDOWN_HOURS * 3600)
    if cooldown_seconds <= 0:
        return scan_ts
    return scan_ts + cooldown_seconds



def resolve_sell_cooldown_details(state, scan_dt):
    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    is_pending_buy_origin_buy = False
    if isinstance(state, dict):
        is_pending_buy_origin_buy = (
            bool(state.get("buy_from_pending_buy")) or
            bool(state.get("buy_from_shadow_pending_buy")) or
            normalize_buy_style(state.get("buy_style")) == "pumping"
        )

    high_peak_status = high_peak_sell_cooldown_status(state)
    high_peak_triggered = bool(high_peak_status.get("triggered"))

    if high_peak_triggered:
        duration_seconds = high_peak_sell_cooldown_duration_seconds()
        cooldown_kind = "pumping_high_peak_buy_to_sell" if is_pending_buy_origin_buy else "high_peak_buy_to_sell"
    else:
        duration_seconds = int(SELL_COOLDOWN_HOURS * 3600)
        cooldown_kind = "pumping_buy_to_sell" if is_pending_buy_origin_buy else "standard"

    cooldown_until_ts = scan_ts + duration_seconds if scan_ts is not None else None
    return {
        "cooldown_until_ts": cooldown_until_ts,
        "cooldown_label": format_duration_compact(duration_seconds),
        "cooldown_kind": cooldown_kind,
        "cooldown_started_ts": scan_ts,
        "cooldown_duration_seconds": duration_seconds,
        "high_peak_sell_cooldown": high_peak_triggered,
        "high_peak_sell_cooldown_peak_pnl_pct": high_peak_status.get("peak_pnl_pct"),
        "high_peak_sell_cooldown_threshold_pct": high_peak_status.get("threshold_pct"),
    }


def finalize_sell_transition(state, candle, scan_dt, reason, extra_event_fields=None):
    pma_gf_plus_lifecycle_for_sell = False
    pma_gf_plus_previous_buy_pma = None
    pma_gf_plus_previous_buy_gf_plus = None
    pma_gf_plus_previous_buy_offset = None
    pma_gf_plus_previous_buy_oma = None
    if isinstance(state, dict):
        try:
            pma_gf_plus_lifecycle_for_sell = bool(active_buy_is_pma_gf_plus_lifecycle(state))
        except Exception:
            pma_gf_plus_lifecycle_for_sell = bool(state.get("buy_from_pma_gf_plus_force") or state.get("pma_gf_plus_force_buy"))
        pma_gf_plus_previous_buy_pma = _safe_finite_float(
            state.get("active_buy_pma_gf_plus_entry_pma") if state.get("active_buy_pma_gf_plus_entry_pma") is not None else
            state.get("pma_gf_plus_force_buy_entry_pma") if state.get("pma_gf_plus_force_buy_entry_pma") is not None else
            state.get("active_buy_pma_gf_plus_last_pma") if state.get("active_buy_pma_gf_plus_last_pma") is not None else
            state.get("active_buy_pma_gf_plus_peak_pma")
        )
        pma_gf_plus_previous_buy_gf_plus = _safe_finite_float(
            state.get("active_buy_pma_gf_plus_entry_gf_plus") if state.get("active_buy_pma_gf_plus_entry_gf_plus") is not None else
            state.get("pma_gf_plus_force_buy_entry_gf_plus") if state.get("pma_gf_plus_force_buy_entry_gf_plus") is not None else
            state.get("active_buy_pma_gf_plus_last_gf_plus") if state.get("active_buy_pma_gf_plus_last_gf_plus") is not None else
            state.get("active_buy_pma_gf_plus_peak_gf_plus")
        )
        pma_gf_plus_previous_buy_offset = _safe_finite_float(
            state.get("active_buy_pma_gf_plus_entry_offset") if state.get("active_buy_pma_gf_plus_entry_offset") is not None else
            state.get("pma_gf_plus_force_buy_entry_offset") if state.get("pma_gf_plus_force_buy_entry_offset") is not None else
            state.get("active_buy_pma_gf_plus_last_offset") if state.get("active_buy_pma_gf_plus_last_offset") is not None else
            state.get("active_buy_pma_gf_plus_peak_offset")
        )
        pma_gf_plus_previous_buy_oma = _safe_finite_float(state.get("last_pma_gf_plus_buy_oma"))
    pma_gf_plus_sell_pma = None
    pma_gf_plus_sell_gf_plus = None
    pma_gf_plus_sell_offset = None
    pma_gf_plus_sell_oma = None
    if isinstance(state, dict):
        pma_gf_plus_sell_pma = _safe_finite_float(
            state.get("active_buy_pma_gf_plus_last_pma") if state.get("active_buy_pma_gf_plus_last_pma") is not None else
            state.get("pma_gf_plus_force_buy_last_pma") if state.get("pma_gf_plus_force_buy_last_pma") is not None else
            pma_gf_plus_previous_buy_pma
        )
        pma_gf_plus_sell_gf_plus = _safe_finite_float(
            state.get("active_buy_pma_gf_plus_last_gf_plus") if state.get("active_buy_pma_gf_plus_last_gf_plus") is not None else
            state.get("pma_gf_plus_force_buy_last_gf_plus") if state.get("pma_gf_plus_force_buy_last_gf_plus") is not None else
            pma_gf_plus_previous_buy_gf_plus
        )
        pma_gf_plus_sell_offset = _safe_finite_float(
            state.get("active_buy_pma_gf_plus_last_offset") if state.get("active_buy_pma_gf_plus_last_offset") is not None else
            state.get("pma_gf_plus_force_buy_last_offset") if state.get("pma_gf_plus_force_buy_last_offset") is not None else
            pma_gf_plus_previous_buy_offset
        )
        pma_gf_plus_sell_oma = _safe_finite_float(state.get("pma_gf_plus_force_buy_oma_value"))

    fib_sell_marker = None
    if isinstance(state, dict) and is_fib_sell_zone_sell_reason(reason, extra_event_fields):
        fib_sell_marker = {
            "last_fib_sell_live_candle_ts": ts_to_int((candle or {}).get("t")) if isinstance(candle, dict) else None,
            "last_fib_sell_scan_ts": ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt),
            "last_fib_sell_price": _safe_positive_float((candle or {}).get("c")) if isinstance(candle, dict) else None,
            "last_fib_sell_reason": str(reason or ""),
            "last_fib_sell_entry_ts": state.get("active_buy_entry_ts") or state.get("buy_event_ts") or state.get("buy_ts"),
        }
    entry_price = state.get("entry_price") if isinstance(state, dict) else None
    buy_ts_for_sell = state.get("buy_event_ts") if isinstance(state, dict) else None
    buy_reference_candle_ts = state.get("buy_reference_candle_ts") if isinstance(state, dict) else None
    if isinstance(state, dict) and is_pumping_style_buy(state):
        active_buy_entry_price = state.get("active_buy_entry_price")
        active_buy_entry_ts = state.get("active_buy_entry_ts")
        if active_buy_entry_price not in (None, 0, 0.0):
            entry_price = active_buy_entry_price
        if active_buy_entry_ts is not None:
            buy_ts_for_sell = active_buy_entry_ts
        if buy_reference_candle_ts is None:
            buy_reference_candle_ts = state.get("buy_ts")
    elif isinstance(state, dict):
        if buy_ts_for_sell is None:
            buy_ts_for_sell = state.get("buy_ts")
        if buy_reference_candle_ts is None:
            buy_reference_candle_ts = state.get("buy_ts")
    sell_pnl_pct = pct_change(entry_price, candle["c"]) if entry_price not in (None, 0, 0.0) and candle else None

    cooldown_details = resolve_sell_cooldown_details(state, scan_dt)
    cooldown_until_ts = cooldown_details.get("cooldown_until_ts")
    cooldown_started_ts = cooldown_details.get("cooldown_started_ts")
    cooldown_duration_seconds = cooldown_details.get("cooldown_duration_seconds")

    if isinstance(state, dict):
        reset_state_to_idle(state, keep_cooldown=False)
        state["cooldown_until_ts"] = cooldown_until_ts
        state["cooldown_kind"] = cooldown_details.get("cooldown_kind")
        state["cooldown_started_ts"] = cooldown_started_ts
        state["cooldown_duration_seconds"] = cooldown_duration_seconds
        state["high_peak_sell_cooldown"] = bool(cooldown_details.get("high_peak_sell_cooldown"))
        state["high_peak_sell_cooldown_peak_pnl_pct"] = cooldown_details.get("high_peak_sell_cooldown_peak_pnl_pct")
        state["high_peak_sell_cooldown_threshold_pct"] = cooldown_details.get("high_peak_sell_cooldown_threshold_pct")
        if pma_gf_plus_lifecycle_for_sell and pma_gf_plus_previous_buy_pma is not None and cooldown_started_ts is not None:
            try:
                post_sell_block_seconds = max(0, int(float(globals().get("PMA_GF_PLUS_FORCE_BUY_POST_SELL_WEAKER_PMA_BLOCK_SECONDS", 2 * 60))))
            except Exception:
                post_sell_block_seconds = 2 * 60
            state["last_pma_gf_plus_sell_ts"] = cooldown_started_ts
            state["last_pma_gf_plus_sell_until_ts"] = int(cooldown_started_ts) + post_sell_block_seconds
            state["last_pma_gf_plus_sell_entry_ts"] = buy_ts_for_sell
            state["last_pma_gf_plus_buy_pma"] = pma_gf_plus_previous_buy_pma
            state["last_pma_gf_plus_buy_gf_plus"] = pma_gf_plus_previous_buy_gf_plus
            state["last_pma_gf_plus_buy_offset"] = pma_gf_plus_previous_buy_offset
            state["last_pma_gf_plus_buy_oma"] = pma_gf_plus_previous_buy_oma
            state["last_pma_gf_plus_sell_pma"] = pma_gf_plus_sell_pma
            state["last_pma_gf_plus_sell_gf_plus"] = pma_gf_plus_sell_gf_plus
            state["last_pma_gf_plus_sell_offset"] = pma_gf_plus_sell_offset
            state["last_pma_gf_plus_sell_oma"] = pma_gf_plus_sell_oma
            state["last_pma_gf_plus_sell_price"] = _safe_positive_float((candle or {}).get("c")) if isinstance(candle, dict) else None
            state["last_pma_gf_plus_sell_reason"] = str(reason or "")
        if isinstance(fib_sell_marker, dict):
            state.update(fib_sell_marker)
        update_pma_gf_plus_bad_buy_score_after_sell(
            state,
            sell_pnl_pct,
            scan_dt=scan_dt,
            reason=reason,
            pma=pma_gf_plus_sell_pma,
            price=_safe_positive_float((candle or {}).get("c")) if isinstance(candle, dict) else None,
            oma=pma_gf_plus_sell_oma,
            offset=pma_gf_plus_sell_offset,
        )

    legacy_buy_block_until_ts = None
    if isinstance(state, dict) and str(cooldown_details.get("cooldown_kind") or "").startswith("pumping"):
        legacy_buy_block_until_ts = set_legacy_buy_block_after_pump_sell(state, scan_dt)

    event_extra = {
        "entry_price": entry_price,
        "entry_ts": buy_ts_for_sell,
        "entry_unix_ts": buy_ts_for_sell,
        "buy_event_ts": buy_ts_for_sell,
        "buy_event_unix_ts": buy_ts_for_sell,
        "buy_reference_candle_ts": buy_reference_candle_ts,
        "buy_reference_candle_unix_ts": buy_reference_candle_ts,
        "pnl_pct": sell_pnl_pct,
        "cooldown_until_ts": cooldown_until_ts,
        "cooldown_kind": cooldown_details.get("cooldown_kind"),
        "cooldown_started_ts": cooldown_started_ts,
        "cooldown_duration_seconds": cooldown_duration_seconds,
        "high_peak_sell_cooldown": bool(cooldown_details.get("high_peak_sell_cooldown")),
        "high_peak_sell_cooldown_peak_pnl_pct": cooldown_details.get("high_peak_sell_cooldown_peak_pnl_pct"),
        "high_peak_sell_cooldown_threshold_pct": cooldown_details.get("high_peak_sell_cooldown_threshold_pct"),
        "legacy_buy_block_until_ts": legacy_buy_block_until_ts,
        "legacy_buy_block_started_ts": cooldown_started_ts if legacy_buy_block_until_ts is not None else None,
        "legacy_buy_block_duration_seconds": legacy_buy_block_after_pump_sell_duration_seconds() if legacy_buy_block_until_ts is not None else None,
        "legacy_buy_block_kind": "pump_sell_to_legacy_buy_block" if legacy_buy_block_until_ts is not None else None,
        "pma_gf_plus_lifecycle_sell": bool(pma_gf_plus_lifecycle_for_sell),
        "pma_gf_plus_previous_buy_pma": pma_gf_plus_previous_buy_pma,
        "pma_gf_plus_previous_buy_gf_plus": pma_gf_plus_previous_buy_gf_plus,
        "pma_gf_plus_previous_buy_offset": pma_gf_plus_previous_buy_offset,
        "pma_gf_plus_post_sell_weaker_pma_block_until_ts": (int(cooldown_started_ts) + int(float(globals().get("PMA_GF_PLUS_FORCE_BUY_POST_SELL_WEAKER_PMA_BLOCK_SECONDS", 2 * 60)))) if (pma_gf_plus_lifecycle_for_sell and pma_gf_plus_previous_buy_pma is not None and cooldown_started_ts is not None) else None,
        "pma_gf_plus_bad_buy_score": state.get("pma_gf_plus_bad_buy_score") if isinstance(state, dict) else None,
        "pma_gf_plus_bad_buy_last_pnl_pct": state.get("pma_gf_plus_bad_buy_last_pnl_pct") if isinstance(state, dict) else None,
        "pma_gf_plus_bad_buy_last_reason": state.get("pma_gf_plus_bad_buy_last_reason") if isinstance(state, dict) else None,
        "pma_gf_plus_bad_buy_last_pma": state.get("pma_gf_plus_bad_buy_last_pma") if isinstance(state, dict) else None,
        "pma_gf_plus_bad_buy_last_oma": state.get("pma_gf_plus_bad_buy_last_oma") if isinstance(state, dict) else None,
        "pma_gf_plus_bad_buy_last_offset": state.get("pma_gf_plus_bad_buy_last_offset") if isinstance(state, dict) else None,
        "pma_gf_plus_bad_buy_last_price": state.get("pma_gf_plus_bad_buy_last_price") if isinstance(state, dict) else None,
        "pma_gf_plus_sell_pma": pma_gf_plus_sell_pma,
        "pma_gf_plus_sell_gf_plus": pma_gf_plus_sell_gf_plus,
        "pma_gf_plus_sell_offset": pma_gf_plus_sell_offset,
        "pma_gf_plus_sell_oma": pma_gf_plus_sell_oma,
    }
    if isinstance(extra_event_fields, dict):
        event_extra.update(extra_event_fields)

    return make_event(
        "sell",
        f"{reason} | cooldown {cooldown_details.get('cooldown_label')}",
        candle,
        event_extra,
    )


def build_live_price_sell_candle(reference_candle, scan_dt=None, live_price=None):
    sell_candle = dict(reference_candle) if isinstance(reference_candle, dict) else {}

    current_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if current_ts is None:
        current_ts = int(time.time())
    sell_candle["t"] = current_ts

    live_price_value = _safe_positive_float(live_price)
    if live_price_value is not None:
        sell_candle["c"] = live_price_value
        if _safe_positive_float(sell_candle.get("o")) is None:
            sell_candle["o"] = live_price_value
        if _safe_positive_float(sell_candle.get("h")) is None or float(sell_candle.get("h")) < live_price_value:
            sell_candle["h"] = live_price_value
        if _safe_positive_float(sell_candle.get("l")) is None or float(sell_candle.get("l")) > live_price_value:
            sell_candle["l"] = live_price_value

    if _safe_positive_float(sell_candle.get("c")) is None:
        return None

    return sell_candle


def build_candidate_live_sell_candle(candidate, reference_candle, scan_dt=None):
    live_price = None
    if isinstance(candidate, dict):
        live_price = resolve_current_market_price(candidate.get("latest_price"), reference_candle, prefer_candle=False, context=candidate)
    return build_live_price_sell_candle(reference_candle, scan_dt=scan_dt, live_price=live_price)


def build_single_event_row(scan_dt, symbol_udf, event, market_row=None):
    row_seed = dict(market_row or {})
    row_seed.setdefault("symbol_udf", symbol_udf)
    row_seed.setdefault("base_symbol", base_symbol_from_market_symbol(symbol_udf) or message_symbol(symbol_udf) or "")
    row_seed.setdefault("market_type", market_type_from_symbol(symbol_udf))
    row_seed.setdefault("quote_currency", row_seed.get("market_type"))
    row = ensure_candidate_defaults(row_seed, scan_dt)

    event_price = event.get("price") if isinstance(event, dict) else None
    event_ts = ts_to_int((event or {}).get("candle_ts"))
    if event_ts is None:
        event_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt) or int(time.time())
    if event_price in (None, 0, 0.0):
        event_price = resolve_current_market_price(row.get("latest_price"), None, prefer_candle=False, context=row)

    row.update({
        "status": "OK",
        "reason": "async_event",
        "signal": False,
        "signal_text": "NONE",
        "closed_count": 0,
        "valid_closed_count": 0,
        "placeholder_closed_count": 0,
        "latest_18_placeholder_count": 0,
        "last_candle": {
            "t": event_ts,
            "o": event_price,
            "h": event_price,
            "l": event_price,
            "c": event_price,
            "v": 0.0,
        },
        "prev_candle": None,
        "change_30m_pct": None,
        "ret_24h_from_30m_pct": None,
        "ret_48h_from_30m_pct": None,
        "sma3": None,
        "sma7": None,
        "sma18": None,
        "gap_close_3_pct": None,
        "gap_3_7_pct": None,
        "gap_7_18_pct": None,
        "pump_4h_pct": None,
        "pump_30m_vs_avg_pct": None,
        "pump_last_30m_pct": None,
        "pump_avg_prev_30m_pct": None,
        "z_score": None,
        "is_pump": False,
        "recent_pump_diff_pct": None,
        "is_recent_pump": False,
        "watch_blocked_recent_pump": False,
        "watch_recent_pump_pct": None,
        "watch_recent_pump_from_ts": None,
        "watch_recent_pump_to_ts": None,
        "strategy_stage": "idle",
        "strategy_stage_before": "pumped",
        "strategy_event": event,
        "strategy_note": event.get("reason") if isinstance(event, dict) else "",
        "watch_anchor_ts": None,
        "possible_buy_anchor_ts": None,
        "possible_buy_price": event.get("possible_buy_price") if isinstance(event, dict) else None,
        "possible_buy_from_bypass": False,
        "buy_from_bypass": False,
        "buy_anchor_ts": event.get("entry_ts") if isinstance(event, dict) else None,
        "pumped_anchor_ts": None,
        "entry_price": event.get("entry_price") if isinstance(event, dict) else None,
        "pumped": False,
        "post_buy_delay_blocked": False,
        "post_buy_candles_since_buy": None,
        "post_buy_candles_remaining": 0,
        "stage_anchor_ts": None,
        "stage_age_hours": None,
        "active_buy_alert": None,
    })
    return row


def dispatch_due_delayed_pump_sells(now_dt=None):
    if now_dt is None:
        now_dt = get_tehran_now()

    current_ts = ts_to_int(now_dt.timestamp())
    if current_ts is None:
        return 0

    due_symbols = []
    with STATE_LOCK:
        strategy_states = load_strategy_states()
        strategy_states, state_changed = normalize_strategy_states(strategy_states, now_dt)
        if state_changed:
            save_strategy_states(strategy_states)

        for symbol, state in strategy_states.items():
            if not isinstance(state, dict):
                continue
            if str(state.get("stage") or "").strip().lower() != "pumped":
                continue
            due_ts = ts_to_int(state.get("pending_pump_sell_due_ts"))
            if due_ts is None or current_ts < due_ts:
                continue
            due_symbols.append(str(symbol or "").strip().upper())

    if not due_symbols:
        return 0

    all_usdt_including_skipped = fetch_usdt_market_stats(include_skipped=True)
    visible_usdt = [
        row for row in all_usdt_including_skipped
        if not should_skip_base_symbol(row.get("base_symbol"))
    ]
    all_scan_markets = list(all_usdt_including_skipped)
    market_context = build_market_context(
        all_usdt_including_skipped,
        all_markets_for_breadth=all_scan_markets,
        all_markets_for_confirmation_boost=all_scan_markets,
    )
    market_lookup = {}
    for row in list(all_usdt_including_skipped):
        symbol_udf = str((row or {}).get("symbol_udf") or "").strip().upper()
        if symbol_udf:
            market_lookup[symbol_udf] = row

    emitted_rows = []

    with STATE_LOCK:
        strategy_states = load_strategy_states()
        strategy_states, _ = normalize_strategy_states(strategy_states, now_dt)
        states_changed = False

        for symbol in due_symbols:
            state = strategy_states.get(symbol)
            if not isinstance(state, dict):
                continue
            if str(state.get("stage") or "").strip().lower() != "pumped":
                continue

            due_ts = ts_to_int(state.get("pending_pump_sell_due_ts"))
            if due_ts is None or current_ts < due_ts:
                continue

            market_row = market_lookup.get(symbol)
            sell_candle = build_candidate_live_sell_candle(market_row, {"t": current_ts, "c": state.get("entry_price")}, now_dt)
            if not sell_candle:
                continue

            sell_event = finalize_sell_transition(
                state,
                sell_candle,
                now_dt,
                f"{PUMP_DELAYED_SELL_SECONDS}s after pump signal",
            )
            if not dedupe_event(sell_event, state, now_dt):
                continue

            apply_shared_sell_cooldown(
                strategy_states,
                symbol,
                sell_event.get("cooldown_until_ts"),
                scan_dt=now_dt,
            )
            strategy_states[symbol] = state
            emitted_rows.append(build_single_event_row(now_dt, symbol, sell_event, market_row=market_row))
            states_changed = True

        if states_changed:
            save_strategy_states(strategy_states)

    if not emitted_rows:
        return 0

    emitted_rows.sort(
        key=lambda item: (
            active_buy_event_priority(((item.get("strategy_event") or {}).get("stage"))),
            -float(item.get("change_24h_pct", 0.0)),
        )
    )

    for row in emitted_rows:
        event = row.get("strategy_event")
        symbol_udf = row.get("symbol_udf")
        text_line = event_to_human_text(symbol_udf, event)
        if text_line:
            print(text_line)

    append_log(
        now_dt,
        len(visible_usdt),
        len(emitted_rows),
        emitted_rows,
        market_context=market_context,
        scan_label="ASYNC-SELL",
    )

    if BALE_SEND_SCAN_DETAILS:
        bale_text = build_bale_scan_output(
            now_dt,
            len(visible_usdt),
            len(emitted_rows),
            emitted_rows,
            detail_mode=BALE_SCAN_DETAILS_MODE,
            market_context=market_context,
            scan_label="FULL",
        )
    else:
        bale_text = build_bale_events_only_output(
            now_dt,
            emitted_rows,
            market_context=market_context,
            scan_label="FULL",
        )

    if bale_text:
        send_bale_notification(bale_text)

    broadcast_local_event("state", build_local_chat_status(
        scan_dt=now_dt,
        all_usdt_count=len(visible_usdt),
        filtered_count=len(emitted_rows),
        ranked_count=len(emitted_rows),
    ))

    return len(emitted_rows)

def delayed_pump_sell_worker_loop():
    print(f"{COL_INFO}[PUMP-SELL]{RESET} Delayed pump sell worker started.")
    while True:
        try:
            dispatch_due_delayed_pump_sells()
        except Exception as exc:
            print(f"{COL_WARN}[PUMP-SELL]{RESET} worker error: {exc}")
            traceback.print_exc()
        time.sleep(DELAYED_PUMP_SELL_POLL_SECONDS)


def should_force_pumped_sell(state, scan_dt, min_scans=PUMP_FORCE_SELL_AFTER_SCANS):
    if not isinstance(state, dict):
        return False
    if str(state.get("stage") or "").strip().lower() != "pumped":
        return False

    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if current_scan_ts is None:
        return False

    pending_due_ts = ts_to_int(state.get("pending_pump_sell_due_ts"))
    if pending_due_ts is not None:
        return current_scan_ts >= pending_due_ts

    pumped_scan_ts = ts_to_int(state.get("pumped_scan_ts"))
    if pumped_scan_ts is None:
        return False

    wait_seconds = max(60, int(max(1, int(min_scans)) * SCAN_INTERVAL_MINUTES * 60))
    return current_scan_ts >= (pumped_scan_ts + wait_seconds)


def bypass_pump_delay_status(candles, state, min_wait_candles=BYPASS_PUMP_WAIT_CANDLES):
    if not candles or not isinstance(state, dict):
        return {
            "blocked": False,
            "candles_since_buy": None,
            "candles_remaining": 0,
        }

    if not state.get("buy_from_bypass"):
        return {
            "blocked": False,
            "candles_since_buy": None,
            "candles_remaining": 0,
        }

    buy_ts = state.get("buy_ts")
    if not buy_ts:
        return {
            "blocked": True,
            "candles_since_buy": None,
            "candles_remaining": int(min_wait_candles),
        }

    buy_idx = find_candle_index_by_ts(candles, buy_ts)
    if buy_idx is None:
        return {
            "blocked": True,
            "candles_since_buy": None,
            "candles_remaining": int(min_wait_candles),
        }

    candles_since_buy = max(0, (len(candles) - 1) - buy_idx)
    candles_remaining = max(0, int(min_wait_candles) - candles_since_buy)

    return {
        "blocked": candles_since_buy < int(min_wait_candles),
        "candles_since_buy": candles_since_buy,
        "candles_remaining": candles_remaining,
    }


def post_buy_delay_status(candles, state, min_wait_candles=POST_BUY_MIN_WAIT_CANDLES):
    if not candles or not isinstance(state, dict):
        return {
            "blocked": False,
            "candles_since_buy": None,
            "candles_remaining": 0,
        }

    if state.get("stage") not in {"buy", "pumped"}:
        return {
            "blocked": False,
            "candles_since_buy": None,
            "candles_remaining": 0,
        }

    buy_ts = state.get("buy_ts")
    if not buy_ts:
        return {
            "blocked": True,
            "candles_since_buy": None,
            "candles_remaining": int(min_wait_candles),
        }

    buy_idx = find_candle_index_by_ts(candles, buy_ts)
    if buy_idx is None:
        return {
            "blocked": True,
            "candles_since_buy": None,
            "candles_remaining": int(min_wait_candles),
        }

    candles_since_buy = max(0, (len(candles) - 1) - buy_idx)
    candles_remaining = max(0, int(min_wait_candles) - candles_since_buy)

    return {
        "blocked": candles_since_buy < int(min_wait_candles),
        "candles_since_buy": candles_since_buy,
        "candles_remaining": candles_remaining,
    }


def get_strategy_path():
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), STATE_FILE)


def load_strategy_states():
    path = get_strategy_path()
    if not os.path.exists(path):
        return {}
    try:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        if isinstance(data, dict):
            return data
    except Exception as exc:
        print(f"{COL_WARN}[STATE]{RESET} load failed: {exc}")
    return {}


def save_strategy_states(states):
    path = get_strategy_path()
    tmp_path = path + ".tmp"
    try:
        with open(tmp_path, "w", encoding="utf-8") as fh:
            json.dump(states, fh, ensure_ascii=False, indent=2, sort_keys=True)
        os.replace(tmp_path, path)
    except Exception as exc:
        print(f"{COL_WARN}[STATE]{RESET} save failed: {exc}")


STRATEGY_STATE_MERGE_STAGE_PRIORITY = {
    "pumped": 5,
    "buy": 4,
    "pumpbox": 3.5,
    "pending_buy": 3,
    "possible_buy": 2,
    "watch": 1,
    "idle": 0,
}


def state_merge_stage_priority(state):
    stage = normalize_strategy_stage_value((state or {}).get("stage"))
    priority = STRATEGY_STATE_MERGE_STAGE_PRIORITY.get(stage, -1)

    cooldown_until_ts = ts_to_int((state or {}).get("cooldown_until_ts"))
    if cooldown_until_ts is not None:
        priority = max(priority, 6)

    last_event_stage = str((state or {}).get("last_event") or "").strip().lower()
    if last_event_stage == "sell":
        priority = max(priority, 7)
    elif last_event_stage == "pumped":
        priority = max(priority, 5)
    elif last_event_stage == "buy":
        priority = max(priority, 4)

    return priority


def state_has_active_buy_identity(state):
    if not isinstance(state, dict):
        return False
    stage = normalize_strategy_stage_value(state.get("stage"))
    if stage not in {"buy", "pumped"}:
        return False
    entry_price = _safe_positive_float(state.get("active_buy_entry_price") or state.get("entry_price"))
    entry_ts = ts_to_int(state.get("active_buy_entry_ts") or state.get("buy_event_ts") or state.get("buy_ts"))
    return bool(entry_price is not None and entry_ts is not None)


def state_active_buy_identity_ts(state):
    if not isinstance(state, dict):
        return None
    for key in ("active_buy_entry_ts", "buy_event_ts", "buy_ts", "entry_ts", "entry_unix_ts"):
        resolved = ts_to_int(state.get(key))
        if resolved is not None:
            return resolved
    return None


def state_last_sell_like_ts(state):
    if not isinstance(state, dict):
        return None
    timestamps = []
    if str(state.get("last_event") or "").strip().lower() == "sell":
        value = ts_to_int(state.get("last_event_ts"))
        if value is not None:
            timestamps.append(value)
    for key in ("cooldown_started_ts", "legacy_buy_block_started_ts"):
        value = ts_to_int(state.get(key))
        if value is not None:
            timestamps.append(value)
    return max(timestamps) if timestamps else None


def state_cooldown_active_at_scan(state, scan_dt=None):
    cooldown_until_ts = ts_to_int((state or {}).get("cooldown_until_ts") if isinstance(state, dict) else None)
    if cooldown_until_ts is None:
        return False
    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if scan_ts is None:
        return False
    return cooldown_until_ts > scan_ts


def state_merge_activity_ts(state):
    if not isinstance(state, dict):
        return None

    timestamps = []
    for key in (
        "last_event_ts",
        "cooldown_started_ts",
        "legacy_buy_block_started_ts",
        "legacy_buy_block_until_ts",
        "pumped_ts",
        "pumping_buy_started_ts",
        "buy_event_ts",
        "active_buy_entry_ts",
        "buy_ts",
        "pumpbox_entry_ts",
        "pumpbox_started_ts",
        "pending_buy_ts",
        "possible_buy_ts",
        "watch_ts",
        "pumping_ts",
        "pumping_seen_ts",
    ):
        ts_value = ts_to_int(state.get(key))
        if ts_value is not None:
            timestamps.append(ts_value)

    last_seen_scan_ts = parse_state_scan_ts(state.get("last_seen_scan_ts"))
    if last_seen_scan_ts is not None:
        timestamps.append(last_seen_scan_ts)

    if not timestamps:
        return None
    return max(timestamps)


# v43: PMA/GF+ force-buy setup/history/lifecycle timing is owned by BUY-1M.
# FULL-5M scans may still read normal market data and run non-PMA legacy logic,
# but they must not erase fresher BUY-1M PMA/GF+ timers, samples, OMA lanes,
# elapsed counters, or active PMA/GF+ lifecycle state during snapshot merge.
PMA_GF_PLUS_BUY_1M_OWNED_STATE_PREFIXES = (
    "pma_gf_plus_",
    "active_buy_pma_gf_plus_",
    "active_buy_non_gf_upper_predict_",
)
PMA_GF_PLUS_BUY_1M_OWNED_STATE_EXACT_KEYS = {
    "buy_from_pma_gf_plus_force",
}


def pma_gf_plus_buy_1m_owned_state_keys(state):
    if not isinstance(state, dict):
        return []
    keys = []
    for key in state.keys():
        key_text = str(key)
        if key_text in PMA_GF_PLUS_BUY_1M_OWNED_STATE_EXACT_KEYS or key_text.startswith(PMA_GF_PLUS_BUY_1M_OWNED_STATE_PREFIXES):
            keys.append(key_text)
    return keys


def pma_gf_plus_buy_1m_tracking_activity_ts(state):
    if not isinstance(state, dict):
        return None
    timestamps = []
    for key in pma_gf_plus_buy_1m_owned_state_keys(state):
        value = state.get(key)
        key_text = str(key)
        if key_text.endswith("_ts") or key_text.endswith("_scan_ts") or "_ts" in key_text:
            if isinstance(value, (list, tuple)):
                for item in value:
                    parsed = ts_to_int(item)
                    if parsed is not None:
                        timestamps.append(parsed)
            else:
                parsed = ts_to_int(value)
                if parsed is not None:
                    timestamps.append(parsed)
    return max(timestamps) if timestamps else None


def preserve_newer_pma_gf_plus_buy_1m_state(primary, secondary, scan_dt=None):
    if not isinstance(primary, dict):
        primary = {}
    if not isinstance(secondary, dict):
        return primary

    primary_ts = pma_gf_plus_buy_1m_tracking_activity_ts(primary)
    secondary_ts = pma_gf_plus_buy_1m_tracking_activity_ts(secondary)
    secondary_has_active_pma_force = bool(secondary.get("buy_from_pma_gf_plus_force") or secondary.get("pma_gf_plus_force_buy"))
    primary_has_active_pma_force = bool(primary.get("buy_from_pma_gf_plus_force") or primary.get("pma_gf_plus_force_buy"))
    primary_active_buy_identity = state_has_active_buy_identity(primary)
    secondary_active_buy_identity = state_has_active_buy_identity(secondary)
    primary_buy_identity_ts = state_active_buy_identity_ts(primary)
    secondary_buy_identity_ts = state_active_buy_identity_ts(secondary)
    same_active_buy_identity = (
        primary_active_buy_identity
        and secondary_active_buy_identity
        and primary_buy_identity_ts is not None
        and secondary_buy_identity_ts is not None
        and primary_buy_identity_ts == secondary_buy_identity_ts
    )

    should_copy_secondary = False
    if secondary_ts is not None and (primary_ts is None or secondary_ts > primary_ts):
        should_copy_secondary = True
    elif secondary_ts is not None and primary_ts is not None and secondary_ts == primary_ts:
        # Equal PMA timestamp: keep truthy/active flags and richer sample arrays
        # from the secondary snapshot rather than allowing a blank FULL snapshot
        # to wipe them.
        should_copy_secondary = secondary_has_active_pma_force and not primary_has_active_pma_force
    elif secondary_has_active_pma_force and not primary_has_active_pma_force and same_active_buy_identity:
        # Boolean-only PMA/GF+ lifecycle flags are allowed to be restored only
        # inside the same confirmed active BUY lifecycle.  Do not copy old PMA
        # flags into an idle/normal snapshot just because a stale secondary
        # state still has buy_from_pma_gf_plus_force=True.
        should_copy_secondary = True

    if not should_copy_secondary:
        return primary

    for key in pma_gf_plus_buy_1m_owned_state_keys(secondary):
        value = secondary.get(key)
        if isinstance(value, list):
            primary[key] = list(value)
        elif isinstance(value, dict):
            primary[key] = dict(value)
        else:
            primary[key] = value
    return primary


def merge_strategy_state_snapshots(current_state, incoming_state, scan_dt=None):
    current_sanitized, _ = sanitize_state_for_freshness(current_state, scan_dt)
    incoming_sanitized, _ = sanitize_state_for_freshness(incoming_state, scan_dt)

    current_activity_ts = state_merge_activity_ts(current_sanitized)
    incoming_activity_ts = state_merge_activity_ts(incoming_sanitized)
    current_priority = state_merge_stage_priority(current_sanitized)
    incoming_priority = state_merge_stage_priority(incoming_sanitized)

    current_active_buy = state_has_active_buy_identity(current_sanitized)
    incoming_active_buy = state_has_active_buy_identity(incoming_sanitized)
    current_buy_ts = state_active_buy_identity_ts(current_sanitized)
    incoming_buy_ts = state_active_buy_identity_ts(incoming_sanitized)

    choose_incoming = True

    # V12 safety: never let a stale idle/sell snapshot erase a newer real BUY.
    # JTO showed that an old SELL left in last_event could have higher merge
    # priority than an incoming PMA/GF+ BUY, so the BUY was logged/delivered but
    # the saved strategy state fell back to idle and later re-bought without a
    # real sell. A genuine active BUY identity always wins over a non-active
    # snapshot unless the current snapshot is still in an active sell cooldown.
    if incoming_active_buy and not current_active_buy:
        current_sell_ts = state_last_sell_like_ts(current_sanitized)
        if not state_cooldown_active_at_scan(current_sanitized, scan_dt=scan_dt):
            if current_sell_ts is None or incoming_buy_ts is None or incoming_buy_ts >= current_sell_ts:
                choose_incoming = True
            else:
                choose_incoming = False
        else:
            choose_incoming = False
    elif current_active_buy and not incoming_active_buy:
        incoming_sell_ts = state_last_sell_like_ts(incoming_sanitized)
        if incoming_sell_ts is not None and current_buy_ts is not None and incoming_sell_ts >= current_buy_ts:
            choose_incoming = True
        else:
            choose_incoming = False
    elif current_priority != incoming_priority and max(current_priority, incoming_priority) >= 4:
        choose_incoming = incoming_priority > current_priority
    elif current_activity_ts is not None and incoming_activity_ts is not None:
        if current_activity_ts > incoming_activity_ts:
            choose_incoming = False
        elif current_activity_ts < incoming_activity_ts:
            choose_incoming = True
        elif current_priority > incoming_priority:
            choose_incoming = False
    elif current_activity_ts is not None and incoming_activity_ts is None:
        choose_incoming = False
    elif current_activity_ts is None and incoming_activity_ts is not None:
        choose_incoming = True
    elif current_priority > incoming_priority:
        choose_incoming = False

    primary = dict(incoming_sanitized if choose_incoming else current_sanitized)
    secondary = current_sanitized if choose_incoming else incoming_sanitized

    primary_cooldown_until_ts = ts_to_int(primary.get("cooldown_until_ts"))
    secondary_cooldown_until_ts = ts_to_int(secondary.get("cooldown_until_ts"))
    if secondary_cooldown_until_ts is not None and (
        primary_cooldown_until_ts is None or secondary_cooldown_until_ts > primary_cooldown_until_ts
    ):
        primary["cooldown_until_ts"] = secondary_cooldown_until_ts
        primary["cooldown_kind"] = secondary.get("cooldown_kind")
        primary["cooldown_started_ts"] = secondary.get("cooldown_started_ts")
        primary["cooldown_duration_seconds"] = secondary.get("cooldown_duration_seconds")

    primary_legacy_buy_block_until_ts = ts_to_int(primary.get("legacy_buy_block_until_ts"))
    secondary_legacy_buy_block_until_ts = ts_to_int(secondary.get("legacy_buy_block_until_ts"))
    if secondary_legacy_buy_block_until_ts is not None and (
        primary_legacy_buy_block_until_ts is None or secondary_legacy_buy_block_until_ts > primary_legacy_buy_block_until_ts
    ):
        primary["legacy_buy_block_until_ts"] = secondary_legacy_buy_block_until_ts
        primary["legacy_buy_block_started_ts"] = secondary.get("legacy_buy_block_started_ts")
        primary["legacy_buy_block_day"] = secondary.get("legacy_buy_block_day")
        primary["legacy_buy_block_reason"] = secondary.get("legacy_buy_block_reason")
        primary["legacy_buy_block_source_symbol"] = secondary.get("legacy_buy_block_source_symbol")

    primary_last_event_ts = ts_to_int(primary.get("last_event_ts"))
    secondary_last_event_ts = ts_to_int(secondary.get("last_event_ts"))
    preserve_secondary_last_event = secondary_last_event_ts is not None and (
        primary_last_event_ts is None or secondary_last_event_ts > primary_last_event_ts
    )
    if preserve_secondary_last_event and state_has_active_buy_identity(primary):
        primary_buy_identity_ts = state_active_buy_identity_ts(primary)
        secondary_last_event_stage = str(secondary.get("last_event") or "").strip().lower()
        # V12 safety: if the chosen primary snapshot is an active BUY, do not
        # reattach an older SELL as last_event merely because the BUY event key
        # uses a reference candle timestamp. That stale SELL was the reason JTO
        # could not persist its BUY state after 17:21.
        if (
            secondary_last_event_stage == "sell" and
            primary_buy_identity_ts is not None and
            secondary_last_event_ts < primary_buy_identity_ts
        ):
            preserve_secondary_last_event = False
    if preserve_secondary_last_event:
        primary["last_event"] = secondary.get("last_event")
        primary["last_event_ts"] = secondary_last_event_ts
        primary["last_event_payload"] = dict(secondary.get("last_event_payload")) if isinstance(secondary.get("last_event_payload"), dict) else secondary.get("last_event_payload")

    primary_last_seen_scan_ts = parse_state_scan_ts(primary.get("last_seen_scan_ts"))
    secondary_last_seen_scan_ts = parse_state_scan_ts(secondary.get("last_seen_scan_ts"))
    if secondary_last_seen_scan_ts is not None and (
        primary_last_seen_scan_ts is None or secondary_last_seen_scan_ts > primary_last_seen_scan_ts
    ):
        primary["last_seen_scan_ts"] = secondary.get("last_seen_scan_ts")

    primary_pumping_seen_ts = ts_to_int(primary.get("pumping_seen_ts"))
    secondary_pumping_seen_ts = ts_to_int(secondary.get("pumping_seen_ts"))
    if secondary_pumping_seen_ts is not None and (
        primary_pumping_seen_ts is None or secondary_pumping_seen_ts > primary_pumping_seen_ts
    ):
        primary["pumping_seen_day"] = secondary.get("pumping_seen_day")
        primary["pumping_seen_ts"] = secondary.get("pumping_seen_ts")

    primary = preserve_newer_pma_gf_plus_buy_1m_state(primary, secondary, scan_dt=scan_dt)
    primary, _ = sanitize_state_for_freshness(primary, scan_dt)
    return primary


def rebuild_active_buy_state_from_open_delivery(symbol_udf, candidate, existing_state, open_buy_record, scan_dt=None):
    """Rehydrate strategy state from the delivered-event ledger open BUY.

    This is a hard reconciliation guard: if the event ledger says a BUY was
    delivered and no matching/later SELL has closed it, strategy_state.json must
    not remain idle or create another BUY.  The rebuilt state is still a normal
    stage=buy lifecycle; PMA/GF+ is only preserved as flags/metadata.
    """
    if not isinstance(open_buy_record, dict):
        return existing_state, False

    payload = open_buy_record.get("payload") if isinstance(open_buy_record.get("payload"), dict) else None
    if not isinstance(payload, dict):
        return existing_state, False

    event = payload.get("event_payload") if isinstance(payload.get("event_payload"), dict) else {}
    entry_ts = _event_delivery_payload_real_entry_ts(payload)
    entry_price = _safe_positive_float(
        event.get("active_buy_entry_price") or
        event.get("entry_price") or
        event.get("price") or
        payload.get("price")
    )
    if entry_ts is None or entry_price is None:
        return existing_state, False

    current_stage = normalize_strategy_stage_value((existing_state or {}).get("stage") if isinstance(existing_state, dict) else None)
    current_entry_ts = ts_to_int((existing_state or {}).get("active_buy_entry_ts") or (existing_state or {}).get("buy_event_ts") or (existing_state or {}).get("buy_ts") if isinstance(existing_state, dict) else None)
    if current_stage in {"buy", "pumped"} and current_entry_ts == entry_ts:
        return existing_state, False

    rebuilt = dict(default_symbol_state())
    if isinstance(existing_state, dict):
        # Preserve harmless context/markers, then override the lifecycle fields
        # with the ledger's delivered BUY identity.
        rebuilt.update(existing_state)

    rebuilt["strategy_logic_version"] = STRATEGY_LOGIC_VERSION
    rebuilt["stage"] = "buy"
    rebuilt["buy_ts"] = entry_ts
    rebuilt["buy_event_ts"] = entry_ts
    rebuilt["entry_ts"] = entry_ts
    rebuilt["entry_unix_ts"] = entry_ts
    rebuilt["entry_price"] = entry_price
    rebuilt["active_buy_entry_price"] = entry_price
    rebuilt["active_buy_entry_ts"] = entry_ts
    rebuilt["active_buy_force_sell_reference_price"] = _safe_positive_float(event.get("active_buy_force_sell_reference_price")) or entry_price

    # v86: rebuilding from an open delivered BUY starts a fresh active-BUY
    # display/sell-streak lifecycle for that delivered entry.  Do not preserve
    # stale/corrupt streak counters from an older idle/sold lifecycle; those can
    # leak into the first active-buy alert as impossible values such as x144.
    rebuilt["active_buy_green_count"] = 0
    rebuilt["active_buy_max_green_count"] = 0
    rebuilt["active_buy_max_green_price"] = None
    rebuilt["active_buy_max_green_scan_ts"] = None
    rebuilt["active_buy_max_green_source"] = None
    rebuilt["active_buy_last_green_price"] = None
    rebuilt["active_buy_red_sent"] = False

    reference_ts = ts_to_int(
        event.get("reference_closed_candle_ts") or
        event.get("reference_closed_candle_unix_ts") or
        event.get("buy_reference_candle_ts") or
        event.get("buy_reference_candle_unix_ts") or
        payload.get("candle_ts") or
        payload.get("candle_unix_ts")
    )
    if reference_ts is not None:
        rebuilt["buy_reference_candle_ts"] = reference_ts

    for key in (
        "buy_style",
        "buy_from_pending_buy",
        "buy_from_shadow_pending_buy",
        "buy_from_legacy_shadow_buy",
        "buy_from_bypass",
        "buy_from_pma_gf_plus_force",
        "pma_gf_plus_force_buy",
        "pma_gf_plus_force_buy_trigger",
        "pma_gf_plus_force_buy_elapsed_seconds",
        "active_buy_pma_gf_plus_qualified_since_buy",
        "active_buy_pma_gf_plus_qualified_ts",
        "active_buy_pma_gf_plus_qualified_trigger",
        "active_buy_pma_gf_plus_qualified_offset",
        "pine_30m_pma",
        "pine_30m_GF_pos",
        "pine_30m_DF0",
        "pine_30m_predict_upper",
        "pine_30m_pma_above_gf_plus_offset",
        "fib_bottom",
        "fib_top",
    ):
        if key in event:
            rebuilt[key] = event.get(key)

    if bool(event.get("buy_from_pma_gf_plus_force") or event.get("pma_gf_plus_force_buy")):
        rebuilt["buy_from_pma_gf_plus_force"] = True
        rebuilt["pma_gf_plus_force_buy"] = True
        rebuilt["active_buy_pma_gf_plus_qualified_since_buy"] = True
        if ts_to_int(rebuilt.get("active_buy_pma_gf_plus_qualified_ts")) is None:
            rebuilt["active_buy_pma_gf_plus_qualified_ts"] = entry_ts
        if not str(rebuilt.get("active_buy_pma_gf_plus_qualified_trigger") or "").strip():
            rebuilt["active_buy_pma_gf_plus_qualified_trigger"] = event.get("pma_gf_plus_force_buy_trigger") or "ledger_open_buy_reconcile"

    current_price = _safe_positive_float((candidate or {}).get("latest_price"))
    peak_price = max([value for value in (entry_price, current_price, _safe_positive_float(event.get("fib_top")), _safe_positive_float(event.get("price"))) if value is not None])
    rebuilt["active_buy_peak_price"] = max(_safe_positive_float(rebuilt.get("active_buy_peak_price")) or entry_price, peak_price)
    rebuilt["active_buy_peak_pnl_pct"] = pct_change(entry_price, rebuilt["active_buy_peak_price"])
    rebuilt["active_buy_peak_scan_ts"] = ts_to_int((scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt))
    rebuilt["active_buy_peak_source"] = "ledger_open_buy_reconcile"
    rebuilt["active_buy_peak_entry_price"] = entry_price
    rebuilt["active_buy_peak_entry_ts"] = entry_ts
    rebuilt["active_buy_highest_wick_high_price"] = max(_safe_positive_float(rebuilt.get("active_buy_highest_wick_high_price")) or entry_price, peak_price)
    rebuilt["active_buy_highest_wick_high_pnl_pct"] = pct_change(entry_price, rebuilt["active_buy_highest_wick_high_price"])
    rebuilt["active_buy_highest_wick_high_scan_ts"] = rebuilt["active_buy_peak_scan_ts"]
    rebuilt["active_buy_highest_wick_high_source"] = "ledger_open_buy_reconcile"
    rebuilt["active_buy_highest_wick_high_entry_price"] = entry_price
    rebuilt["active_buy_highest_wick_high_entry_ts"] = entry_ts

    # Do not let a stale pre-BUY sell/cooldown from a false/orphan SELL keep
    # overriding the rebuilt active BUY lifecycle.
    for key in ("cooldown_until_ts", "cooldown_kind", "cooldown_started_ts", "cooldown_duration_seconds"):
        started_ts = ts_to_int(rebuilt.get("cooldown_started_ts"))
        if started_ts is None or started_ts <= entry_ts:
            rebuilt[key] = None
    legacy_started_ts = ts_to_int(rebuilt.get("legacy_buy_block_started_ts"))
    if legacy_started_ts is None or legacy_started_ts <= entry_ts:
        clear_legacy_buy_block_fields(rebuilt)

    rebuilt["last_event"] = "buy"
    rebuilt["last_event_ts"] = entry_ts
    rebuilt["last_event_key"] = payload.get("key") or open_buy_record.get("key")
    rebuilt["last_event_payload"] = dict(event) if isinstance(event, dict) else event
    rebuilt["reconciled_from_open_delivered_buy"] = True
    rebuilt["reconciled_from_open_delivered_buy_at_ts"] = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    rebuilt["reconciled_from_open_delivered_buy_entry_ts"] = entry_ts

    ensure_active_buy_state_defaults(rebuilt)
    return rebuilt, True



