def ts_to_int(value):
    try:
        return int(float(value))
    except Exception:
        return None


def _scan_counter_reset_reason_key(counter_key):
    return f"{str(counter_key or '').strip()}_reset_reason"


def set_state_scan_counter(state, counter_key, value, reset_reason=None):
    if not isinstance(state, dict):
        return 0

    try:
        new_value = max(0, int(value or 0))
    except Exception:
        new_value = 0

    reason_key = _scan_counter_reset_reason_key(counter_key)
    state[counter_key] = new_value
    if new_value <= 0:
        state[reason_key] = str(reset_reason or "counter reset")
    else:
        state[reason_key] = None
    return new_value


def increment_state_scan_counter(state, counter_key, delta=1):
    if not isinstance(state, dict):
        return 0
    try:
        delta_value = int(delta or 0)
    except Exception:
        delta_value = 0
    current_value = int(state.get(counter_key, 0) or 0)
    return set_state_scan_counter(state, counter_key, current_value + delta_value)


def scan_counter_reset_reason(state, counter_key):
    if not isinstance(state, dict):
        return None
    value = state.get(_scan_counter_reset_reason_key(counter_key))
    text = str(value or "").strip()
    return text or None


def is_exact_2h_sandbox_active(state):
    return bool((state or {}).get("exact_2h_sandbox_active"))


def sandbox_blocks_shadow_pending_buy():
    """Shadow pending-buy is blocked during sandbox only when instant sandbox BUY is enabled."""
    return bool(ENABLE_SANDBOX_INSTANT_BUY_ABOVE_BREAKOUT)


def clear_shadow_pending_buy_for_sandbox_if_needed(state):
    if sandbox_blocks_shadow_pending_buy():
        clear_shadow_pending_buy_fields(
            state,
            reset_reason="shadow pending-buy disabled while exact/legacy sandbox instant BUY is enabled",
        )
        return True
    return False


def clear_exact_2h_sandbox_fields(state):
    if not isinstance(state, dict):
        return
    state["exact_2h_sandbox_active"] = False
    state["exact_2h_sandbox_entry_price"] = None
    state["exact_2h_sandbox_entry_ts"] = None
    state["exact_2h_sandbox_reference_candle_ts"] = None
    state["exact_2h_sandbox_started_at"] = None
    state["exact_2h_sandbox_from_bypass"] = False
    state["exact_2h_sandbox_survived_active_range"] = False
    state["exact_2h_sandbox_survival_scan_ts"] = None
    state["exact_2h_sandbox_survival_recheck_ts"] = None
    state["exact_2h_sandbox_confirm_scan_count"] = 0
    state["exact_2h_sandbox_last_confirm_scan_ts"] = None
    state["exact_2h_sandbox_buy_window_snapshot"] = {}
    state["exact_2h_sandbox_source"] = "exact_2h"
    state["exact_2h_sandbox_legacy_reason"] = None
    state["exact_2h_sandbox_legacy_event_extra"] = {}


def clear_exact_2h_sandbox_shadow_after_buy_fields(state):
    if not isinstance(state, dict):
        return
    state["exact_2h_sandbox_pending_shadow_after_buy"] = False
    state["exact_2h_sandbox_buy_scan_ts"] = None
    state["exact_2h_sandbox_real_entry_price"] = None


def clear_all_exact_2h_sandbox_fields(state):
    clear_exact_2h_sandbox_fields(state)
    clear_exact_2h_sandbox_shadow_after_buy_fields(state)


def start_exact_2h_sandbox(state, entry_candle, scan_dt, from_bypass=False, buy_window_snapshot=None, source="exact_2h", legacy_reason=None, legacy_event_extra=None):
    if not bool(ENABLE_LEGACY_BUY_FLOW):
        if isinstance(state, dict):
            state["exact_2h_sandbox_legacy_disabled_reason"] = "legacy buy flow disabled"
        return False
    if not isinstance(state, dict) or not isinstance(entry_candle, dict):
        return False
    entry_price = _safe_positive_float(entry_candle.get("c"))
    reference_ts = ts_to_int(entry_candle.get("t"))
    if entry_price is None or reference_ts is None:
        return False
    clear_exact_2h_sandbox_fields(state)
    clear_shadow_pending_buy_for_sandbox_if_needed(state)
    state["exact_2h_sandbox_active"] = True
    state["exact_2h_sandbox_entry_price"] = entry_price
    state["exact_2h_sandbox_entry_ts"] = reference_ts
    state["exact_2h_sandbox_reference_candle_ts"] = reference_ts
    state["exact_2h_sandbox_started_at"] = scan_dt.strftime("%Y-%m-%d %H:%M:%S") if isinstance(scan_dt, datetime) else None
    state["exact_2h_sandbox_from_bypass"] = bool(from_bypass)
    state["exact_2h_sandbox_survived_active_range"] = False
    state["exact_2h_sandbox_survival_scan_ts"] = None
    state["exact_2h_sandbox_survival_recheck_ts"] = None
    state["exact_2h_sandbox_confirm_scan_count"] = 0
    state["exact_2h_sandbox_last_confirm_scan_ts"] = None
    state["exact_2h_sandbox_buy_window_snapshot"] = dict(buy_window_snapshot or {})
    state["exact_2h_sandbox_source"] = str(source or "exact_2h")
    state["exact_2h_sandbox_legacy_reason"] = legacy_reason
    state["exact_2h_sandbox_legacy_event_extra"] = dict(legacy_event_extra or {})
    state["exact_2h_sandbox_pending_shadow_after_buy"] = False
    state["exact_2h_sandbox_buy_scan_ts"] = None
    state["exact_2h_sandbox_real_entry_price"] = None
    return True


def exact_2h_sandbox_candles_since_entry(state, candles):
    if not isinstance(state, dict) or not candles:
        return None
    reference_ts = ts_to_int(state.get("exact_2h_sandbox_reference_candle_ts") or state.get("exact_2h_sandbox_entry_ts"))
    if reference_ts is None:
        return None
    entry_idx = find_candle_index_by_ts(candles, reference_ts)
    if entry_idx is None:
        return None
    return max(0, (len(candles) - 1) - entry_idx)


def build_live_price_buy_candle(reference_candle, live_price=None):
    buy_candle = dict(reference_candle) if isinstance(reference_candle, dict) else {}
    live_price_value = _safe_positive_float(live_price)
    if live_price_value is not None:
        buy_candle["c"] = live_price_value
        if _safe_positive_float(buy_candle.get("o")) is None:
            buy_candle["o"] = live_price_value
        if _safe_positive_float(buy_candle.get("h")) is None or float(buy_candle.get("h")) < live_price_value:
            buy_candle["h"] = live_price_value
        if _safe_positive_float(buy_candle.get("l")) is None or float(buy_candle.get("l")) > live_price_value:
            buy_candle["l"] = live_price_value
    if _safe_positive_float(buy_candle.get("c")) is None:
        return None
    return buy_candle


def build_exact_2h_sandbox_buy_reason():
    return (
        f"exact last {BUY_WINDOW_EXACT_HOURS}h closed window confirmed BUY on USDT: "
        f"SMA3>SMA7, SMA7-SMA18 >= {RULE2_MIN_7_OVER_18_PCT:.3f}%, "
        "majority green candles, majority non-flat candles, the latest 2 closed candle bodies and the live candle body stayed on or above SMA7, "
        f"and the live candle stayed green for at least {EXACT_BUY_LIVE_CANDLE_MIN_AGE_MINUTES:g} minutes"
    )


def build_legacy_sandbox_buy_reason(state):
    source = str((state or {}).get("exact_2h_sandbox_source") or "legacy").strip() or "legacy"
    base_reason = (state or {}).get("exact_2h_sandbox_legacy_reason")
    if not base_reason:
        base_reason = "legacy BUY candidate"
    return f"{base_reason}; confirmed by legacy sandbox source={source} after active-range survival"


def exact_2h_sandbox_event_extra(state, buy_window_snapshot=None, current_price=None):
    snapshot = dict(buy_window_snapshot or {})
    legacy_extra = dict((state or {}).get("exact_2h_sandbox_legacy_event_extra") or {})
    # Preserve the real sandbox-confirmed entry fields. The legacy candidate
    # snapshot may contain the old direct-buy entry price, but the actual BUY
    # entry after sandbox confirmation is the current live price.
    for protected_key in ("entry_price", "buy_style", "buy_from_pending_buy"):
        legacy_extra.pop(protected_key, None)
    return {
        "entry_price": current_price,
        "buy_style": "legacy",
        "buy_from_pending_buy": False,
        "buy_window_hours": BUY_WINDOW_EXACT_HOURS,
        "buy_window_candles": BUY_WINDOW_EXACT_CANDLES,
        "buy_window_green_count": snapshot.get("buy_window_green_count"),
        "buy_window_not_flat_count": snapshot.get("buy_window_not_flat_count"),
        "buy_window_all_above_sma7": snapshot.get("buy_window_all_above_sma7"),
        "buy_window_required_closed_candles_above_sma7": BUY_WINDOW_ABOVE_SMA7_REQUIRED_CLOSED_CANDLES,
        "buy_window_live_candle_above_sma7": snapshot.get("buy_window_live_candle_above_sma7"),
        "buy_window_market_type": snapshot.get("buy_window_market_type"),
        "buy_window_live_candle_age_minutes": snapshot.get("buy_window_live_candle_age_minutes"),
        "buy_window_live_candle_last_minutes_blocked": snapshot.get("buy_window_live_candle_last_minutes_blocked"),
        "buy_window_live_candle_green": snapshot.get("buy_window_live_candle_green"),
        "buy_window_latest_closed_green": snapshot.get("buy_window_latest_closed_green"),
        "buy_window_latest_closed_ref": snapshot.get("buy_window_latest_closed_ref"),
        "buy_window_previous_closed_ref": snapshot.get("buy_window_previous_closed_ref"),
        "buy_window_oldest_closed_ref": snapshot.get("buy_window_oldest_closed_ref"),
        "exact_2h_sandbox_entry_price": state.get("exact_2h_sandbox_entry_price"),
        "exact_2h_sandbox_survival_scan_ts": state.get("exact_2h_sandbox_survival_scan_ts"),
        "exact_2h_sandbox_survival_recheck_ts": state.get("exact_2h_sandbox_survival_recheck_ts"),
        "exact_2h_sandbox_survival_recheck_minutes": EXACT_TWO_HOUR_SANDBOX_SURVIVAL_RECHECK_MINUTES,
        "exact_2h_sandbox_confirm_scan_count": state.get("exact_2h_sandbox_confirm_scan_count"),
        "exact_2h_sandbox_confirmed": True,
        "exact_2h_sandbox_source": state.get("exact_2h_sandbox_source") or "exact_2h",
        "legacy_sandbox_source": state.get("exact_2h_sandbox_source") or "exact_2h",
        "legacy_sandbox_original_reason": state.get("exact_2h_sandbox_legacy_reason"),
        **legacy_extra,
    }



def sandbox_instant_breakout_status(state, current_price=None):
    entry_price = _safe_positive_float((state or {}).get("exact_2h_sandbox_entry_price"))
    live_price = _safe_positive_float(current_price)
    try:
        breakout_pct = float(SANDBOX_INSTANT_BUY_BREAKOUT_PCT)
    except Exception:
        breakout_pct = float(BUY_BREAKOUT_TOTAL_PCT)

    status = {
        "enabled": bool(ENABLE_SANDBOX_INSTANT_BUY_ABOVE_BREAKOUT),
        "reached": False,
        "entry_price": entry_price,
        "current_price": live_price,
        "breakout_pct": breakout_pct,
        "trigger_price": None,
        "pnl_pct": None,
    }

    if not status["enabled"] or entry_price is None or live_price is None:
        return status

    trigger_price = entry_price * (1.0 + (breakout_pct / 100.0))
    status["trigger_price"] = trigger_price
    status["pnl_pct"] = pct_change(entry_price, live_price)
    # User requested "goes above 1.9", so this is intentionally strict >, not >=.
    status["reached"] = live_price > trigger_price
    return status


def promote_exact_2h_sandbox_to_real_buy_on_breakout(state, latest_closed_candle, live_candle, scan_dt, live_price=None, buy_window_snapshot=None, breakout_price=None):
    if not isinstance(state, dict):
        return None

    pumpbox_entry_price = _safe_positive_float(live_price)
    if pumpbox_entry_price is None:
        return None

    reference_candle = live_candle if isinstance(live_candle, dict) else latest_closed_candle
    pumpbox_candle = build_live_price_buy_candle(reference_candle, live_price=pumpbox_entry_price)
    if not isinstance(pumpbox_candle, dict):
        return None

    snapshot = dict(buy_window_snapshot or state.get("exact_2h_sandbox_buy_window_snapshot") or {})
    sandbox_entry_price = state.get("exact_2h_sandbox_entry_price")
    sandbox_entry_ts = state.get("exact_2h_sandbox_entry_ts")
    sandbox_reference_candle_ts = state.get("exact_2h_sandbox_reference_candle_ts")
    sandbox_survival_scan_ts = state.get("exact_2h_sandbox_survival_scan_ts")
    sandbox_confirm_scan_count = state.get("exact_2h_sandbox_confirm_scan_count")
    sandbox_source = str(state.get("exact_2h_sandbox_source") or "exact_2h").strip() or "exact_2h"
    from_bypass = bool(state.get("exact_2h_sandbox_from_bypass"))

    breakout_check_price = _safe_positive_float(breakout_price)
    if breakout_check_price is None:
        breakout_check_price = pumpbox_entry_price
    breakout_status = sandbox_instant_breakout_status(state, breakout_check_price)
    event_extra = exact_2h_sandbox_event_extra(state, buy_window_snapshot=snapshot, current_price=pumpbox_entry_price)
    event_extra.update({
        "price": pumpbox_entry_price,
        "entry_price": pumpbox_entry_price,
        "buy_style": "legacy",
        "buy_from_pending_buy": False,
        "sandbox_instant_breakout_buy": False,
        "sandbox_instant_breakout_to_pumpbox": True,
        "sandbox_instant_breakout_enabled": bool(ENABLE_SANDBOX_INSTANT_BUY_ABOVE_BREAKOUT),
        "sandbox_instant_breakout_pct": breakout_status.get("breakout_pct"),
        "sandbox_instant_breakout_trigger_price": breakout_status.get("trigger_price"),
        "sandbox_instant_breakout_pnl_pct": breakout_status.get("pnl_pct"),
        "sandbox_instant_breakout_body_top_price": breakout_check_price,
        "sandbox_instant_breakout_pumpbox_entry_price": pumpbox_entry_price,
        "sandbox_instant_breakout_source": sandbox_source,
        "exact_2h_sandbox_entry_price": sandbox_entry_price,
        "exact_2h_sandbox_entry_ts": sandbox_entry_ts,
        "exact_2h_sandbox_reference_candle_ts": sandbox_reference_candle_ts,
        "exact_2h_sandbox_survival_scan_ts": sandbox_survival_scan_ts,
        "exact_2h_sandbox_confirm_scan_count": sandbox_confirm_scan_count,
    })

    pumpbox_started = start_pumpbox(
        state,
        pumpbox_candle,
        scan_dt,
        current_price=pumpbox_entry_price,
        source=f"{sandbox_source}_instant_breakout",
        buy_style="legacy",
        from_bypass=from_bypass,
        from_exact_2h_sandbox=True,
        event_extra=event_extra,
        legacy_pending_shadow_after_buy=True,
        legacy_sandbox_snapshot={
            "exact_2h_sandbox_entry_price": sandbox_entry_price,
            "exact_2h_sandbox_entry_ts": sandbox_entry_ts,
            "exact_2h_sandbox_reference_candle_ts": sandbox_reference_candle_ts,
            "exact_2h_sandbox_survival_scan_ts": sandbox_survival_scan_ts,
            "exact_2h_sandbox_confirm_scan_count": sandbox_confirm_scan_count,
            "exact_2h_sandbox_source": sandbox_source,
        },
    )
    if not pumpbox_started:
        return None

    # The instant sandbox breakout is no longer a real BUY by itself. It only
    # hands off into pumpbox. V14 pumpbox streak reset then requires a fresh
    # post-pumpbox +ACTIVE_BUY_GREEN_TRIGGER_PCT move before real BUY, while
    # process_pumpbox also re-checks the pumpbox safety gates.
    clear_exact_2h_sandbox_fields(state)

    return {
        "pumpbox_started": True,
        "sandbox_source": sandbox_source,
        "sandbox_instant_breakout_pct": breakout_status.get("breakout_pct"),
        "sandbox_instant_breakout_trigger_price": breakout_status.get("trigger_price"),
        "sandbox_instant_breakout_pnl_pct": breakout_status.get("pnl_pct"),
        "sandbox_instant_breakout_body_top_price": breakout_check_price,
        "sandbox_instant_breakout_pumpbox_entry_price": pumpbox_entry_price,
    }


def process_exact_2h_sandbox(state, candidate, candles, latest_closed_candle, live_candle, scan_dt, current_price=None):
    status = {"active": is_exact_2h_sandbox_active(state), "event": None, "note": None, "cancelled": False, "confirmed": False}
    if not bool(ENABLE_LEGACY_BUY_FLOW):
        if status["active"]:
            clear_all_exact_2h_sandbox_fields(state)
            status["active"] = False
            status["cancelled"] = True
            status["note"] = "legacy buy flow disabled; exact/legacy sandbox was cleared"
        return status
    if not status["active"]:
        return status

    clear_shadow_pending_buy_for_sandbox_if_needed(state)

    current_stage = str((state or {}).get("stage") or "idle").strip().lower()
    if current_stage in {"buy", "pumped", "pending_buy"}:
        clear_exact_2h_sandbox_fields(state)
        status["cancelled"] = True
        status["note"] = "exact 2h sandbox cancelled because another active buy-side stage took over"
        return status

    entry_price = _safe_positive_float(state.get("exact_2h_sandbox_entry_price"))
    live_price = _safe_positive_float(current_price)
    if live_price is None and isinstance(candidate, dict):
        live_price = resolve_current_market_price(candidate.get("latest_price"), latest_closed_candle, prefer_candle=False, context=candidate)
    if live_price is None:
        live_price = _safe_positive_float((live_candle or {}).get("c"))
    if live_price is None:
        live_price = _safe_positive_float((latest_closed_candle or {}).get("c"))

    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if entry_price is None or live_price is None or current_scan_ts is None:
        status["note"] = "exact 2h sandbox waiting: missing entry/current price or scan timestamp"
        return status

    live_body_top_price = _safe_positive_float((live_candle or {}).get("body_top"))
    if live_body_top_price is None:
        live_body_top_price = live_price

    pnl_pct_from_sandbox_entry = pct_change(entry_price, live_price)
    threshold_price = entry_price * (1.0 + (ACTIVE_BUY_RANGE_SELL_UPPER_PCT / 100.0))

    # Breakout must be proven by the live body top, not by the top wick/high.
    instant_breakout = sandbox_instant_breakout_status(state, live_body_top_price)
    status["sandbox_instant_breakout"] = instant_breakout
    if bool(instant_breakout.get("reached")):
        if is_legacy_buy_blocked_after_recent_pump_sell(state, scan_dt):
            status["note"] = legacy_buy_block_note(state, scan_dt) or "sandbox instant breakout pumpbox handoff blocked after recent pump-style sell"
            return status
        pumpbox_handoff = promote_exact_2h_sandbox_to_real_buy_on_breakout(
            state,
            latest_closed_candle,
            live_candle,
            scan_dt,
            live_price=live_price,
            breakout_price=live_body_top_price,
        )
        if isinstance(pumpbox_handoff, dict) and bool(pumpbox_handoff.get("pumpbox_started")):
            status["pumpbox_started"] = True
            status["confirmed"] = False
            status["note"] = (
                "sandbox instant breakout reached: live body-top moved strictly above "
                f"+{instant_breakout.get('breakout_pct'):.3f}% from sandbox entry; "
                "entered pumpbox instead of real BUY, so a fresh post-pumpbox "
                f"fixed +{PUMPBOX_CONFIRM_PCT:.3f}% pumpbox confirmation held for 1 real minute plus pumpbox safety gates are required before BUY"
            )
            return status
        status["note"] = "sandbox instant breakout reached but pumpbox could not be started"
        return status

    candles_since_entry = exact_2h_sandbox_candles_since_entry(state, candles)
    if candles_since_entry is None:
        status["note"] = "exact 2h sandbox waiting: reference candle is not available yet"
        return status

    if not bool(state.get("exact_2h_sandbox_survived_active_range")):
        if candles_since_entry < ACTIVE_BUY_RANGE_SELL_AFTER_CANDLES:
            status["note"] = f"exact 2h sandbox waiting for active-range eligibility ({candles_since_entry}/{ACTIVE_BUY_RANGE_SELL_AFTER_CANDLES} closed candles)"
            return status
        if pnl_pct_from_sandbox_entry is None or pnl_pct_from_sandbox_entry <= ACTIVE_BUY_RANGE_SELL_UPPER_PCT:
            clear_exact_2h_sandbox_fields(state)
            status["cancelled"] = True
            status["note"] = "exact 2h sandbox cancelled without cooldown because it did not survive above the active-buy upper range"
            return status
        state["exact_2h_sandbox_survived_active_range"] = True
        state["exact_2h_sandbox_survival_scan_ts"] = current_scan_ts
        try:
            recheck_delay_seconds = max(0, int(float(EXACT_TWO_HOUR_SANDBOX_SURVIVAL_RECHECK_MINUTES) * 60))
        except Exception:
            recheck_delay_seconds = 0
        state["exact_2h_sandbox_survival_recheck_ts"] = current_scan_ts + recheck_delay_seconds
        state["exact_2h_sandbox_confirm_scan_count"] = 0
        state["exact_2h_sandbox_last_confirm_scan_ts"] = None
        status["note"] = (
            "exact 2h sandbox survived the active-buy upper range; "
            f"waiting for {EXACT_TWO_HOUR_SANDBOX_CONFIRM_SCANS} confirmation scan(s) above +{ACTIVE_BUY_RANGE_SELL_UPPER_PCT:.3f}% before pumpbox"
        )
        if int(EXACT_TWO_HOUR_SANDBOX_CONFIRM_SCANS) > 0:
            return status

    survival_scan_ts = ts_to_int(state.get("exact_2h_sandbox_survival_scan_ts"))
    recheck_ts = ts_to_int(state.get("exact_2h_sandbox_survival_recheck_ts"))
    try:
        recheck_delay_seconds = max(0, int(float(EXACT_TWO_HOUR_SANDBOX_SURVIVAL_RECHECK_MINUTES) * 60))
    except Exception:
        recheck_delay_seconds = 0
    if survival_scan_ts is not None:
        expected_recheck_ts = survival_scan_ts + recheck_delay_seconds
        if recheck_ts is None or recheck_delay_seconds <= 0:
            recheck_ts = expected_recheck_ts
            state["exact_2h_sandbox_survival_recheck_ts"] = recheck_ts

    last_confirm_scan_ts = ts_to_int(state.get("exact_2h_sandbox_last_confirm_scan_ts"))
    if int(EXACT_TWO_HOUR_SANDBOX_CONFIRM_SCANS) > 0 and survival_scan_ts is not None and current_scan_ts <= survival_scan_ts:
        status["note"] = "exact 2h sandbox survived active range; confirmation scans start after the survival scan"
        return status
    if recheck_ts is not None and current_scan_ts < recheck_ts:
        remaining_seconds = max(0, recheck_ts - current_scan_ts)
        status["note"] = f"exact 2h sandbox survived active range; waiting {remaining_seconds}s before confirmation scans can continue"
        return status
    if last_confirm_scan_ts is not None and current_scan_ts <= last_confirm_scan_ts:
        status["note"] = "exact 2h sandbox confirmation already counted for this scan"
        return status

    if live_price <= threshold_price:
        clear_exact_2h_sandbox_fields(state)
        status["cancelled"] = True
        status["note"] = (
            "exact 2h sandbox cancelled without cooldown because it no longer stayed "
            "above the active-buy upper range while waiting for sandbox breakout"
        )
        return status

    if bool(ENABLE_SANDBOX_INSTANT_BUY_ABOVE_BREAKOUT):
        status["note"] = (
            "sandbox instant BUY is enabled; keeping sandbox active and waiting for "
            f"live body-top to move strictly above +{SANDBOX_INSTANT_BUY_BREAKOUT_PCT:.3f}% "
            "from sandbox entry instead of entering pumpbox or confirming by active-range survival"
        )
        return status

    count = int(state.get("exact_2h_sandbox_confirm_scan_count", 0) or 0) + 1
    state["exact_2h_sandbox_confirm_scan_count"] = count
    state["exact_2h_sandbox_last_confirm_scan_ts"] = current_scan_ts
    if count < EXACT_TWO_HOUR_SANDBOX_CONFIRM_SCANS:
        status["note"] = f"exact 2h sandbox confirmation scan {count}/{EXACT_TWO_HOUR_SANDBOX_CONFIRM_SCANS} stayed above active-buy upper range"
        return status

    if is_legacy_buy_blocked_after_recent_pump_sell(state, scan_dt):
        status["note"] = legacy_buy_block_note(state, scan_dt) or "exact 2h sandbox legacy BUY blocked after recent pump-style sell"
        return status

    buy_candle = build_live_price_buy_candle(latest_closed_candle, live_price=live_price)
    if not isinstance(buy_candle, dict):
        clear_exact_2h_sandbox_fields(state)
        status["cancelled"] = True
        status["note"] = "exact 2h sandbox cancelled without cooldown because the pumpbox candle could not be built"
        return status

    snapshot = dict(state.get("exact_2h_sandbox_buy_window_snapshot") or {})
    sandbox_entry_price = state.get("exact_2h_sandbox_entry_price")
    sandbox_entry_ts = state.get("exact_2h_sandbox_entry_ts")
    sandbox_reference_candle_ts = state.get("exact_2h_sandbox_reference_candle_ts")
    sandbox_survival_scan_ts = state.get("exact_2h_sandbox_survival_scan_ts")
    sandbox_confirm_scan_count = state.get("exact_2h_sandbox_confirm_scan_count")
    sandbox_source = str(state.get("exact_2h_sandbox_source") or "exact_2h")
    from_bypass = bool(state.get("exact_2h_sandbox_from_bypass"))

    event_extra = exact_2h_sandbox_event_extra(state, buy_window_snapshot=snapshot, current_price=live_price)
    event_extra["exact_2h_sandbox_entry_price"] = sandbox_entry_price
    event_extra["exact_2h_sandbox_survival_scan_ts"] = sandbox_survival_scan_ts
    event_extra["exact_2h_sandbox_survival_recheck_ts"] = state.get("exact_2h_sandbox_survival_recheck_ts")
    event_extra["exact_2h_sandbox_survival_recheck_minutes"] = EXACT_TWO_HOUR_SANDBOX_SURVIVAL_RECHECK_MINUTES
    event_extra["exact_2h_sandbox_confirm_scan_count"] = sandbox_confirm_scan_count

    event_extra.update({
        "price": live_price,
        "entry_price": live_price,
        "buy_style": "legacy",
        "buy_from_pending_buy": False,
        "exact_2h_sandbox_confirmed_buy": True,
        "exact_2h_sandbox_confirmed_direct_real_buy": False,
        "exact_2h_sandbox_source": sandbox_source,
        "sandbox_instant_breakout_enabled": bool(ENABLE_SANDBOX_INSTANT_BUY_ABOVE_BREAKOUT),
        "sandbox_confirmed_to_pumpbox": True,
    })

    pumpbox_started = start_pumpbox(
        state,
        buy_candle,
        scan_dt,
        current_price=live_price,
        source=sandbox_source,
        buy_style="legacy",
        from_bypass=from_bypass,
        from_exact_2h_sandbox=True,
        event_extra=event_extra,
        legacy_pending_shadow_after_buy=True,
        legacy_sandbox_snapshot={
            "exact_2h_sandbox_entry_price": sandbox_entry_price,
            "exact_2h_sandbox_entry_ts": sandbox_entry_ts,
            "exact_2h_sandbox_reference_candle_ts": sandbox_reference_candle_ts,
            "exact_2h_sandbox_survival_scan_ts": sandbox_survival_scan_ts,
            "exact_2h_sandbox_confirm_scan_count": sandbox_confirm_scan_count,
            "exact_2h_sandbox_source": sandbox_source,
        },
    )
    if not pumpbox_started:
        clear_exact_2h_sandbox_fields(state)
        status["cancelled"] = True
        status["note"] = "sandbox confirmed but pumpbox could not be started"
        return status

    clear_exact_2h_sandbox_fields(state)
    status["pumpbox_started"] = True
    status["note"] = (
        f"{sandbox_source} sandbox confirmed with {EXACT_TWO_HOUR_SANDBOX_CONFIRM_SCANS} confirmation scan(s); "
        "sandbox instant BUY is disabled, so it entered pumpbox flag before real BUY"
    )
    return status


def promote_exact_2h_sandbox_confirmed_buy_to_shadow_next_scan(state, candles, live_candle, scan_dt, current_price=None):
    if not bool(ENABLE_LEGACY_BUY_FLOW):
        if isinstance(state, dict) and bool(state.get("exact_2h_sandbox_pending_shadow_after_buy")):
            clear_all_exact_2h_sandbox_fields(state)
        return None
    if not isinstance(state, dict) or not bool(state.get("exact_2h_sandbox_pending_shadow_after_buy")):
        return None
    if str(state.get("stage") or "idle").strip().lower() != "buy":
        clear_all_exact_2h_sandbox_fields(state)
        return None
    if infer_buy_style(state) != "legacy":
        clear_all_exact_2h_sandbox_fields(state)
        return None
    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    buy_scan_ts = ts_to_int(state.get("exact_2h_sandbox_buy_scan_ts"))
    if current_scan_ts is None or (buy_scan_ts is not None and current_scan_ts <= buy_scan_ts):
        return None
    reference_candle = candles[-1] if candles and isinstance(candles[-1], dict) else None
    working_live_candle = live_candle if isinstance(live_candle, dict) else reference_candle
    if not isinstance(reference_candle, dict) or not isinstance(working_live_candle, dict):
        return None
    real_entry_price = _safe_positive_float(state.get("exact_2h_sandbox_real_entry_price")) or _safe_positive_float(state.get("active_buy_entry_price")) or _safe_positive_float(state.get("entry_price"))
    candles_since_buy = exact_2h_sandbox_candles_since_entry(state, candles)
    prepare_shadow_pending_buy_tracking_state(state, reference_candle, working_live_candle, scan_dt)
    state["shadow_pending_buy_ts"] = current_scan_ts
    state["shadow_pending_buy_price"] = (working_live_candle or {}).get("body_top") or (working_live_candle or {}).get("c") or real_entry_price
    # This is the existing legacy post-BUY shadow/rollover path. The real BUY
    # has already passed pumpbox, so do not create a second pumpbox here.
    shadow_promoted = promote_buy_state_from_shadow_pending_buy_unchecked(
        state,
        working_live_candle,
        scan_dt,
        from_legacy_buy=True,
        source_name="exact_2h_sandbox_shadow",
        from_exact_2h_sandbox=True,
    )
    if not shadow_promoted:
        return None
    if real_entry_price is not None:
        state["entry_price"] = real_entry_price
        state["active_buy_entry_price"] = real_entry_price
        if state.get("active_buy_force_sell_reference_price") is None:
            state["active_buy_force_sell_reference_price"] = real_entry_price
    clear_all_exact_2h_sandbox_fields(state)
    arm_legacy_shadow_buy_rollover_next_scan(state, scan_dt, reference_candle=reference_candle, live_candle=working_live_candle)
    return build_shadow_pending_buy_event(
        working_live_candle,
        current_price if current_price is not None else ((working_live_candle or {}).get("c")),
        state,
        shadow_pending_buy_price=state.get("shadow_pending_buy_price"),
        reason="shadow pending-buy fallback confirmed on the next scan after exact 2h sandbox BUY confirmation",
        candles_since_buy=candles_since_buy,
    )


def scan_result_history_ok_count(history):
    if not isinstance(history, list):
        return 0
    count = 0
    for item in history:
        if isinstance(item, dict) and bool(item.get("ok")):
            count += 1
    return count


def _scan_result_history_append(history, scan_dt, is_ok, max_keep=None):
    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    normalized = []
    if isinstance(history, list):
        for item in history:
            if isinstance(item, dict):
                item_ts = ts_to_int(item.get("ts"))
                if item_ts is None:
                    continue
                normalized.append({"ts": item_ts, "ok": bool(item.get("ok"))})
            elif isinstance(item, (list, tuple)) and len(item) >= 2:
                item_ts = ts_to_int(item[0])
                if item_ts is None:
                    continue
                normalized.append({"ts": item_ts, "ok": bool(item[1])})
    if scan_ts is not None:
        if normalized and normalized[-1].get("ts") == scan_ts:
            normalized[-1] = {"ts": scan_ts, "ok": bool(is_ok)}
        else:
            normalized.append({"ts": scan_ts, "ok": bool(is_ok)})
    else:
        normalized.append({"ts": None, "ok": bool(is_ok)})
    if max_keep is not None and max_keep > 0 and len(normalized) > max_keep:
        normalized = normalized[-max_keep:]
    return normalized


def _scan_history_tail_recent_ok(history):
    if not isinstance(history, list) or not history:
        return False
    tail = history[-2:]
    return any(bool(item.get("ok")) for item in tail if isinstance(item, dict))


def _scan_history_has_majority_ok(history, minimum_count):
    if not isinstance(history, list):
        return False
    recent = history[-int(minimum_count):] if minimum_count is not None and minimum_count > 0 else list(history)
    if minimum_count is not None and minimum_count > 0 and len(recent) < int(minimum_count):
        return False
    ok_count = sum(1 for item in recent if isinstance(item, dict) and bool(item.get("ok")))
    return ok_count > (len(recent) / 2.0)


def confirmation_history_allows_buy(history, required_scans):
    return (
        _scan_history_has_majority_ok(history, required_scans) and
        _scan_history_tail_recent_ok(history)
    )


def partial_confirmation_history_allows_buy(
    history,
    minimum_ok_scans=5,
    max_window_seconds=None,
    scan_dt=None,
    confirmation_scan_count=None,
):
    if not isinstance(history, list):
        return False

    normalized = []
    for item in history:
        if not isinstance(item, dict):
            continue
        item_ts = ts_to_int(item.get("ts"))
        if item_ts is None:
            continue
        normalized.append({"ts": item_ts, "ok": bool(item.get("ok"))})

    if not normalized:
        return False

    try:
        confirmation_scan_count = int(confirmation_scan_count or BUY_CONFIRM_SCANS)
    except Exception:
        confirmation_scan_count = int(BUY_CONFIRM_SCANS)
    confirmation_scan_count = max(1, confirmation_scan_count)

    recent = normalized[-confirmation_scan_count:]
    ok_count = sum(1 for item in recent if bool(item.get("ok")))
    required_ok = int(minimum_ok_scans or 0)
    return (
        len(recent) >= required_ok and
        ok_count >= required_ok and
        _scan_history_tail_recent_ok(recent)
    )


def start_pending_buy_extension_window(state, prefix, scan_dt):
    if not isinstance(state, dict):
        return
    history_key = f"{prefix}_extension_history"
    active_key = f"{prefix}_extension_active"
    start_key = f"{prefix}_extension_start_ts"
    state[active_key] = True
    state[start_key] = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    state[history_key] = []


def clear_pending_buy_extension_window(state, prefix):
    if not isinstance(state, dict):
        return
    state[f"{prefix}_extension_active"] = False
    state[f"{prefix}_extension_start_ts"] = None
    state[f"{prefix}_extension_history"] = []


def record_pending_buy_extension_scan(state, prefix, scan_dt, is_ok):
    if not isinstance(state, dict):
        return []
    history_key = f"{prefix}_extension_history"
    state[history_key] = _scan_result_history_append(state.get(history_key), scan_dt, is_ok, max_keep=16)
    return state[history_key]


def pending_buy_extension_window_elapsed(state, prefix, scan_dt, minutes=PENDING_BUY_EXTENSION_MINUTES):
    if not isinstance(state, dict):
        return False
    start_ts = ts_to_int(state.get(f"{prefix}_extension_start_ts"))
    current_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if start_ts is None or current_ts is None:
        return False
    return current_ts >= (start_ts + int(minutes * 60))


def pending_buy_extension_allows_buy(state, prefix, scan_dt, minutes=PENDING_BUY_EXTENSION_MINUTES):
    if not isinstance(state, dict):
        return False
    if not pending_buy_extension_window_elapsed(state, prefix, scan_dt, minutes=minutes):
        return False
    history = state.get(f"{prefix}_extension_history")
    return (
        _scan_history_has_majority_ok(history, None) and
        _scan_history_tail_recent_ok(history)
    )


def buy_min_hold_elapsed(state, scan_dt, minutes=FORCE_SELL_MIN_HOLD_MINUTES):
    buy_ts = ts_to_int((state or {}).get("buy_ts"))
    current_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if buy_ts is None or current_ts is None:
        return False
    return current_ts >= (buy_ts + int(minutes * 60))


def age_hours_from_ts(scan_dt, ts_value):
    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    anchor_ts = ts_to_int(ts_value)
    if scan_ts is None or anchor_ts is None:
        return None
    return max(0.0, (scan_ts - anchor_ts) / 3600.0)


def age_hours_str(scan_dt, ts_value):
    age_hours = age_hours_from_ts(scan_dt, ts_value)
    if age_hours is None:
        return "-"
    return f"{age_hours:.1f}h"


def parse_state_scan_ts(value):
    text = str(value or "").strip()
    if not text:
        return None

    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
        try:
            return int(datetime.strptime(text, fmt).timestamp())
        except Exception:
            continue

    return ts_to_int(text)


def scan_day_key(scan_dt):
    if isinstance(scan_dt, datetime):
        return scan_dt.strftime("%Y-%m-%d")

    scan_ts = ts_to_int(scan_dt)
    if scan_ts is None:
        return None

    try:
        return datetime.fromtimestamp(scan_ts).strftime("%Y-%m-%d")
    except Exception:
        return None


def clear_expired_pumping_seen_today(state, scan_dt):
    if not isinstance(state, dict):
        return

    current_day = scan_day_key(scan_dt)
    if current_day is None:
        return

    stored_day = str(state.get("pumping_seen_day") or "").strip()
    if stored_day and stored_day != current_day:
        state["pumping_seen_day"] = None
        state["pumping_seen_ts"] = None


def has_pumping_seen_today(state, scan_dt):
    if not isinstance(state, dict):
        return False

    clear_expired_pumping_seen_today(state, scan_dt)
    current_day = scan_day_key(scan_dt)
    if current_day is None:
        return False

    return str(state.get("pumping_seen_day") or "").strip() == current_day


def is_pumping_flag_active(state, scan_dt=None):
    if not isinstance(state, dict):
        return False

    pumping_ts = ts_to_int(state.get("pumping_ts"))
    if pumping_ts is None:
        return False

    if scan_dt is not None and not is_ts_fresh(scan_dt, pumping_ts, PUMP_STAGE_MAX_AGE_HOURS):
        return False

    return True


def candidate_has_pumping_seen_today(candidate, states, scan_dt):
    if isinstance(candidate, dict) and candidate.get("pumping_seen_today"):
        return True

    if not isinstance(states, dict):
        states = {}

    symbol = ""
    base_symbol = ""
    if isinstance(candidate, dict):
        symbol = str(candidate.get("symbol_udf") or "").strip().upper()
        base_symbol = str(candidate.get("base_symbol") or base_symbol_from_market_symbol(symbol) or "").strip().upper()

    symbols_to_check = []
    if symbol:
        symbols_to_check.append(symbol)
    if base_symbol:
        for market_type in ("USDT",):
            market_symbol = f"{base_symbol}{market_type}"
            if market_symbol not in symbols_to_check:
                symbols_to_check.append(market_symbol)

    for market_symbol in symbols_to_check:
        if has_pumping_seen_today(states.get(market_symbol), scan_dt):
            return True

    return False


def mark_pumping_seen_today(state, scan_dt):
    if not isinstance(state, dict):
        return

    current_day = scan_day_key(scan_dt)
    current_scan_ts = int(scan_dt.timestamp()) if isinstance(scan_dt, datetime) else ts_to_int(scan_dt)
    if current_day is None:
        return

    if str(state.get("pumping_seen_day") or "").strip() != current_day:
        state["pumping_seen_day"] = current_day
        state["pumping_seen_ts"] = current_scan_ts
        return

    if ts_to_int(state.get("pumping_seen_ts")) is None and current_scan_ts is not None:
        state["pumping_seen_ts"] = current_scan_ts


def is_ts_fresh(scan_dt, ts_value, max_age_hours):
    if max_age_hours is None:
        return ts_to_int(ts_value) is not None
    age_hours = age_hours_from_ts(scan_dt, ts_value)
    if age_hours is None:
        return False
    return age_hours <= float(max_age_hours)


def get_stage_max_age_hours(stage):
    return STAGE_MAX_AGE_HOURS.get(str(stage or "").strip().lower())


def get_event_max_age_hours(stage):
    return EVENT_MAX_AGE_HOURS.get(str(stage or "").strip().lower())


def get_state_stage_anchor_ts(state, stage=None):
    if not isinstance(state, dict):
        return None

    stage_name = str(stage or state.get("stage") or "").strip().lower()
    if stage_name == "watch":
        return state.get("watch_ts")
    if stage_name == "possible_buy":
        return state.get("possible_buy_ts")
    if stage_name == "pending_buy":
        return state.get("pending_buy_ts") or state.get("possible_buy_ts")
    if stage_name == "pumpbox":
        return state.get("pumpbox_started_ts") or state.get("pumpbox_entry_ts")
    if stage_name == "buy":
        return state.get("buy_event_ts") or state.get("buy_ts")
    if stage_name == "pumped":
        return state.get("pumped_ts") or state.get("buy_event_ts") or state.get("buy_ts")
    return None


