def pumpbox_no_buy_2h_final_confirm_enabled():
    try:
        return bool(ENABLE_PUMPBOX_NO_BUY_2H_PMA_GF_PLUS_FINAL_CONFIRM)
    except Exception:
        return False


def pumpbox_no_buy_2h_final_confirm_window_seconds():
    try:
        return max(1, int(PUMPBOX_NO_BUY_2H_FINAL_CONFIRM_WINDOW_SECONDS))
    except Exception:
        return 2 * 60 * 60


def get_pumpbox_no_buy_2h_final_confirm_state_path():
    return os.path.join(get_script_dir(), PUMPBOX_NO_BUY_2H_FINAL_CONFIRM_FILE)


def default_pumpbox_no_buy_2h_final_confirm_state():
    return {
        "schema_version": 1,
        "last_buy_signal_ts": None,
        "last_buy_signal_at": None,
        "last_buy_signal_symbol": None,
        "last_buy_signal_source": None,
        "last_drought_check_ts": None,
        "last_drought_check_at": None,
        "last_drought_check_symbol": None,
        "last_drought_check_passed": None,
        "last_drought_check_reason": None,
        "last_drought_check_pma": None,
        "last_drought_check_gf_plus": None,
    }


def normalize_pumpbox_no_buy_2h_final_confirm_state(state):
    base = default_pumpbox_no_buy_2h_final_confirm_state()
    if isinstance(state, dict):
        for key in base:
            if key in state:
                base[key] = state.get(key)
    base["schema_version"] = 1
    for key in ("last_buy_signal_ts", "last_drought_check_ts"):
        base[key] = ts_to_int(base.get(key))
    return base


def load_pumpbox_no_buy_2h_final_confirm_state_unlocked():
    path = get_pumpbox_no_buy_2h_final_confirm_state_path()
    if not os.path.exists(path):
        return default_pumpbox_no_buy_2h_final_confirm_state()
    try:
        with open(path, "r", encoding="utf-8") as fh:
            return normalize_pumpbox_no_buy_2h_final_confirm_state(json.load(fh))
    except Exception:
        return default_pumpbox_no_buy_2h_final_confirm_state()


def save_pumpbox_no_buy_2h_final_confirm_state_unlocked(state):
    path = get_pumpbox_no_buy_2h_final_confirm_state_path()
    tmp_path = path + ".tmp"
    try:
        with open(tmp_path, "w", encoding="utf-8") as fh:
            json.dump(
                normalize_pumpbox_no_buy_2h_final_confirm_state(state),
                fh,
                ensure_ascii=False,
                indent=2,
                sort_keys=True,
            )
        os.replace(tmp_path, path)
    except Exception as exc:
        print(f"{COL_WARN}[PUMPBOX/GF+]{RESET} state save failed: {exc}")


def pumpbox_no_buy_2h_final_confirm_scan_state_buy_ts(scan_dt=None):
    """Best-effort bootstrap from the strategy state file when the small gate file is absent/stale."""
    try:
        states = load_strategy_states()
    except Exception:
        return None, None

    best_ts = None
    best_symbol = None
    for symbol, state in (states or {}).items():
        if not isinstance(state, dict):
            continue

        candidate_ts_values = []
        last_event_payload = state.get("last_event_payload") if isinstance(state.get("last_event_payload"), dict) else {}
        if normalize_strategy_stage_value(last_event_payload.get("stage")) == "buy":
            candidate_ts_values.extend([
                last_event_payload.get("signal_scan_ts"),
                last_event_payload.get("buy_signal_scan_ts"),
                last_event_payload.get("created_ts"),
                state.get("last_event_ts"),
                last_event_payload.get("candle_ts"),
                last_event_payload.get("candle_unix_ts"),
            ])
        if str(state.get("last_event") or "").strip().lower() == "buy":
            candidate_ts_values.append(state.get("last_event_ts"))
        if normalize_strategy_stage_value(state.get("stage")) in {"buy", "pumped"}:
            candidate_ts_values.extend([
                state.get("active_buy_entry_ts"),
                state.get("buy_event_ts"),
                state.get("buy_ts"),
                state.get("pumping_buy_started_ts"),
            ])

        for value in candidate_ts_values:
            ts_value = ts_to_int(value)
            if ts_value is None:
                continue
            if best_ts is None or ts_value > best_ts:
                best_ts = ts_value
                best_symbol = str(symbol or "").strip().upper() or None

    return best_ts, best_symbol


def pumpbox_no_buy_2h_final_confirm_load_effective_state(scan_dt=None):
    with PUMPBOX_NO_BUY_2H_FINAL_CONFIRM_STATE_LOCK:
        state = load_pumpbox_no_buy_2h_final_confirm_state_unlocked()
        fallback_ts, fallback_symbol = pumpbox_no_buy_2h_final_confirm_scan_state_buy_ts(scan_dt=scan_dt)
        current_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
        window_seconds = pumpbox_no_buy_2h_final_confirm_window_seconds()

        saved_buy_ts = ts_to_int(state.get("last_buy_signal_ts"))
        should_bootstrap = False
        if fallback_ts is not None and (saved_buy_ts is None or fallback_ts > saved_buy_ts):
            # Bootstrap only for a fresh/relevant BUY so a very old state entry cannot
            # suppress the intended no-BUY drought check after restart.
            if current_ts is None or fallback_ts >= (current_ts - window_seconds):
                should_bootstrap = True
        if should_bootstrap:
            state["last_buy_signal_ts"] = fallback_ts
            state["last_buy_signal_at"] = datetime.fromtimestamp(fallback_ts).strftime("%Y-%m-%d %H:%M:%S")
            state["last_buy_signal_symbol"] = fallback_symbol
            state["last_buy_signal_source"] = "strategy_state_bootstrap"
            save_pumpbox_no_buy_2h_final_confirm_state_unlocked(state)
        return state


def record_pumpbox_no_buy_2h_final_confirm_buy_signal(scan_dt=None, event=None, symbol=None, source=None):
    if scan_dt is None:
        scan_dt = get_tehran_now()
    current_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if current_ts is None:
        current_ts = int(time.time())

    event = event if isinstance(event, dict) else {}
    event_symbol = (
        symbol
        or event.get("symbol_udf")
        or event.get("symbol")
        or event.get("symbol_name")
        or event.get("base_symbol")
    )
    event_source = source or event.get("pumpbox_source") or event.get("source") or event.get("reason")

    with PUMPBOX_NO_BUY_2H_FINAL_CONFIRM_STATE_LOCK:
        state = load_pumpbox_no_buy_2h_final_confirm_state_unlocked()
        state["last_buy_signal_ts"] = current_ts
        state["last_buy_signal_at"] = scan_dt.strftime("%Y-%m-%d %H:%M:%S") if isinstance(scan_dt, datetime) else None
        state["last_buy_signal_symbol"] = str(event_symbol or "").strip().upper() or None
        state["last_buy_signal_source"] = str(event_source or "").strip() or None
        save_pumpbox_no_buy_2h_final_confirm_state_unlocked(state)


def _pumpbox_no_buy_2h_final_confirm_safe_float(value):
    try:
        number = float(value)
    except Exception:
        return None
    if not math.isfinite(number):
        return None
    return number


def pumpbox_no_buy_2h_final_confirm_status(candidate, scan_dt, pine_30m_status):
    current_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    window_seconds = pumpbox_no_buy_2h_final_confirm_window_seconds()
    pine_30m_status = pine_30m_status if isinstance(pine_30m_status, dict) else {}
    symbol = str(
        (candidate or {}).get("symbol_udf")
        or (candidate or {}).get("symbol")
        or ""
    ).strip().upper()

    status = {
        "enabled": pumpbox_no_buy_2h_final_confirm_enabled(),
        "required": False,
        "blocked": False,
        "passed": None,
        "reason": None,
        "window_seconds": window_seconds,
        "current_ts": current_ts,
        "symbol": symbol,
        "last_buy_signal_ts": None,
        "last_drought_check_ts": None,
        "seconds_since_last_buy_signal": None,
        "seconds_since_last_drought_check": None,
        "pma": pine_30m_status.get("pma"),
        "gf_plus": pine_30m_status.get("GF_pos"),
        "gf_plus_source": "GF_pos",
        "pma_above_gf_plus": False,
    }

    if not status["enabled"]:
        return status
    if current_ts is None:
        status["reason"] = "pumpbox final no-BUY 2h PMA>GF+ confirmer skipped because scan timestamp is unavailable"
        return status

    gate_state = pumpbox_no_buy_2h_final_confirm_load_effective_state(scan_dt=scan_dt)
    last_buy_ts = ts_to_int(gate_state.get("last_buy_signal_ts"))
    last_check_ts = ts_to_int(gate_state.get("last_drought_check_ts"))
    status["last_buy_signal_ts"] = last_buy_ts
    status["last_drought_check_ts"] = last_check_ts

    if last_buy_ts is not None:
        status["seconds_since_last_buy_signal"] = max(0, current_ts - last_buy_ts)
        if status["seconds_since_last_buy_signal"] < window_seconds:
            status["reason"] = "pumpbox final PMA>GF+ drought confirmer not required: a BUY signal exists inside the last 2 hours"
            return status

    if last_check_ts is not None:
        status["seconds_since_last_drought_check"] = max(0, current_ts - last_check_ts)
        if status["seconds_since_last_drought_check"] < window_seconds:
            status["reason"] = "pumpbox final PMA>GF+ drought confirmer already consumed for this 2-hour no-BUY window"
            return status

    status["required"] = True
    pma = _pumpbox_no_buy_2h_final_confirm_safe_float(pine_30m_status.get("pma"))
    gf_plus = _pumpbox_no_buy_2h_final_confirm_safe_float(pine_30m_status.get("GF_pos"))
    status["pma"] = pma
    status["gf_plus"] = gf_plus

    if pma is None or gf_plus is None:
        status["blocked"] = True
        status["passed"] = False
        status["reason"] = (
            "pumpbox skipped by final no-BUY 2h confirmer: Pine PMA/GF+ data is unavailable, "
            "so PMA cannot be proven above GF+"
        )
        return status

    status["pma_above_gf_plus"] = bool(pma > gf_plus)
    status["passed"] = bool(status["pma_above_gf_plus"])
    if status["passed"]:
        status["reason"] = (
            f"pumpbox final no-BUY 2h confirmer passed: PMA {pma:.6f} > GF+ {gf_plus:.6f}"
        )
        return status

    status["blocked"] = True
    status["reason"] = (
        f"pumpbox skipped by final no-BUY 2h confirmer: no BUY signal in the last 2 hours, "
        f"and PMA {pma:.6f} is not above GF+ {gf_plus:.6f}"
    )
    return status


def record_pumpbox_no_buy_2h_final_confirm_attempt(scan_dt, candidate=None, gate_status=None):
    gate_status = gate_status if isinstance(gate_status, dict) else {}
    current_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if current_ts is None:
        current_ts = int(time.time())
    symbol = str(
        (candidate or {}).get("symbol_udf")
        or (candidate or {}).get("symbol")
        or gate_status.get("symbol")
        or ""
    ).strip().upper() or None

    with PUMPBOX_NO_BUY_2H_FINAL_CONFIRM_STATE_LOCK:
        state = load_pumpbox_no_buy_2h_final_confirm_state_unlocked()
        state["last_drought_check_ts"] = current_ts
        state["last_drought_check_at"] = scan_dt.strftime("%Y-%m-%d %H:%M:%S") if isinstance(scan_dt, datetime) else None
        state["last_drought_check_symbol"] = symbol
        state["last_drought_check_passed"] = bool(gate_status.get("passed"))
        state["last_drought_check_reason"] = gate_status.get("reason")
        state["last_drought_check_pma"] = gate_status.get("pma")
        state["last_drought_check_gf_plus"] = gate_status.get("gf_plus")
        save_pumpbox_no_buy_2h_final_confirm_state_unlocked(state)

def is_pumpbox_active(state):
    return bool(isinstance(state, dict) and state.get("pumpbox_active"))


def clear_pumpbox_fields(state):
    if not isinstance(state, dict):
        return
    state["pumpbox_active"] = False
    state["pumpbox_entry_price"] = None
    state["pumpbox_entry_ts"] = None
    state["pumpbox_streak_base_price"] = None
    state["pumpbox_streak_base_ts"] = None
    state["pumpbox_streak_base_source"] = None
    state["pumpbox_reference_candle_ts"] = None
    state["pumpbox_started_ts"] = None
    state["pumpbox_started_at"] = None
    state["pumpbox_source"] = None
    state["pumpbox_buy_style"] = None
    state["pumpbox_from_bypass"] = False
    state["pumpbox_from_pending_buy"] = False
    state["pumpbox_from_shadow_pending_buy"] = False
    state["pumpbox_from_legacy_shadow_buy"] = False
    state["pumpbox_from_exact_2h_sandbox"] = False
    state["pumpbox_pending_buy_price"] = None
    state["pumpbox_possible_buy_price"] = None
    state["pumpbox_shadow_pending_buy_price"] = None
    state["pumpbox_reference_closed_candle_ts"] = None
    state["pumpbox_fib_bottom"] = None
    state["pumpbox_fib_top"] = None
    state["pumpbox_buy_event_extra"] = {}
    state["pumpbox_legacy_pending_shadow_after_buy"] = False
    state["pumpbox_legacy_sandbox_snapshot"] = {}
    state["pumpbox_real_buy_scan_ts"] = None
    state["pumpbox_confirm_above_since_ts"] = None
    state["pumpbox_confirm_above_since_at"] = None
    state["pumpbox_confirm_elapsed_seconds"] = None
    state["pumpbox_confirm_threshold_price"] = None
    state["pumpbox_confirm_pct"] = None
    state["pumpbox_confirm_hold_seconds"] = None
    state["pumpbox_last_note"] = None


def pumpbox_reference_price_from_candle(candle, fallback_price=None):
    for value in (
        fallback_price,
        (candle or {}).get("c") if isinstance(candle, dict) else None,
        (candle or {}).get("body_top") if isinstance(candle, dict) else None,
        (candle or {}).get("h") if isinstance(candle, dict) else None,
    ):
        price = _safe_positive_float(value)
        if price is not None:
            return price
    return None


def start_pumpbox(
    state,
    entry_candle,
    scan_dt,
    *,
    current_price=None,
    source="unknown",
    buy_style="pumping",
    from_bypass=False,
    from_pending_buy=False,
    from_shadow_pending_buy=False,
    from_legacy_shadow_buy=False,
    from_exact_2h_sandbox=False,
    pending_buy_price=None,
    possible_buy_price=None,
    shadow_pending_buy_price=None,
    event_extra=None,
    legacy_pending_shadow_after_buy=False,
    legacy_sandbox_snapshot=None,
):
    if not bool(ENABLE_PUMPBOX_GATE):
        return False
    if not isinstance(state, dict):
        return False

    if normalize_strategy_stage_value(state.get("stage")) in {"buy", "pumped"}:
        state["pumpbox_start_block_reason"] = "active real BUY already exists; pumpbox/pre-buy confirmation is disabled while in BUY"
        return False

    normalized_start_buy_style = normalize_buy_style(buy_style) or "pumping"
    if normalized_start_buy_style == "legacy" and not bool(ENABLE_LEGACY_BUY_FLOW):
        state["pumpbox_start_block_reason"] = "legacy buy flow disabled"
        return False

    entry_price = pumpbox_reference_price_from_candle(entry_candle, fallback_price=current_price)
    if entry_price is None:
        return False

    fib_rebuy_block = same_live_candle_fib_sell_rebuy_block_status(state, live_candle=entry_candle, scan_dt=scan_dt)
    if bool(fib_rebuy_block.get("blocked")):
        state["pumpbox_start_block_reason"] = fib_rebuy_block.get("reason")
        state["pumpbox_start_fib_sell_same_live_candle_rebuy_blocked"] = True
        state["pumpbox_start_live_candle_ts"] = fib_rebuy_block.get("live_candle_ts")
        state["pumpbox_start_last_fib_sell_live_candle_ts"] = fib_rebuy_block.get("last_fib_sell_live_candle_ts")
        return False

    live_sma18_gate = live_candle_green_with_optional_sma_stack_status(
        entry_candle,
        sma_stack_guard_enabled=bool(ENABLE_PUMPBOX_START_LIVE_SMA_STACK_GUARD),
        context_label="pumpbox start",
    )
    if not bool(live_sma18_gate.get("allowed")):
        state["pumpbox_start_block_reason"] = live_sma18_gate.get("effective_reason") or live_sma18_gate.get("reason")
        state["pumpbox_start_live_green_body_top_above_sma18_allowed"] = False
        state["pumpbox_start_live_sma_stack_guard_enabled"] = bool(ENABLE_PUMPBOX_START_LIVE_SMA_STACK_GUARD)
        state["pumpbox_start_live_sma_stack_raw_allowed"] = bool(live_sma18_gate.get("raw_allowed"))
        state["pumpbox_start_live_is_green"] = bool(live_sma18_gate.get("live_is_green"))
        state["pumpbox_start_live_body_top"] = live_sma18_gate.get("live_body_top")
        state["pumpbox_start_live_sma3"] = live_sma18_gate.get("live_sma3")
        state["pumpbox_start_live_sma18"] = live_sma18_gate.get("live_sma18")
        state["pumpbox_start_live_body_top_to_sma18_pct"] = live_sma18_gate.get("live_body_top_to_sma18_pct")
        state["pumpbox_start_live_sma3_to_sma18_pct"] = live_sma18_gate.get("live_sma3_to_sma18_pct")
        return False

    state["pumpbox_start_block_reason"] = None
    state["pumpbox_start_live_green_body_top_above_sma18_allowed"] = True
    state["pumpbox_start_live_sma_stack_guard_enabled"] = bool(ENABLE_PUMPBOX_START_LIVE_SMA_STACK_GUARD)
    state["pumpbox_start_live_sma_stack_raw_allowed"] = bool(live_sma18_gate.get("raw_allowed"))
    state["pumpbox_start_live_is_green"] = bool(live_sma18_gate.get("live_is_green"))
    state["pumpbox_start_live_body_top"] = live_sma18_gate.get("live_body_top")
    state["pumpbox_start_live_sma3"] = live_sma18_gate.get("live_sma3")
    state["pumpbox_start_live_sma18"] = live_sma18_gate.get("live_sma18")
    state["pumpbox_start_live_body_top_to_sma18_pct"] = live_sma18_gate.get("live_body_top_to_sma18_pct")
    state["pumpbox_start_live_sma3_to_sma18_pct"] = live_sma18_gate.get("live_sma3_to_sma18_pct")

    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if current_scan_ts is None:
        return False

    reference_ts = ts_to_int((entry_candle or {}).get("t")) if isinstance(entry_candle, dict) else None
    if reference_ts is None:
        reference_ts = current_scan_ts

    if is_exact_2h_sandbox_active(state) and sandbox_blocks_shadow_pending_buy() and not from_exact_2h_sandbox:
        # With sandbox instant BUY enabled, sandbox owns the pre-buy flow. Do not
        # wipe it or convert a non-sandbox BUY attempt into pumpbox. A sandbox
        # instant-breakout handoff may still enter pumpbox so the extra post-
        # pumpbox streak and pumpbox safety gates are enforced before real BUY.
        return False

    # Starting a new pumpbox clears old pumpbox/pre-buy leftovers but deliberately
    # does not set any sell cooldown. A failed pumpbox can re-enter immediately.
    clear_pumpbox_fields(state)
    if not from_exact_2h_sandbox:
        clear_all_exact_2h_sandbox_fields(state)
    clear_pending_buy_extension_window(state, "pending_buy")
    clear_pending_buy_extension_window(state, "shadow_pending_buy")

    # The pumpbox entry price is kept for debug/source compatibility, but the
    # required active-buy streak must start AFTER the pumpbox was created.
    # Therefore use a separate streak base anchored to the live price at the
    # pumpbox-start scan. This prevents the same pending-buy/direct-overlap
    # breakout assignment from also satisfying pumpbox confirmation.
    pumpbox_streak_base_price = _safe_positive_float(current_price) or entry_price

    state["pumpbox_active"] = True
    state["pumpbox_entry_price"] = entry_price
    state["pumpbox_entry_ts"] = current_scan_ts
    state["pumpbox_streak_base_price"] = pumpbox_streak_base_price
    state["pumpbox_streak_base_ts"] = current_scan_ts
    state["pumpbox_streak_base_source"] = "pumpbox_start_live_price" if _safe_positive_float(current_price) is not None else "pumpbox_entry_price"
    state["pumpbox_reference_candle_ts"] = reference_ts
    state["pumpbox_started_ts"] = current_scan_ts
    state["pumpbox_started_at"] = scan_dt.strftime("%Y-%m-%d %H:%M:%S") if isinstance(scan_dt, datetime) else None
    state["pumpbox_source"] = str(source or "unknown")
    state["pumpbox_buy_style"] = normalize_buy_style(buy_style) or "pumping"
    state["pumpbox_from_bypass"] = bool(from_bypass)
    state["pumpbox_from_pending_buy"] = bool(from_pending_buy)
    state["pumpbox_from_shadow_pending_buy"] = bool(from_shadow_pending_buy)
    state["pumpbox_from_legacy_shadow_buy"] = bool(from_legacy_shadow_buy)
    state["pumpbox_from_exact_2h_sandbox"] = bool(from_exact_2h_sandbox)
    state["pumpbox_pending_buy_price"] = pending_buy_price
    state["pumpbox_possible_buy_price"] = possible_buy_price if possible_buy_price is not None else pending_buy_price
    state["pumpbox_shadow_pending_buy_price"] = shadow_pending_buy_price
    state["pumpbox_reference_closed_candle_ts"] = state.get("tracking_reference_prev_closed_ts") or state.get("shadow_pending_buy_reference_prev_closed_ts")
    state["pumpbox_fib_bottom"] = state.get("fib_bottom") or state.get("shadow_pending_buy_fib_bottom")
    state["pumpbox_fib_top"] = state.get("fib_top") or state.get("shadow_pending_buy_fib_top")
    state["pumpbox_buy_event_extra"] = dict(event_extra or {})
    state["pumpbox_legacy_pending_shadow_after_buy"] = bool(legacy_pending_shadow_after_buy)
    state["pumpbox_legacy_sandbox_snapshot"] = dict(legacy_sandbox_snapshot or {})
    state["pumpbox_real_buy_scan_ts"] = None
    state["pumpbox_confirm_above_since_ts"] = None
    state["pumpbox_confirm_above_since_at"] = None
    state["pumpbox_confirm_elapsed_seconds"] = None
    state["pumpbox_confirm_threshold_price"] = None
    state["pumpbox_confirm_pct"] = float(PUMPBOX_CONFIRM_PCT)
    state["pumpbox_confirm_hold_seconds"] = int(PUMPBOX_CONFIRM_HOLD_SECONDS)
    state["pumpbox_last_note"] = "pumpbox started; waiting for fixed +1.00% confirmation held for 1 real minute after pumpbox entry"

    # Keep tracking fields when they describe the breakout source. Clear only
    # countdown/confirmation state so the pumpbox remains a clean pre-buy gate.
    set_state_scan_counter(state, "pending_buy_scan_count", 0, reset_reason="pumpbox started")
    set_state_scan_counter(state, "shadow_pending_buy_scan_count", 0, reset_reason="pumpbox started")
    state["pending_buy_confirmation_history"] = []
    state["shadow_pending_buy_confirmation_history"] = []

    return True


def pumpbox_closed_candles_since_start(state, candles):
    if not isinstance(state, dict) or not candles:
        return None
    start_ts = ts_to_int(state.get("pumpbox_started_ts") or state.get("pumpbox_entry_ts"))
    if start_ts is None:
        return None
    return closed_candles_finished_after_ts(candles, start_ts)


def pumpbox_current_price(current_price=None, live_candle=None, latest_closed_candle=None, candidate=None):
    price = _safe_positive_float(current_price)
    if price is not None:
        return price
    if isinstance(candidate, dict):
        price = resolve_current_market_price(
            candidate.get("latest_price"),
            live_candle if isinstance(live_candle, dict) else latest_closed_candle,
            prefer_candle=False,
            context=candidate,
        )
        if price is not None:
            return price
    if isinstance(live_candle, dict):
        for key in ("c", "body_top", "h"):
            price = _safe_positive_float(live_candle.get(key))
            if price is not None:
                return price
    if isinstance(latest_closed_candle, dict):
        return _safe_positive_float(latest_closed_candle.get("c"))
    return None


def pumpbox_first_streak_status(state, current_price=None):
    entry_price = _safe_positive_float((state or {}).get("pumpbox_entry_price"))
    streak_base_price = _safe_positive_float((state or {}).get("pumpbox_streak_base_price")) or entry_price
    probe_price = _safe_positive_float(current_price)
    try:
        confirm_pct = float(PUMPBOX_CONFIRM_PCT)
    except Exception:
        confirm_pct = 1.0

    status = {
        "reached": False,
        "entry_price": entry_price,
        "streak_base_price": streak_base_price,
        "streak_base_ts": ts_to_int((state or {}).get("pumpbox_streak_base_ts")),
        "streak_base_source": (state or {}).get("pumpbox_streak_base_source"),
        "current_price": probe_price,
        "required_streaks": int(PUMPBOX_REQUIRED_GREEN_STREAKS),
        "current_streaks": 0,
        "trigger_price": None,
        "confirm_pct": confirm_pct,
        "confirm_threshold_price": None,
        "confirm_threshold_reached": False,
    }
    if streak_base_price is None or probe_price is None:
        return status

    trigger_price = streak_base_price * (1.0 + (confirm_pct / 100.0))
    status["trigger_price"] = trigger_price
    status["confirm_threshold_price"] = trigger_price
    status["confirm_threshold_reached"] = probe_price >= trigger_price
    status["current_trigger_price"] = trigger_price
    status["current_streaks"] = 1 if status["confirm_threshold_reached"] else 0
    status["reached"] = bool(status["confirm_threshold_reached"])
    return status

def build_pumpbox_event(state, candle, current_price=None, reason=None, extra=None):
    # Pumpbox is intentionally a state flag, not a user-visible stage/signal/event.
    # Keep this compatibility helper non-emitting so future call sites cannot
    # accidentally produce signal=PUMPBOX / stage=pumpbox again.
    return None


def activate_real_buy_from_pumpbox(state, live_candle, scan_dt, *, current_price=None):
    if not isinstance(state, dict) or not is_pumpbox_active(state):
        return None
    if bool(globals().get("ONLY_ALLOW_PMA_GF_PLUS_FORCE_BUYS", False)):
        return None

    buy_style = normalize_buy_style(state.get("pumpbox_buy_style")) or "pumping"
    source = str(state.get("pumpbox_source") or "pumpbox").strip() or "pumpbox"
    entry_price = _safe_positive_float(state.get("pumpbox_entry_price"))
    real_buy_price = pumpbox_current_price(current_price=current_price, live_candle=live_candle)
    if real_buy_price is None:
        real_buy_price = entry_price
    if real_buy_price is None:
        return None

    buy_candle = build_live_price_buy_candle(live_candle, live_price=real_buy_price)
    if not isinstance(buy_candle, dict):
        return None
    # The pumpbox confirmation price is the actual real BUY price. Keep the
    # candle body aligned with that price so the unchecked BUY helpers do not
    # accidentally anchor entry/force-sell logic to an older live-candle body.
    candle_open = _safe_positive_float(buy_candle.get("o")) or real_buy_price
    buy_candle["c"] = real_buy_price
    buy_candle["h"] = max(_safe_positive_float(buy_candle.get("h")) or real_buy_price, real_buy_price)
    buy_candle["l"] = min(_safe_positive_float(buy_candle.get("l")) or real_buy_price, real_buy_price)
    buy_candle["body_top"] = max(candle_open, real_buy_price)
    buy_candle["body_bottom"] = min(candle_open, real_buy_price)

    pumpbox_snapshot = {
        "pumpbox_entry_price": state.get("pumpbox_entry_price"),
        "pumpbox_entry_ts": state.get("pumpbox_entry_ts"),
        "pumpbox_streak_base_price": state.get("pumpbox_streak_base_price"),
        "pumpbox_streak_base_ts": state.get("pumpbox_streak_base_ts"),
        "pumpbox_streak_base_source": state.get("pumpbox_streak_base_source"),
        "pumpbox_started_ts": state.get("pumpbox_started_ts"),
        "pumpbox_started_at": state.get("pumpbox_started_at"),
        "pumpbox_source": source,
        "pumpbox_buy_style": buy_style,
        "pumpbox_from_pending_buy": bool(state.get("pumpbox_from_pending_buy")),
        "pumpbox_from_shadow_pending_buy": bool(state.get("pumpbox_from_shadow_pending_buy")),
        "pumpbox_from_legacy_shadow_buy": bool(state.get("pumpbox_from_legacy_shadow_buy")),
        "pumpbox_from_exact_2h_sandbox": bool(state.get("pumpbox_from_exact_2h_sandbox")),
        "pumpbox_reference_closed_candle_ts": state.get("pumpbox_reference_closed_candle_ts"),
        "pumpbox_fib_bottom": state.get("pumpbox_fib_bottom"),
        "pumpbox_fib_top": state.get("pumpbox_fib_top"),
        "pumpbox_pending_buy_price": state.get("pumpbox_pending_buy_price"),
        "pumpbox_possible_buy_price": state.get("pumpbox_possible_buy_price"),
        "pumpbox_shadow_pending_buy_price": state.get("pumpbox_shadow_pending_buy_price"),
        "pumpbox_legacy_sandbox_snapshot": dict(state.get("pumpbox_legacy_sandbox_snapshot") or {}),
    }
    event_extra = dict(state.get("pumpbox_buy_event_extra") or {})

    if buy_style == "legacy" and not bool(state.get("pumpbox_from_shadow_pending_buy")):
        from_bypass = bool(state.get("pumpbox_from_bypass"))
        legacy_pending_shadow_after_buy = bool(state.get("pumpbox_legacy_pending_shadow_after_buy"))
        legacy_sandbox_snapshot = dict(state.get("pumpbox_legacy_sandbox_snapshot") or {})
        clear_pumpbox_fields(state)
        activate_legacy_buy_state_unchecked(state, buy_candle, from_bypass=from_bypass, scan_dt=scan_dt)
        reset_active_buy_anchor_to_real_buy_price(state, real_buy_price, scan_dt=scan_dt)
        if legacy_pending_shadow_after_buy:
            state["exact_2h_sandbox_pending_shadow_after_buy"] = True
            state["exact_2h_sandbox_buy_scan_ts"] = state.get("active_buy_entry_ts")
            state["exact_2h_sandbox_real_entry_price"] = real_buy_price
            # Preserve sandbox data for the existing next-scan shadow/rollover path.
            state["exact_2h_sandbox_entry_price"] = legacy_sandbox_snapshot.get("exact_2h_sandbox_entry_price")
            state["exact_2h_sandbox_entry_ts"] = legacy_sandbox_snapshot.get("exact_2h_sandbox_entry_ts")
            state["exact_2h_sandbox_reference_candle_ts"] = legacy_sandbox_snapshot.get("exact_2h_sandbox_reference_candle_ts")
            state["exact_2h_sandbox_confirm_scan_count"] = legacy_sandbox_snapshot.get("exact_2h_sandbox_confirm_scan_count")
            state["exact_2h_sandbox_source"] = legacy_sandbox_snapshot.get("exact_2h_sandbox_source") or source
        reason = f"pumpbox held fixed +{PUMPBOX_CONFIRM_PCT:.3f}% confirmation by current price; legacy real BUY activated from {source}"
        merged_extra = {
            **event_extra,
            **pumpbox_snapshot,
            **active_buy_identity_event_extra(state, fallback_entry_price=real_buy_price),
            "price": real_buy_price,
            "buy_style": "legacy",
            "buy_from_pending_buy": False,
            "pumpbox_real_buy_confirmed": True,
            "active_buy_green_count_at_buy": pumpbox_first_streak_status(pumpbox_snapshot, real_buy_price).get("current_streaks"),
        }
        return make_event("buy", reason, buy_candle, merged_extra)

    from_legacy_shadow = bool(state.get("pumpbox_from_legacy_shadow_buy")) or (buy_style == "legacy" and bool(state.get("pumpbox_from_shadow_pending_buy")))
    from_shadow = bool(state.get("pumpbox_from_shadow_pending_buy"))
    from_exact_sandbox = bool(state.get("pumpbox_from_exact_2h_sandbox"))
    shadow_price = state.get("pumpbox_shadow_pending_buy_price")
    pending_buy_price = state.get("pumpbox_pending_buy_price")
    possible_buy_price = state.get("pumpbox_possible_buy_price")

    clear_pumpbox_fields(state)
    if from_shadow:
        # Shadow/rollover BUY is a continuation marker, not the first real BUY.
        # Keep the original active-BUY PnL anchor that was reset at the first
        # real BUY; do not reset active_buy_entry_price/force-sell reference here.
        promote_buy_state_from_shadow_pending_buy_unchecked(
            state,
            buy_candle,
            scan_dt,
            from_legacy_buy=from_legacy_shadow,
            source_name=source,
            from_exact_2h_sandbox=from_exact_sandbox,
        )
        if from_legacy_shadow:
            arm_legacy_shadow_buy_rollover_next_scan(state, scan_dt, reference_candle=buy_candle, live_candle=buy_candle)
        reason = f"pumpbox held fixed +{PUMPBOX_CONFIRM_PCT:.3f}% confirmation by current price; shadow pending-buy real BUY activated from {source}"
        merged_extra = {
            **event_extra,
            **pumpbox_snapshot,
            **active_buy_identity_event_extra(state, fallback_entry_price=real_buy_price),
            "price": real_buy_price,
            "pending_buy_price": shadow_price or pending_buy_price,
            "possible_buy_price": possible_buy_price or shadow_price or pending_buy_price,
            "shadow_pending_buy_price": shadow_price,
            "buy_style": "pumping",
            "buy_from_shadow_pending_buy": True,
            "buy_from_legacy_shadow_buy": bool(from_legacy_shadow),
            "pumpbox_real_buy_confirmed": True,
        }
        return make_event("buy", reason, buy_candle, merged_extra)

    promote_buy_state_unchecked(state, buy_candle, scan_dt)
    reset_active_buy_anchor_to_real_buy_price(state, real_buy_price, scan_dt=scan_dt)
    reason = f"pumpbox held fixed +{PUMPBOX_CONFIRM_PCT:.3f}% confirmation by current price; pumping real BUY activated from {source}"
    merged_extra = {
        **event_extra,
        **pumpbox_snapshot,
        **active_buy_identity_event_extra(state, fallback_entry_price=real_buy_price),
        "price": real_buy_price,
        "pending_buy_price": pending_buy_price,
        "possible_buy_price": possible_buy_price or pending_buy_price,
        "buy_style": "pumping",
        "buy_from_pending_buy": bool(pending_buy_price is not None or pumpbox_snapshot.get("pumpbox_from_pending_buy")),
        "pumpbox_real_buy_confirmed": True,
    }
    if pending_buy_price is not None:
        state["pending_buy_price"] = pending_buy_price
        state["possible_buy_price"] = possible_buy_price or pending_buy_price
    return make_event("buy", reason, buy_candle, merged_extra)


def reset_pumpbox_confirmation_hold(state):
    if not isinstance(state, dict):
        return
    state["pumpbox_confirm_above_since_ts"] = None
    state["pumpbox_confirm_above_since_at"] = None
    state["pumpbox_confirm_elapsed_seconds"] = None


def process_pumpbox(state, candidate, candles, live_candle, latest_closed_candle, scan_dt, current_price=None, pine_30m_guard_status=None):
    status = {
        "active": is_pumpbox_active(state),
        "event": None,
        "note": None,
        "reset": False,
        "confirmed": False,
        "skip_current_coin": False,
    }
    if not status["active"]:
        return status
    if bool(globals().get("ONLY_ALLOW_PMA_GF_PLUS_FORCE_BUYS", False)):
        status["note"] = "force-buy-only mode active; pumpbox skipped"
        return status

    pine_30m_guard_status = pine_30m_guard_status if isinstance(pine_30m_guard_status, dict) else {}
    status["pine_30m_confirm_guard_enabled"] = bool(pine_30m_guard_status.get("guard_enabled"))
    status["pine_30m_confirm_guard_blocked"] = bool(pine_30m_guard_status.get("guard_blocked"))
    status["pine_30m_pma_available"] = bool(pine_30m_guard_status.get("pma_available"))
    status["pine_30m_pma"] = pine_30m_guard_status.get("pma")
    status["pine_30m_middle_line"] = pine_30m_guard_status.get("middle_line")
    status["pine_30m_pma_guard_add"] = pine_30m_guard_status.get("pma_guard_add")
    status["pine_30m_pma_guard_line_mode"] = pine_30m_guard_status.get("pma_guard_line_mode")
    status["pine_30m_pma_guard_line_source"] = pine_30m_guard_status.get("pma_guard_line_source")
    status["pine_30m_pma_required_line"] = pine_30m_guard_status.get("pma_required_line")
    status["pine_30m_pma_above_required_line"] = bool(pine_30m_guard_status.get("pma_above_required_line"))

    if normalize_buy_style(state.get("pumpbox_buy_style")) == "legacy" and not bool(ENABLE_LEGACY_BUY_FLOW):
        clear_pumpbox_fields(state)
        clear_all_exact_2h_sandbox_fields(state)
        clear_shadow_pending_buy_fields(state, reset_reason="legacy buy flow disabled")
        status["active"] = False
        status["reset"] = True
        status["note"] = "legacy buy flow disabled; legacy pumpbox was cleared"
        return status

    live_price = pumpbox_current_price(
        current_price=current_price,
        live_candle=live_candle,
        latest_closed_candle=latest_closed_candle,
        candidate=candidate,
    )
    streak_status = pumpbox_first_streak_status(state, live_price)
    status.update(streak_status)

    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    pumpbox_streak_base_ts = ts_to_int(state.get("pumpbox_streak_base_ts") or state.get("pumpbox_started_ts") or state.get("pumpbox_entry_ts"))
    status["pumpbox_streak_base_ts"] = pumpbox_streak_base_ts
    if current_scan_ts is not None and pumpbox_streak_base_ts is not None and current_scan_ts <= pumpbox_streak_base_ts:
        closed_count = pumpbox_closed_candles_since_start(state, candles)
        status["closed_candles_since_pumpbox"] = closed_count
        status["note"] = (
            "pumpbox just started; fixed +1.00% confirmation timer starts after pumpbox entry "
            f"(threshold reached={bool(streak_status.get('confirm_threshold_reached'))})"
        )
        return status

    # V3 safety: an already-open pumpbox still cannot confirm into a real BUY
    # unless the coin's current 24h change satisfies ENTRY_MIN_24H_CHANGE_PCT.
    # V4 safety: the latest closed candle must also be non-flat versus the
    # previous closed candle by more than ENTRY_CLOSED_FLAT_CHANGE_PCT.
    # V5/V2 safety: the live candle must be green, its body-top must be above live SMA18, and live SMA3 must be above live SMA18.
    # V7 safety: active pumpbox confirmation must also require the live body-top
    # to break the current reference closed wick-top by BUY_BREAKOUT_TOTAL_PCT.
    # These protect pumpboxes created by an older process before the latest gates.
    fib_rebuy_block = same_live_candle_fib_sell_rebuy_block_status(state, live_candle=live_candle, scan_dt=scan_dt)
    status["fib_sell_same_live_candle_rebuy_blocked"] = bool(fib_rebuy_block.get("blocked"))
    if bool(fib_rebuy_block.get("blocked")):
        reset_pumpbox_confirmation_hold(state)
        status["note"] = fib_rebuy_block.get("reason")
        return status

    pma_downcross_block = pine_30m_df0_downcross_buy_block_status(pine_30m_guard_status)
    status["pine_30m_pma_df0_downcross_buy_blocked"] = bool(pma_downcross_block.get("blocked"))
    if bool(pma_downcross_block.get("blocked")):
        reset_pumpbox_confirmation_hold(state)
        status["note"] = pma_downcross_block.get("reason")
        return status

    entry_24h_gate = entry_24h_requirement_status(candidate, candles=candles, live_candle=live_candle)
    status["entry_allowed"] = bool(entry_24h_gate.get("allowed"))
    status["entry_block_reason"] = entry_24h_gate.get("reason")
    status["entry_24h_closed_pct"] = entry_24h_gate.get("closed_24h_pct")
    status["entry_24h_live_pct"] = entry_24h_gate.get("live_24h_pct")
    status["entry_24h_required_pct"] = entry_24h_gate.get("required_pct")
    status["entry_24h_source"] = entry_24h_gate.get("source")
    if not status["entry_allowed"]:
        reset_pumpbox_confirmation_hold(state)
        status["note"] = entry_24h_gate.get("reason")
        return status

    prev_closed_for_non_flat = candles[-2] if isinstance(candles, list) and len(candles) >= 2 else None
    latest_closed_for_non_flat = candles[-1] if isinstance(candles, list) and len(candles) >= 1 else latest_closed_candle
    non_flat_gate = latest_closed_non_flat_requirement_status(prev_closed_for_non_flat, latest_closed_for_non_flat)
    status["latest_closed_non_flat_allowed"] = bool(non_flat_gate.get("allowed"))
    status["latest_closed_non_flat_block_reason"] = non_flat_gate.get("reason")
    status["latest_closed_vs_prev_pct"] = non_flat_gate.get("latest_vs_prev_pct")
    status["latest_closed_non_flat_required_abs_pct"] = non_flat_gate.get("required_abs_pct")
    if not status["latest_closed_non_flat_allowed"]:
        reset_pumpbox_confirmation_hold(state)
        status["note"] = non_flat_gate.get("reason")
        return status

    live_sma18_gate = live_candle_green_with_optional_sma_stack_status(
        live_candle,
        sma_stack_guard_enabled=bool(ENABLE_PUMPBOX_CONFIRM_LIVE_SMA_STACK_GUARD),
        context_label="pumpbox confirmation",
    )
    status["live_green_body_top_above_sma18_allowed"] = bool(live_sma18_gate.get("allowed"))
    status["live_green_body_top_above_sma18_raw_allowed"] = bool(live_sma18_gate.get("raw_allowed"))
    status["live_sma_stack_guard_enabled"] = bool(ENABLE_PUMPBOX_CONFIRM_LIVE_SMA_STACK_GUARD)
    status["live_green_body_top_above_sma18_block_reason"] = live_sma18_gate.get("effective_reason") or live_sma18_gate.get("reason")
    status["live_is_green"] = bool(live_sma18_gate.get("live_is_green"))
    status["live_body_top"] = live_sma18_gate.get("live_body_top")
    status["live_sma3"] = live_sma18_gate.get("live_sma3")
    status["live_sma18"] = live_sma18_gate.get("live_sma18")
    status["live_body_top_to_sma18_pct"] = live_sma18_gate.get("live_body_top_to_sma18_pct")
    status["live_sma3_to_sma18_pct"] = live_sma18_gate.get("live_sma3_to_sma18_pct")
    if not status["live_green_body_top_above_sma18_allowed"]:
        reset_pumpbox_confirmation_hold(state)
        status["note"] = live_sma18_gate.get("effective_reason") or live_sma18_gate.get("reason")
        return status

    current_reference_breakout_gate = live_body_top_current_reference_breakout_status(
        candles,
        live_candle or latest_closed_candle,
        breakout_pct=BUY_BREAKOUT_TOTAL_PCT,
    )
    status["live_body_top_current_reference_breakout_allowed"] = bool(current_reference_breakout_gate.get("allowed"))
    status["live_body_top_current_reference_breakout_block_reason"] = current_reference_breakout_gate.get("reason")
    status["current_reference_closed_wick_top"] = current_reference_breakout_gate.get("reference_closed_wick_top")
    status["current_reference_closed_raw_wick_top"] = current_reference_breakout_gate.get("reference_closed_raw_wick_top")
    status["current_reference_closed_body_top"] = current_reference_breakout_gate.get("reference_closed_body_top")
    status["current_reference_breakout_top_source"] = current_reference_breakout_gate.get("reference_breakout_top_source")
    status["current_reference_body_top_used_due_to_upper_wick"] = bool(current_reference_breakout_gate.get("reference_body_top_used_due_to_upper_wick"))
    status["current_reference_upper_wick_pct"] = current_reference_breakout_gate.get("reference_upper_wick_pct")
    status["current_reference_body_size_pct"] = current_reference_breakout_gate.get("reference_body_size_pct")
    status["current_reference_upper_wick_body_margin_pct"] = current_reference_breakout_gate.get("reference_upper_wick_body_margin_pct")
    status["current_reference_breakout_threshold"] = current_reference_breakout_gate.get("live_breakout_threshold")
    status["current_reference_breakout_needed_pct"] = current_reference_breakout_gate.get("breakout_needed_pct")
    status["current_reference_live_body_top"] = current_reference_breakout_gate.get("live_body_top")
    status["current_reference_live_high"] = current_reference_breakout_gate.get("live_high")
    status["current_reference_live_body_vs_threshold_pct"] = current_reference_breakout_gate.get("live_body_vs_breakout_threshold_pct")
    status["current_reference_live_high_vs_threshold_pct"] = current_reference_breakout_gate.get("live_high_vs_breakout_threshold_pct")
    if not status["live_body_top_current_reference_breakout_allowed"]:
        reset_pumpbox_confirmation_hold(state)
        status["note"] = current_reference_breakout_gate.get("reason")
        return status

    rejection_guard = buy_rejection_guard_status(state, current_price=live_price, live_candle=live_candle or latest_closed_candle)
    status["buy_rejection_guard_active"] = bool(rejection_guard.get("active"))
    status["buy_rejection_guard_allowed"] = bool(rejection_guard.get("allowed"))
    status["buy_rejection_guard_cleared"] = bool(rejection_guard.get("cleared"))
    status["buy_rejection_guard_high"] = rejection_guard.get("guard_high")
    status["buy_rejection_guard_current_price"] = rejection_guard.get("current_price")
    status["buy_rejection_guard_current_price_vs_high_pct"] = rejection_guard.get("current_price_vs_guard_high_pct")
    status["buy_rejection_guard_rejection_wick_pct"] = rejection_guard.get("guard_rejection_wick_pct")
    status["buy_rejection_guard_min_wick_pct"] = rejection_guard.get("guard_min_wick_pct")
    if not bool(rejection_guard.get("allowed", True)):
        reset_pumpbox_confirmation_hold(state)
        status["note"] = rejection_guard.get("reason")
        return status

    if bool(pine_30m_guard_status.get("guard_blocked")):
        reset_pumpbox_confirmation_hold(state)
        status["confirm_guard_blocked"] = True
        status["note"] = pine_30m_guard_note("pumpbox", pine_30m_guard_status)
        return status

    try:
        confirm_hold_seconds = max(0, int(PUMPBOX_CONFIRM_HOLD_SECONDS))
    except Exception:
        confirm_hold_seconds = 60
    status["confirm_pct"] = streak_status.get("confirm_pct")
    status["confirm_threshold_price"] = streak_status.get("confirm_threshold_price") or streak_status.get("trigger_price")
    status["confirm_hold_seconds"] = confirm_hold_seconds
    status["confirm_threshold_reached"] = bool(streak_status.get("confirm_threshold_reached") or streak_status.get("reached"))

    if status["confirm_threshold_reached"]:
        above_since_ts = ts_to_int(state.get("pumpbox_confirm_above_since_ts"))
        if above_since_ts is None:
            above_since_ts = current_scan_ts
            state["pumpbox_confirm_above_since_ts"] = above_since_ts
            state["pumpbox_confirm_above_since_at"] = scan_dt.strftime("%Y-%m-%d %H:%M:%S") if isinstance(scan_dt, datetime) else None
        elapsed_seconds = max(0, (current_scan_ts or above_since_ts) - above_since_ts) if current_scan_ts is not None else 0
        state["pumpbox_confirm_elapsed_seconds"] = elapsed_seconds
        state["pumpbox_confirm_threshold_price"] = status.get("confirm_threshold_price")
        state["pumpbox_confirm_pct"] = status.get("confirm_pct")
        state["pumpbox_confirm_hold_seconds"] = confirm_hold_seconds
        status["confirm_above_since_ts"] = above_since_ts
        status["confirm_above_since_at"] = state.get("pumpbox_confirm_above_since_at")
        status["confirm_elapsed_seconds"] = elapsed_seconds
        status["confirm_hold_ready"] = elapsed_seconds >= confirm_hold_seconds

        if status["confirm_hold_ready"]:
            drought_gate = pumpbox_no_buy_2h_final_confirm_status(candidate, scan_dt, pine_30m_guard_status)
            status["pumpbox_no_buy_2h_pma_gf_plus_final_confirm_enabled"] = bool(drought_gate.get("enabled"))
            status["pumpbox_no_buy_2h_pma_gf_plus_final_confirm_required"] = bool(drought_gate.get("required"))
            status["pumpbox_no_buy_2h_pma_gf_plus_final_confirm_blocked"] = bool(drought_gate.get("blocked"))
            status["pumpbox_no_buy_2h_pma_gf_plus_final_confirm_passed"] = drought_gate.get("passed")
            status["pumpbox_no_buy_2h_pma_gf_plus_final_confirm_reason"] = drought_gate.get("reason")
            status["pumpbox_no_buy_2h_pma_gf_plus_final_confirm_pma"] = drought_gate.get("pma")
            status["pumpbox_no_buy_2h_pma_gf_plus_final_confirm_gf_plus"] = drought_gate.get("gf_plus")
            status["pumpbox_no_buy_2h_pma_gf_plus_final_confirm_last_buy_signal_ts"] = drought_gate.get("last_buy_signal_ts")
            status["pumpbox_no_buy_2h_pma_gf_plus_final_confirm_last_check_ts"] = drought_gate.get("last_drought_check_ts")
            if bool(drought_gate.get("required")) and bool(drought_gate.get("blocked")):
                record_pumpbox_no_buy_2h_final_confirm_attempt(scan_dt, candidate=candidate, gate_status=drought_gate)
                clear_pumpbox_fields(state)
                status["active"] = False
                status["reset"] = True
                status["skip_current_coin"] = True
                status["confirm_guard_blocked"] = True
                status["note"] = drought_gate.get("reason")
                return status

            event = activate_real_buy_from_pumpbox(state, live_candle or latest_closed_candle, scan_dt, current_price=live_price)
            if isinstance(event, dict):
                if bool(drought_gate.get("required")):
                    record_pumpbox_no_buy_2h_final_confirm_attempt(scan_dt, candidate=candidate, gate_status=drought_gate)
                status["event"] = event
                status["confirmed"] = True
                status["note"] = (
                    f"pumpbox confirmed: current price held above fixed +{float(status.get('confirm_pct') or PUMPBOX_CONFIRM_PCT):.3f}% "
                    f"threshold for {elapsed_seconds}s/{confirm_hold_seconds}s after pumpbox entry"
                )
                return status
            status["note"] = "pumpbox held fixed confirmation threshold but real BUY candle could not be built"
            return status

        status["note"] = (
            f"pumpbox fixed +{float(status.get('confirm_pct') or PUMPBOX_CONFIRM_PCT):.3f}% threshold reached; "
            f"waiting for 1-minute hold ({elapsed_seconds}s/{confirm_hold_seconds}s)"
        )
        return status

    reset_pumpbox_confirmation_hold(state)

    closed_count = pumpbox_closed_candles_since_start(state, candles)
    status["closed_candles_since_pumpbox"] = closed_count
    if closed_count is not None and closed_count >= int(PUMPBOX_MAX_CLOSED_CANDLES):
        clear_pumpbox_fields(state)
        status["reset"] = True
        status["note"] = (
            f"pumpbox reset without cooldown after {closed_count} closed candles "
            "because current price did not hold the fixed +1.00% confirmation threshold after pumpbox entry"
        )
        return status

    status["note"] = (
        f"pumpbox waiting for fixed +{float(streak_status.get('confirm_pct') or PUMPBOX_CONFIRM_PCT):.3f}% confirmation after pumpbox entry; "
        f"threshold={fmt_price_auto(streak_status.get('trigger_price'))}; "
        f"closed candles since pumpbox={closed_count}"
    )
    return status


def attach_pumpbox_status_to_result(result, pumpbox_status):
    """Expose pumpbox flag anchors in scan logs without changing strategy behavior."""
    if not isinstance(result, dict) or not isinstance(pumpbox_status, dict):
        return result

    result["pumpbox_active"] = bool(pumpbox_status.get("active"))
    result["pumpbox_entry_price"] = pumpbox_status.get("entry_price")
    result["pumpbox_streak_base_price"] = pumpbox_status.get("streak_base_price")
    result["pumpbox_streak_base_ts"] = pumpbox_status.get("streak_base_ts")
    result["pumpbox_streak_base_source"] = pumpbox_status.get("streak_base_source")
    result["pumpbox_trigger_price"] = pumpbox_status.get("trigger_price")
    result["pumpbox_confirm_pct"] = pumpbox_status.get("confirm_pct")
    result["pumpbox_confirm_threshold_price"] = pumpbox_status.get("confirm_threshold_price")
    result["pumpbox_confirm_threshold_reached"] = bool(pumpbox_status.get("confirm_threshold_reached"))
    result["pumpbox_confirm_hold_seconds"] = pumpbox_status.get("confirm_hold_seconds")
    result["pumpbox_confirm_above_since_ts"] = pumpbox_status.get("confirm_above_since_ts")
    result["pumpbox_confirm_elapsed_seconds"] = pumpbox_status.get("confirm_elapsed_seconds")
    result["pumpbox_confirm_hold_ready"] = bool(pumpbox_status.get("confirm_hold_ready"))
    result["pumpbox_current_price"] = pumpbox_status.get("current_price")
    result["pumpbox_current_streaks"] = pumpbox_status.get("current_streaks")
    result["pumpbox_required_streaks"] = pumpbox_status.get("required_streaks")
    result["pumpbox_closed_candles_since_start"] = pumpbox_status.get("closed_candles_since_pumpbox")
    result["pumpbox_reached"] = bool(pumpbox_status.get("reached"))
    result["pumpbox_pine_30m_confirm_guard_enabled"] = bool(pumpbox_status.get("pine_30m_confirm_guard_enabled"))
