def clear_pumping_fields(state):
    if not isinstance(state, dict):
        return
    state["pumping_ts"] = None
    state["pumping_24h_pct"] = None



def sync_pending_buy_legacy_fields(state):
    if not isinstance(state, dict):
        return
    if state.get("pending_buy_ts") is not None:
        state["possible_buy_ts"] = state.get("pending_buy_ts")
        state["possible_buy_signal_scan_ts"] = state.get("pending_buy_ts")
    if state.get("pending_buy_price") is not None:
        state["possible_buy_price"] = state.get("pending_buy_price")



def normalize_buy_style(value):
    text = str(value or "").strip().lower()
    if text in {"pumping", "legacy"}:
        return text
    return None



def infer_buy_style(state):
    if not isinstance(state, dict):
        return None

    buy_style = normalize_buy_style(state.get("buy_style"))
    if buy_style:
        return buy_style

    stage = str(state.get("stage") or "").strip().lower()

    if stage in {"buy", "pumped"}:
        return "pumping" if bool(state.get("buy_from_pending_buy")) else "legacy"

    if stage == "pending_buy":
        return "pumping"

    if bool(state.get("buy_from_pending_buy")):
        return "pumping"

    if state.get("pending_buy_ts") or state.get("tracking_reference_prev_closed_ts") or state.get("fib_bottom") or state.get("fib_top"):
        return "pumping"

    if state.get("buy_ts"):
        return "legacy"

    return None



def is_pumping_style_buy(state):
    return infer_buy_style(state) == "pumping"



def is_shadow_pending_buy_buy(state):
    return bool((state or {}).get("buy_from_shadow_pending_buy"))



def is_legacy_shadow_buy(state):
    return bool((state or {}).get("buy_from_legacy_shadow_buy"))



def is_direct_pumping_pending_buy(state):
    return (
        is_pumping_style_buy(state) and
        bool((state or {}).get("buy_from_pending_buy")) and
        not is_legacy_shadow_buy(state)
    )



def is_unconditional_rollover_buy(state):
    return is_direct_pumping_pending_buy(state) or is_legacy_shadow_buy(state)



def is_fib_bottom_force_sell_buy(state):
    if not ENABLE_FIB_BOTTOM_SELL_BEHAVIOR:
        return False
    return is_direct_pumping_pending_buy(state) or is_legacy_shadow_buy(state)



def get_live_force_sell_reference(state):
    entry_price = _safe_positive_float((state or {}).get("entry_price"))
    active_buy_entry_price = _safe_positive_float((state or {}).get("active_buy_entry_price"))
    if is_pumping_style_buy(state) and bool((state or {}).get("rollover_active")):
        rollover_reference_body_top = _safe_positive_float((state or {}).get("rollover_reference_body_top"))
        if rollover_reference_body_top is not None:
            return rollover_reference_body_top, "rollover green candle body top", "rollover_body_top"
    if is_pumping_style_buy(state):
        breakout_reference_wick_top = _safe_positive_float((state or {}).get("active_buy_force_sell_reference_price"))
        if breakout_reference_wick_top is not None:
            return breakout_reference_wick_top, "selected breakout wick top", "breakout_wick_top"
        if active_buy_entry_price is not None:
            return active_buy_entry_price, "active buy price", "active_buy_entry_price"
    return entry_price, "buy price", "entry_price"




def active_buy_management_force_sell_reference(state):
    """
    Reference used by the universal active BUY force-sell guard.

    For pumping buys this intentionally prefers active_buy_entry_price because
    that is the same management anchor used by active-buy status PnL. The older
    get_live_force_sell_reference() may switch to breakout/rollover references,
    which is useful for strategy exits but can delay the simple live stop.
    """
    if not isinstance(state, dict):
        return None, "buy price", "entry_price"

    entry_price = _safe_positive_float(state.get("entry_price"))
    active_buy_entry_price = _safe_positive_float(state.get("active_buy_entry_price"))

    if is_pumping_style_buy(state) and active_buy_entry_price is not None:
        return active_buy_entry_price, "active buy price", "active_buy_entry_price"

    if entry_price is not None:
        return entry_price, "buy price", "entry_price"

    if active_buy_entry_price is not None:
        return active_buy_entry_price, "active buy price", "active_buy_entry_price"

    return None, "buy price", "entry_price"



