def active_buy_profit_pullback_candle_window_status(current_forming_candle, scan_dt=None):
    age_minutes = current_candle_age_minutes(current_forming_candle, scan_dt=scan_dt)
    status = {
        "age_minutes": age_minutes,
        "first_window": False,
        "last_window": False,
        "midpoint_window": False,
        "allowed": False,
        "stale": False,
        "window_minutes": ACTIVE_BUY_PROFIT_PULLBACK_WINDOW_MINUTES,
        "candle_minutes": ACTIVE_BUY_PROFIT_PULLBACK_CANDLE_MINUTES,
        "midpoint_minute": ACTIVE_BUY_PROFIT_PULLBACK_MIDPOINT_MINUTE,
        "midpoint_window_minutes": ACTIVE_BUY_PROFIT_PULLBACK_MIDPOINT_WINDOW_MINUTES,
    }
    if age_minutes is None:
        return status

    try:
        window_minutes = max(0.0, float(ACTIVE_BUY_PROFIT_PULLBACK_WINDOW_MINUTES))
    except Exception:
        window_minutes = 5.0
    try:
        candle_minutes = max(0.0, float(ACTIVE_BUY_PROFIT_PULLBACK_CANDLE_MINUTES))
    except Exception:
        candle_minutes = 30.0
    try:
        midpoint_minute = max(0.0, float(ACTIVE_BUY_PROFIT_PULLBACK_MIDPOINT_MINUTE))
    except Exception:
        midpoint_minute = 15.0
    try:
        midpoint_window_minutes = max(0.0, float(ACTIVE_BUY_PROFIT_PULLBACK_MIDPOINT_WINDOW_MINUTES))
    except Exception:
        midpoint_window_minutes = 1.0

    status["window_minutes"] = window_minutes
    status["candle_minutes"] = candle_minutes
    status["midpoint_minute"] = midpoint_minute
    status["midpoint_window_minutes"] = midpoint_window_minutes

    # The v4 pullback rule is explicitly tied to the current 30m candle age.
    # If the live/current candle is stale or unavailable, do not treat an old
    # closed candle as being in the last-window and do not sell from this rule.
    if candle_minutes > 0 and age_minutes > candle_minutes:
        status["stale"] = True
        return status

    status["first_window"] = age_minutes <= window_minutes
    status["last_window"] = age_minutes >= max(0.0, candle_minutes - window_minutes)
    status["midpoint_window"] = abs(age_minutes - midpoint_minute) <= midpoint_window_minutes
    status["allowed"] = bool(status["first_window"] or status["last_window"] or status["midpoint_window"])
    return status


def maybe_sell_active_buy_profit_pullback_before_second_streak(state, candidate, latest_closed_candle, current_forming_candle, scan_dt, current_price=None):
    """
    V4 live profit-pullback guard.

    While any real active BUY style (legacy or pumping/rollover) has not reached
    the second active-buy green streak, arm after live PnL from the active BUY
    price exceeds the configured arm percent. If the position trades above the
    configured disable percent even once, this pullback rule is permanently
    disabled for that position. Otherwise, after it is armed, track the highest
    live PnL peak and sell when the current live PnL is below that peak during
    an allowed candle window. If the peak is at least +1.30% and current PnL is
    still within 0.30 percentage points of that peak, keep holding.
    """
    if not ENABLE_ACTIVE_BUY_PROFIT_PULLBACK_BEFORE_SECOND_STREAK_SELL:
        return None
    if not isinstance(state, dict):
        return None

    # v43 strict FULL isolation: do not even fill active-buy default fields
    # for PMA/GF+ lifecycles when a FULL-5M scan is only checking that a
    # non-PMA sell should be skipped. BUY-1M owns those lifecycle mutations.
    stage_pre = str(state.get("stage") or "idle").strip().lower()
    if (
        stage_pre in {"buy", "pumped"}
        and not pma_gf_plus_skip_mutation_allowed()
        and active_buy_is_pma_gf_plus_lifecycle(state)
    ):
        return None

    ensure_active_buy_state_defaults(state)

    stage = str(state.get("stage") or "idle").strip().lower()
    if stage not in {"buy", "pumped"}:
        reset_active_buy_profit_pullback_tracking(state)
        return None

    if should_skip_non_pma_sell_for_pma_gf_plus_lifecycle(
        state,
        "active_buy_profit_pullback_before_second_streak",
        scan_dt=scan_dt,
        reason="skipped profit-pullback sell because PMA/GF+ lifecycle is PMA-only",
    ):
        if pma_gf_plus_skip_mutation_allowed():
            reset_active_buy_profit_pullback_tracking(state)
        return None

    active_entry_price = _safe_positive_float(state.get("active_buy_entry_price"))
    if active_entry_price is None:
        active_entry_price = _safe_positive_float(state.get("entry_price"))
    live_price = _safe_positive_float(current_price)

    live_reference_candle = current_forming_candle if isinstance(current_forming_candle, dict) else latest_closed_candle
    if live_price is None and isinstance(candidate, dict):
        live_price = resolve_current_market_price(
            candidate.get("latest_price"),
            live_reference_candle,
            prefer_candle=False,
            context=candidate,
        )
    if live_price in (None, 0, 0.0):
        live_price = _safe_positive_float((live_reference_candle or {}).get("c"))

    if active_entry_price in (None, 0, 0.0) or live_price in (None, 0, 0.0):
        return None

    live_pnl_pct = pct_change(active_entry_price, live_price)
    if live_pnl_pct is None:
        return None

    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    try:
        disable_after_pct = float(ACTIVE_BUY_PROFIT_PULLBACK_DISABLE_AFTER_PCT)
    except Exception:
        disable_after_pct = 2.0

    previous_disable_peak_pct = None
    try:
        previous_disable_peak_pct = float(state.get("active_buy_profit_pullback_peak_pnl_pct"))
    except Exception:
        previous_disable_peak_pct = None

    disable_trigger_pct = live_pnl_pct
    if previous_disable_peak_pct is not None and previous_disable_peak_pct > disable_trigger_pct:
        disable_trigger_pct = previous_disable_peak_pct

    if bool(state.get("active_buy_profit_pullback_disabled_after_2pct")):
        return None

    if disable_trigger_pct > disable_after_pct:
        state["active_buy_profit_pullback_disabled_after_2pct"] = True
        state["active_buy_profit_pullback_disabled_after_pct"] = disable_trigger_pct
        state["active_buy_profit_pullback_disabled_after_scan_ts"] = scan_ts
        return None

    try:
        second_streak_count = max(1, int(ACTIVE_BUY_PROFIT_PULLBACK_SECOND_STREAK_COUNT))
    except Exception:
        second_streak_count = 2

    live_streak_count, live_streak_trigger_price = active_buy_current_streak(live_price, active_entry_price)
    stored_streak_count = active_buy_green_streak_count(state)
    if max(live_streak_count, stored_streak_count) >= second_streak_count:
        reset_active_buy_profit_pullback_tracking(state)
        return None

    try:
        arm_pct = float(ACTIVE_BUY_PROFIT_PULLBACK_ARM_PCT)
    except Exception:
        arm_pct = 1.0
    try:
        min_drop_pct = max(0.0, float(ACTIVE_BUY_PROFIT_PULLBACK_MIN_DROP_PCT))
    except Exception:
        min_drop_pct = 0.0

    candle_ts = ts_to_int((live_reference_candle or {}).get("t"))

    previous_pnl_pct = None
    try:
        previous_pnl_pct = float(state.get("active_buy_profit_pullback_last_pnl_pct"))
    except Exception:
        previous_pnl_pct = None
    previous_price = _safe_positive_float(state.get("active_buy_profit_pullback_last_price"))

    seen_above = bool(state.get("active_buy_profit_pullback_seen_above_pct")) or live_pnl_pct > arm_pct

    previous_peak_pct = None
    try:
        previous_peak_pct = float(state.get("active_buy_profit_pullback_peak_pnl_pct"))
    except Exception:
        previous_peak_pct = None
    previous_peak_price = _safe_positive_float(state.get("active_buy_profit_pullback_peak_price"))

    peak_pnl_pct = live_pnl_pct
    peak_price = live_price
    if previous_peak_pct is not None and previous_peak_pct > peak_pnl_pct:
        peak_pnl_pct = previous_peak_pct
        if previous_peak_price is not None:
            peak_price = previous_peak_price

    state["active_buy_profit_pullback_peak_pnl_pct"] = peak_pnl_pct
    state["active_buy_profit_pullback_peak_price"] = peak_price

    seen_above = bool(seen_above or (peak_pnl_pct is not None and peak_pnl_pct > arm_pct))

    try:
        peak_keep_min_pct = float(ACTIVE_BUY_PROFIT_PULLBACK_PEAK_KEEP_MIN_PCT)
    except Exception:
        peak_keep_min_pct = 1.30
    try:
        peak_keep_near_pct = max(0.0, float(ACTIVE_BUY_PROFIT_PULLBACK_PEAK_KEEP_NEAR_PCT))
    except Exception:
        peak_keep_near_pct = 0.30

    pullback_from_peak_pct = None
    if peak_pnl_pct is not None:
        pullback_from_peak_pct = peak_pnl_pct - live_pnl_pct

    near_peak_keep = bool(
        peak_pnl_pct is not None and
        peak_pnl_pct >= peak_keep_min_pct and
        pullback_from_peak_pct is not None and
        pullback_from_peak_pct <= peak_keep_near_pct
    )

    window_status = active_buy_profit_pullback_candle_window_status(
        current_forming_candle if isinstance(current_forming_candle, dict) else None,
        scan_dt=scan_dt,
    )
    pullback_detected = bool(
        seen_above and
        peak_pnl_pct is not None and
        live_pnl_pct < (peak_pnl_pct - min_drop_pct) and
        not near_peak_keep
    )

    state["active_buy_profit_pullback_seen_above_pct"] = seen_above
    state["active_buy_profit_pullback_last_pnl_pct"] = live_pnl_pct
    state["active_buy_profit_pullback_last_price"] = live_price
    state["active_buy_profit_pullback_last_scan_ts"] = scan_ts
    state["active_buy_profit_pullback_last_candle_ts"] = candle_ts

    if not pullback_detected or not bool(window_status.get("allowed")):
        return None

    sell_candle = build_live_price_sell_candle(
        live_reference_candle,
        scan_dt=scan_dt,
        live_price=live_price,
    )
    if not isinstance(sell_candle, dict):
        return None

    sell_event = finalize_sell_transition(
        state,
        sell_candle,
        scan_dt,
        (
            "active BUY profit pullback before second streak: live PnL was above "
            f"+{arm_pct:.3f}% and then pulled back from the highest tracked peak "
            f"{peak_pnl_pct:+.3f}% to {live_pnl_pct:+.3f}% during an allowed candle window "
            f"(first/last {window_status.get('window_minutes'):g}m or midpoint "
            f"{window_status.get('midpoint_minute'):g}±{window_status.get('midpoint_window_minutes'):g}m)"
        ),
        {
            "active_buy_profit_pullback_sell": True,
            "active_buy_profit_pullback_enabled": True,
            "active_buy_profit_pullback_arm_pct": arm_pct,
            "active_buy_profit_pullback_second_streak_count": second_streak_count,
            "active_buy_profit_pullback_window_minutes": window_status.get("window_minutes"),
            "active_buy_profit_pullback_candle_minutes": window_status.get("candle_minutes"),
            "active_buy_profit_pullback_candle_age_minutes": window_status.get("age_minutes"),
            "active_buy_profit_pullback_first_window": bool(window_status.get("first_window")),
            "active_buy_profit_pullback_last_window": bool(window_status.get("last_window")),
            "active_buy_profit_pullback_midpoint_window": bool(window_status.get("midpoint_window")),
            "active_buy_profit_pullback_midpoint_minute": window_status.get("midpoint_minute"),
            "active_buy_profit_pullback_midpoint_window_minutes": window_status.get("midpoint_window_minutes"),
            "active_buy_profit_pullback_previous_pnl_pct": previous_pnl_pct,
            "active_buy_profit_pullback_current_pnl_pct": live_pnl_pct,
            "active_buy_profit_pullback_previous_peak_pnl_pct": previous_peak_pct,
            "active_buy_profit_pullback_peak_pnl_pct": state.get("active_buy_profit_pullback_peak_pnl_pct"),
            "active_buy_profit_pullback_from_peak_pct": pullback_from_peak_pct,
            "active_buy_profit_pullback_peak_keep_min_pct": peak_keep_min_pct,
            "active_buy_profit_pullback_peak_keep_near_pct": peak_keep_near_pct,
            "active_buy_profit_pullback_near_peak_keep": near_peak_keep,
            "active_buy_profit_pullback_previous_price": previous_price,
            "active_buy_profit_pullback_previous_peak_price": previous_peak_price,
            "active_buy_profit_pullback_current_price": live_price,
            "active_buy_profit_pullback_live_streak_count": live_streak_count,
            "active_buy_profit_pullback_stored_streak_count": stored_streak_count,
            "active_buy_profit_pullback_live_streak_trigger_price": live_streak_trigger_price,
            "active_buy_price": active_entry_price,
            "current_price": live_price,
            "entry_pnl_pct": live_pnl_pct,
            "rollover_active": bool(state.get("rollover_active")),
            "buy_style": infer_buy_style(state),
            "live_force_sell": False,
        },
    )

    return {
        "event": sell_event,
        "pnl_pct": live_pnl_pct,
        "previous_pnl_pct": previous_pnl_pct,
        "peak_pnl_pct": peak_pnl_pct,
        "pullback_from_peak_pct": pullback_from_peak_pct,
        "near_peak_keep": near_peak_keep,
        "current_price": live_price,
        "previous_price": previous_price,
        "peak_price": peak_price,
        "active_buy_price": active_entry_price,
        "window_status": window_status,
        "live_streak_count": live_streak_count,
        "stored_streak_count": stored_streak_count,
        "rollover_active": bool(state.get("rollover_active")),
    }



def active_buy_first_buy_ts(state):
    """Return the real first BUY timestamp used by elapsed sell guards."""
    if not isinstance(state, dict):
        return None

    ts = pumping_buy_actual_start_ts(state)
    if ts is not None:
        return ts

    candidates = []
    for key in ("active_buy_entry_ts", "buy_event_ts", "buy_ts"):
        value = ts_to_int(state.get(key))
        if value is not None:
            candidates.append(value)
    return min(candidates) if candidates else None




def active_buy_started_on_scan(state, scan_dt=None):
    """Return True when the current real active BUY was created in this scan.

    This is a delivery-safety guard, not a strategy stage. GF+ buys remain normal
    stage=buy events with PMA/GF+ flags. When a BUY is born in the same scan,
    no sell rule may overwrite that outgoing BUY before the BUY alert is delivered.
    """
    if not isinstance(state, dict):
        return False

    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if scan_ts is None:
        return False

    stage = normalize_strategy_stage_value(state.get("stage"))
    if stage not in {"buy", "pumped"}:
        return False

    candidates = []
    for key in (
        "active_buy_entry_ts",
        "buy_event_ts",
        "buy_ts",
        "first_buy_ts",
        "active_buy_first_buy_ts",
        "active_buy_pma_gf_plus_buy_ts",
    ):
        value = ts_to_int(state.get(key))
        if value is not None:
            candidates.append(value)

    first_buy_ts = active_buy_first_buy_ts(state)
    if first_buy_ts is not None:
        candidates.append(first_buy_ts)

    return any(int(value) == int(scan_ts) for value in candidates)


def active_buy_live_entry_price(state):
    if not isinstance(state, dict):
        return None
    active_entry = _safe_positive_float(state.get("active_buy_entry_price"))
    if active_entry is not None:
        return active_entry
    return _safe_positive_float(state.get("entry_price"))


def maybe_sell_active_buy_min_progress_after_elapsed_window(state, candidate, latest_closed_candle, current_forming_candle, scan_dt, current_price=None):
    """
    Progress-hold sell guard for active BUYs.

    Requested behavior:
    - Universal hard force sell is separate and remains controlled by FORCE_SELL_FROM_BUY_SIGNAL_PCT.
    - The -0.16% elapsed drawback rule is separate and untouched.
    - Until the active BUY has traded above +ACTIVE_BUY_MIN_PROGRESS_EXIT_PCT at least once,
      sell after ACTIVE_BUY_MIN_PROGRESS_EXIT_MINUTES from the real BUY start.
    - After it has traded above that threshold once, every later drop back below/at the
      threshold starts a fresh ACTIVE_BUY_MIN_PROGRESS_REDROP_EXIT_MINUTES timer.
      If it gets above the threshold again, that 2-minute timer is cleared and will
      restart fresh on the next drop below/at the threshold.
    """
    if not bool(ACTIVE_BUY_MIN_PROGRESS_EXIT_ENABLED):
        return None
    if not isinstance(state, dict):
        return None

    # v43 strict FULL isolation: do not fill/reset active-buy progress
    # tracking for PMA/GF+ lifecycles from a FULL-5M scan.
    stage_pre = str(state.get("stage") or "idle").strip().lower()
    if (
        stage_pre in {"buy", "pumped"}
        and not pma_gf_plus_skip_mutation_allowed()
        and active_buy_is_pma_gf_plus_lifecycle(state)
    ):
        return None

    ensure_active_buy_state_defaults(state)
    stage = str(state.get("stage") or "idle").strip().lower()
    if stage not in {"buy", "pumped"}:
        reset_active_buy_min_progress_tracking(state)
        return None

    if should_skip_non_pma_sell_for_pma_gf_plus_lifecycle(
        state,
        "active_buy_min_progress_elapsed_window",
        scan_dt=scan_dt,
        reason="skipped min-progress/reclaim-drawback sell because PMA/GF+ lifecycle is PMA-only",
    ):
        if pma_gf_plus_skip_mutation_allowed():
            reset_active_buy_min_progress_tracking(state)
        return None

    entry_price = active_buy_live_entry_price(state)
    live_reference_candle = current_forming_candle if isinstance(current_forming_candle, dict) else latest_closed_candle
    live_price = _safe_positive_float(current_price)
    if live_price is None and isinstance(candidate, dict):
        live_price = resolve_current_market_price(
            candidate.get("latest_price"),
            live_reference_candle,
            prefer_candle=False,
            context=candidate,
        )
    if live_price in (None, 0, 0.0):
        live_price = _safe_positive_float((live_reference_candle or {}).get("c"))

    if entry_price in (None, 0, 0.0) or live_price in (None, 0, 0.0):
        return None

    live_pnl_pct = pct_change(entry_price, live_price)
    if live_pnl_pct is None:
        return None

    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    first_buy_ts = active_buy_first_buy_ts(state)
    if current_scan_ts is None or first_buy_ts is None:
        return None

    previous_peak_pct = None
    try:
        previous_peak_pct = float(state.get("active_buy_min_progress_peak_pnl_pct"))
    except Exception:
        previous_peak_pct = None
    previous_peak_price = _safe_positive_float(state.get("active_buy_min_progress_peak_price"))

    peak_pnl_pct = live_pnl_pct
    peak_price = live_price
    peak_scan_ts = current_scan_ts
    if previous_peak_pct is not None and previous_peak_pct > peak_pnl_pct:
        peak_pnl_pct = previous_peak_pct
        if previous_peak_price is not None:
            peak_price = previous_peak_price
        peak_scan_ts = ts_to_int(state.get("active_buy_min_progress_peak_scan_ts")) or current_scan_ts

    state["active_buy_min_progress_peak_pnl_pct"] = peak_pnl_pct
    state["active_buy_min_progress_peak_price"] = peak_price
    state["active_buy_min_progress_peak_scan_ts"] = peak_scan_ts
    state["active_buy_min_progress_last_pnl_pct"] = live_pnl_pct

    try:
        initial_window_minutes = max(0.0, float(ACTIVE_BUY_MIN_PROGRESS_EXIT_MINUTES))
    except Exception:
        initial_window_minutes = 10.0
    try:
        required_pct = float(ACTIVE_BUY_MIN_PROGRESS_EXIT_PCT)
    except Exception:
        required_pct = 0.90
    try:
        redrop_window_minutes = max(0.0, float(ACTIVE_BUY_MIN_PROGRESS_REDROP_EXIT_MINUTES))
    except Exception:
        redrop_window_minutes = 2.0

    elapsed_minutes_from_buy = max(0.0, (current_scan_ts - int(first_buy_ts)) / 60.0)
    currently_above = bool(live_pnl_pct > required_pct)
    currently_below_or_equal = not currently_above

    seen_above_state = bool(state.get("active_buy_min_progress_above_required_seen"))
    peak_reached = bool(peak_pnl_pct is not None and peak_pnl_pct > required_pct)
    if currently_above:
        seen_above_state = True
        state["active_buy_min_progress_above_required_seen"] = True
        state["active_buy_min_progress_above_required_seen_ts"] = current_scan_ts
        state["active_buy_min_progress_redrop_below_since_ts"] = None
        state["active_buy_min_progress_redrop_elapsed_seconds"] = None
        return None
    elif peak_reached:
        # Covers positions loaded from older state where peak was already above +0.90
        # but the explicit seen-above flag did not exist yet.
        seen_above_state = True
        state["active_buy_min_progress_above_required_seen"] = True
        if ts_to_int(state.get("active_buy_min_progress_above_required_seen_ts")) is None:
            state["active_buy_min_progress_above_required_seen_ts"] = peak_scan_ts

    if not seen_above_state:
        state["active_buy_min_progress_redrop_below_since_ts"] = None
        state["active_buy_min_progress_redrop_elapsed_seconds"] = None
        if elapsed_minutes_from_buy < initial_window_minutes:
            return None
        reason_detail = "never traded above"
        active_window_minutes = initial_window_minutes
        active_elapsed_minutes = elapsed_minutes_from_buy
        redrop_below_since_ts = None
        redrop_elapsed_seconds = None
        redrop_required_seconds = None
        sell_mode = "initial_never_above"
    else:
        redrop_required_seconds = max(1, int(round(redrop_window_minutes * 60.0)))
        redrop_below_since_ts = ts_to_int(state.get("active_buy_min_progress_redrop_below_since_ts"))
        if redrop_below_since_ts is None:
            redrop_below_since_ts = current_scan_ts
            state["active_buy_min_progress_redrop_below_since_ts"] = redrop_below_since_ts
        redrop_elapsed_seconds = max(0, int(current_scan_ts - int(redrop_below_since_ts)))
        state["active_buy_min_progress_redrop_elapsed_seconds"] = redrop_elapsed_seconds
        if redrop_elapsed_seconds < redrop_required_seconds:
            return None
        reason_detail = "reclaimed then fell back below"
        active_window_minutes = redrop_window_minutes
        active_elapsed_minutes = redrop_elapsed_seconds / 60.0
        sell_mode = "redrop_after_reclaim"

    sell_candle = build_live_price_sell_candle(
        live_reference_candle,
        scan_dt=scan_dt,
        live_price=live_price,
    )
    if not isinstance(sell_candle, dict):
        return None

    if sell_mode == "redrop_after_reclaim":
        reason_text = (
            f"active BUY +{required_pct:.3f}% reclaim drawback guard: {reason_detail} "
            f"+{required_pct:.3f}% and stayed below/at it for {redrop_elapsed_seconds}s"
        )
    else:
        reason_text = (
            f"active BUY 10m progress guard: {reason_detail} +{required_pct:.3f}% "
            f"within {initial_window_minutes:.1f} minutes from first BUY start"
        )

    sell_event = finalize_sell_transition(
        state,
        sell_candle,
        scan_dt,
        reason_text,
        {
            "active_buy_min_progress_exit": True,
            "active_buy_min_progress_mode": sell_mode,
            "active_buy_min_progress_required_pct": required_pct,
            "active_buy_min_progress_window_minutes": active_window_minutes,
            "active_buy_min_progress_initial_window_minutes": initial_window_minutes,
            "active_buy_min_progress_redrop_window_minutes": redrop_window_minutes,
            "active_buy_min_progress_elapsed_minutes": active_elapsed_minutes,
            "active_buy_min_progress_elapsed_from_buy_minutes": elapsed_minutes_from_buy,
            "active_buy_min_progress_current_pnl_pct": live_pnl_pct,
            "active_buy_min_progress_peak_pnl_pct": peak_pnl_pct,
            "active_buy_min_progress_peak_price": peak_price,
            "active_buy_min_progress_peak_scan_ts": peak_scan_ts,
            "active_buy_min_progress_peak_reached": peak_reached,
            "active_buy_min_progress_above_required_seen": seen_above_state,
            "active_buy_min_progress_above_required_seen_ts": state.get("active_buy_min_progress_above_required_seen_ts"),
            "active_buy_min_progress_redrop_below_since_ts": redrop_below_since_ts,
            "active_buy_min_progress_redrop_elapsed_seconds": redrop_elapsed_seconds,
            "active_buy_min_progress_redrop_required_seconds": redrop_required_seconds,
            "active_buy_min_progress_currently_holding": currently_above,
            "entry_price": entry_price,
            "current_price": live_price,
            "buy_style": infer_buy_style(state),
            "first_buy_ts": first_buy_ts,
            "live_force_sell": False,
        },
    )

    return {
        "event": sell_event,
        "pnl_pct": live_pnl_pct,
        "peak_pnl_pct": peak_pnl_pct,
        "current_price": live_price,
        "entry_price": entry_price,
        "elapsed_minutes": active_elapsed_minutes,
        "elapsed_from_buy_minutes": elapsed_minutes_from_buy,
        "required_pct": required_pct,
        "peak_reached": peak_reached,
        "above_required_seen": seen_above_state,
        "currently_holding": currently_above,
        "redrop_below_since_ts": redrop_below_since_ts,
        "redrop_elapsed_seconds": redrop_elapsed_seconds,
        "buy_style": infer_buy_style(state),
    }


def maybe_force_sell_active_buy_on_non_flat_samples(state, candidate, latest_closed_candle, current_forming_candle, scan_dt):
    """
    V100 global active-BUY liquidity guard.

    This guard intentionally runs before PMA/GF+ non-PMA-sell skip checks. It
    applies to normal active BUYs and force-buy lifecycles. Unlike V99, it is
    not a first-window-only check: while the active BUY remains open, every
    scan maintains a rolling ACTIVE_BUY_NON_FLAT_SAMPLE_WINDOW_MINUTES lookback
    over live PnL samples from the active-buy entry anchor. If a fully observed
    rolling window has fewer than ACTIVE_BUY_NON_FLAT_SAMPLE_MIN_COUNT non-flat
    PnL samples, the position is force-sold as inactive/illiquid.

    The tracker is lifecycle-local. It is reset when the active BUY is no
    longer in buy/pumped stage, and sell finalization resets the symbol state,
    so related counts/history do not remain stored after the position is done.
    """
    if not bool(globals().get("ENABLE_ACTIVE_BUY_NON_FLAT_SAMPLE_FORCE_SELL", False)):
        return None
    if not isinstance(state, dict):
        return None

    stage = str(state.get("stage") or "idle").strip().lower()
    if stage not in {"buy", "pumped"}:
        reset_active_buy_non_flat_sample_tracking(state)
        return None

    first_buy_ts = active_buy_first_buy_ts(state)
    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if first_buy_ts is None or current_scan_ts is None:
        return None
    first_buy_ts = int(first_buy_ts)
    current_scan_ts = int(current_scan_ts)

    pma_gf_plus_force_buy_active = bool(
        state.get("buy_from_pma_gf_plus_force") or
        state.get("pma_gf_plus_force_buy") or
        state.get("pma_gf_plus_force_buy_trigger")
    )
    if pma_gf_plus_force_buy_active and not bool(globals().get("ACTIVE_BUY_NON_FLAT_SAMPLE_APPLIES_TO_PMA_GF_PLUS_FORCE_BUYS", True)):
        return None

    try:
        window_seconds = max(1, int(round(float(globals().get("ACTIVE_BUY_NON_FLAT_SAMPLE_WINDOW_MINUTES", 6.0)) * 60.0)))
    except Exception:
        window_seconds = 6 * 60
    try:
        min_count = max(1, int(float(globals().get("ACTIVE_BUY_NON_FLAT_SAMPLE_MIN_COUNT", 4))))
    except Exception:
        min_count = 4
    try:
        min_delta_pct = max(0.0, float(globals().get("ACTIVE_BUY_NON_FLAT_SAMPLE_MIN_PNL_DELTA_PCT", 0.001)))
    except Exception:
        min_delta_pct = 0.001
    try:
        history_max = max(min_count + 8, int(float(globals().get("ACTIVE_BUY_NON_FLAT_SAMPLE_HISTORY_MAX", 96))))
    except Exception:
        history_max = 96

    tracked_buy_ts = ts_to_int(state.get("active_buy_non_flat_sample_buy_ts"))
    new_non_flat_sample_lifecycle = bool(tracked_buy_ts != first_buy_ts)
    if new_non_flat_sample_lifecycle:
        reset_active_buy_non_flat_sample_tracking(state)
        state["active_buy_non_flat_sample_buy_ts"] = first_buy_ts
        # Start observation from the real BUY if we are already seeing the BUY
        # in its first window. If the bot was restarted/upgraded after the
        # first window was already over, start a fresh observed rolling window
        # from now instead of retroactively selling with 0 samples.
        if current_scan_ts <= first_buy_ts + window_seconds:
            state["active_buy_non_flat_sample_tracking_started_ts"] = first_buy_ts
            state["active_buy_non_flat_sample_bootstrap_skipped_old_buy"] = False
        else:
            state["active_buy_non_flat_sample_tracking_started_ts"] = current_scan_ts
            state["active_buy_non_flat_sample_bootstrap_skipped_old_buy"] = True

    tracking_started_ts = ts_to_int(state.get("active_buy_non_flat_sample_tracking_started_ts"))
    if tracking_started_ts is None:
        tracking_started_ts = first_buy_ts if current_scan_ts <= first_buy_ts + window_seconds else current_scan_ts
        state["active_buy_non_flat_sample_tracking_started_ts"] = tracking_started_ts
    tracking_started_ts = int(tracking_started_ts)

    live_reference_candle = current_forming_candle if isinstance(current_forming_candle, dict) else latest_closed_candle
    live_current_price = None
    if isinstance(candidate, dict):
        live_current_price = resolve_current_market_price(
            candidate.get("latest_price"),
            live_reference_candle,
            prefer_candle=False,
            context=candidate,
        )
    if live_current_price in (None, 0, 0.0):
        live_current_price = _safe_positive_float((live_reference_candle or {}).get("c"))

    active_entry_price = active_buy_live_entry_price(state)
    live_pnl_pct = (
        pct_change(active_entry_price, live_current_price)
        if active_entry_price not in (None, 0, 0.0) and live_current_price not in (None, 0, 0.0)
        else None
    )
    if live_pnl_pct is None:
        return None

    history = state.get("active_buy_non_flat_sample_history")
    if not isinstance(history, list):
        history = []

    previous_pnl = None
    if history:
        try:
            previous_pnl = float(history[-1].get("pnl_pct"))
        except Exception:
            previous_pnl = None

    # The first sample in a lifecycle/window is a baseline, not a non-flat
    # movement by itself. Later samples count only when live PnL changes enough
    # from the previous recorded sample.
    non_flat = bool(previous_pnl is not None and abs(float(live_pnl_pct) - float(previous_pnl)) >= min_delta_pct)
    sample = {
        "ts": current_scan_ts,
        "pnl_pct": live_pnl_pct,
        "price": live_current_price,
        "non_flat": non_flat,
        "min_delta_pct": min_delta_pct,
    }
    if history and ts_to_int(history[-1].get("ts")) == current_scan_ts:
        history[-1] = sample
    else:
        history.append(sample)

    rolling_window_start_ts = current_scan_ts - window_seconds
    trimmed_history = []
    for item in history:
        if not isinstance(item, dict):
            continue
        item_ts = ts_to_int(item.get("ts"))
        if item_ts is None:
            continue
        if int(item_ts) >= rolling_window_start_ts:
            trimmed_history.append(item)
    history = trimmed_history[-history_max:]

    non_flat_count = sum(1 for item in history if isinstance(item, dict) and bool(item.get("non_flat")))
    sample_count = len(history)
    elapsed_seconds = max(0, current_scan_ts - first_buy_ts)
    observed_elapsed_seconds = max(0, current_scan_ts - tracking_started_ts)
    window_elapsed = observed_elapsed_seconds >= window_seconds

    state["active_buy_non_flat_sample_buy_ts"] = first_buy_ts
    state["active_buy_non_flat_sample_tracking_started_ts"] = tracking_started_ts
    state["active_buy_non_flat_sample_history"] = history
    state["active_buy_non_flat_sample_count"] = non_flat_count
    state["active_buy_non_flat_sample_sample_count"] = sample_count
    state["active_buy_non_flat_sample_window_seconds"] = window_seconds
    state["active_buy_non_flat_sample_min_count"] = min_count
    state["active_buy_non_flat_sample_min_pnl_delta_pct"] = min_delta_pct
    state["active_buy_non_flat_sample_last_scan_ts"] = current_scan_ts
    state["active_buy_non_flat_sample_last_pnl_pct"] = live_pnl_pct
    state["active_buy_non_flat_sample_last_price"] = live_current_price
    state["active_buy_non_flat_sample_elapsed_seconds"] = elapsed_seconds
    state["active_buy_non_flat_sample_observed_elapsed_seconds"] = observed_elapsed_seconds
    state["active_buy_non_flat_sample_rolling_window_start_ts"] = rolling_window_start_ts
    state["active_buy_non_flat_sample_window_elapsed"] = bool(window_elapsed)
    state["active_buy_non_flat_sample_force_buy_active"] = bool(pma_gf_plus_force_buy_active)
    state["active_buy_non_flat_sample_passed"] = bool(window_elapsed and non_flat_count >= min_count)
    state["active_buy_non_flat_sample_failed"] = False

    if not window_elapsed:
        return None

    if non_flat_count >= min_count:
        return None

    state["active_buy_non_flat_sample_failed"] = True

    sell_candle = build_live_price_sell_candle(
        live_reference_candle,
        scan_dt=scan_dt,
        live_price=live_current_price,
    )
    if not isinstance(sell_candle, dict):
        return None

    reason = (
        "global active-BUY rolling non-flat sample force sell: only "
        f"{non_flat_count}/{min_count} non-flat live PnL samples were observed "
        f"inside the latest {window_seconds}s rolling window; coin looks inactive/illiquid"
    )
    sell_event = finalize_sell_transition(
        state,
        sell_candle,
        scan_dt,
        reason,
        {
            "active_buy_non_flat_sample_force_sell": True,
            "active_buy_non_flat_sample_rolling_window": True,
            "active_buy_non_flat_sample_count": non_flat_count,
            "active_buy_non_flat_sample_sample_count": sample_count,
            "active_buy_non_flat_sample_min_count": min_count,
            "active_buy_non_flat_sample_window_seconds": window_seconds,
            "active_buy_non_flat_sample_elapsed_seconds": elapsed_seconds,
            "active_buy_non_flat_sample_observed_elapsed_seconds": observed_elapsed_seconds,
            "active_buy_non_flat_sample_rolling_window_start_ts": rolling_window_start_ts,
            "active_buy_non_flat_sample_tracking_started_ts": tracking_started_ts,
            "active_buy_non_flat_sample_min_pnl_delta_pct": min_delta_pct,
            "active_buy_non_flat_sample_history": history,
            "active_buy_non_flat_sample_applies_to_force_buys": bool(globals().get("ACTIVE_BUY_NON_FLAT_SAMPLE_APPLIES_TO_PMA_GF_PLUS_FORCE_BUYS", True)),
            "active_buy_non_flat_sample_force_buy_active": bool(pma_gf_plus_force_buy_active),
            "entry_pnl_pct": live_pnl_pct,
            "current_price": live_current_price,
            "buy_signal_price": active_entry_price,
            "force_sell_reference_price": active_entry_price,
            "force_sell_reference_kind": "active_buy_entry_price",
            "buy_style": infer_buy_style(state),
            "live_force_sell": True,
        },
    )

    # finalize_sell_transition resets the symbol state to idle. Make the clear
    # explicit too, so this tracker never leaves stale counts/history after its
    # own sell path completes.
    reset_active_buy_non_flat_sample_tracking(state)

    return {
        "event": sell_event,
        "pnl_pct": live_pnl_pct,
        "reference_label": "active buy price",
        "reference_price": active_entry_price,
        "current_price": live_current_price,
        "buy_style": infer_buy_style(state),
        "active_buy_non_flat_sample_force_sell": True,
        "non_flat_sample_force_sell": True,
        "non_flat_sample_rolling_window": True,
        "non_flat_sample_count": non_flat_count,
        "non_flat_sample_sample_count": sample_count,
        "non_flat_sample_min_count": min_count,
        "non_flat_sample_window_seconds": window_seconds,
        "non_flat_sample_elapsed_seconds": elapsed_seconds,
        "non_flat_sample_observed_elapsed_seconds": observed_elapsed_seconds,
        "pma_gf_plus_force_buy_active": bool(pma_gf_plus_force_buy_active),
    }

def maybe_force_sell_active_buy_on_buy_signal_scan(state, candidate, latest_closed_candle, current_forming_candle, scan_dt):
    """
    BUY-1M universal safety net for every active BUY position.

    This is deliberately outside the fib/rollover/pending-buy machinery so both
    legacy and pumping buys sell as soon as the live active-management PnL crosses
    UNIVERSAL_ACTIVE_BUY_FORCE_SELL_PCT.
    """
    if not isinstance(state, dict):
        return None

    stage = str(state.get("stage") or "idle").strip().lower()
    if stage not in {"buy", "pumped"}:
        return None

    non_flat_sample_force_sell = maybe_force_sell_active_buy_on_non_flat_samples(
        state,
        candidate,
        latest_closed_candle,
        current_forming_candle,
        scan_dt,
    )
    if isinstance(non_flat_sample_force_sell, dict) and isinstance(non_flat_sample_force_sell.get("event"), dict):
        return non_flat_sample_force_sell

    if not UNIVERSAL_ACTIVE_BUY_FORCE_SELL_ENABLED:
        return None

    if should_skip_non_pma_sell_for_pma_gf_plus_lifecycle(
        state,
        "active_buy_universal_elapsed_peak_drawdown_force_sell",
        scan_dt=scan_dt,
        reason="skipped universal/elapsed/peak-drawdown active-buy sell because PMA/GF+ lifecycle is PMA-only",
    ):
        return None

    buy_style = infer_buy_style(state)
    is_pumping = buy_style == "pumping"
    if is_pumping and not UNIVERSAL_ACTIVE_BUY_FORCE_SELL_APPLIES_TO_PUMPING:
        return None
    if (not is_pumping) and not UNIVERSAL_ACTIVE_BUY_FORCE_SELL_APPLIES_TO_LEGACY:
        return None

    live_reference_candle = current_forming_candle if isinstance(current_forming_candle, dict) else latest_closed_candle
    live_current_price = None
    if isinstance(candidate, dict):
        live_current_price = resolve_current_market_price(
            candidate.get("latest_price"),
            live_reference_candle,
            prefer_candle=False,
            context=candidate,
        )
    if live_current_price in (None, 0, 0.0):
        live_current_price = _safe_positive_float((live_reference_candle or {}).get("c"))

    reference_price, reference_label, reference_kind = active_buy_management_force_sell_reference(state)
    live_pnl_pct = (
        pct_change(reference_price, live_current_price)
        if reference_price not in (None, 0, 0.0) and live_current_price not in (None, 0, 0.0)
        else None
    )
    if live_pnl_pct is None:
        return None

    try:
        force_sell_pct = float(UNIVERSAL_ACTIVE_BUY_FORCE_SELL_PCT)
    except Exception:
        force_sell_pct = float(FORCE_SELL_FROM_BUY_SIGNAL_PCT)

    try:
        min_hold_minutes = float(UNIVERSAL_ACTIVE_BUY_FORCE_SELL_MIN_HOLD_MINUTES)
    except Exception:
        min_hold_minutes = 0.0

    if min_hold_minutes > 0 and not buy_min_hold_elapsed(state, scan_dt, minutes=min_hold_minutes):
        return None

    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    entry_price = active_buy_live_entry_price(state)
    live_pnl_pct_from_entry = (
        pct_change(entry_price, live_current_price)
        if entry_price not in (None, 0, 0.0) and live_current_price not in (None, 0, 0.0)
        else None
    )

    pma_gf_plus_force_buy_active = bool(
        state.get("buy_from_pma_gf_plus_force") or
        state.get("pma_gf_plus_force_buy") or
        state.get("pma_gf_plus_force_buy_trigger")
    )
    # A position can become a GF+ lifecycle after the real BUY, even if it did
    # not enter through the PMA/GF+ force-buy bypass. The PMA/GF+ manager sets
    # this when PMA-GF+ reaches the instant offset or holds above GF+ long
    # enough. These qualified lifecycles get the same skip treatment requested
    # for "GF+ ones".
    pma_gf_plus_qualified_active = bool(state.get("active_buy_pma_gf_plus_qualified_since_buy"))

    peak_drawdown_sell = False
    peak_drawdown_arm_pct = None
    peak_drawdown_required_drop_pct = None
    peak_drawdown_required_seconds = None
    peak_drawdown_since_ts = None
    peak_drawdown_elapsed_seconds = None
    peak_drawdown_peak_pnl_pct = None
    peak_drawdown_drop_pct = None
    if bool(globals().get("GLOBAL_ACTIVE_BUY_PEAK_DRAWDOWN_FORCE_SELL_ENABLED", True)):
        peak_drawdown_applies = (
            (is_pumping and bool(globals().get("GLOBAL_ACTIVE_BUY_PEAK_DRAWDOWN_FORCE_SELL_APPLIES_TO_PUMPING", True))) or
            ((not is_pumping) and bool(globals().get("GLOBAL_ACTIVE_BUY_PEAK_DRAWDOWN_FORCE_SELL_APPLIES_TO_LEGACY", True)))
        )
        skip_for_pma_gf_plus = bool(
            (
                pma_gf_plus_force_buy_active and
                bool(globals().get("GLOBAL_ACTIVE_BUY_PEAK_DRAWDOWN_FORCE_SELL_SKIP_PMA_GF_PLUS_FORCE_BUY", True))
            ) or (
                pma_gf_plus_qualified_active and
                bool(globals().get("GLOBAL_ACTIVE_BUY_PEAK_DRAWDOWN_FORCE_SELL_SKIP_PMA_GF_PLUS_QUALIFIED", True))
            )
        )
        if peak_drawdown_applies and not skip_for_pma_gf_plus and current_scan_ts is not None:
            try:
                peak_drawdown_arm_pct = float(globals().get("GLOBAL_ACTIVE_BUY_PEAK_DRAWDOWN_FORCE_SELL_ARM_PCT", FIB_SELL_ZONE_PEAK_PNL_ARM_PCT))
            except Exception:
                peak_drawdown_arm_pct = 1.618
            try:
                peak_drawdown_required_drop_pct = max(0.0, float(globals().get("GLOBAL_ACTIVE_BUY_PEAK_DRAWDOWN_FORCE_SELL_DROP_PCT", 3.20)))
            except Exception:
                peak_drawdown_required_drop_pct = 3.20
            try:
                peak_drawdown_required_seconds = max(1, int(round(float(globals().get("GLOBAL_ACTIVE_BUY_PEAK_DRAWDOWN_FORCE_SELL_SECONDS", 30)))))
            except Exception:
                peak_drawdown_required_seconds = 30

            # Ensure the same real-BUY peak tracker used by the fib sell-zone gate
            # is current even when this helper is called directly in tests.
            update_active_buy_peak_pnl_state(
                state,
                live_current_price,
                active_buy_live_entry_price(state) or entry_price,
                scan_dt=scan_dt,
                source="active_buy_global_peak_drawdown",
                live_candle=live_reference_candle,
            )
            peak_drawdown_peak_pnl_pct = active_buy_peak_pnl_pct(state)
            state["active_buy_peak_drawdown_arm_pct"] = peak_drawdown_arm_pct
            state["active_buy_peak_drawdown_required_drop_pct"] = peak_drawdown_required_drop_pct
            state["active_buy_peak_drawdown_required_seconds"] = peak_drawdown_required_seconds
            state["active_buy_peak_drawdown_peak_pnl_pct"] = peak_drawdown_peak_pnl_pct
            state["active_buy_peak_drawdown_current_pnl_pct"] = live_pnl_pct_from_entry
            state["active_buy_peak_drawdown_peak_scan_ts"] = ts_to_int(state.get("active_buy_peak_scan_ts"))

            if (
                peak_drawdown_peak_pnl_pct is not None and
                live_pnl_pct_from_entry is not None and
                peak_drawdown_peak_pnl_pct >= peak_drawdown_arm_pct
            ):
                peak_drawdown_drop_pct = peak_drawdown_peak_pnl_pct - live_pnl_pct_from_entry
                state["active_buy_peak_drawdown_drop_pct"] = peak_drawdown_drop_pct
                if peak_drawdown_drop_pct >= peak_drawdown_required_drop_pct:
                    peak_drawdown_since_ts = ts_to_int(state.get("active_buy_peak_drawdown_below_since_ts"))
                    if peak_drawdown_since_ts is None:
                        peak_drawdown_since_ts = current_scan_ts
                        state["active_buy_peak_drawdown_below_since_ts"] = peak_drawdown_since_ts
                    peak_drawdown_elapsed_seconds = max(0, int(current_scan_ts - peak_drawdown_since_ts))
                    state["active_buy_peak_drawdown_elapsed_seconds"] = peak_drawdown_elapsed_seconds
                    peak_drawdown_sell = peak_drawdown_elapsed_seconds >= peak_drawdown_required_seconds
                else:
                    reset_global_active_buy_peak_drawdown_tracking(state)
                    state["active_buy_peak_drawdown_peak_pnl_pct"] = peak_drawdown_peak_pnl_pct
                    state["active_buy_peak_drawdown_current_pnl_pct"] = live_pnl_pct_from_entry
                    state["active_buy_peak_drawdown_drop_pct"] = peak_drawdown_drop_pct
                    state["active_buy_peak_drawdown_required_drop_pct"] = peak_drawdown_required_drop_pct
                    state["active_buy_peak_drawdown_required_seconds"] = peak_drawdown_required_seconds
                    state["active_buy_peak_drawdown_arm_pct"] = peak_drawdown_arm_pct
                    state["active_buy_peak_drawdown_peak_scan_ts"] = ts_to_int(state.get("active_buy_peak_scan_ts"))
            else:
                reset_global_active_buy_peak_drawdown_tracking(state)
                state["active_buy_peak_drawdown_peak_pnl_pct"] = peak_drawdown_peak_pnl_pct
                state["active_buy_peak_drawdown_current_pnl_pct"] = live_pnl_pct_from_entry
                state["active_buy_peak_drawdown_required_drop_pct"] = peak_drawdown_required_drop_pct
                state["active_buy_peak_drawdown_required_seconds"] = peak_drawdown_required_seconds
                state["active_buy_peak_drawdown_arm_pct"] = peak_drawdown_arm_pct
        elif skip_for_pma_gf_plus:
            reset_global_active_buy_peak_drawdown_tracking(state)

    elapsed_drawdown_sell = False
    elapsed_drawdown_threshold_pct = None
    elapsed_drawdown_required_seconds = None
    elapsed_drawdown_since_ts = None
    elapsed_drawdown_elapsed_seconds = None
    if bool(ACTIVE_BUY_ELAPSED_DRAWDOWN_FORCE_SELL_ENABLED):
        drawdown_applies = (
            (is_pumping and bool(ACTIVE_BUY_ELAPSED_DRAWDOWN_FORCE_SELL_APPLIES_TO_PUMPING)) or
            ((not is_pumping) and bool(ACTIVE_BUY_ELAPSED_DRAWDOWN_FORCE_SELL_APPLIES_TO_LEGACY))
        )
        if drawdown_applies and current_scan_ts is not None:
            try:
                elapsed_drawdown_threshold_pct = float(ACTIVE_BUY_ELAPSED_DRAWDOWN_FORCE_SELL_PCT)
            except Exception:
                elapsed_drawdown_threshold_pct = -0.90
            try:
                elapsed_drawdown_required_seconds = max(1, int(round(float(ACTIVE_BUY_ELAPSED_DRAWDOWN_FORCE_SELL_MINUTES) * 60.0)))
            except Exception:
                elapsed_drawdown_required_seconds = 120

            if live_pnl_pct <= elapsed_drawdown_threshold_pct:
                elapsed_drawdown_since_ts = ts_to_int(state.get("active_buy_elapsed_drawdown_below_since_ts"))
                if elapsed_drawdown_since_ts is None:
                    elapsed_drawdown_since_ts = current_scan_ts
                    state["active_buy_elapsed_drawdown_below_since_ts"] = elapsed_drawdown_since_ts
                elapsed_drawdown_elapsed_seconds = max(0, int(current_scan_ts - elapsed_drawdown_since_ts))
                state["active_buy_elapsed_drawdown_threshold_pct"] = elapsed_drawdown_threshold_pct
                state["active_buy_elapsed_drawdown_elapsed_seconds"] = elapsed_drawdown_elapsed_seconds
                state["active_buy_elapsed_drawdown_last_pnl_pct"] = live_pnl_pct
                elapsed_drawdown_sell = elapsed_drawdown_elapsed_seconds >= elapsed_drawdown_required_seconds
            else:
                reset_active_buy_elapsed_drawdown_tracking(state)

    universal_threshold_sell = bool(live_pnl_pct <= force_sell_pct)
    universal_skip_for_pma_gf_plus = bool(
        (
            pma_gf_plus_force_buy_active and
            bool(globals().get("UNIVERSAL_ACTIVE_BUY_FORCE_SELL_SKIP_PMA_GF_PLUS_FORCE_BUY", True))
        ) or (
            pma_gf_plus_qualified_active and
            bool(globals().get("UNIVERSAL_ACTIVE_BUY_FORCE_SELL_SKIP_PMA_GF_PLUS_QUALIFIED", True))
        )
    )
    if universal_threshold_sell and universal_skip_for_pma_gf_plus:
        universal_threshold_sell = False
        state["pma_gf_plus_universal_force_sell_skipped"] = True
        state["pma_gf_plus_universal_force_sell_skipped_reason"] = "force_buy" if pma_gf_plus_force_buy_active else "qualified_since_buy"
        state["pma_gf_plus_universal_force_sell_skipped_pnl_pct"] = live_pnl_pct
        state["pma_gf_plus_universal_force_sell_skipped_threshold_pct"] = force_sell_pct
        state["pma_gf_plus_universal_force_sell_skipped_ts"] = current_scan_ts
        # Backward-compatible fields used by earlier v3/v5 diagnostics.
        state["pma_gf_plus_force_buy_universal_force_sell_skipped"] = True
        state["pma_gf_plus_force_buy_universal_force_sell_skipped_pnl_pct"] = live_pnl_pct
        state["pma_gf_plus_force_buy_universal_force_sell_skipped_threshold_pct"] = force_sell_pct
        state["pma_gf_plus_force_buy_universal_force_sell_skipped_ts"] = current_scan_ts

    if peak_drawdown_sell or elapsed_drawdown_sell or universal_threshold_sell:
        sell_candle = build_live_price_sell_candle(
            live_reference_candle,
            scan_dt=scan_dt,
            live_price=live_current_price,
        )
        if not isinstance(sell_candle, dict):
            return None

        if peak_drawdown_sell:
            reason = (
                f"BUY-1M global peak-drawdown force sell hit: active BUY peak PnL reached "
                f"{peak_drawdown_peak_pnl_pct:+.3f}% after arming above {peak_drawdown_arm_pct:+.3f}%, "
                f"then current PnL stayed {peak_drawdown_drop_pct:.3f} percentage points below peak "
                f"for {peak_drawdown_elapsed_seconds}s/{peak_drawdown_required_seconds}s"
            )
            extra_flags = {
                "global_active_buy_peak_drawdown_force_sell": True,
                "active_buy_peak_drawdown_arm_pct": peak_drawdown_arm_pct,
                "active_buy_peak_drawdown_peak_pnl_pct": peak_drawdown_peak_pnl_pct,
                "active_buy_peak_drawdown_current_pnl_pct": live_pnl_pct_from_entry,
                "active_buy_peak_drawdown_drop_pct": peak_drawdown_drop_pct,
                "active_buy_peak_drawdown_required_drop_pct": peak_drawdown_required_drop_pct,
                "active_buy_peak_drawdown_elapsed_seconds": peak_drawdown_elapsed_seconds,
                "active_buy_peak_drawdown_required_seconds": peak_drawdown_required_seconds,
                "active_buy_peak_drawdown_below_since_ts": peak_drawdown_since_ts,
                "active_buy_peak_drawdown_peak_scan_ts": state.get("active_buy_peak_scan_ts"),
            }
        elif elapsed_drawdown_sell:
            reason = (
                f"BUY-1M elapsed drawdown force sell hit: current price stayed at or below "
                f"{elapsed_drawdown_threshold_pct:+.3f}% from {reference_label} for "
                f"{elapsed_drawdown_elapsed_seconds}s elapsed"
            )
            extra_flags = {
                "elapsed_drawdown_force_sell": True,
                "elapsed_drawdown_threshold_pct": elapsed_drawdown_threshold_pct,
                "elapsed_drawdown_elapsed_seconds": elapsed_drawdown_elapsed_seconds,
                "elapsed_drawdown_required_seconds": elapsed_drawdown_required_seconds,
                "elapsed_drawdown_below_since_ts": elapsed_drawdown_since_ts,
            }
        else:
            reason = f"BUY-1M universal force sell hit: current price reached {force_sell_pct:+.3f}% or lower from {reference_label}"
            extra_flags = {
                "universal_active_buy_force_sell": True,
            }

        sell_event = finalize_sell_transition(
            state,
            sell_candle,
            scan_dt,
            reason,
            {
                "entry_pnl_pct": live_pnl_pct_from_entry,
                "force_sell_reference_pnl_pct": live_pnl_pct,
                "current_price": live_current_price,
                "buy_signal_price": entry_price,
                "force_sell_reference_price": reference_price,
                "force_sell_reference_kind": reference_kind,
                "buy_style": buy_style,
                "live_force_sell": True,
                **extra_flags,
            },
        )

        return {
            "event": sell_event,
            "pnl_pct": live_pnl_pct,
            "reference_label": reference_label,
            "reference_price": reference_price,
            "current_price": live_current_price,
            "buy_style": buy_style,
            "peak_drawdown_force_sell": peak_drawdown_sell,
            "peak_drawdown_peak_pnl_pct": peak_drawdown_peak_pnl_pct,
            "peak_drawdown_current_pnl_pct": live_pnl_pct_from_entry,
            "peak_drawdown_drop_pct": peak_drawdown_drop_pct,
            "peak_drawdown_elapsed_seconds": peak_drawdown_elapsed_seconds,
            "peak_drawdown_required_seconds": peak_drawdown_required_seconds,
            "elapsed_drawdown_force_sell": elapsed_drawdown_sell,
            "elapsed_drawdown_elapsed_seconds": elapsed_drawdown_elapsed_seconds,
            "elapsed_drawdown_required_seconds": elapsed_drawdown_required_seconds,
        }

    return None


def _safe_finite_float(value):
    try:
        if value is None:
            return None
        result = float(value)
        if not math.isfinite(result):
            return None
        return result
    except Exception:
        return None


def pine_30m_status_from_strategy_result(result):
    if not isinstance(result, dict):
        return {}
    return {
        "pma": result.get("pine_30m_pma"),
        "pma_flat_neutral": bool(result.get("pine_30m_pma_flat_neutral")),
        "pma_flat_neutral_reason": result.get("pine_30m_pma_flat_neutral_reason"),
        "pma_flat_neutral_threshold_pct": result.get("pine_30m_pma_flat_neutral_threshold_pct"),
        "pma_sample_changes_pct": result.get("pine_30m_pma_sample_changes_pct"),
        "prev_pma": result.get("pine_30m_prev_pma"),
        "prev_pma_flat_neutral": bool(result.get("pine_30m_prev_pma_flat_neutral")),
        "prev_prev_pma": result.get("pine_30m_prev_prev_pma"),
        "prev_pma_candle_ts": result.get("pine_30m_prev_pma_candle_ts"),
        "prev_pma_candle_close_ts": result.get("pine_30m_prev_pma_candle_close_ts"),
        "prev_prev_pma_candle_ts": result.get("pine_30m_prev_prev_pma_candle_ts"),
        "prev_prev_pma_candle_close_ts": result.get("pine_30m_prev_prev_pma_candle_close_ts"),
        "DF0": result.get("pine_30m_DF0"),
        "GF_pos": result.get("pine_30m_GF_pos"),
        "predict_upper": result.get("pine_30m_predict_upper"),
        "pma_required_line": result.get("pine_30m_pma_required_line"),
        "pma_guard_eval_pma": result.get("pine_30m_pma_guard_eval_pma"),
        "pma_guard_eval_source": result.get("pine_30m_pma_guard_eval_source"),
        "pma_available": result.get("pine_30m_pma_available"),
        "available": result.get("pine_30m_available"),
        "reason": result.get("pine_30m_reason"),
    }


def pine_30m_df0_is_above(pma, df0):
    pma_value = _safe_finite_float(pma)
    df0_value = _safe_finite_float(df0)
    if pma_value is None or df0_value is None:
        return False
    if bool(PINE_30M_DF0_FORCE_SELL_STRICT_ABOVE):
        return pma_value > df0_value
    return pma_value >= df0_value


def pine_30m_df0_is_below(pma, df0):
    pma_value = _safe_finite_float(pma)
    df0_value = _safe_finite_float(df0)
    if pma_value is None or df0_value is None:
        return False
    if bool(PINE_30M_DF0_FORCE_SELL_STRICT_BELOW):
        return pma_value < df0_value
    return pma_value <= df0_value


def active_buy_pine_df0_below_confirmation_seconds():
    try:
        return max(1, int(float(PINE_30M_DF0_FORCE_SELL_BELOW_CONFIRM_SECONDS)))
    except Exception:
        return 12 * 60


def active_buy_pine_df0_below_confirmation_majority_ratio():
    try:
        return max(0.0, min(1.0, float(PINE_30M_DF0_FORCE_SELL_BELOW_CONFIRM_MAJORITY_RATIO)))
    except Exception:
        return 0.5


def update_active_buy_pine_df0_below_confirmation_window(state, current_scan_ts, currently_below, pma, df0):
    """Track below-DF0 confirmation scans over a real-time window.

    The window starts at the first scan that is below DF0 after a closed PMA has
    armed the DF0 force-sell rule. Every distinct scan timestamp during the
    window is counted; below scans are counted separately. At/after the configured
    elapsed time, a sell is allowed only if below scans are the majority.
    """
    if not isinstance(state, dict) or current_scan_ts is None:
        return {
            "active": False,
            "confirmed": False,
            "elapsed_seconds": None,
            "confirm_seconds": active_buy_pine_df0_below_confirmation_seconds(),
            "total_scans": 0,
            "below_scans": 0,
            "below_ratio": None,
        }

    current_scan_ts = int(current_scan_ts)
    confirm_seconds = active_buy_pine_df0_below_confirmation_seconds()
    majority_ratio = active_buy_pine_df0_below_confirmation_majority_ratio()
    started_ts = ts_to_int(state.get("active_buy_pine_df0_below_window_started_ts"))

    if started_ts is None:
        if not currently_below:
            return {
                "active": False,
                "confirmed": False,
                "elapsed_seconds": None,
                "confirm_seconds": confirm_seconds,
                "total_scans": 0,
                "below_scans": 0,
                "below_ratio": None,
            }
        started_ts = current_scan_ts
        state["active_buy_pine_df0_below_window_started_ts"] = started_ts
        state["active_buy_pine_df0_below_window_total_scans"] = 0
        state["active_buy_pine_df0_below_window_below_scans"] = 0
        state["active_buy_pine_df0_below_window_last_scan_ts"] = None

    total_scans = int(state.get("active_buy_pine_df0_below_window_total_scans") or 0)
    below_scans = int(state.get("active_buy_pine_df0_below_window_below_scans") or 0)
    last_scan_ts = ts_to_int(state.get("active_buy_pine_df0_below_window_last_scan_ts"))

    if last_scan_ts != current_scan_ts:
        total_scans += 1
        if currently_below:
            below_scans += 1
        state["active_buy_pine_df0_below_window_total_scans"] = total_scans
        state["active_buy_pine_df0_below_window_below_scans"] = below_scans
        state["active_buy_pine_df0_below_window_last_scan_ts"] = current_scan_ts

    state["active_buy_pine_df0_below_window_last_pma"] = pma
    state["active_buy_pine_df0_below_window_last_df0"] = df0

    elapsed_seconds = max(0, current_scan_ts - int(started_ts))
    below_ratio = (below_scans / total_scans) if total_scans > 0 else None
    confirmed = bool(
        elapsed_seconds >= confirm_seconds and
        total_scans > 0 and
        below_ratio is not None and
        below_ratio > majority_ratio
    )

    status = {
        "active": True,
        "confirmed": confirmed,
        "started_ts": started_ts,
        "elapsed_seconds": elapsed_seconds,
        "confirm_seconds": confirm_seconds,
        "total_scans": total_scans,
        "below_scans": below_scans,
        "below_ratio": below_ratio,
        "majority_ratio": majority_ratio,
    }

    if elapsed_seconds >= confirm_seconds and not confirmed:
        reset_active_buy_pine_df0_below_confirmation_window(state)
        status["reset_after_failed_majority"] = True

    return status




def active_buy_is_pma_gf_plus_lifecycle(state, pine_30m_status=None, scan_dt=None):
    """Return True when this active BUY is managed by the PMA/GF+ lifecycle rules.

    GF+ is not a strategy stage.  It is a flag/qualification on a normal BUY.
    The generic Pine DF0 exit should not manage these lifecycles; the dedicated
    PMA/GF+ DF0 rule handles them with the 5-minute and closed-above-max(GF+,DF0)
    requirements.
    """
    if not isinstance(state, dict):
        return False

    if bool(
        state.get("buy_from_pma_gf_plus_force") or
        state.get("pma_gf_plus_force_buy") or
        state.get("pma_gf_plus_force_buy_trigger") or
        state.get("active_buy_pma_gf_plus_qualified_since_buy")
    ):
        return True

    pine_30m_status = pine_30m_status if isinstance(pine_30m_status, dict) else {}
    try:
        pma, gf_plus, offset = pma_gf_plus_values(pine_30m_status)
    except Exception:
        pma = gf_plus = offset = None
    if pma is None or gf_plus is None or offset is None:
        return False

    try:
        instant_offset = float(PMA_GF_PLUS_FORCE_BUY_INSTANT_OFFSET)
    except Exception:
        instant_offset = 2.0
    if offset >= instant_offset:
        return True

    if offset <= 0:
        return False

    # V11.5: hold-seconds qualification was removed for PMA/GF+ lifecycle
    # management. A non-force active BUY only becomes a PMA/GF+ lifecycle by
    # reaching the instant PMA-GF+ offset threshold.
    return False


def should_skip_non_pma_sell_for_pma_gf_plus_lifecycle(state, sell_key, scan_dt=None, reason=None):
    """Return True when a PMA/GF+ lifecycle must ignore legacy/pump sell logic.

    V11.5 isolated PMA/GF+ positions from non-PMA sell systems. V11.8 keeps
    legacy/pump peak/streak/min-progress/drawdown/hard-exit sells skipped, but
    explicitly allows fib sell-zone management for PMA/GF+ lifecycles; rollover-specific failure sells are disabled by switch.
    """
    if not isinstance(state, dict):
        return False
    if not active_buy_is_pma_gf_plus_lifecycle(state):
        return False
    if not pma_gf_plus_skip_mutation_allowed():
        # FULL-5M isolation: skip the non-PMA sell decision without writing
        # PMA/GF+ skip/debug fields or resetting PMA/GF+ lifecycle timers.
        return True
    key = str(sell_key or "non_pma_sell").strip().lower().replace(" ", "_")
    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    state[f"pma_gf_plus_skipped_{key}"] = True
    state[f"pma_gf_plus_skipped_{key}_ts"] = scan_ts
    state[f"pma_gf_plus_skipped_{key}_reason"] = reason or "PMA/GF+ lifecycle uses PMA-only sell rules"
    state["pma_gf_plus_last_skipped_non_pma_sell_key"] = key
    state["pma_gf_plus_last_skipped_non_pma_sell_ts"] = scan_ts
    state["pma_gf_plus_last_skipped_non_pma_sell_reason"] = state[f"pma_gf_plus_skipped_{key}_reason"]
    return True


def maybe_force_sell_active_buy_on_pine_df0_cross(state, candidate, latest_closed_candle, current_forming_candle, scan_dt, pine_30m_status):
    """Sell an active real BUY when PMA falls back below Pine DF0 after a closed above-DF0 PMA.

    The tracking window starts from the real BUY timestamp, not from watch/pumpbox/
    shadow setup timestamps. DF0 is the Pine purple line: Daily Frequency for the
    most recent closed day.

    V2 behavior:
    - live PMA above DF0 is NOT enough to arm the rule;
    - the rule arms only after the latest CLOSED PMA has closed above DF0 once;
    - after arming, sell on a CLOSED PMA below DF0, or after 12 real minutes when
      below-DF0 live PMA was the majority of confirmation scans in that window.
    """
    if not bool(ENABLE_PINE_30M_DF0_CROSS_FORCE_SELL):
        return None
    if not isinstance(state, dict):
        return None

    # v43 strict FULL isolation: generic Pine DF0 must not create/reset
    # PMA/GF+ lifecycle-related active-buy tracking during FULL-5M scans.
    stage_pre = str(state.get("stage") or "idle").strip().lower()
    if (
        stage_pre in {"buy", "pumped"}
        and not pma_gf_plus_skip_mutation_allowed()
        and active_buy_is_pma_gf_plus_lifecycle(state, pine_30m_status=pine_30m_status, scan_dt=scan_dt)
    ):
        return None

    ensure_active_buy_state_defaults(state)
    stage = str(state.get("stage") or "idle").strip().lower()
    if stage not in {"buy", "pumped"}:
        reset_active_buy_pine_df0_tracking(state)
        return None

    if bool(globals().get("PINE_30M_DF0_FORCE_SELL_SKIP_PMA_GF_PLUS_LIFECYCLE", True)):
        if active_buy_is_pma_gf_plus_lifecycle(state, pine_30m_status=pine_30m_status, scan_dt=scan_dt):
            if pma_gf_plus_skip_mutation_allowed():
                state["active_buy_pine_df0_skipped_for_pma_gf_plus_lifecycle"] = True
                state["active_buy_pine_df0_skipped_for_pma_gf_plus_lifecycle_ts"] = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
                reset_active_buy_pine_df0_below_confirmation_window(state)
            return None

    first_buy_ts = active_buy_first_buy_ts(state)
    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if first_buy_ts is None or current_scan_ts is None:
        return None

    tracked_buy_ts = ts_to_int(state.get("active_buy_pine_df0_buy_ts"))
    if tracked_buy_ts != int(first_buy_ts):
        reset_active_buy_pine_df0_tracking(state)
        state["active_buy_pine_df0_buy_ts"] = int(first_buy_ts)

    if not isinstance(pine_30m_status, dict):
        return None

    pma = _safe_finite_float(pine_30m_status.get("pma"))
    closed_pma = _safe_finite_float(pine_30m_status.get("prev_pma"))
    df0 = _safe_finite_float(pine_30m_status.get("DF0"))
    if pma is None or df0 is None:
        return None

    was_seen_above = bool(state.get("active_buy_pine_df0_seen_above"))
    closed_above = pine_30m_df0_is_above(closed_pma, df0)
    closed_below = pine_30m_df0_is_below(closed_pma, df0)
    live_below = pine_30m_df0_is_below(pma, df0)

    if closed_above:
        if not was_seen_above:
            state["active_buy_pine_df0_seen_above_ts"] = current_scan_ts
            state["active_buy_pine_df0_seen_above_pma"] = closed_pma
            state["active_buy_pine_df0_seen_above_df0"] = df0
        state["active_buy_pine_df0_seen_above"] = True
        reset_active_buy_pine_df0_below_confirmation_window(state)

    state["active_buy_pine_df0_last_pma"] = pma
    state["active_buy_pine_df0_last_df0"] = df0
    state["active_buy_pine_df0_last_scan_ts"] = current_scan_ts

    if not bool(state.get("active_buy_pine_df0_seen_above")):
        return None

    below_window_status = None
    sell_trigger_mode = None
    sell_trigger_pma = pma

    if closed_below:
        sell_trigger_mode = "closed_below_df0"
        sell_trigger_pma = closed_pma
        reset_active_buy_pine_df0_below_confirmation_window(state)
    else:
        below_window_status = update_active_buy_pine_df0_below_confirmation_window(
            state,
            current_scan_ts,
            live_below,
            pma,
            df0,
        )
        if bool((below_window_status or {}).get("confirmed")):
            sell_trigger_mode = "majority_below_df0_window"

    if sell_trigger_mode is None:
        return None

    live_reference_candle = current_forming_candle if isinstance(current_forming_candle, dict) else latest_closed_candle
    live_current_price = None
    if isinstance(candidate, dict):
        live_current_price = resolve_current_market_price(
            candidate.get("latest_price"),
            live_reference_candle,
            prefer_candle=False,
            context=candidate,
        )
    if live_current_price in (None, 0, 0.0):
        live_current_price = _safe_positive_float((live_reference_candle or {}).get("c"))

    sell_candle = build_live_price_sell_candle(
        live_reference_candle,
        scan_dt=scan_dt,
        live_price=live_current_price,
    )
    if not isinstance(sell_candle, dict):
        return None

    entry_price = active_buy_live_entry_price(state)
    entry_pnl_pct = (
        pct_change(entry_price, live_current_price)
        if entry_price not in (None, 0, 0.0) and live_current_price not in (None, 0, 0.0)
        else None
    )

    seen_ts = ts_to_int(state.get("active_buy_pine_df0_seen_above_ts"))
    if sell_trigger_mode == "closed_below_df0":
        reason_text = (
            f"Pine 30m DF0 force sell: PMA closed above purple DF0 during active BUY "
            f"and later CLOSED below it (closed PMA {closed_pma:.6f} < DF0 {df0:.6f})"
        )
    else:
        elapsed_seconds = (below_window_status or {}).get("elapsed_seconds")
        total_scans = (below_window_status or {}).get("total_scans")
        below_scans = (below_window_status or {}).get("below_scans")
        below_ratio = (below_window_status or {}).get("below_ratio")
        reason_text = (
            f"Pine 30m DF0 force sell: after PMA closed above purple DF0, live PMA stayed below DF0 "
            f"for the majority of confirmation scans over {format_duration_compact(elapsed_seconds or 0)} "
            f"({below_scans}/{total_scans}, ratio {below_ratio:.3f}; PMA {pma:.6f} < DF0 {df0:.6f})"
        )

    sell_event = finalize_sell_transition(
        state,
        sell_candle,
        scan_dt,
        reason_text,
        {
            "pine_30m_df0_force_sell": True,
            "pine_30m_df0_force_sell_trigger_mode": sell_trigger_mode,
            "pine_30m_pma": pma,
            "pine_30m_closed_pma": closed_pma,
            "pine_30m_DF0": df0,
            "pine_30m_seen_above_DF0": True,
            "pine_30m_seen_above_DF0_ts": seen_ts,
            "pine_30m_seen_above_DF0_pma": state.get("active_buy_pine_df0_seen_above_pma"),
            "pine_30m_seen_above_DF0_df0": state.get("active_buy_pine_df0_seen_above_df0"),
            "pine_30m_below_window": below_window_status,
            "active_buy_first_buy_ts": first_buy_ts,
            "entry_price": entry_price,
            "entry_pnl_pct": entry_pnl_pct,
            "current_price": live_current_price,
            "buy_style": infer_buy_style(state),
            "live_force_sell": True,
        },
    )

    return {
        "event": sell_event,
        "pma": pma,
        "closed_pma": closed_pma,
        "DF0": df0,
        "seen_above_ts": seen_ts,
        "entry_pnl_pct": entry_pnl_pct,
        "current_price": live_current_price,
        "buy_style": infer_buy_style(state),
        "trigger_mode": sell_trigger_mode,
        "below_window": below_window_status,
    }


def reset_pma_gf_plus_force_buy_tracking(state):
    if not isinstance(state, dict):
        return
    state["pma_gf_plus_force_buy_above_since_ts"] = None
    state["pma_gf_plus_force_buy_above_elapsed_seconds"] = None
    state["pma_gf_plus_force_buy_upper_predict_since_ts"] = None
    state["pma_gf_plus_force_buy_upper_predict_elapsed_seconds"] = None
    state["pma_gf_plus_force_buy_upper_predict_line"] = None
    state["pma_gf_plus_force_buy_upper_predict_add"] = None
    state["pma_gf_plus_force_buy_setup_source"] = None
    state["pma_gf_plus_force_buy_setup_reason"] = None
    state["pma_gf_plus_force_buy_setup_line"] = None
    state["pma_gf_plus_force_buy_gf_plus_since_ts"] = None
    state["pma_gf_plus_force_buy_gf_plus_elapsed_seconds"] = None
    state["pma_gf_plus_force_buy_last_pma"] = None
    state["pma_gf_plus_force_buy_last_gf_plus"] = None
    state["pma_gf_plus_force_buy_last_offset"] = None
    state["pma_gf_plus_force_buy_last_reason"] = None
    reset_pma_gf_plus_force_buy_final_survival_tracking(state)
    # V14: always-on PMA/GF+ price/OMA history is persistent and age-pruned.
    # Resetting setup/readiness timers must not wipe history because every
    # scanned symbol should carry its 30m+7s sample window until that explicit
    # age window naturally expires.
    state["pma_gf_plus_force_buy_oma_last_passed"] = None

def reset_active_buy_non_gf_upper_predict_tracking(state):
    if not isinstance(state, dict):
        return
    state["active_buy_non_gf_upper_predict_closed_peak_pma"] = None
    state["active_buy_non_gf_upper_predict_closed_peak_ts"] = None
    state["active_buy_non_gf_upper_predict_closed_peak_predict_upper"] = None
    state["active_buy_non_gf_upper_predict_closed_peak_gf_plus"] = None
    state["active_buy_non_gf_upper_predict_latest_closed_above_ts"] = None
    state["active_buy_non_gf_upper_predict_latest_closed_above_pma"] = None
    state["active_buy_non_gf_upper_predict_below_peak_since_ts"] = None
    state["active_buy_non_gf_upper_predict_below_peak_elapsed_seconds"] = None
    state["active_buy_non_gf_upper_predict_last_pma"] = None
    state["active_buy_non_gf_upper_predict_last_closed_pma"] = None
    state["active_buy_non_gf_upper_predict_last_predict_upper"] = None
    state["active_buy_non_gf_upper_predict_last_gf_plus"] = None


def reset_active_buy_pma_gf_plus_tracking(state):
    if not isinstance(state, dict):
        return
    state["active_buy_pma_gf_plus_buy_ts"] = None
    state["active_buy_pma_gf_plus_entry_trigger"] = None
    state["active_buy_pma_gf_plus_entry_line_kind"] = None
    state["active_buy_pma_gf_plus_entry_line_value"] = None
    state["pma_gf_plus_force_buy_entry_line_kind"] = None
    state["pma_gf_plus_force_buy_entry_line_value"] = None
    state["pma_gf_plus_force_buy_trigger"] = None
