def pma_gf_plus_values(pine_30m_status):
    pine_30m_status = pine_30m_status if isinstance(pine_30m_status, dict) else {}
    pma = _safe_finite_float(pine_30m_status.get("pma"))
    gf_plus = _safe_finite_float(pine_30m_status.get("GF_pos"))
    if pma is None or gf_plus is None:
        return None, None, None
    return pma, gf_plus, pma - gf_plus


def pma_gf_plus_upper_predict_reference_line(pine_30m_status):
    pine_30m_status = pine_30m_status if isinstance(pine_30m_status, dict) else {}
    predict_upper_line = _safe_finite_float(pine_30m_status.get("predict_upper"))
    if predict_upper_line is None:
        predict_upper_line = _safe_finite_float(pine_30m_status.get("pma_required_line"))
    return predict_upper_line


def pma_gf_plus_force_buy_uses_upper_predict_line(state=None):
    if bool(globals().get("ENABLE_PMA_GF_PLUS_FORCE_BUY_USE_UPPER_PREDICT_LINE", False)):
        return True
    if isinstance(state, dict):
        for key in (
            "active_buy_pma_gf_plus_entry_line_kind",
            "pma_gf_plus_force_buy_entry_line_kind",
            "force_buy_line_kind",
        ):
            if str(state.get(key) or "").strip().lower() == "upper_predict":
                return True
    return False


def pma_gf_plus_active_sell_environment(state, pine_30m_status, gf_plus=None, df0=None):
    """Return the PMA line environment used by active PMA force-buy sells.

    In normal mode, sells remain GF+/DF0-based. In the optional upper-predict
    force-buy environment, DF0 is replaced by the neutral/middle 0.0 line and
    the GF-minus timer becomes (Upper Predict + configured entry offset) - margin.
    """
    upper_line = pma_gf_plus_upper_predict_reference_line(pine_30m_status)
    enabled = bool(globals().get("PMA_GF_PLUS_UPPER_PREDICT_SELL_ENVIRONMENT_ENABLED", True))
    use_upper = bool(enabled and upper_line is not None and pma_gf_plus_force_buy_uses_upper_predict_line(state))
    gf_plus_value = _safe_finite_float(gf_plus)
    df0_value = _safe_finite_float(df0)
    if use_upper:
        try:
            upper_offset = float(globals().get("PMA_GF_PLUS_FORCE_BUY_UPPER_PREDICT_LINE_OFFSET", 1.20))
        except Exception:
            upper_offset = 1.20
        upper_entry_line = upper_line + upper_offset
        return {
            "enabled": True,
            "use_upper_predict": True,
            "line_kind": "upper_predict",
            "line_label": "Upper Predict",
            "line_value": upper_line,
            "upper_predict_line": upper_line,
            "upper_predict_force_buy_offset": upper_offset,
            "upper_predict_entry_line": upper_entry_line,
            "gf_plus": gf_plus_value,
            "df0_raw": df0_value,
            "df0_sell_line": 0.0,
            "df0_sell_line_kind": "middle_line_0",
            "df0_sell_line_label": "middle line 0.0",
            "gf_minus_base_line": upper_entry_line,
            "gf_minus_base_line_kind": "upper_predict_plus_offset",
            "gf_minus_base_line_label": "Upper Predict + offset",
        }
    return {
        "enabled": enabled,
        "use_upper_predict": False,
        "line_kind": "gf_plus",
        "line_label": "GF+",
        "line_value": gf_plus_value,
        "gf_plus": gf_plus_value,
        "df0_raw": df0_value,
        "df0_sell_line": df0_value,
        "df0_sell_line_kind": "df0",
        "df0_sell_line_label": "DF0",
        "gf_minus_base_line": gf_plus_value,
        "gf_minus_base_line_kind": "gf_plus",
        "gf_minus_base_line_label": "GF+",
    }




def _pma_gf_plus_force_buy_history_window_seconds():
    try:
        configured = int(float(globals().get("PMA_GF_PLUS_FORCE_BUY_HISTORY_WINDOW_SECONDS", int(PINE_30M_TIMEFRAME_SECONDS) + 7)))
    except Exception:
        configured = int(PINE_30M_TIMEFRAME_SECONDS) + 7
    return max(1, configured)


def _pma_gf_plus_force_buy_close_grace_seconds():
    try:
        configured = int(float(globals().get("PMA_GF_PLUS_FORCE_BUY_CLOSE_TRANSITION_GRACE_SECONDS", 7)))
    except Exception:
        configured = 7
    return max(0, configured)


def _pma_gf_plus_force_buy_close_grace_status(pine_30m_status, scan_dt=None):
    pine_30m_status = pine_30m_status if isinstance(pine_30m_status, dict) else {}
    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    close_ts = ts_to_int(pine_30m_status.get("prev_pma_candle_close_ts"))
    grace_seconds = _pma_gf_plus_force_buy_close_grace_seconds()
    in_grace = False
    elapsed = None
    if scan_ts is not None and close_ts is not None:
        elapsed = int(scan_ts - close_ts)
        in_grace = bool(0 <= elapsed <= grace_seconds)
    return {
        "enabled": bool(globals().get("PMA_GF_PLUS_FORCE_BUY_USE_CLOSED_PMA_DURING_CLOSE_GRACE", True)),
        "in_grace": bool(in_grace),
        "scan_ts": scan_ts,
        "prev_pma_candle_close_ts": close_ts,
        "elapsed_seconds": elapsed,
        "grace_seconds": grace_seconds,
    }


def _pma_gf_plus_force_buy_live_pma_better_status(live_pma, closed_pma, current_price=None, reference_candle=None, live_candle_age_seconds=None):
    """Return whether live PMA is reliable enough to replace closed PMA during the 30m close grace.

    V18: during the 120s post-close transition, closed PMA remains the default
    for force-buy entry gates.  Live PMA may take over only when the new live
    candle is at least 7 seconds old, live PMA is clearly better than closed PMA,
    and current price confirms momentum.
    """
    try:
        min_pma_delta = float(globals().get("PMA_GF_PLUS_FORCE_BUY_CLOSE_GRACE_LIVE_BETTER_MIN_PMA_DELTA", 0.20))
    except Exception:
        min_pma_delta = 0.20
    try:
        min_price_momentum_pct = float(globals().get("PMA_GF_PLUS_FORCE_BUY_CLOSE_GRACE_LIVE_BETTER_MIN_PRICE_MOMENTUM_PCT", 0.01))
    except Exception:
        min_price_momentum_pct = 0.01
    try:
        min_live_age_seconds = max(0, int(float(globals().get("PMA_GF_PLUS_FORCE_BUY_CLOSE_GRACE_LIVE_BETTER_MIN_LIVE_AGE_SECONDS", 7))))
    except Exception:
        min_live_age_seconds = 7

    live_pma = _safe_finite_float(live_pma)
    closed_pma = _safe_finite_float(closed_pma)
    current_price = _safe_positive_float(current_price)
    reference_candle = reference_candle if isinstance(reference_candle, dict) else {}
    live_candle_age_seconds = ts_to_int(live_candle_age_seconds)

    live_age_ok = bool(live_candle_age_seconds is not None and live_candle_age_seconds >= min_live_age_seconds)

    pma_delta = (live_pma - closed_pma) if live_pma is not None and closed_pma is not None else None
    pma_better = bool(pma_delta is not None and pma_delta >= min_pma_delta)

    momentum_refs = []
    for key in ("o", "c", "body_top"):
        value = _safe_positive_float(reference_candle.get(key))
        if value is not None:
            momentum_refs.append(value)
    reference_price = max(momentum_refs) if momentum_refs else None
    price_momentum_pct = pct_change(reference_price, current_price) if reference_price not in (None, 0, 0.0) and current_price not in (None, 0, 0.0) else None
    price_momentum_ok = bool(price_momentum_pct is not None and price_momentum_pct >= min_price_momentum_pct)

    return {
        "live_better": bool(live_age_ok and pma_better and price_momentum_ok),
        "live_age_ok": live_age_ok,
        "live_candle_age_seconds": live_candle_age_seconds,
        "min_live_age_seconds": min_live_age_seconds,
        "pma_better": pma_better,
        "price_momentum_ok": price_momentum_ok,
        "pma_delta": pma_delta,
        "min_pma_delta": min_pma_delta,
        "current_price": current_price,
        "reference_price": reference_price,
        "price_momentum_pct": price_momentum_pct,
        "min_price_momentum_pct": min_price_momentum_pct,
    }


def pma_gf_plus_force_buy_values(pine_30m_status, scan_dt=None, current_price=None, reference_candle=None, force_upper_predict_line=None):
    """Return the PMA/GF+ values used by force-buy entry gates.

    V18 keeps the 30m close transition smooth: for the first 120 seconds after
    a 30m PMA candle closes, entry gates use latest CLOSED PMA by default.
    Live PMA is allowed during that grace only if the live candle is at least
    7 seconds old, live PMA is clearly better than closed PMA, and current price
    confirms momentum.  Existing active-position
    exits still use pma_gf_plus_values() directly, with separate sell-side
    invalid-PMA suppression.
    """
    pine_30m_status = pine_30m_status if isinstance(pine_30m_status, dict) else {}
    live_pma = _safe_finite_float(pine_30m_status.get("pma"))
    live_current_slot_ok = bool(pine_30m_status.get("live_candle_current_slot_ok"))
    live_missing_current_slot = bool(pine_30m_status.get("live_candle_missing_current_slot"))
    live_pma_for_entry = live_pma if live_current_slot_ok else None
    closed_pma = _safe_finite_float(pine_30m_status.get("prev_pma"))
    gf_plus = _safe_finite_float(pine_30m_status.get("GF_pos"))
    force_buy_line_value = gf_plus
    force_buy_line_kind = "gf_plus"
    force_buy_line_source = "GF_pos"
    if force_upper_predict_line is None:
        use_upper_predict_line_for_values = bool(globals().get("ENABLE_PMA_GF_PLUS_FORCE_BUY_USE_UPPER_PREDICT_LINE", False))
    else:
        use_upper_predict_line_for_values = bool(force_upper_predict_line)
    if use_upper_predict_line_for_values:
        predict_upper_line = _safe_finite_float(pine_30m_status.get("predict_upper"))
        if predict_upper_line is None:
            predict_upper_line = _safe_finite_float(pine_30m_status.get("pma_required_line"))
        if predict_upper_line is not None:
            force_buy_line_value = predict_upper_line
            force_buy_line_kind = "upper_predict"
            force_buy_line_source = "predict_upper"
    grace = _pma_gf_plus_force_buy_close_grace_status(pine_30m_status, scan_dt=scan_dt)
    better = _pma_gf_plus_force_buy_live_pma_better_status(
        live_pma_for_entry,
        closed_pma,
        current_price=current_price,
        reference_candle=reference_candle,
        live_candle_age_seconds=grace.get("elapsed_seconds"),
    )
    # V48: live-PMA BUY execution is disabled during the 120s close-grace.
    # During grace, entry gates listen to the latest CLOSED PMA only.  Live PMA
    # may still build setup/quality/OMA history after 7s elsewhere, but it must
    # not execute a normal live instant-offset BUY until the grace ends.  The
    # only live-assisted BUY still allowed inside grace is the closed-PMA direct
    # branch, which explicitly requires latest CLOSED PMA proof above GF+ and
    # live PMA >= that closed proof + the configured +0.20.
    live_overall_better_than_closed = False
    live_entry_disabled_by_close_grace = bool(
        grace.get("enabled") and
        grace.get("in_grace") and
        bool(globals().get("PMA_GF_PLUS_FORCE_BUY_DISABLE_LIVE_ENTRY_DURING_CLOSE_GRACE", True))
    )
    use_closed = bool(
        live_entry_disabled_by_close_grace and
        closed_pma is not None
    )
    pma = closed_pma if use_closed else live_pma_for_entry
    if use_closed:
        source = "closed_pma_close_grace_live_entry_disabled"
    elif live_current_slot_ok:
        source = "live_pma"
    else:
        source = "live_pma_unavailable_no_current_slot"
    status = {
        "force_buy_pma_source": source,
        "force_buy_live_pma": live_pma,
        "force_buy_live_pma_for_entry": live_pma_for_entry,
        "force_buy_live_pma_current_slot_ok": bool(live_current_slot_ok),
        "force_buy_live_pma_missing_current_slot": bool(live_missing_current_slot),
        "force_buy_live_pma_unusable_reason": None if live_current_slot_ok else "missing_current_live_candle_slot",
        "force_buy_live_pma_flat_neutral": bool(pine_30m_status.get("pma_flat_neutral")),
        "force_buy_live_pma_flat_neutral_status": pine_30m_status.get("pma_flat_neutral_status"),
        "force_buy_closed_pma": closed_pma,
        "force_buy_closed_pma_flat_neutral": bool(pine_30m_status.get("prev_pma_flat_neutral")),
        "force_buy_line_kind": force_buy_line_kind,
        "force_buy_line_value": force_buy_line_value,
        "force_buy_line_source": force_buy_line_source,
        "force_buy_line_override_enabled": bool(force_buy_line_kind != "gf_plus"),
        "force_buy_close_grace": grace,
        "force_buy_live_pma_better_status": better,
        "force_buy_live_pma_better_during_close_grace": bool(better.get("live_better")),
        "force_buy_live_pma_overall_better_than_closed_during_close_grace": False,
        "force_buy_close_grace_disabled_by_live_overall_better": False,
        "force_buy_live_entry_disabled_during_close_grace": bool(live_entry_disabled_by_close_grace),
    }
    if pma is None or force_buy_line_value is None:
        return None, None, None, status
    return pma, force_buy_line_value, pma - force_buy_line_value, status


def _pma_gf_plus_prune_timed_samples(samples, sample_ts, current_scan_ts, max_age_seconds=None):
    """Keep stored samples persistent except for the explicit age window.

    Missing timestamps are kept defensively instead of being dropped; this avoids
    losing history after older state migrations. Samples with known timestamps
    older than the configured 30m+grace window are pruned.
    """
    if max_age_seconds is None:
        max_age_seconds = _pma_gf_plus_force_buy_history_window_seconds()
    try:
        max_age_seconds = max(1, int(max_age_seconds))
    except Exception:
        max_age_seconds = int(PINE_30M_TIMEFRAME_SECONDS) + 7
    samples = list(samples or [])
    sample_ts = list(sample_ts or [])
    kept_samples = []
    kept_ts = []
    for idx, item in enumerate(samples):
        numeric = _safe_finite_float(item)
        if numeric is None:
            continue
        ts_value = ts_to_int(sample_ts[idx]) if idx < len(sample_ts) else None
        if current_scan_ts is not None and ts_value is not None and current_scan_ts - ts_value > max_age_seconds:
            continue
        kept_samples.append(float(numeric))
        kept_ts.append(ts_value)
    return kept_samples, kept_ts




def _pma_gf_plus_force_buy_history_bounds(reference_candle=None, pine_30m_status=None, scan_dt=None, state=None):
    """Return current-candle anchored PMA/GF+ history bounds.

    V15: history is valid for the current live 30m candle age, plus the close
    transition grace after that candle closes.  It is not a rolling 30m+7s
    lookback.  During the first grace seconds after a close, keep the just-closed
    candle's history and do not require the new live PMA history yet.
    """
    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    candle_seconds = int(globals().get('PINE_30M_TIMEFRAME_SECONDS', 30 * 60) or (30 * 60))
    grace_seconds = _pma_gf_plus_force_buy_close_grace_seconds()
    pine_30m_status = pine_30m_status if isinstance(pine_30m_status, dict) else {}
    reference_candle = reference_candle if isinstance(reference_candle, dict) else {}

    prev_close_ts = ts_to_int(pine_30m_status.get('prev_pma_candle_close_ts'))
    grace = _pma_gf_plus_force_buy_close_grace_status(pine_30m_status, scan_dt=scan_dt)
    if bool(grace.get('enabled') and grace.get('in_grace')) and prev_close_ts is not None:
        start_ts = prev_close_ts - candle_seconds
        end_ts = prev_close_ts + grace_seconds
        source = 'just_closed_candle_plus_grace'
    else:
        start_ts = ts_to_int(reference_candle.get('t'))
        if start_ts is None and isinstance(state, dict):
            start_ts = ts_to_int(state.get('pma_gf_plus_force_buy_history_candle_start_ts'))
        end_ts = (start_ts + candle_seconds + grace_seconds) if start_ts is not None else None
        source = 'current_live_candle_age_plus_grace'

    if scan_ts is not None and end_ts is not None:
        end_ts = min(end_ts, scan_ts)

    if isinstance(state, dict):
        state['pma_gf_plus_force_buy_history_candle_start_ts'] = start_ts
        state['pma_gf_plus_force_buy_history_window_start_ts'] = start_ts
        state['pma_gf_plus_force_buy_history_window_end_ts'] = end_ts
        state['pma_gf_plus_force_buy_history_window_source'] = source

    return {
        'start_ts': start_ts,
        'end_ts': end_ts,
        'scan_ts': scan_ts,
        'source': source,
        'grace_seconds': grace_seconds,
        'candle_seconds': candle_seconds,
        'close_grace': grace,
    }


def _pma_gf_plus_prune_samples_by_bounds(samples, sample_ts, start_ts=None, end_ts=None):
    samples = list(samples or [])
    sample_ts = list(sample_ts or [])
    if start_ts is None and end_ts is None:
        return samples, sample_ts
    kept_samples = []
    kept_ts = []
    for idx, item in enumerate(samples):
        numeric = _safe_finite_float(item)
        if numeric is None:
            continue
        ts_value = ts_to_int(sample_ts[idx]) if idx < len(sample_ts) else None
        # Unknown timestamps are kept to avoid destructive loss during migration.
        if ts_value is not None:
            if start_ts is not None and ts_value < start_ts:
                continue
            if end_ts is not None and ts_value > end_ts:
                continue
        kept_samples.append(float(numeric))
        kept_ts.append(ts_value)
    return kept_samples, kept_ts

def pma_gf_plus_force_buy_closed_pma_floor_status(pine_30m_status):
    """Validate the PMA midpoint floor for PMA/GF+ force-buy setup.

    v3 correction: this guard may use LIVE PMA from above the midpoint between
    0.0 and Predict Lower, matching the original live-PMA start behavior.  The
    old latest-CLOSED-PMA value is still reported for diagnostics, but closed
    PMA above Predict Upper is handled separately by the 5-second GF+ grace
    branch in pma_gf_plus_force_buy_status().
    """
    enabled = bool(globals().get("PMA_GF_PLUS_FORCE_BUY_REQUIRE_CLOSED_PMA_ABOVE_HALF_PREDICT_LOWER", True))
    use_live_pma = bool(globals().get("PMA_GF_PLUS_FORCE_BUY_USE_LIVE_PMA_MID_LOWER_START", True))
    status = {
        "enabled": enabled,
        "passed": not enabled,
        "pma": None,
        "prev_pma": None,
        "used_pma": None,
        "used_pma_kind": "live" if use_live_pma else "closed",
        "predict_lower": None,
        "factor": None,
        "threshold": None,
        "threshold_source": None,
        "reason": "PMA midpoint(0.0, Predict Lower) guard disabled" if not enabled else None,
    }
    if not enabled:
        return status

    pine_30m_status = pine_30m_status if isinstance(pine_30m_status, dict) else {}
    live_pma = _safe_finite_float(pine_30m_status.get("pma"))
    prev_pma = _safe_finite_float(pine_30m_status.get("prev_pma"))
    predict_lower = _safe_finite_float(pine_30m_status.get("predict_lower"))
    try:
        factor = float(globals().get("PMA_GF_PLUS_FORCE_BUY_LIVE_PMA_PREDICT_LOWER_FACTOR" if use_live_pma else "PMA_GF_PLUS_FORCE_BUY_CLOSED_PMA_PREDICT_LOWER_FACTOR", 0.5))
    except Exception:
        factor = 0.5
    used_pma = live_pma if use_live_pma else prev_pma
    used_kind = "live PMA" if use_live_pma else "latest CLOSED PMA"
    status.update({"pma": live_pma, "prev_pma": prev_pma, "used_pma": used_pma, "used_pma_kind": "live" if use_live_pma else "closed", "predict_lower": predict_lower, "factor": factor})

    if used_pma is None:
        status["reason"] = f"{used_kind} unavailable; PMA/GF+ force BUY blocked"
        return status
    if predict_lower is None:
        status["reason"] = "Predict Lower unavailable; PMA/GF+ force BUY blocked"
        return status

    threshold = 0.0 + ((predict_lower - 0.0) * factor)
    status["threshold"] = threshold
    status["threshold_source"] = "midpoint_from_0_to_predict_lower"
    if used_pma >= threshold:
        status["passed"] = True
        status["reason"] = f"{used_kind} {used_pma:.6f} >= midpoint(0.0, Predict Lower) threshold {threshold:.6f}"
    else:
        status["reason"] = f"{used_kind} {used_pma:.6f} < midpoint(0.0, Predict Lower) threshold {threshold:.6f}; PMA/GF+ force BUY blocked"
    return status

def pma_gf_plus_force_buy_post_sell_weaker_pma_block_status(state, current_pma, scan_dt):
    """Return the 1-hour post-sell GF+ rebuy blocker status.

    The blocker is only active after a PMA/GF+ lifecycle sell. During the window,
    a new GF+ force-BUY is allowed only when the current attempt PMA is at least
    PMA_GF_PLUS_FORCE_BUY_POST_SELL_REQUIRED_PMA_IMPROVEMENT above the previous
    GF+ BUY PMA. This blocks weak/stale rebuys on the same failed GF+ cycle.
    """
    status = {
        "enabled": bool(globals().get("PMA_GF_PLUS_FORCE_BUY_POST_SELL_WEAKER_PMA_BLOCK_ENABLED", True)),
        "blocked": False,
        "reason": None,
        "previous_buy_pma": None,
        "current_pma": current_pma,
        "required_improvement": None,
        "required_current_pma": None,
        "sell_ts": None,
        "until_ts": None,
        "remaining_seconds": None,
    }
    if not bool(status.get("enabled")) or not isinstance(state, dict):
        return status

    current_pma_value = _safe_finite_float(current_pma)
    previous_buy_pma = _safe_finite_float(state.get("last_pma_gf_plus_buy_pma"))
    sell_ts = ts_to_int(state.get("last_pma_gf_plus_sell_ts"))
    until_ts = ts_to_int(state.get("last_pma_gf_plus_sell_until_ts"))
    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)

    try:
        required_improvement = max(0.0, float(globals().get("PMA_GF_PLUS_FORCE_BUY_POST_SELL_REQUIRED_PMA_IMPROVEMENT", 0.50)))
    except Exception:
        required_improvement = 0.50

    required_current_pma = (previous_buy_pma + required_improvement) if previous_buy_pma is not None else None

    status.update({
        "previous_buy_pma": previous_buy_pma,
        "current_pma": current_pma_value,
        "required_improvement": required_improvement,
        "required_current_pma": required_current_pma,
        "sell_ts": sell_ts,
        "until_ts": until_ts,
    })

    if current_scan_ts is None or sell_ts is None:
        return status

    try:
        window_seconds = max(0, int(float(globals().get("PMA_GF_PLUS_FORCE_BUY_POST_SELL_WEAKER_PMA_BLOCK_SECONDS", 2 * 60))))
    except Exception:
        window_seconds = 2 * 60

    if until_ts is None:
        until_ts = int(sell_ts) + window_seconds
        status["until_ts"] = until_ts

    remaining_seconds = int(until_ts) - int(current_scan_ts)
    status["remaining_seconds"] = max(0, remaining_seconds)
    if remaining_seconds <= 0:
        return status

    if previous_buy_pma is None or current_pma_value is None or required_current_pma is None:
        return status

    if current_pma_value < required_current_pma:
        status["blocked"] = True
        status["reason"] = (
            f"PMA/GF+ force BUY blocked for {format_duration_compact(remaining_seconds)} after previous GF+ sell: "
            f"current attempt PMA {current_pma_value:.6f} must be at least "
            f"previous BUY PMA {previous_buy_pma:.6f} + {required_improvement:.6f} = {required_current_pma:.6f}"
        )
    return status


def pma_gf_plus_force_buy_reentry_gate_status(state, pma, gf_plus, offset, oma_status=None, quality_status=None, scan_dt=None):
    """Return V9 PMA/OMA post-sell re-entry gate status.

    This replaces the old short post-sell weaker-PMA blocker. It does not reset
    the PMA/GF+ above-hold timer; it only blocks current-scan BUY readiness when
    the symbol is trying to re-enter after a recent sell without stronger PMA/OMA
    structure.
    """
    status = {
        "enabled": bool(globals().get("ENABLE_PMA_GF_PLUS_REENTRY_GATE", True)),
        "passed": True,
        "blocked": False,
        "reason": "PMA/OMA re-entry gate disabled",
        "sell_ts": None,
        "sell_age_seconds": None,
        "max_age_seconds": None,
        "current_pma": _safe_finite_float(pma),
        "current_gf_plus": _safe_finite_float(gf_plus),
        "current_offset": _safe_finite_float(offset),
        "current_oma": None,
        "last_buy_ts": None,
        "last_buy_age_seconds": None,
        "last_buy_max_age_seconds": None,
        "last_buy_anchor_expired": False,
        "last_buy_pma": None,
        "last_buy_oma": None,
        "last_buy_offset": None,
        "last_sell_pma": None,
        "last_sell_oma": None,
        "last_sell_offset": None,
        "last_sell_price": None,
        "bad_buy_pma": None,
        "instant_reentry_ok": False,
        "pma_stronger_ok": False,
        "oma_stronger_ok": False,
        "reclaim_ok": False,
        "weaker_than_bad_buy_pma": False,
    }
    if not bool(status.get("enabled")) or not isinstance(state, dict):
        return status

    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    sell_ts = ts_to_int(state.get("last_pma_gf_plus_sell_ts"))
    status["sell_ts"] = sell_ts
    if current_scan_ts is None or sell_ts is None:
        status["reason"] = "no recent PMA/GF+ sell to gate"
        return status

    try:
        max_age_seconds = max(0, int(float(globals().get("PMA_GF_PLUS_REENTRY_GATE_MAX_AGE_SECONDS", 2 * 60 * 60))))
    except Exception:
        max_age_seconds = 2 * 60 * 60
    status["max_age_seconds"] = max_age_seconds
    sell_age_seconds = max(0, int(current_scan_ts - sell_ts))
    status["sell_age_seconds"] = sell_age_seconds
    if max_age_seconds > 0 and sell_age_seconds > max_age_seconds:
        status["reason"] = "PMA/OMA re-entry gate expired after max age"
        return status

    current_pma = status.get("current_pma")
    current_offset = status.get("current_offset")
    current_oma = _safe_finite_float((oma_status or {}).get("oma") if isinstance(oma_status, dict) else None)
    status["current_oma"] = current_oma

    last_buy_ts = ts_to_int(state.get("last_pma_gf_plus_buy_ts"))
    if last_buy_ts is None:
        last_buy_ts = ts_to_int(state.get("last_pma_gf_plus_sell_entry_ts"))
    status["last_buy_ts"] = last_buy_ts
    try:
        last_buy_max_age_seconds = max(0, int(float(globals().get("PMA_GF_PLUS_REENTRY_GATE_LAST_BUY_MAX_AGE_SECONDS", max_age_seconds))))
    except Exception:
        last_buy_max_age_seconds = max_age_seconds
    status["last_buy_max_age_seconds"] = last_buy_max_age_seconds
    last_buy_anchor_expired = False
    if current_scan_ts is not None and last_buy_ts is not None:
        last_buy_age_seconds = max(0, int(current_scan_ts - last_buy_ts))
        status["last_buy_age_seconds"] = last_buy_age_seconds
        if last_buy_max_age_seconds > 0 and last_buy_age_seconds > last_buy_max_age_seconds:
            last_buy_anchor_expired = True
            status["last_buy_anchor_expired"] = True

    last_buy_pma = None if last_buy_anchor_expired else _safe_finite_float(state.get("last_pma_gf_plus_buy_pma"))
    last_buy_oma = None if last_buy_anchor_expired else _safe_finite_float(state.get("last_pma_gf_plus_buy_oma"))
    last_buy_offset = None if last_buy_anchor_expired else _safe_finite_float(state.get("last_pma_gf_plus_buy_offset"))
    last_sell_pma = _safe_finite_float(state.get("last_pma_gf_plus_sell_pma"))
    last_sell_oma = _safe_finite_float(state.get("last_pma_gf_plus_sell_oma"))
    last_sell_offset = _safe_finite_float(state.get("last_pma_gf_plus_sell_offset"))
    last_sell_price = _safe_positive_float(state.get("last_pma_gf_plus_sell_price"))
    bad_buy_pma = _safe_finite_float(state.get("pma_gf_plus_bad_buy_last_pma"))
    status.update({
        "last_buy_ts": last_buy_ts,
        "last_buy_pma": last_buy_pma,
        "last_buy_oma": last_buy_oma,
        "last_buy_offset": last_buy_offset,
        "last_sell_pma": last_sell_pma,
        "last_sell_oma": last_sell_oma,
        "last_sell_offset": last_sell_offset,
        "last_sell_price": last_sell_price,
        "bad_buy_pma": bad_buy_pma,
    })

    try:
        instant_offset = float(globals().get("PMA_GF_PLUS_REENTRY_GATE_INSTANT_OFFSET", PMA_GF_PLUS_FORCE_BUY_INSTANT_OFFSET))
    except Exception:
        instant_offset = 3.2
    try:
        pma_improvement = max(0.0, float(globals().get("PMA_GF_PLUS_REENTRY_GATE_PMA_IMPROVEMENT", 0.10)))
    except Exception:
        pma_improvement = 0.10
    try:
        oma_improvement = max(0.0, float(globals().get("PMA_GF_PLUS_REENTRY_GATE_OMA_IMPROVEMENT", 0.05)))
    except Exception:
        oma_improvement = 0.05
    try:
        reclaim_min_offset = max(0.0, float(globals().get("PMA_GF_PLUS_REENTRY_GATE_RECLAIM_MIN_OFFSET", PMA_GF_PLUS_FORCE_BUY_HOLD_MIN_OFFSET)))
    except Exception:
        reclaim_min_offset = 1.00

    status.update({
        "instant_offset_required": instant_offset,
        "pma_improvement_required": pma_improvement,
        "oma_improvement_required": oma_improvement,
        "reclaim_min_offset": reclaim_min_offset,
    })

    if current_offset is not None and current_offset >= instant_offset:
        status["instant_reentry_ok"] = True
        status["reason"] = f"PMA/OMA re-entry gate passed: instant offset {current_offset:.6f} >= +{instant_offset:.3f}"
        return status

    block_weaker_than_bad_buy_pma = bool(globals().get("PMA_GF_PLUS_REENTRY_GATE_BLOCK_WEAKER_THAN_BAD_BUY_PMA", True))
    if block_weaker_than_bad_buy_pma and bad_buy_pma is not None and current_pma is not None and current_pma < bad_buy_pma:
        status["passed"] = False
        status["blocked"] = True
        status["weaker_than_bad_buy_pma"] = True
        status["reason"] = f"PMA/GF+ force buy blocked: current PMA {current_pma:.6f} is weaker than last bad-buy PMA {bad_buy_pma:.6f}"
        return status

    if last_buy_pma is not None and current_pma is not None and current_pma >= (last_buy_pma + pma_improvement):
        status["pma_stronger_ok"] = True
    if last_buy_oma is not None and current_oma is not None and current_oma >= (last_buy_oma + oma_improvement):
        status["oma_stronger_ok"] = True
    if last_sell_offset is not None and last_sell_offset <= 0 and current_offset is not None and current_offset >= reclaim_min_offset:
        status["reclaim_ok"] = True

    pma_oma_stronger_ok = bool(status["pma_stronger_ok"] and status["oma_stronger_ok"])
    status["pma_oma_stronger_ok"] = pma_oma_stronger_ok

    if pma_oma_stronger_ok or status["reclaim_ok"]:
        parts = []
        if pma_oma_stronger_ok:
            parts.append(
                f"PMA {current_pma:.6f} >= last buy PMA {last_buy_pma:.6f} + {pma_improvement:.3f} "
                f"AND OMA {current_oma:.6f} >= last buy OMA {last_buy_oma:.6f} + {oma_improvement:.3f}"
            )
        if status["reclaim_ok"]:
            parts.append(f"offset reached GF+ with {current_offset:.6f} >= +{reclaim_min_offset:.3f}")
        status["reason"] = "PMA/OMA re-entry gate passed: " + "; ".join(parts)
        return status

    # If no reliable PMA/OMA history exists, do not create a permanent blind block.
    if last_buy_pma is None and last_buy_oma is None and last_sell_offset is None and bad_buy_pma is None:
        if bool(status.get("last_buy_anchor_expired")):
            status["reason"] = "PMA/OMA re-entry gate passed: previous buy PMA/OMA anchor expired after 2h"
        else:
            status["reason"] = "PMA/OMA re-entry gate passed: no comparable prior buy structure"
        return status

    status["passed"] = False
    status["blocked"] = True
    status["reason"] = (
        "PMA/GF+ force buy blocked: PMA/OMA re-entry gate needs stronger structure "
        f"after prior buy (current PMA {current_pma if current_pma is not None else '-'}, "
        f"last buy PMA {last_buy_pma if last_buy_pma is not None else '-'}, "
        f"current OMA {current_oma if current_oma is not None else '-'}, "
        f"last buy OMA {last_buy_oma if last_buy_oma is not None else '-'}, "
        f"current offset {current_offset if current_offset is not None else '-'})"
    )
    return status


def pma_gf_plus_force_buy_fib_range_status(state):
    """Return any already-built fib range PMA/GF+ force-BUY can reuse.

    PMA/GF+ force-BUY bypasses confirmation, but it must not emit a BUY event
    with fib_bottom/fib_top = null.  A valid range may come from the normal
    active/pending fib fields, shadow-pending fields, or pumpbox fields. If none
    exists, activation will create a replacement range from real candle/buy-price
    data instead of blocking the BUY.
    """
    status = {
        "required": bool(globals().get("PMA_GF_PLUS_FORCE_BUY_REQUIRE_REAL_FIB_RANGE", True)),
        "valid": False,
        "fib_bottom": None,
        "fib_top": None,
        "source": None,
        "reason": None,
    }
    if not isinstance(state, dict):
        status["reason"] = "missing state"
        return status
    if not status["required"]:
        status["valid"] = True
        status["reason"] = "fib range not required"
        return status

    try:
        min_zone_pct = float(globals().get("PMA_GF_PLUS_FORCE_BUY_FIB_MIN_ZONE_PCT", FIB_SELL_MIN_ZONE_PCT))
    except Exception:
        min_zone_pct = FIB_SELL_MIN_ZONE_PCT

    candidates = [
        ("state_fib", state.get("fib_bottom"), state.get("fib_top")),
        ("pumpbox_fib", state.get("pumpbox_fib_bottom"), state.get("pumpbox_fib_top")),
        ("shadow_pending_buy_fib", state.get("shadow_pending_buy_fib_bottom"), state.get("shadow_pending_buy_fib_top")),
    ]
    for source, fib_bottom, fib_top in candidates:
        low, high = normalized_fib_bounds(fib_bottom, fib_top)
        if fib_range_is_real(low, high, min_zone_pct=min_zone_pct):
            status.update({
                "valid": True,
                "fib_bottom": low,
                "fib_top": high,
                "source": source,
                "reason": f"valid {source} range",
            })
            return status

    # Return the best available raw values for debugging, even though invalid.
    for source, fib_bottom, fib_top in candidates:
        low, high = normalized_fib_bounds(fib_bottom, fib_top)
        if low is not None or high is not None:
            status.update({
                "fib_bottom": low,
                "fib_top": high,
                "source": source,
                "reason": f"{source} range is missing/too small",
            })
            return status

    status["reason"] = "no existing fib range available for PMA/GF+ force BUY"
    return status


def _pma_gf_plus_force_buy_created_fib_range(state, reference_candle=None, buy_candle=None, current_price=None, scan_dt=None):
    """Build/initialize the PMA/GF+ force-BUY fib range exactly like pump-style BUYs.

    PMA/GF+ force-BUY bypasses pumpbox confirmation, but it must still enter the
    same pumping fib lifecycle: reference breakout fields, fib_live_candle_ts,
    fib_bottom/fib_top, and later rollover/readjustment all need to exist exactly
    as they do for normal pump-based BUYs.

    Order:
    1) Reuse a real existing pumpbox/pending/shadow fib range if it already exists.
    2) Initialize the same breakout-tracking fields used by pump-based BUYs
       (prepare_breakout_tracking_state + update_pumping_breakout_fib_top_from_live).
    3) If the PMA/GF+ BUY bypass happened without a price breakout and that exact
       pump-style range is still too narrow, create a real candle-data range from
       the reference/live candles so fib/rollover never receives nulls.
    4) Last resort only: create a minimum-width range around the real BUY price,
       explicitly marked synthetic, so the bot never emits null fib fields.
    """
    status = pma_gf_plus_force_buy_fib_range_status(state)
    if bool(status.get("valid")):
        status["created"] = False
        status["pump_style_initialized"] = False
        status["synthetic_min_width"] = False
        return status

    result = dict(status)
    result.update({
        "created": True,
        "valid": False,
        "pump_style_initialized": False,
        "synthetic_min_width": False,
    })

    try:
        min_zone_pct = float(globals().get("PMA_GF_PLUS_FORCE_BUY_FIB_MIN_ZONE_PCT", FIB_SELL_MIN_ZONE_PCT))
    except Exception:
        min_zone_pct = FIB_SELL_MIN_ZONE_PCT
    min_zone_pct = _safe_non_negative_float(min_zone_pct)
    if min_zone_pct is None:
        min_zone_pct = 0.0

    reference_candle = reference_candle if isinstance(reference_candle, dict) else {}
    buy_candle = buy_candle if isinstance(buy_candle, dict) else {}
    current_scan_ts = _scan_ts_value(scan_dt)

    # First, do the same initialization path used by pump-based BUY tracking.
    # This gives PMA/GF+ force-BUY the same fib_live_candle_ts/reference fields
    # needed by the active BUY rollover code.
    try:
        if isinstance(state, dict) and reference_candle and buy_candle and scan_dt is not None:
            prepare_breakout_tracking_state(state, reference_candle, buy_candle, scan_dt)
            update_pumping_breakout_fib_top_from_live(
                state,
                buy_candle,
                scan_dt,
                source="pma_gf_plus_force_buy_live_high",
            )

            # v57: PMA/GF+ fib management uses the latest closed candle body-top
            # as fib_bottom.  The old pump-style initializer uses the reference
            # wick as both bottom/top; keep its bookkeeping, but replace the
            # bottom before validating/returning the PMA force-buy fib range.
            reference_body_top = _safe_positive_float(
                reference_candle.get("body_top") or
                max(
                    _safe_positive_float(reference_candle.get("o")) or 0.0,
                    _safe_positive_float(reference_candle.get("c")) or 0.0,
                )
            )
            initialized_fib_top = _safe_positive_float(state.get("fib_top"))
            if reference_body_top is not None and initialized_fib_top is not None:
                set_state_fib_bounds(
                    state,
                    reference_body_top,
                    initialized_fib_top,
                    bottom_source="pma_gf_plus_force_buy_latest_closed_body_top",
                )
                state["fib_bottom_updated_scan_ts"] = current_scan_ts
                state["fib_bottom_latest_closed_ts"] = reference_candle.get("t")

            result["pump_style_initialized"] = True
            pump_status = pma_gf_plus_force_buy_fib_range_status(state)
            if bool(pump_status.get("valid")):
                pump_status["created"] = True
                pump_status["pump_style_initialized"] = True
                pump_status["synthetic_min_width"] = False
                pump_status["source"] = "created_pump_style_breakout_tracking"
                pump_status["reason"] = "created PMA/GF+ force-BUY fib range using the same pump breakout-tracking path"
                pump_status["zone_pct"] = pct_change(pump_status.get("fib_bottom"), pump_status.get("fib_top"))
                pump_status["fib_live_candle_ts"] = state.get("fib_live_candle_ts")
                pump_status["tracking_reference_prev_closed_ts"] = state.get("tracking_reference_prev_closed_ts")
                pump_status["tracking_reference_prev_closed_wick_top"] = state.get("tracking_reference_prev_closed_wick_top")
                return pump_status
    except Exception as exc:
        result["pump_style_error"] = str(exc)

    top_candidates = []
    bottom_candidates = []

    for source, candle in (("buy", buy_candle), ("reference", reference_candle)):
        for key in ("h", "body_top", "c", "o"):
            value = _safe_positive_float(candle.get(key))
            if value is not None:
                top_candidates.append((f"{source}_{key}", value))
        for key in ("l", "body_bottom", "o", "c"):
            value = _safe_positive_float(candle.get(key))
            if value is not None:
                bottom_candidates.append((f"{source}_{key}", value))

    current_price_value = _safe_positive_float(current_price)
    if current_price_value is not None:
        top_candidates.append(("current_price", current_price_value))

    buy_price = _safe_positive_float(
        buy_candle.get("c") or buy_candle.get("body_top") or current_price_value or reference_candle.get("c")
    )
    if buy_price is not None:
        top_candidates.append(("buy_price", buy_price))

    # Real candle-data fallback: still no nulls, but no fake price levels unless
    # the market data itself cannot produce a real minimum-width range.
    best = None
    for bottom_source, bottom in bottom_candidates:
        for top_source, top in top_candidates:
            low, high = normalized_fib_bounds(bottom, top)
            if not fib_range_is_real(low, high, min_zone_pct=min_zone_pct):
                continue
            zone_pct = pct_change(low, high) if low not in (None, 0, 0.0) else None
            candidate = (zone_pct if zone_pct is not None else 0.0, low, high, bottom_source, top_source)
            if best is None or candidate[0] > best[0]:
                best = candidate

    if best is not None:
        zone_pct, low, high, bottom_source, top_source = best
        set_state_fib_bounds(
            state,
            low,
            high,
            bottom_source=f"pma_gf_plus_force_buy_real_candle_{bottom_source}",
        )
        state["fib_top_source"] = f"pma_gf_plus_force_buy_real_candle_{top_source}"
        state["fib_live_candle_ts"] = buy_candle.get("t") or state.get("fib_live_candle_ts")
        state["fib_top_updated_scan_ts"] = current_scan_ts
        result.update({
            "valid": True,
            "fib_bottom": low,
            "fib_top": high,
            "source": f"created_real_candle_range_{bottom_source}_to_{top_source}",
            "reason": f"created PMA/GF+ force-BUY fib range from real candle data after pump-style init was too narrow ({zone_pct:.3f}% width)",
            "zone_pct": zone_pct,
            "fib_live_candle_ts": state.get("fib_live_candle_ts"),
            "tracking_reference_prev_closed_ts": state.get("tracking_reference_prev_closed_ts"),
            "tracking_reference_prev_closed_wick_top": state.get("tracking_reference_prev_closed_wick_top"),
        })
        return result

    # Last resort: never emit null fib fields. This is not preferred, but it is
    # safer than letting active BUY management and rollover operate on nulls.
    if buy_price is not None and buy_price > 0:
        safety_pct = max(float(min_zone_pct or 0.0), 0.01) + 0.001
        high = buy_price
        low = buy_price / (1.0 + (safety_pct / 100.0))
        if fib_range_is_real(low, high, min_zone_pct=min_zone_pct):
            set_state_fib_bounds(
                state,
                low,
                high,
                bottom_source="pma_gf_plus_force_buy_min_width_from_buy_price",
            )
            state["fib_top_source"] = "pma_gf_plus_force_buy_buy_price"
            state["fib_live_candle_ts"] = buy_candle.get("t") or state.get("fib_live_candle_ts")
            state["fib_top_updated_scan_ts"] = current_scan_ts
            result.update({
                "valid": True,
                "fib_bottom": low,
                "fib_top": high,
                "source": "created_min_width_from_buy_price",
                "reason": f"created PMA/GF+ force-BUY minimum-width fib range from buy price after pump-style and candle-data ranges were unavailable ({safety_pct:.3f}% width)",
                "zone_pct": pct_change(low, high),
                "synthetic_min_width": True,
                "fib_live_candle_ts": state.get("fib_live_candle_ts"),
                "tracking_reference_prev_closed_ts": state.get("tracking_reference_prev_closed_ts"),
                "tracking_reference_prev_closed_wick_top": state.get("tracking_reference_prev_closed_wick_top"),
            })
            return result

    result["reason"] = result.get("reason") or "could not create PMA/GF+ force-BUY fib range"
    return result





def _parse_pma_gf_plus_oma_offsets(value):
    offsets = []
    if isinstance(value, (list, tuple)):
        iterable = value
    else:
        iterable = []
    for item in iterable:
        try:
            numeric = float(item)
        except Exception:
            continue
        if math.isfinite(numeric):
            offsets.append(numeric)
    return offsets



