def _pma_gf_plus_force_buy_lane_key(key, lane):
    base = "pma_gf_plus_force_buy_"
    lane = str(lane or "").strip()
    if not lane or lane in {"default", "shared"} or not str(key).startswith(base):
        return key
    return base + lane + "_" + str(key)[len(base):]


def _pma_gf_plus_force_buy_clear_lane_state(state, lane):
    if not isinstance(state, dict):
        return
    for key in PMA_GF_PLUS_FORCE_BUY_LANE_STATE_KEYS:
        state.pop(_pma_gf_plus_force_buy_lane_key(key, lane), None)


def _pma_gf_plus_force_buy_copy_lane_state(state, src_lane, dst_lane):
    if not isinstance(state, dict):
        return
    for key in PMA_GF_PLUS_FORCE_BUY_LANE_STATE_KEYS:
        src_key = _pma_gf_plus_force_buy_lane_key(key, src_lane)
        dst_key = _pma_gf_plus_force_buy_lane_key(key, dst_lane)
        if src_key in state:
            value = state.get(src_key)
            if isinstance(value, list):
                value = list(value)
            elif isinstance(value, dict):
                value = dict(value)
            state[dst_key] = value
        else:
            state.pop(dst_key, None)


def _pma_gf_plus_force_buy_promote_live_future_on_new_closed_pma(state, pine_30m_status=None, scan_dt=None):
    """Promote the just-finished live setup lane into the closed-transition lane.

    v35: after a live 30m PMA candle closes, the live-future setup/history that
    was collected after the first 7 seconds becomes the current closed-PMA setup.
    Then the new live-future lane is cleared so the next live candle can build
    its own independent data without mixing into the closed/direct 0-120s branch.
    """
    if not isinstance(state, dict) or not isinstance(pine_30m_status, dict):
        return {"promoted": False, "reason": "missing state/status"}
    close_ts = ts_to_int(pine_30m_status.get("prev_pma_candle_close_ts"))
    if close_ts is None:
        return {"promoted": False, "reason": "missing prev_pma_candle_close_ts"}
    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if scan_ts is not None and close_ts > scan_ts:
        return {
            "promoted": False,
            "reason": "closed PMA timestamp is still in the future; do not promote/clear live_future before the candle actually closes",
            "close_ts": close_ts,
            "scan_ts": scan_ts,
            "seconds_until_close": int(close_ts - scan_ts),
        }
    last_close_ts = ts_to_int(state.get("pma_gf_plus_force_buy_closed_transition_lane_close_ts"))
    if last_close_ts == close_ts:
        return {"promoted": False, "reason": "same closed PMA timestamp", "close_ts": close_ts}
    _pma_gf_plus_force_buy_copy_lane_state(state, "live_future", "closed_transition")
    _pma_gf_plus_force_buy_clear_lane_state(state, "live_future")
    state["pma_gf_plus_force_buy_closed_transition_lane_close_ts"] = close_ts
    state["pma_gf_plus_force_buy_live_future_lane_reset_close_ts"] = close_ts
    return {"promoted": True, "reason": "live_future promoted to closed_transition on new closed PMA", "close_ts": close_ts, "previous_close_ts": last_close_ts}


def _pma_gf_plus_force_buy_call_with_lane(state, lane, func, *args, **kwargs):
    """Run a hard-coded PMA/GF+ quality/OMA function against a separated lane."""
    if not isinstance(state, dict) or not lane or str(lane) in {"default", "shared"}:
        return func(state, *args, **kwargs)
    sentinel = object()
    saved = {}
    try:
        for key in PMA_GF_PLUS_FORCE_BUY_LANE_STATE_KEYS:
            saved[key] = state.get(key, sentinel)
            lane_key = _pma_gf_plus_force_buy_lane_key(key, lane)
            if lane_key in state:
                value = state.get(lane_key)
                if isinstance(value, list):
                    value = list(value)
                elif isinstance(value, dict):
                    value = dict(value)
                state[key] = value
            else:
                state.pop(key, None)
        result = func(state, *args, **kwargs)
        for key in PMA_GF_PLUS_FORCE_BUY_LANE_STATE_KEYS:
            lane_key = _pma_gf_plus_force_buy_lane_key(key, lane)
            if key in state:
                value = state.get(key)
                if isinstance(value, list):
                    value = list(value)
                elif isinstance(value, dict):
                    value = dict(value)
                state[lane_key] = value
            else:
                state.pop(lane_key, None)
        return result
    finally:
        for key, value in saved.items():
            if value is sentinel:
                state.pop(key, None)
            else:
                state[key] = value


def pma_gf_plus_force_buy_quality_gate_status_for_lane(state, lane, *args, **kwargs):
    return _pma_gf_plus_force_buy_call_with_lane(
        state,
        lane,
        pma_gf_plus_force_buy_quality_gate_status,
        *args,
        **kwargs,
    )


def pma_gf_plus_force_buy_oma_filter_status_for_lane(state, lane, *args, **kwargs):
    return _pma_gf_plus_force_buy_call_with_lane(
        state,
        lane,
        pma_gf_plus_force_buy_oma_filter_status,
        *args,
        **kwargs,
    )


def pma_gf_plus_force_buy_lane_snapshot(state, lane):
    """Return the stored pass state for a lane without mutating it."""
    if not isinstance(state, dict):
        return {}
    def get(key):
        return state.get(_pma_gf_plus_force_buy_lane_key(key, lane))
    return {
        "lane": lane,
        "quality_passed": bool(get("pma_gf_plus_force_buy_quality_last_passed")),
        "quality_reason": get("pma_gf_plus_force_buy_quality_last_reason"),
        "quality_non_flat_sample_count": get("pma_gf_plus_force_buy_quality_non_flat_sample_count"),
        "quality_avg_expansion_pct": get("pma_gf_plus_force_buy_quality_avg_expansion_pct"),
        "quality_positive_sample_ratio": get("pma_gf_plus_force_buy_quality_positive_sample_ratio"),
        "oma_passed": bool(get("pma_gf_plus_force_buy_oma_last_passed")),
        "oma_reason": get("pma_gf_plus_force_buy_oma_last_reason"),
        "oma_value": get("pma_gf_plus_force_buy_oma_value"),
        "oma_delta": get("pma_gf_plus_force_buy_oma_delta"),
        "oma_positive_delta_ratio": get("pma_gf_plus_force_buy_oma_positive_delta_ratio"),
        "oma_non_flat_delta_count": get("pma_gf_plus_force_buy_oma_non_flat_delta_count"),
    }

def pma_gf_plus_force_buy_oma_filter_status(state, offset, scan_dt=None, pma_flat_neutral=False):
    """Return the V8 simple-average OMA filter decision for PMA/GF+ force BUY.

    OMA here is the moving average of the caller-supplied setup-listening
    distance.  For normal setup-listening force-buy branches the caller now
    supplies PMA - midpoint(0.0, Predict Lower), not PMA - GF+. It is evaluated
    synchronously inside the existing force-buy scan path and never resets the
    PMA/GF+ above-hold timer. It only blocks the current scan's BUY readiness.
    """
    status = {
        "enabled": bool(globals().get("ENABLE_PMA_GF_PLUS_OMA_FILTER", True)),
        "passed": True,
        "reason": "PMA/GF+ OMA filter disabled",
        "offset": offset,
        "offsets": [],
        "sample_count": 0,
        "length": None,
        "oma": None,
        "previous_oma": None,
        "delta": None,
        "min_value": None,
        "require_rising": None,
        "rising_min_delta": None,
        "last_scan_ts": None,
        "updated_this_scan": False,
        "positive_ratio_required": bool(globals().get("PMA_GF_PLUS_FORCE_BUY_REQUIRE_OMA_POSITIVE_RATIO", True)),
        "flat_neutral_pma": bool(pma_flat_neutral),
        "flat_neutral_offset_ignored": None,
        "flat_neutral_delta_forced": False,
        "positive_ratio_min": None,
        "delta_samples": [],
        "delta_sample_ts": [],
        "delta_sample_count": 0,
        "positive_delta_count": 0,
        "negative_delta_count": 0,
        "flat_delta_count": 0,
        "non_flat_delta_count": 0,
        "min_non_flat_delta_count": None,
        "positive_delta_ratio": None,
    }

    try:
        length = max(1, int(float(globals().get("PMA_GF_PLUS_OMA_LENGTH", 4))))
    except Exception:
        length = 4
    try:
        min_value = float(globals().get("PMA_GF_PLUS_OMA_MIN_VALUE", 0.50))
    except Exception:
        min_value = 0.50
    require_rising = bool(globals().get("PMA_GF_PLUS_OMA_REQUIRE_RISING", True))
    try:
        rising_min_delta = float(globals().get("PMA_GF_PLUS_OMA_RISING_MIN_DELTA", 0.10))
    except Exception:
        rising_min_delta = 0.10

    status["length"] = length
    status["min_value"] = min_value
    status["require_rising"] = require_rising
    status["rising_min_delta"] = rising_min_delta

    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    last_scan_ts = ts_to_int((state or {}).get("pma_gf_plus_force_buy_oma_last_scan_ts")) if isinstance(state, dict) else None
    status["last_scan_ts"] = last_scan_ts

    offsets = _parse_pma_gf_plus_oma_offsets((state or {}).get("pma_gf_plus_force_buy_oma_offsets") if isinstance(state, dict) else None)
    offsets = offsets[-length:]
    previous_oma = _safe_finite_float((state or {}).get("pma_gf_plus_force_buy_oma_value")) if isinstance(state, dict) else None

    try:
        current_offset = float(offset) if offset is not None else None
    except Exception:
        current_offset = None
    if current_offset is not None and not math.isfinite(current_offset):
        current_offset = None

    flat_neutral_pma = bool(pma_flat_neutral)

    if current_offset is None:
        passed = False
        reason = "PMA/GF+ force buy blocked: OMA offset unavailable"
    else:
        if flat_neutral_pma:
            # V39: flat-neutral PMA has zero OMA effect, but should still keep
            # the OMA stream alive.  If there is no previous OMA, seed neutral
            # 0.0 and append a 0.0 flat delta for continuity/debug.
            status["flat_neutral_offset_ignored"] = current_offset
            oma_value = previous_oma if previous_oma is not None else ((sum(offsets) / len(offsets)) if offsets else 0.0)
            previous_value_for_delta = previous_oma if previous_oma is not None else 0.0
            oma_delta = 0.0
        else:
            # Do not double-count if status is evaluated more than once in the same scan.
            if current_scan_ts is None or last_scan_ts != current_scan_ts:
                offsets.append(current_offset)
                offsets = offsets[-length:]
                status["updated_this_scan"] = True
            elif not offsets:
                offsets.append(current_offset)
                offsets = offsets[-length:]
                status["updated_this_scan"] = True

            oma_value = (sum(offsets) / len(offsets)) if offsets else None
            if status.get("updated_this_scan"):
                previous_value_for_delta = previous_oma
            else:
                previous_value_for_delta = _safe_finite_float((state or {}).get("pma_gf_plus_force_buy_oma_prev_value")) if isinstance(state, dict) else None
            oma_delta = (oma_value - previous_value_for_delta) if oma_value is not None and previous_value_for_delta is not None else None

        status["offsets"] = list(offsets)
        status["sample_count"] = len(offsets)
        status["oma"] = oma_value
        status["previous_oma"] = previous_value_for_delta
        status["delta"] = oma_delta

        try:
            oma_positive_ratio_min = float(globals().get("PMA_GF_PLUS_FORCE_BUY_OMA_POSITIVE_RATIO_MIN", 0.32))
        except Exception:
            oma_positive_ratio_min = 0.32
        try:
            positive_ratio_max_samples = max(1, int(float(globals().get("PMA_GF_PLUS_FORCE_BUY_POSITIVE_RATIO_MAX_SAMPLES", 240))))
        except Exception:
            positive_ratio_max_samples = 240
        try:
            positive_delta_flat_threshold = max(0.0, float(globals().get("PMA_GF_PLUS_FORCE_BUY_OMA_POSITIVE_DELTA_FLAT_THRESHOLD", 0.01)))
        except Exception:
            positive_delta_flat_threshold = 0.01
        delta_samples = []
        delta_sample_ts = []
        if isinstance(state, dict):
            raw_delta_samples = state.get("pma_gf_plus_force_buy_oma_delta_samples")
            raw_delta_sample_ts = state.get("pma_gf_plus_force_buy_oma_delta_sample_ts")
            if isinstance(raw_delta_samples, list):
                for idx, item in enumerate(raw_delta_samples):
                    numeric = _safe_finite_float(item)
                    if numeric is not None:
                        delta_samples.append(float(numeric))
                        ts_value = None
                        if isinstance(raw_delta_sample_ts, list) and idx < len(raw_delta_sample_ts):
                            ts_value = ts_to_int(raw_delta_sample_ts[idx])
                        delta_sample_ts.append(ts_value)
            delta_samples, delta_sample_ts = _pma_gf_plus_prune_timed_samples(
                delta_samples,
                delta_sample_ts,
                current_scan_ts,
                max_age_seconds=_pma_gf_plus_force_buy_history_window_seconds(),
            )
            delta_samples, delta_sample_ts = _pma_gf_plus_prune_samples_by_bounds(
                delta_samples,
                delta_sample_ts,
                ts_to_int(state.get("pma_gf_plus_force_buy_history_window_start_ts")),
                ts_to_int(state.get("pma_gf_plus_force_buy_history_window_end_ts")),
            )
            last_delta_sample_ts = ts_to_int(state.get("pma_gf_plus_force_buy_oma_delta_last_sample_ts"))
        else:
            last_delta_sample_ts = None
        if oma_delta is not None and current_scan_ts is not None and current_scan_ts != last_delta_sample_ts:
            if flat_neutral_pma:
                oma_delta = 0.0
                status["delta"] = 0.0
                status["flat_neutral_delta_forced"] = True
            delta_samples.append(float(oma_delta))
            delta_sample_ts.append(current_scan_ts)
            if len(delta_samples) > positive_ratio_max_samples:
                delta_samples = delta_samples[-positive_ratio_max_samples:]
                delta_sample_ts = delta_sample_ts[-positive_ratio_max_samples:]
            delta_samples, delta_sample_ts = _pma_gf_plus_prune_timed_samples(
                delta_samples,
                delta_sample_ts,
                current_scan_ts,
                max_age_seconds=_pma_gf_plus_force_buy_history_window_seconds(),
            )
            delta_samples, delta_sample_ts = _pma_gf_plus_prune_samples_by_bounds(
                delta_samples,
                delta_sample_ts,
                ts_to_int(state.get("pma_gf_plus_force_buy_history_window_start_ts")) if isinstance(state, dict) else None,
                ts_to_int(state.get("pma_gf_plus_force_buy_history_window_end_ts")) if isinstance(state, dict) else None,
            )
            if isinstance(state, dict):
                state["pma_gf_plus_force_buy_oma_delta_last_sample_ts"] = current_scan_ts
        try:
            min_non_flat_delta_count = max(0, int(float(globals().get("PMA_GF_PLUS_FORCE_BUY_MIN_NON_FLAT_OMA_DELTA_SAMPLES", 7))))
        except Exception:
            min_non_flat_delta_count = 4
        positive_delta_count = sum(1 for item in delta_samples if item > positive_delta_flat_threshold)
        negative_delta_count = sum(1 for item in delta_samples if item < -positive_delta_flat_threshold)
        flat_delta_count = sum(1 for item in delta_samples if -positive_delta_flat_threshold <= item <= positive_delta_flat_threshold)
        non_flat_delta_count = positive_delta_count + negative_delta_count
        delta_sample_count = len(delta_samples)
        positive_delta_ratio = (positive_delta_count / non_flat_delta_count) if non_flat_delta_count else None
        status.update({
            "positive_ratio_min": oma_positive_ratio_min,
            "positive_delta_flat_threshold": positive_delta_flat_threshold,
            "delta_samples": list(delta_samples),
            "delta_sample_ts": list(delta_sample_ts),
            "delta_sample_count": delta_sample_count,
            "positive_delta_count": positive_delta_count,
            "negative_delta_count": negative_delta_count,
            "flat_delta_count": flat_delta_count,
            "non_flat_delta_count": non_flat_delta_count,
            "min_non_flat_delta_count": min_non_flat_delta_count,
            "positive_delta_ratio": positive_delta_ratio,
        })

        passed = True
        reason = "PMA/GF+ OMA filter passed"
        if bool(status.get("enabled")):
            if oma_value is None:
                passed = False
                reason = "PMA/GF+ force buy blocked: OMA unavailable"
            elif oma_value < min_value:
                passed = False
                reason = f"PMA/GF+ force buy blocked: OMA {oma_value:.6f} below required +{min_value:.3f}"
            elif require_rising:
                if previous_value_for_delta is None or oma_delta is None:
                    passed = False
                    reason = "PMA/GF+ force buy blocked: OMA rising history unavailable"
                elif flat_neutral_pma:
                    passed = False
                    reason = "PMA/GF+ force buy waiting: flat-neutral PMA gave OMA zero effect, not a negative OMA sample"
                elif oma_delta < rising_min_delta:
                    passed = False
                    reason = f"PMA/GF+ force buy blocked: OMA not rising enough ({oma_delta:+.6f} vs required +{rising_min_delta:.3f})"
            if passed and bool(globals().get("PMA_GF_PLUS_FORCE_BUY_REQUIRE_OMA_POSITIVE_RATIO", True)):
                ratio = _safe_finite_float(status.get("positive_delta_ratio"))
                sample_count = int(status.get("delta_sample_count") or 0)
                positive_count = int(status.get("positive_delta_count") or 0)
                negative_count = int(status.get("negative_delta_count") or 0)
                flat_count = int(status.get("flat_delta_count") or 0)
                non_flat_count = int(status.get("non_flat_delta_count") or 0)
                min_non_flat_count = int(status.get("min_non_flat_delta_count") or 0)
                if non_flat_count < min_non_flat_count:
                    passed = False
                    reason = (
                        "PMA/GF+ force buy blocked: not enough non-flat OMA-delta samples for positive-ratio gate "
                        f"({non_flat_count}/{min_non_flat_count}; total={sample_count}, flat={flat_count})"
                    )
                elif ratio is None:
                    passed = False
                    reason = "PMA/GF+ force buy blocked: OMA-positive ratio history unavailable since setup start"
                elif ratio + 1e-12 < _safe_finite_float(status.get("positive_ratio_min")):
                    required_ratio = _safe_finite_float(status.get("positive_ratio_min")) or 0.32
                    passed = False
                    reason = (
                        "PMA/GF+ force buy blocked: OMA was not positive often enough since setup start "
                        f"({positive_count}/{non_flat_count} non-flat = {ratio:.3f} < required {required_ratio:.3f}; "
                        f"negative={negative_count}, flat={flat_count}; ±{positive_delta_flat_threshold:.3f} is neutral)"
                    )

    if current_offset is None:
        status["offsets"] = list(offsets)
        status["sample_count"] = len(offsets)
        status["oma"] = _safe_finite_float((state or {}).get("pma_gf_plus_force_buy_oma_value")) if isinstance(state, dict) else None
        status["previous_oma"] = _safe_finite_float((state or {}).get("pma_gf_plus_force_buy_oma_prev_value")) if isinstance(state, dict) else None
        status["delta"] = _safe_finite_float((state or {}).get("pma_gf_plus_force_buy_oma_delta")) if isinstance(state, dict) else None

    status["passed"] = bool(passed) if bool(status.get("enabled")) else True
    status["reason"] = reason if bool(status.get("enabled")) else "PMA/GF+ OMA filter disabled"

    if isinstance(state, dict):
        state["pma_gf_plus_force_buy_oma_offsets"] = list(status.get("offsets") or [])
        state["pma_gf_plus_force_buy_oma_value"] = status.get("oma")
        state["pma_gf_plus_force_buy_oma_prev_value"] = status.get("previous_oma")
        state["pma_gf_plus_force_buy_oma_delta"] = status.get("delta")
        state["pma_gf_plus_force_buy_oma_delta_samples"] = list(status.get("delta_samples") or [])
        state["pma_gf_plus_force_buy_oma_delta_sample_ts"] = list(status.get("delta_sample_ts") or [])
        state["pma_gf_plus_force_buy_oma_delta_sample_count"] = int(status.get("delta_sample_count") or 0)
        state["pma_gf_plus_force_buy_oma_positive_delta_count"] = int(status.get("positive_delta_count") or 0)
        state["pma_gf_plus_force_buy_oma_negative_delta_count"] = int(status.get("negative_delta_count") or 0)
        state["pma_gf_plus_force_buy_oma_flat_delta_count"] = int(status.get("flat_delta_count") or 0)
        state["pma_gf_plus_force_buy_oma_non_flat_delta_count"] = int(status.get("non_flat_delta_count") or 0)
        state["pma_gf_plus_force_buy_oma_positive_delta_ratio"] = status.get("positive_delta_ratio")
        if current_scan_ts is not None and current_offset is not None:
            state["pma_gf_plus_force_buy_oma_last_scan_ts"] = current_scan_ts
        state["pma_gf_plus_force_buy_oma_last_reason"] = status.get("reason")
        state["pma_gf_plus_force_buy_oma_last_passed"] = bool(status.get("passed"))

    return status

def _pma_gf_plus_bad_buy_score_window_seconds():
    try:
        return max(0, int(float(globals().get("PMA_GF_PLUS_BAD_BUY_SCORE_WINDOW_SECONDS", globals().get("PMA_GF_PLUS_BAD_BUY_SCORE_MAX_AGE_SECONDS", 2 * 60 * 60)))))
    except Exception:
        return 2 * 60 * 60


def _pma_gf_plus_normalize_bad_buy_score_event(event):
    if not isinstance(event, dict):
        return None
    event_ts = ts_to_int(event.get("ts"))
    if event_ts is None:
        return None
    try:
        delta = int(event.get("delta") or 0)
    except Exception:
        delta = 0
    try:
        pnl = float(event.get("pnl_pct")) if event.get("pnl_pct") is not None else None
    except Exception:
        pnl = None
    normalized = {
        "ts": event_ts,
        "delta": delta,
        "clear": bool(event.get("clear")),
        "pnl_pct": pnl,
        "reason": str(event.get("reason") or ""),
        "pma": _safe_finite_float(event.get("pma")),
        "oma": _safe_finite_float(event.get("oma")),
        "offset": _safe_finite_float(event.get("offset")),
        "price": _safe_positive_float(event.get("price")),
    }
    return normalized


def pma_gf_plus_prune_and_recompute_bad_buy_score(state, scan_dt=None):
    """Recompute bad-buy score from a true rolling 2-hour event window.

    Each scored sell event ages out independently. A >= clear-win event inside
    the window clears prior penalty in that window, then later events can build
    score again. This replaces the older scalar score that only expired from the
    last update timestamp.
    """
    if not isinstance(state, dict):
        return {
            "score": 0,
            "events": [],
            "window_seconds": _pma_gf_plus_bad_buy_score_window_seconds(),
            "expired_count": 0,
            "last_ts": None,
            "last_bad_event": None,
        }

    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    window_seconds = _pma_gf_plus_bad_buy_score_window_seconds()

    raw_events = state.get("pma_gf_plus_bad_buy_score_events")
    events = []
    if isinstance(raw_events, list):
        for raw in raw_events:
            item = _pma_gf_plus_normalize_bad_buy_score_event(raw)
            if item is not None:
                events.append(item)
    else:
        # Backward compatibility for states created before the rolling event list.
        try:
            legacy_score = int(state.get("pma_gf_plus_bad_buy_score") or 0)
        except Exception:
            legacy_score = 0
        legacy_ts = ts_to_int(state.get("pma_gf_plus_bad_buy_last_ts"))
        if legacy_score > 0 and legacy_ts is not None:
            events.append({
                "ts": legacy_ts,
                "delta": legacy_score,
                "clear": False,
                "pnl_pct": state.get("pma_gf_plus_bad_buy_last_pnl_pct"),
                "reason": str(state.get("pma_gf_plus_bad_buy_last_reason") or "legacy scalar bad-buy score"),
                "pma": _safe_finite_float(state.get("pma_gf_plus_bad_buy_last_pma")),
                "oma": _safe_finite_float(state.get("pma_gf_plus_bad_buy_last_oma")),
                "offset": _safe_finite_float(state.get("pma_gf_plus_bad_buy_last_offset")),
                "price": _safe_positive_float(state.get("pma_gf_plus_bad_buy_last_price")),
            })

    events.sort(key=lambda item: int(item.get("ts") or 0))
    kept = []
    expired_count = 0
    for item in events:
        item_ts = ts_to_int(item.get("ts"))
        expired = False
        if window_seconds > 0 and current_scan_ts is not None and item_ts is not None:
            expired = current_scan_ts - item_ts > window_seconds
        if expired:
            expired_count += 1
        else:
            kept.append(item)

    score = 0
    last_bad_event = None
    last_ts = None
    last_event = None
    for item in kept:
        last_ts = ts_to_int(item.get("ts"))
        last_event = item
        if bool(item.get("clear")):
            score = 0
            continue
        delta = int(item.get("delta") or 0)
        score = max(0, score + delta)
        if delta > 0:
            last_bad_event = item

    state["pma_gf_plus_bad_buy_score_events"] = kept
    state["pma_gf_plus_bad_buy_score"] = int(max(0, score))
    if last_event is not None:
        state["pma_gf_plus_bad_buy_last_pnl_pct"] = last_event.get("pnl_pct")
        state["pma_gf_plus_bad_buy_last_ts"] = last_event.get("ts")
        state["pma_gf_plus_bad_buy_last_reason"] = last_event.get("reason")
    else:
        state["pma_gf_plus_bad_buy_last_pnl_pct"] = None
        state["pma_gf_plus_bad_buy_last_ts"] = None
        state["pma_gf_plus_bad_buy_last_reason"] = "expired after rolling 2h window" if expired_count else None

    if last_bad_event is not None:
        state["pma_gf_plus_bad_buy_last_pma"] = last_bad_event.get("pma")
        state["pma_gf_plus_bad_buy_last_oma"] = last_bad_event.get("oma")
        state["pma_gf_plus_bad_buy_last_offset"] = last_bad_event.get("offset")
        state["pma_gf_plus_bad_buy_last_price"] = last_bad_event.get("price")
    else:
        state["pma_gf_plus_bad_buy_last_pma"] = None
        state["pma_gf_plus_bad_buy_last_oma"] = None
        state["pma_gf_plus_bad_buy_last_offset"] = None
        state["pma_gf_plus_bad_buy_last_price"] = None

    return {
        "score": int(max(0, score)),
        "events": kept,
        "window_seconds": window_seconds,
        "expired_count": expired_count,
        "last_ts": last_ts,
        "last_bad_event": last_bad_event,
    }
def pma_gf_plus_force_buy_quality_gate_status(
    state,
    candidate=None,
    reference_candle=None,
    current_price=None,
    scan_dt=None,
    pine_30m_status=None,
    pma=None,
    gf_plus=None,
    offset=None,
):
    """Return the V6 PMA/GF+ force-BUY quality gate decision.

    This gate is deliberately buy-side only. It does not change active exits;
    it only prevents PMA/GF+ force BUY from firing when PMA is strong but live
    price action is not proving continuation.
    """
    status = {
        "enabled": bool(globals().get("ENABLE_PMA_GF_PLUS_FORCE_BUY_QUALITY_GATE", True)),
        "passed": True,
        "reason": "PMA/GF+ force buy quality gate disabled",
        "live_price": None,
        "previous_price": None,
        "price_above_last_scan_pct": None,
        "min_price_above_last_scan_pct": None,
        "live_green_body_ok": None,
        "body_top": None,
        "body_bottom": None,
        "rejection_wick_pct": None,
        "max_rejection_wick_pct": None,
        "pre_entry_sma18_guard_enabled": bool(globals().get("ENABLE_PMA_GF_PLUS_FORCE_BUY_PRE_ENTRY_SMA18_GUARD", True)),
        "pre_entry_sma18_guard_passed": True,
        "pre_entry_sma18_guard_reason": None,
        "pre_entry_sma18": None,
        "pre_entry_body_bottom": None,
        "pre_entry_body_bottom_to_sma18_pct": None,
        "pre_entry_min_body_bottom_to_sma18_pct": None,
        # Deprecated aliases retained for downstream compatibility; they mirror
        # the body-bottom guard value, not the plain live price.
        "pre_entry_live_price_to_sma18_pct": None,
        "pre_entry_min_live_price_to_sma18_pct": None,
        "bad_buy_score": 0,
        "bad_score_hardened": False,
        "required_offset_for_bad_score": None,
        "required_price_expansion_for_bad_score": None,
        "price_positive_ratio_required": bool(globals().get("PMA_GF_PLUS_FORCE_BUY_REQUIRE_PRICE_POSITIVE_RATIO", True)),
        "price_positive_ratio_min": None,
        "price_expansion_samples": [],
        "price_expansion_effective_samples": [],
        "price_expansion_sample_ts": [],
        "price_split_gate_enabled": bool(globals().get("PMA_GF_PLUS_FORCE_BUY_PRICE_EXPANSION_SPLIT_GATE_ENABLED", True)),
        "price_split_source": None,
        "price_split_max_imbalance_ratio": None,
        "price_split_min_balance_ratio": None,
        "price_split_balance_ratio": None,
        "price_split_combined_avg_pct": None,
        "price_split_min_half_avg_pct": None,
        "price_split_min_combined_avg_pct": None,
        "price_split_first_avg_pct": None,
        "price_split_second_avg_pct": None,
        "price_split_first_sample_count": 0,
        "price_split_second_sample_count": 0,
        "price_split_first_non_flat_count": 0,
        "price_split_second_non_flat_count": 0,
        "price_split_min_non_flat_per_half": None,
        "price_split_passed": None,
        "price_sample_count": 0,
        "price_positive_sample_count": 0,
        "price_negative_sample_count": 0,
        "price_flat_sample_count": 0,
        "price_non_flat_sample_count": 0,
        "price_min_non_flat_sample_count": None,
        "price_positive_sample_ratio": None,
        "price_avg_expansion_pct": None,
        "pma": pma,
        "gf_plus": gf_plus,
        "offset": offset,
    }

    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    history_bounds = _pma_gf_plus_force_buy_history_bounds(reference_candle=reference_candle, pine_30m_status=pine_30m_status, scan_dt=scan_dt, state=state)
    history_start_ts = history_bounds.get("start_ts")
    history_end_ts = history_bounds.get("end_ts")
    status["history_window_start_ts"] = history_start_ts
    status["history_window_end_ts"] = history_end_ts
    status["history_window_source"] = history_bounds.get("source")

    live_price = _safe_positive_float(current_price)
    if live_price is None and isinstance(candidate, dict):
        live_price = resolve_current_market_price(candidate.get("latest_price"), reference_candle, prefer_candle=False, context=candidate)
    if live_price is None:
        live_price = _safe_positive_float((reference_candle or {}).get("c")) if isinstance(reference_candle, dict) else None
    status["live_price"] = live_price

    previous_price = _safe_positive_float((state or {}).get("pma_gf_plus_force_buy_quality_last_price")) if isinstance(state, dict) else None
    previous_scan_ts = ts_to_int((state or {}).get("pma_gf_plus_force_buy_quality_last_scan_ts")) if isinstance(state, dict) else None
    try:
        quality_last_price_max_age_seconds = max(0, int(float(globals().get("PMA_GF_PLUS_FORCE_BUY_QUALITY_LAST_PRICE_MAX_AGE_SECONDS", _pma_gf_plus_force_buy_history_window_seconds()))))
    except Exception:
        quality_last_price_max_age_seconds = _pma_gf_plus_force_buy_history_window_seconds()
    previous_price_expired = False
    if (
        quality_last_price_max_age_seconds > 0 and
        current_scan_ts is not None and
        previous_scan_ts is not None and
        current_scan_ts - previous_scan_ts > quality_last_price_max_age_seconds
    ):
        previous_price_expired = True
        previous_price = None
        previous_scan_ts = None
        if isinstance(state, dict):
            state["pma_gf_plus_force_buy_quality_last_price"] = None
            state["pma_gf_plus_force_buy_quality_last_scan_ts"] = None
            state["pma_gf_plus_force_buy_quality_last_reason"] = "expired stale price reference"
            state["pma_gf_plus_force_buy_quality_last_passed"] = None
    status["previous_price"] = previous_price
    status["previous_scan_ts"] = previous_scan_ts
    status["previous_price_expired"] = previous_price_expired
    status["previous_price_max_age_seconds"] = quality_last_price_max_age_seconds

    if live_price not in (None, 0, 0.0) and previous_price not in (None, 0, 0.0):
        status["price_above_last_scan_pct"] = pct_change(previous_price, live_price)

    try:
        price_positive_ratio_min = float(globals().get("PMA_GF_PLUS_FORCE_BUY_PRICE_POSITIVE_RATIO_MIN", 0.32))
    except Exception:
        price_positive_ratio_min = 0.32
    try:
        positive_ratio_max_samples = max(1, int(float(globals().get("PMA_GF_PLUS_FORCE_BUY_POSITIVE_RATIO_MAX_SAMPLES", 240))))
    except Exception:
        positive_ratio_max_samples = 240
    try:
        price_positive_flat_threshold = max(0.0, float(globals().get("PMA_GF_PLUS_FORCE_BUY_POSITIVE_SAMPLE_FLAT_THRESHOLD_PCT", 0.01)))
    except Exception:
        price_positive_flat_threshold = 0.01
    status["price_positive_ratio_min"] = price_positive_ratio_min
    status["price_positive_flat_threshold_pct"] = price_positive_flat_threshold
    price_samples = []
    price_sample_ts = []
    if isinstance(state, dict):
        raw_samples = state.get("pma_gf_plus_force_buy_quality_expansion_samples")
        raw_sample_ts = state.get("pma_gf_plus_force_buy_quality_expansion_sample_ts")
        if isinstance(raw_samples, list):
            for idx, item in enumerate(raw_samples):
                numeric = _safe_finite_float(item)
                if numeric is not None:
                    price_samples.append(float(numeric))
                    ts_value = None
                    if isinstance(raw_sample_ts, list) and idx < len(raw_sample_ts):
                        ts_value = ts_to_int(raw_sample_ts[idx])
                    price_sample_ts.append(ts_value)
        price_samples, price_sample_ts = _pma_gf_plus_prune_timed_samples(
            price_samples,
            price_sample_ts,
            current_scan_ts,
            max_age_seconds=_pma_gf_plus_force_buy_history_window_seconds(),
        )
        price_samples, price_sample_ts = _pma_gf_plus_prune_samples_by_bounds(price_samples, price_sample_ts, history_start_ts, history_end_ts)
        last_sample_ts = ts_to_int(state.get("pma_gf_plus_force_buy_quality_last_sample_ts"))
    else:
        last_sample_ts = None
    price_sample = _safe_finite_float(status.get("price_above_last_scan_pct"))
    if price_sample is not None and current_scan_ts is not None and current_scan_ts != last_sample_ts:
        price_samples.append(float(price_sample))
        price_sample_ts.append(current_scan_ts)
        if len(price_samples) > positive_ratio_max_samples:
            price_samples = price_samples[-positive_ratio_max_samples:]
            price_sample_ts = price_sample_ts[-positive_ratio_max_samples:]
        price_samples, price_sample_ts = _pma_gf_plus_prune_timed_samples(
            price_samples,
            price_sample_ts,
            current_scan_ts,
            max_age_seconds=_pma_gf_plus_force_buy_history_window_seconds(),
        )
        price_samples, price_sample_ts = _pma_gf_plus_prune_samples_by_bounds(price_samples, price_sample_ts, history_start_ts, history_end_ts)
        if isinstance(state, dict):
            state["pma_gf_plus_force_buy_quality_last_sample_ts"] = current_scan_ts
    try:
        price_min_non_flat_samples = max(0, int(float(globals().get("PMA_GF_PLUS_FORCE_BUY_MIN_NON_FLAT_PRICE_SAMPLES", 7))))
    except Exception:
        price_min_non_flat_samples = 4
    price_positive_sample_count = sum(1 for item in price_samples if item > price_positive_flat_threshold)
    price_negative_sample_count = sum(1 for item in price_samples if item < -price_positive_flat_threshold)
    price_flat_sample_count = sum(1 for item in price_samples if -price_positive_flat_threshold <= item <= price_positive_flat_threshold)
    price_non_flat_sample_count = price_positive_sample_count + price_negative_sample_count
    price_sample_count = len(price_samples)
    # Flats stay in the raw stored/debug sample window, but they are DISCLUDED
    # from every force-buy proof denominator.  In v23, the "effective" list is
    # the non-flat-only list used by the +0.32 average, the 32% majority, and the
    # split-half expansion checks.  A ±0.01% sample is therefore neither a zero
    # value in the average nor a denominator item in the ratio.
    price_non_flat_values = [float(item) for item in price_samples if abs(float(item)) > price_positive_flat_threshold]
    price_effective_samples = list(price_non_flat_values)
    price_avg_expansion_pct = (sum(price_non_flat_values) / len(price_non_flat_values)) if price_non_flat_values else None
    price_positive_sample_ratio = (price_positive_sample_count / price_non_flat_sample_count) if price_non_flat_sample_count else None

    def _v7_price_split_avg(values, ts_values, setup_source_value, setup_since_value, now_value):
        split_enabled = bool(globals().get("PMA_GF_PLUS_FORCE_BUY_PRICE_EXPANSION_SPLIT_GATE_ENABLED", True))
        try:
            min_half_avg = float(globals().get("PMA_GF_PLUS_FORCE_BUY_PRICE_EXPANSION_SPLIT_MIN_HALF_AVG_PCT", 0.01))
        except Exception:
            min_half_avg = 0.16
        try:
            min_combined_avg = float(globals().get(
                "PMA_GF_PLUS_FORCE_BUY_PRICE_EXPANSION_SPLIT_MIN_COMBINED_AVG_PCT",
                globals().get("PMA_GF_PLUS_FORCE_BUY_MIN_PRICE_ABOVE_LAST_SCAN_PCT", 0.32),
            ))
        except Exception:
            min_combined_avg = 0.32
        try:
            min_non_flat_per_half = max(0, int(float(globals().get(
                "PMA_GF_PLUS_FORCE_BUY_PRICE_EXPANSION_SPLIT_MIN_NON_FLAT_PER_HALF", 2
            ))))
        except Exception:
            min_non_flat_per_half = 2
        # Backward-compatible debug fields retained from v6. They are reported
        # but no longer decide the v7 split pass/fail result.
        try:
            max_imbalance_ratio = max(1.0, float(globals().get("PMA_GF_PLUS_FORCE_BUY_PRICE_EXPANSION_SPLIT_MAX_IMBALANCE_RATIO", 2.0)))
        except Exception:
            max_imbalance_ratio = 2.0
        try:
            min_balance_ratio = float(globals().get("PMA_GF_PLUS_FORCE_BUY_PRICE_EXPANSION_SPLIT_MIN_BALANCE_RATIO", 0.50))
        except Exception:
            min_balance_ratio = 0.50
        source = str(setup_source_value or "")
        values = list(values or [])
        ts_values = list(ts_values or [])
        first_values = []
        second_values = []
        if not values:
            return {
                "enabled": split_enabled,
                "source": source or None,
                "max_imbalance_ratio": max_imbalance_ratio,
                "min_balance_ratio": min_balance_ratio,
                "balance_ratio": None,
                "combined_avg_pct": None,
                "min_half_avg_pct": min_half_avg,
                "min_combined_avg_pct": min_combined_avg,
                "min_non_flat_per_half": min_non_flat_per_half,
                "first_avg_pct": None,
                "second_avg_pct": None,
                "first_count": 0,
                "second_count": 0,
                "first_non_flat_count": 0,
                "second_non_flat_count": 0,
                "passed": None,
            }
        closed_like = source in {"closed_upper_5s_gf_plus_grace", "live_upper_after_closed", "closed_upper_waiting_for_gf_plus_or_live_upper"}
        if closed_like:
            try:
                half_n = max(1, int(float(globals().get("PMA_GF_PLUS_FORCE_BUY_PRICE_EXPANSION_CLOSED_SPLIT_HALF_SAMPLES", 15))))
            except Exception:
                half_n = 15
            first_values = values[:half_n]
            second_values = values[half_n:half_n * 2] if len(values) > half_n else values[half_n:]
            if not second_values and len(values) >= 2:
                mid = len(values) // 2
                first_values = values[:mid]
                second_values = values[mid:]
        else:
            setup_ts = ts_to_int(setup_since_value)
            now_ts = ts_to_int(now_value)
            if setup_ts is not None and now_ts is not None and now_ts > setup_ts and len(ts_values) == len(values) and all(ts is not None for ts in ts_values):
                mid_ts = setup_ts + ((now_ts - setup_ts) / 2.0)
                first_values = [v for v, ts in zip(values, ts_values) if ts <= mid_ts]
                second_values = [v for v, ts in zip(values, ts_values) if ts > mid_ts]
            if not first_values or not second_values:
                mid = len(values) // 2
                first_values = values[:mid]
                second_values = values[mid:]
        def _avg_and_nonflat(bucket):
            bucket = [float(x) for x in (bucket or []) if _safe_finite_float(x) is not None]
            non_flat_values = [x for x in bucket if abs(x) > price_positive_flat_threshold]
            non_flat = len(non_flat_values)
            avg = (sum(non_flat_values) / len(non_flat_values)) if non_flat_values else None
            return avg, len(bucket), non_flat
        first_avg, first_count, first_non_flat = _avg_and_nonflat(first_values)
        second_avg, second_count, second_non_flat = _avg_and_nonflat(second_values)
        combined_avg = None
        balance_ratio = None
        passed_split = None
        if first_avg is not None and second_avg is not None:
            # v7 semantics: combine the two half-averages as a sum, not an
            # average-of-averages and not a v6 balance ratio. Each half must
            # contribute at least +0.16, and together they must reach +0.32.
            combined_avg = first_avg + second_avg
            if first_avg > 0 and second_avg > 0:
                weaker = min(first_avg, second_avg)
                stronger = max(first_avg, second_avg)
                balance_ratio = weaker / stronger if stronger else None
        if split_enabled:
            passed_split = bool(
                first_avg is not None and second_avg is not None and
                first_non_flat >= min_non_flat_per_half and
                second_non_flat >= min_non_flat_per_half and
                first_avg + 1e-12 >= min_half_avg and
                second_avg + 1e-12 >= min_half_avg and
                combined_avg is not None and
                combined_avg + 1e-12 >= min_combined_avg
            )
        return {
            "enabled": split_enabled,
            "source": source or None,
            "max_imbalance_ratio": max_imbalance_ratio,
            "min_balance_ratio": min_balance_ratio,
            "balance_ratio": balance_ratio,
            "combined_avg_pct": combined_avg,
            "min_half_avg_pct": min_half_avg,
            "min_combined_avg_pct": min_combined_avg,
            "min_non_flat_per_half": min_non_flat_per_half,
            "first_avg_pct": first_avg,
            "second_avg_pct": second_avg,
            "first_count": first_count,
            "second_count": second_count,
            "first_non_flat_count": first_non_flat,
            "second_non_flat_count": second_non_flat,
            "passed": passed_split,
        }

    setup_source_for_split = state.get("pma_gf_plus_force_buy_setup_source") if isinstance(state, dict) else None
    setup_since_for_split = state.get("pma_gf_plus_force_buy_upper_predict_since_ts") if isinstance(state, dict) else None
    split_status = _v7_price_split_avg(
        price_effective_samples,
        price_sample_ts,
        setup_source_for_split,
        setup_since_for_split,
        current_scan_ts,
    )

    status.update({
        "price_expansion_samples": list(price_samples),
        "price_expansion_effective_samples": list(price_effective_samples),
        "price_expansion_sample_ts": list(price_sample_ts),
        "price_split_gate_enabled": bool(split_status.get("enabled")),
        "price_split_source": split_status.get("source"),
        "price_split_max_imbalance_ratio": split_status.get("max_imbalance_ratio"),
        "price_split_min_balance_ratio": split_status.get("min_balance_ratio"),
        "price_split_balance_ratio": split_status.get("balance_ratio"),
        "price_split_combined_avg_pct": split_status.get("combined_avg_pct"),
        "price_split_min_half_avg_pct": split_status.get("min_half_avg_pct"),
        "price_split_min_combined_avg_pct": split_status.get("min_combined_avg_pct"),
        "price_split_first_avg_pct": split_status.get("first_avg_pct"),
        "price_split_second_avg_pct": split_status.get("second_avg_pct"),
        "price_split_first_sample_count": split_status.get("first_count"),
        "price_split_second_sample_count": split_status.get("second_count"),
        "price_split_first_non_flat_count": split_status.get("first_non_flat_count"),
        "price_split_second_non_flat_count": split_status.get("second_non_flat_count"),
        "price_split_min_non_flat_per_half": split_status.get("min_non_flat_per_half"),
        "price_split_passed": split_status.get("passed"),
        "price_sample_count": price_sample_count,
        "price_positive_sample_count": price_positive_sample_count,
        "price_negative_sample_count": price_negative_sample_count,
        "price_flat_sample_count": price_flat_sample_count,
        "price_non_flat_sample_count": price_non_flat_sample_count,
        "price_min_non_flat_sample_count": price_min_non_flat_samples,
        "price_positive_sample_ratio": price_positive_sample_ratio,
        "price_avg_expansion_pct": price_avg_expansion_pct,
    })

    body_top = None
    body_bottom = None
    rejection_wick_pct = None
    live_green_body_ok = None
    if isinstance(reference_candle, dict):
        open_price = _safe_positive_float(reference_candle.get("o"))
        close_price = live_price if live_price is not None else _safe_positive_float(reference_candle.get("c"))
        high_price = _safe_positive_float(reference_candle.get("h"))
        if open_price is not None and close_price is not None:
            body_top = max(open_price, close_price)
            body_bottom = min(open_price, close_price)
            live_green_body_ok = close_price >= open_price
        if body_top not in (None, 0, 0.0) and high_price is not None and high_price > body_top:
            rejection_wick_pct = pct_change(body_top, high_price)
    status["body_top"] = body_top
    status["body_bottom"] = body_bottom
    status["live_green_body_ok"] = live_green_body_ok
    status["rejection_wick_pct"] = rejection_wick_pct

    live_sma18 = _safe_positive_float((reference_candle or {}).get("sma18")) if isinstance(reference_candle, dict) else None
    body_bottom_to_sma18_pct = (
        pct_change(live_sma18, body_bottom)
        if live_sma18 not in (None, 0, 0.0) and body_bottom not in (None, 0, 0.0)
        else None
    )
    status["pre_entry_sma18"] = live_sma18
    status["pre_entry_body_bottom"] = body_bottom
    status["pre_entry_body_bottom_to_sma18_pct"] = body_bottom_to_sma18_pct
    # Deprecated aliases retained for downstream compatibility; these now mirror
    # body-bottom-to-SMA18, not plain live-price-to-SMA18.
    status["pre_entry_live_price_to_sma18_pct"] = body_bottom_to_sma18_pct
    try:
        pre_entry_min_body_bottom_to_sma18_pct = float(globals().get(
            "PMA_GF_PLUS_FORCE_BUY_PRE_ENTRY_MIN_BODY_BOTTOM_TO_SMA18_PCT",
            globals().get("PMA_GF_PLUS_FORCE_BUY_PRE_ENTRY_MIN_LIVE_PRICE_TO_SMA18_PCT", -1.50),
        ))
    except Exception:
        pre_entry_min_body_bottom_to_sma18_pct = -1.50
    status["pre_entry_min_body_bottom_to_sma18_pct"] = pre_entry_min_body_bottom_to_sma18_pct
    status["pre_entry_min_live_price_to_sma18_pct"] = pre_entry_min_body_bottom_to_sma18_pct

    try:
        min_price_above = float(globals().get("PMA_GF_PLUS_FORCE_BUY_MIN_PRICE_ABOVE_LAST_SCAN_PCT", 0.15))
    except Exception:
        min_price_above = 0.15
    try:
        max_rejection_wick = float(globals().get("PMA_GF_PLUS_FORCE_BUY_MAX_REJECTION_WICK_PCT", 3.0))
    except Exception:
        max_rejection_wick = 3.0
    status["min_price_above_last_scan_pct"] = min_price_above
    status["max_rejection_wick_pct"] = max_rejection_wick

    score_window = pma_gf_plus_prune_and_recompute_bad_buy_score(state, scan_dt=scan_dt) if isinstance(state, dict) else {
        "score": 0,
        "events": [],
        "window_seconds": _pma_gf_plus_bad_buy_score_window_seconds(),
        "expired_count": 0,
        "last_ts": None,
    }
    bad_score = int(score_window.get("score") or 0)
    bad_score_last_ts = ts_to_int(score_window.get("last_ts"))
    bad_score_max_age_seconds = int(score_window.get("window_seconds") or 0)
    bad_score_expired = bool(int(score_window.get("expired_count") or 0) > 0)
    status["bad_buy_score"] = bad_score
    status["bad_buy_score_last_ts"] = bad_score_last_ts
    status["bad_buy_score_expired"] = bad_score_expired
    status["bad_buy_score_max_age_seconds"] = bad_score_max_age_seconds
    status["bad_buy_score_window_event_count"] = len(score_window.get("events") or [])
    status["bad_buy_score_window_expired_count"] = int(score_window.get("expired_count") or 0)

    passed = True
    reason = "PMA/GF+ force buy quality gate passed"

    if bool(status.get("enabled")):
        if live_price in (None, 0, 0.0):
            passed = False
            reason = "PMA/GF+ force buy blocked: live price unavailable for quality gate"
        elif bool(globals().get("ENABLE_PMA_GF_PLUS_FORCE_BUY_PRE_ENTRY_SMA18_GUARD", True)) and (
            live_sma18 in (None, 0, 0.0) or body_bottom_to_sma18_pct is None or body_bottom_to_sma18_pct < pre_entry_min_body_bottom_to_sma18_pct
        ):
            passed = False
            status["pre_entry_sma18_guard_passed"] = False
            if live_sma18 in (None, 0, 0.0) or body_bottom_to_sma18_pct is None:
                reason = "PMA/GF+ force buy blocked: live SMA18 unavailable for pre-entry SMA18 guard"
            else:
                reason = (
                    "PMA/GF+ force buy blocked: current live candle body bottom is too far below SMA18 "
                    f"({body_bottom_to_sma18_pct:+.3f}% vs minimum {pre_entry_min_body_bottom_to_sma18_pct:+.3f}%)"
                )
            status["pre_entry_sma18_guard_reason"] = reason
        elif bool(globals().get("PMA_GF_PLUS_FORCE_BUY_REQUIRE_PRICE_EXPANSION", True)):
            avg_price_expansion = _safe_finite_float(status.get("price_avg_expansion_pct"))
            non_flat_count = int(status.get("price_non_flat_sample_count") or 0)
            min_non_flat_count = int(status.get("price_min_non_flat_sample_count") or 0)
            if previous_price in (None, 0, 0.0) and not status.get("price_expansion_samples"):
                passed = False
                reason = "PMA/GF+ force buy blocked: price history unavailable for average expansion check"
            elif non_flat_count < min_non_flat_count:
                passed = False
                reason = (
                    "PMA/GF+ force buy blocked: not enough non-flat price samples for average expansion "
                    f"({non_flat_count}/{min_non_flat_count}; ±{price_positive_flat_threshold:.3f}% is neutral flat)"
                )
            elif avg_price_expansion is None or avg_price_expansion < min_price_above:
                passed = False
                shown = plain_pct(avg_price_expansion) if avg_price_expansion is not None else "-"
                reason = f"PMA/GF+ force buy blocked: average price expansion {shown} < required +{min_price_above:.3f}%"
            elif bool(globals().get("PMA_GF_PLUS_FORCE_BUY_PRICE_EXPANSION_SPLIT_GATE_ENABLED", True)):
                split_passed = status.get("price_split_passed")
                balance_ratio = _safe_finite_float(status.get("price_split_balance_ratio"))
                min_balance_ratio = _safe_finite_float(status.get("price_split_min_balance_ratio"))
                max_imbalance_ratio = _safe_finite_float(status.get("price_split_max_imbalance_ratio"))
                combined_avg = _safe_finite_float(status.get("price_split_combined_avg_pct"))
                min_half_avg = _safe_finite_float(status.get("price_split_min_half_avg_pct"))
                min_combined_avg = _safe_finite_float(status.get("price_split_min_combined_avg_pct"))
                first_avg = _safe_finite_float(status.get("price_split_first_avg_pct"))
                second_avg = _safe_finite_float(status.get("price_split_second_avg_pct"))
                first_non_flat = int(status.get("price_split_first_non_flat_count") or 0)
                second_non_flat = int(status.get("price_split_second_non_flat_count") or 0)
                min_non_flat_per_half = int(status.get("price_split_min_non_flat_per_half") or 0)
                if not split_passed:
                    passed = False
                    reason = (
                        "PMA/GF+ force buy blocked: split price expansion averages failed "
                        f"(first_avg={plain_pct(first_avg) if first_avg is not None else '-'} "
                        f">= required +{(min_half_avg if min_half_avg is not None else 0.01):.3f}%, "
                        f"second_avg={plain_pct(second_avg) if second_avg is not None else '-'} "
                        f">= required +{(min_half_avg if min_half_avg is not None else 0.01):.3f}%, "
                        f"combined_first_plus_second={plain_pct(combined_avg) if combined_avg is not None else '-'} "
                        f">= required +{(min_combined_avg if min_combined_avg is not None else 0.32):.3f}%; "
                        f"non_flat first/second={first_non_flat}/{second_non_flat} >= {min_non_flat_per_half}/{min_non_flat_per_half}; "
                        f"v6_balance_debug={balance_ratio if balance_ratio is not None else '-'} "
                        f"vs {min_balance_ratio if min_balance_ratio is not None else 0.50}, "
                        f"max_imbalance_debug={max_imbalance_ratio if max_imbalance_ratio is not None else 2.0}:1)"
                    )

        if passed and bool(globals().get("PMA_GF_PLUS_FORCE_BUY_REQUIRE_PRICE_POSITIVE_RATIO", True)):
            ratio = _safe_finite_float(status.get("price_positive_sample_ratio"))
            sample_count = int(status.get("price_sample_count") or 0)
            positive_count = int(status.get("price_positive_sample_count") or 0)
            negative_count = int(status.get("price_negative_sample_count") or 0)
            flat_count = int(status.get("price_flat_sample_count") or 0)
            non_flat_count = int(status.get("price_non_flat_sample_count") or 0)
            min_non_flat_count = int(status.get("price_min_non_flat_sample_count") or 0)
            if non_flat_count < min_non_flat_count:
                passed = False
                reason = (
                    "PMA/GF+ force buy blocked: not enough non-flat price samples for positive-ratio gate "
                    f"({non_flat_count}/{min_non_flat_count}; total={sample_count}, flat={flat_count})"
                )
            elif ratio is None:
                passed = False
                reason = "PMA/GF+ force buy blocked: price-positive ratio history unavailable since setup start"
            elif ratio + 1e-12 < price_positive_ratio_min:
                passed = False
                reason = (
                    "PMA/GF+ force buy blocked: price was not positive often enough since setup start "
                    f"({positive_count}/{non_flat_count} non-flat = {ratio:.3f} < required {price_positive_ratio_min:.3f}; "
                    f"negative={negative_count}, flat={flat_count}; ±{price_positive_flat_threshold:.3f}% is neutral)"
                )

        if passed and bool(globals().get("PMA_GF_PLUS_FORCE_BUY_REQUIRE_LIVE_GREEN_BODY", True)):
            if live_green_body_ok is False:
                passed = False
                reason = "PMA/GF+ force buy blocked: PMA ok but live candle body is not green"

        if passed and rejection_wick_pct is not None and rejection_wick_pct > max_rejection_wick:
            passed = False
            reason = f"PMA/GF+ force buy blocked: rejection wick {rejection_wick_pct:.3f}% > max {max_rejection_wick:.3f}%"

        if passed and bool(globals().get("ENABLE_PMA_GF_PLUS_FORCE_BUY_PRE_ENTRY_SMA18_GUARD", True)):
            if live_sma18 in (None, 0, 0.0) or body_bottom_to_sma18_pct is None:
                passed = False
                status["pre_entry_sma18_guard_passed"] = False
                reason = "PMA/GF+ force buy blocked: live SMA18 unavailable for pre-entry SMA18 guard"
                status["pre_entry_sma18_guard_reason"] = reason
            elif body_bottom_to_sma18_pct < pre_entry_min_body_bottom_to_sma18_pct:
                passed = False
                status["pre_entry_sma18_guard_passed"] = False
                reason = (
                    "PMA/GF+ force buy blocked: current live candle body bottom is too far below SMA18 "
                    f"({body_bottom_to_sma18_pct:+.3f}% vs minimum {pre_entry_min_body_bottom_to_sma18_pct:+.3f}%)"
                )
                status["pre_entry_sma18_guard_reason"] = reason
            else:
                status["pre_entry_sma18_guard_passed"] = True
                status["pre_entry_sma18_guard_reason"] = (
                    f"pre-entry SMA18 guard passed: live body bottom {body_bottom_to_sma18_pct:+.3f}% vs SMA18 "
                    f">= {pre_entry_min_body_bottom_to_sma18_pct:+.3f}%"
                )

        if passed and bool(globals().get("PMA_GF_PLUS_FORCE_BUY_BAD_SCORE_ENABLED", True)) and bad_score > 0:
            try:
                threshold = int(globals().get("PMA_GF_PLUS_FORCE_BUY_BAD_SCORE_THRESHOLD", 2))
            except Exception:
                threshold = 2
            try:
                hard_threshold = int(globals().get("PMA_GF_PLUS_FORCE_BUY_BAD_SCORE_HARD_THRESHOLD", 4))
            except Exception:
                hard_threshold = 4
            required_offset = None
            required_price_expansion = None
            if bad_score >= hard_threshold:
                try:
                    required_offset = float(globals().get("PMA_GF_PLUS_FORCE_BUY_BAD_SCORE_HARD_MIN_OFFSET", PMA_GF_PLUS_FORCE_BUY_INSTANT_OFFSET + 0.80))
                except Exception:
                    required_offset = 4.0
                try:
                    required_price_expansion = float(globals().get("PMA_GF_PLUS_FORCE_BUY_BAD_SCORE_HARD_MIN_PRICE_ABOVE_LAST_SCAN_PCT", 1.00))
                except Exception:
                    required_price_expansion = 1.00
            elif bad_score >= threshold:
                try:
                    required_offset = float(globals().get("PMA_GF_PLUS_FORCE_BUY_BAD_SCORE_MIN_OFFSET", PMA_GF_PLUS_FORCE_BUY_INSTANT_OFFSET))
                except Exception:
                    required_offset = 3.2
                try:
                    required_price_expansion = float(globals().get("PMA_GF_PLUS_FORCE_BUY_BAD_SCORE_MIN_PRICE_ABOVE_LAST_SCAN_PCT", 0.50))
                except Exception:
                    required_price_expansion = 0.50

            if required_offset is not None and required_price_expansion is not None:
                status["bad_score_hardened"] = True
                status["required_offset_for_bad_score"] = required_offset
                status["required_price_expansion_for_bad_score"] = required_price_expansion
                price_expansion = status.get("price_avg_expansion_pct")
                offset_ok = offset is not None and offset >= required_offset
                expansion_ok = price_expansion is not None and price_expansion >= required_price_expansion
                if not (offset_ok or expansion_ok):
                    passed = False
                    shown_expansion = plain_pct(price_expansion) if price_expansion is not None else "-"
                    shown_offset = f"{offset:.6f}" if offset is not None else "-"
                    reason = (
                        f"PMA/GF+ force buy blocked: recent bad-buy score {bad_score} requires "
                        f"offset >= +{required_offset:.3f} or average price expansion >= +{required_price_expansion:.3f}% "
                        f"(offset {shown_offset}, expansion {shown_expansion})"
                    )

    status["passed"] = bool(passed)
    status["reason"] = reason

    if isinstance(state, dict):
        if live_price not in (None, 0, 0.0):
            state["pma_gf_plus_force_buy_quality_last_price"] = live_price
            state["pma_gf_plus_force_buy_quality_last_scan_ts"] = current_scan_ts
        state["pma_gf_plus_force_buy_quality_last_reason"] = reason
        state["pma_gf_plus_force_buy_quality_last_passed"] = bool(passed)
        state["pma_gf_plus_force_buy_quality_expansion_samples"] = list(status.get("price_expansion_samples") or [])
        state["pma_gf_plus_force_buy_quality_expansion_sample_ts"] = list(status.get("price_expansion_sample_ts") or [])
        state["pma_gf_plus_force_buy_history_window_start_ts"] = status.get("history_window_start_ts")
        state["pma_gf_plus_force_buy_history_window_end_ts"] = status.get("history_window_end_ts")
        state["pma_gf_plus_force_buy_history_window_source"] = status.get("history_window_source")
        state["pma_gf_plus_force_buy_quality_sample_count"] = int(status.get("price_sample_count") or 0)
        state["pma_gf_plus_force_buy_quality_positive_sample_count"] = int(status.get("price_positive_sample_count") or 0)
        state["pma_gf_plus_force_buy_quality_negative_sample_count"] = int(status.get("price_negative_sample_count") or 0)
        state["pma_gf_plus_force_buy_quality_flat_sample_count"] = int(status.get("price_flat_sample_count") or 0)
        state["pma_gf_plus_force_buy_quality_non_flat_sample_count"] = int(status.get("price_non_flat_sample_count") or 0)
        state["pma_gf_plus_force_buy_quality_avg_expansion_pct"] = status.get("price_avg_expansion_pct")
        state["pma_gf_plus_force_buy_quality_split_first_avg_pct"] = status.get("price_split_first_avg_pct")
        state["pma_gf_plus_force_buy_quality_split_second_avg_pct"] = status.get("price_split_second_avg_pct")
        state["pma_gf_plus_force_buy_quality_split_combined_avg_pct"] = status.get("price_split_combined_avg_pct")
        state["pma_gf_plus_force_buy_quality_split_min_half_avg_pct"] = status.get("price_split_min_half_avg_pct")
        state["pma_gf_plus_force_buy_quality_split_min_combined_avg_pct"] = status.get("price_split_min_combined_avg_pct")
        state["pma_gf_plus_force_buy_quality_split_balance_ratio"] = status.get("price_split_balance_ratio")
        state["pma_gf_plus_force_buy_quality_split_passed"] = status.get("price_split_passed")
        state["pma_gf_plus_force_buy_quality_positive_sample_ratio"] = status.get("price_positive_sample_ratio")

    return status

def update_pma_gf_plus_bad_buy_score_after_sell(state, pnl_pct, scan_dt=None, reason=None, pma=None, price=None, oma=None, offset=None):
    if not isinstance(state, dict):
        return None

    try:
        pnl = float(pnl_pct) if pnl_pct is not None else None
    except Exception:
        pnl = None

    if pnl is None or not math.isfinite(pnl):
        current = pma_gf_plus_prune_and_recompute_bad_buy_score(state, scan_dt=scan_dt)
        return current.get("score")

    try:
        hard_loss_pct = float(globals().get("PMA_GF_PLUS_BAD_BUY_SCORE_HARD_LOSS_PCT", -1.50))
    except Exception:
        hard_loss_pct = -1.50
    try:
        loss_pct = float(globals().get("PMA_GF_PLUS_BAD_BUY_SCORE_LOSS_PCT", -0.80))
    except Exception:
        loss_pct = -0.80
    try:
        win_decay_pct = float(globals().get("PMA_GF_PLUS_BAD_BUY_SCORE_WIN_DECAY_PCT", 2.00))
    except Exception:
        win_decay_pct = 2.00
    try:
        clear_win_pct = float(globals().get("PMA_GF_PLUS_BAD_BUY_SCORE_CLEAR_WIN_PCT", 5.00))
    except Exception:
        clear_win_pct = 5.00

    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if scan_ts is None:
        try:
            scan_ts = int(time.time())
        except Exception:
            scan_ts = None

    delta = 0
    clear = False
    bad_cycle = False
    if pnl <= hard_loss_pct:
        delta = 2
        bad_cycle = True
    elif pnl <= loss_pct:
        delta = 1
        bad_cycle = True
    elif pnl >= clear_win_pct:
        clear = True
        delta = 0
    elif pnl >= win_decay_pct:
        delta = -1

    raw_events = state.get("pma_gf_plus_bad_buy_score_events")
    events = list(raw_events) if isinstance(raw_events, list) else []

    # If this is the first v10.5 update on a state that only has the older
    # scalar score, preserve that penalty as a legacy event before appending
    # the new sell result.
    if not events:
        try:
            legacy_score = int(state.get("pma_gf_plus_bad_buy_score") or 0)
        except Exception:
            legacy_score = 0
        legacy_ts = ts_to_int(state.get("pma_gf_plus_bad_buy_last_ts"))
        if legacy_score > 0 and legacy_ts is not None and legacy_ts != scan_ts:
            events.append({
                "ts": legacy_ts,
                "delta": legacy_score,
                "clear": False,
                "pnl_pct": state.get("pma_gf_plus_bad_buy_last_pnl_pct"),
                "reason": str(state.get("pma_gf_plus_bad_buy_last_reason") or "legacy scalar bad-buy score"),
                "pma": _safe_finite_float(state.get("pma_gf_plus_bad_buy_last_pma")),
                "oma": _safe_finite_float(state.get("pma_gf_plus_bad_buy_last_oma")),
                "offset": _safe_finite_float(state.get("pma_gf_plus_bad_buy_last_offset")),
                "price": _safe_positive_float(state.get("pma_gf_plus_bad_buy_last_price")),
            })

    events.append({
        "ts": scan_ts,
        "delta": delta,
        "clear": clear,
        "pnl_pct": pnl,
        "reason": str(reason or ""),
        "pma": _safe_finite_float(pma) if bad_cycle else None,
        "oma": _safe_finite_float(oma) if bad_cycle else None,
        "offset": _safe_finite_float(offset) if bad_cycle else None,
        "price": _safe_positive_float(price) if bad_cycle else None,
    })
    state["pma_gf_plus_bad_buy_score_events"] = events

    score_window = pma_gf_plus_prune_and_recompute_bad_buy_score(state, scan_dt=scan_dt)
    return score_window.get("score")


def reset_pma_gf_plus_force_buy_final_survival_tracking(state):
    if not isinstance(state, dict):
        return
    state["pma_gf_plus_force_buy_final_survival_since_ts"] = None
    state["pma_gf_plus_force_buy_final_survival_elapsed_seconds"] = None
    state["pma_gf_plus_force_buy_final_survival_last_reason"] = None
    state["pma_gf_plus_force_buy_final_survival_last_passed"] = None
    state["pma_gf_plus_force_buy_final_survival_start_price"] = None
    state["pma_gf_plus_force_buy_final_survival_current_price"] = None
    state["pma_gf_plus_force_buy_final_survival_price_drop_pct"] = None
    state["pma_gf_plus_force_buy_final_survival_max_drop_pct"] = None
    state["pma_gf_plus_force_buy_final_survival_quality_expansion_samples"] = []
    state["pma_gf_plus_force_buy_final_survival_quality_last_sample_ts"] = None
    state["pma_gf_plus_force_buy_final_survival_quality_avg_expansion_pct"] = None
    state["pma_gf_plus_force_buy_final_survival_quality_sample_count"] = 0


def _pma_gf_plus_force_buy_final_survival_record_quality_sample(state, quality_status=None, scan_dt=None):
    """Record scan-to-scan price expansion samples during the final survival hold.

    The final BUY emission check uses the average expansion over the hold, not a
    single last-scan value. This avoids rejecting one noisy last tick while still
    blocking flat/negative holds.
    """
    summary = {
        "sample_pct": None,
        "avg_pct": None,
        "sample_count": 0,
        "samples": [],
    }
    if not isinstance(state, dict):
        return summary
    sample = _safe_finite_float((quality_status or {}).get("price_above_last_scan_pct") if isinstance(quality_status, dict) else None)
    sample_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    samples = state.get("pma_gf_plus_force_buy_final_survival_quality_expansion_samples")
    if not isinstance(samples, list):
        samples = []
    last_sample_ts = ts_to_int(state.get("pma_gf_plus_force_buy_final_survival_quality_last_sample_ts"))
    if sample is not None and sample_ts is not None and sample_ts != last_sample_ts:
        samples.append(float(sample))
        # Keep the list bounded while preserving the final-hold window samples.
        max_samples = max(8, int(float(globals().get("PMA_GF_PLUS_FORCE_BUY_FINAL_SURVIVAL_HOLD_SECONDS", 30))) + 5)
        samples = samples[-max_samples:]
        state["pma_gf_plus_force_buy_final_survival_quality_last_sample_ts"] = sample_ts
    valid_samples = [_safe_finite_float(x) for x in samples]
    valid_samples = [x for x in valid_samples if x is not None]
    try:
        final_positive_flat_threshold = max(0.0, float(globals().get("PMA_GF_PLUS_FORCE_BUY_FINAL_SURVIVAL_POSITIVE_SAMPLE_FLAT_THRESHOLD_PCT", 0.01)))
    except Exception:
        final_positive_flat_threshold = 0.01
    non_flat_samples = [float(x) for x in valid_samples if abs(float(x)) > final_positive_flat_threshold]
    # v23: final-survival average also discludes ±0.01 flat samples.
    # Flats remain in raw samples for debug/counts, but do not enter the average
    # denominator used by the final survival +0.32/majority-style checks.
    avg_pct = (sum(non_flat_samples) / len(non_flat_samples)) if non_flat_samples else None
    state["pma_gf_plus_force_buy_final_survival_quality_expansion_samples"] = valid_samples
    state["pma_gf_plus_force_buy_final_survival_quality_avg_expansion_pct"] = avg_pct
    state["pma_gf_plus_force_buy_final_survival_quality_sample_count"] = len(valid_samples)
    state["pma_gf_plus_force_buy_final_survival_quality_non_flat_sample_count"] = len(non_flat_samples)
    summary.update({
        "sample_pct": sample,
        "avg_pct": avg_pct,
        "sample_count": len(valid_samples),
        "non_flat_sample_count": len(non_flat_samples),
        "effective_samples": non_flat_samples,
        "samples": valid_samples,
    })
    return summary


def pma_gf_plus_force_buy_prebuy_fib_closed_gate_status(state, reference_candle=None, current_price=None, scan_dt=None):
    """Return whether the v10.4 pre-BUY fib closed-candle gate passes.

    This is intentionally a pre-buy filter only: the same/reference closed
    candle may block the final survival hold, but after the BUY is emitted the
    post-buy fib closed-candle sell path must wait for a new closed candle.
    """
    status = {
        "enabled": bool(globals().get("PMA_GF_PLUS_FORCE_BUY_FINAL_SURVIVAL_USE_FIB_CLOSED_FAILURE_GATE", True)),
        "passed": True,
        "reason": "pre-BUY fib closed-candle gate disabled",
        "closed_failure": False,
        "latest_closed_close": None,
        "latest_closed_ts": None,
        "threshold_price": None,
        "fib_bottom": None,
        "fib_top": None,
        "fib_valid": False,
        "fib_source": None,
    }
    if not bool(status.get("enabled")):
        return status

    live_price = _safe_positive_float(current_price)
    if live_price is None:
        live_price = _safe_positive_float((reference_candle or {}).get("c") if isinstance(reference_candle, dict) else None)
    buy_candle = build_live_price_buy_candle(reference_candle, live_price=live_price)
    if not isinstance(buy_candle, dict):
        status["passed"] = True
        status["reason"] = "pre-BUY fib closed-candle gate skipped: buy candle unavailable"
        return status

    # Preview the exact fib range that a PMA/GF+ force BUY would create without
    # mutating the live strategy state. This keeps the old instant fib failure
    # behavior as a pre-buy gate.
    preview_state = dict(state or {})
    fib_status = _pma_gf_plus_force_buy_created_fib_range(
        preview_state,
        reference_candle=reference_candle,
        buy_candle=buy_candle,
        current_price=live_price,
        scan_dt=scan_dt,
    )
    fib_bottom = _safe_positive_float(preview_state.get("fib_bottom") if preview_state.get("fib_bottom") is not None else fib_status.get("fib_bottom"))
    fib_top = _safe_positive_float(preview_state.get("fib_top") if preview_state.get("fib_top") is not None else fib_status.get("fib_top"))
    status.update({
        "fib_bottom": fib_bottom,
        "fib_top": fib_top,
        "fib_valid": bool(fib_status.get("valid")),
        "fib_source": fib_status.get("source"),
    })
    if not bool(fib_status.get("valid")):
        status["passed"] = True
        status["reason"] = "pre-BUY fib closed-candle gate skipped: valid fib preview unavailable"
        return status

    fib_zone = fib_sell_zone_status(fib_bottom, fib_top, live_price)
    threshold_price = _safe_positive_float(fib_zone.get("threshold_price"))
    latest_closed_close = _safe_positive_float((reference_candle or {}).get("c")) if isinstance(reference_candle, dict) else None
    latest_closed_ts = ts_to_int((reference_candle or {}).get("t")) if isinstance(reference_candle, dict) else None
    status.update({
        "latest_closed_close": latest_closed_close,
        "latest_closed_ts": latest_closed_ts,
        "threshold_price": threshold_price,
        "fib_zone": fib_zone,
    })

    closed_failure = bool(
        threshold_price is not None and
        latest_closed_close is not None and
        latest_closed_close <= threshold_price
    )
    status["closed_failure"] = closed_failure
    if closed_failure:
        status["passed"] = False
        status["reason"] = (
            "PMA/GF+ force buy final survival blocked: latest CLOSED candle "
            f"{latest_closed_close:g} <= fib 0.382 threshold {threshold_price:g}"
        )
    else:
        status["passed"] = True
        status["reason"] = "pre-BUY fib closed-candle gate passed"
    return status


def pma_gf_plus_force_buy_final_survival_status(
    state,
    reference_candle=None,
    current_price=None,
    scan_dt=None,
):
    """Final PMA/GF+ survival gate after all normal BUY gates already passed."""
    status = {
        "enabled": bool(globals().get("ENABLE_PMA_GF_PLUS_FORCE_BUY_FINAL_SURVIVAL_GATE", True)),
        "passed": True,
        "reason": "final survival gate disabled",
        "since_ts": None,
        "elapsed_seconds": None,
        "required_seconds": None,
        "prebuy_fib_gate": None,
        "start_price": None,
        "current_price": None,
        "price_drop_pct": None,
        "price_max_drop_pct": None,
        "price_gate_passed": None,
        "failed_hard_reset": False,
    }
    if not bool(status.get("enabled")):
        return status
    if not isinstance(state, dict):
        status["passed"] = False
        status["reason"] = "PMA/GF+ force buy final survival blocked: missing state"
        return status

    try:
        required_seconds = max(0, int(float(globals().get("PMA_GF_PLUS_FORCE_BUY_FINAL_SURVIVAL_HOLD_SECONDS", 4))))
    except Exception:
        required_seconds = 4
    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    status["required_seconds"] = required_seconds

    prebuy_gate = pma_gf_plus_force_buy_prebuy_fib_closed_gate_status(
        state,
        reference_candle=reference_candle,
        current_price=current_price,
        scan_dt=scan_dt,
    )
    status["prebuy_fib_gate"] = prebuy_gate
    if bool(prebuy_gate.get("enabled")) and not bool(prebuy_gate.get("passed")):
        # A real failure during the final survival window means the whole
        # prehold + hold sequence must prove itself again from scratch.
        reset_pma_gf_plus_force_buy_tracking(state)
        status["passed"] = False
        status["failed_hard_reset"] = True
        status["reason"] = prebuy_gate.get("reason") or "PMA/GF+ force buy final survival blocked by pre-BUY fib gate"
        return status

    live_price = _safe_positive_float(current_price)
    if live_price is None:
        live_price = _safe_positive_float((reference_candle or {}).get("c") if isinstance(reference_candle, dict) else None)
    try:
        max_drop_pct = abs(float(globals().get("PMA_GF_PLUS_FORCE_BUY_FINAL_SURVIVAL_MAX_DROP_FROM_START_PCT", 0.10)))
    except Exception:
        max_drop_pct = 0.10
    status["price_max_drop_pct"] = max_drop_pct
    status["current_price"] = live_price

    since_ts = ts_to_int(state.get("pma_gf_plus_force_buy_final_survival_since_ts"))
    if since_ts is None:
        since_ts = current_scan_ts
        state["pma_gf_plus_force_buy_final_survival_since_ts"] = since_ts
        state["pma_gf_plus_force_buy_final_survival_start_price"] = live_price
    hold_start_price = _safe_positive_float(state.get("pma_gf_plus_force_buy_final_survival_start_price"))
    if hold_start_price is None and live_price is not None:
        hold_start_price = live_price
        state["pma_gf_plus_force_buy_final_survival_start_price"] = hold_start_price

    price_drop_pct = pct_change(hold_start_price, live_price) if hold_start_price not in (None, 0, 0.0) and live_price is not None else None
    state["pma_gf_plus_force_buy_final_survival_current_price"] = live_price
    state["pma_gf_plus_force_buy_final_survival_price_drop_pct"] = price_drop_pct
    state["pma_gf_plus_force_buy_final_survival_max_drop_pct"] = max_drop_pct
    status["start_price"] = hold_start_price
    status["price_drop_pct"] = price_drop_pct
    status["price_gate_passed"] = True
    if price_drop_pct is not None and price_drop_pct < -max_drop_pct:
        # Do not keep a half-proven setup alive after it deteriorates during
        # the survival hold. Reset PMA/GF+ prehold and final hold together.
        reset_pma_gf_plus_force_buy_tracking(state)
        status["passed"] = False
        status["price_gate_passed"] = False
        status["failed_hard_reset"] = True
        status["reason"] = (
            "PMA/GF+ force buy final survival reset: current price "
            f"{live_price:g} is {price_drop_pct:+.3f}% below hold-start price "
            f"{hold_start_price:g}, worse than allowed -{max_drop_pct:.3f}%"
        )
        return status

    elapsed = max(0, int((current_scan_ts or since_ts) - since_ts)) if since_ts is not None else 0
    state["pma_gf_plus_force_buy_final_survival_elapsed_seconds"] = elapsed
    status["since_ts"] = since_ts
    status["elapsed_seconds"] = elapsed

    if elapsed >= required_seconds:
        status["passed"] = True
        status["reason"] = f"PMA/GF+ final survival hold passed {elapsed}s/{required_seconds}s"
    else:
        status["passed"] = False
        status["reason"] = f"PMA/GF+ force buy pending: final survival hold {elapsed}s/{required_seconds}s"

    state["pma_gf_plus_force_buy_final_survival_last_reason"] = status.get("reason")
    state["pma_gf_plus_force_buy_final_survival_last_passed"] = bool(status.get("passed"))
    return status

def pma_gf_plus_breakout_force_buy_status(breakout_snapshot=None, offset=None):
    """Return whether the V11 breakout-backed PMA/GF+ force BUY trigger passes."""
    status = {
        "enabled": bool(globals().get("ENABLE_PMA_GF_PLUS_BREAKOUT_FORCE_BUY", True)),
        "passed": False,
        "reason": "PMA/GF+ breakout force BUY disabled",
        "force_only_required": bool(globals().get("PMA_GF_PLUS_BREAKOUT_FORCE_BUY_REQUIRE_FORCE_ONLY_MODE", True)),
        "force_only_active": bool(globals().get("ONLY_ALLOW_PMA_GF_PLUS_FORCE_BUYS", False)),
        "old_breakout_fully_true": False,
        "setup_eligible": False,
        "volume_velocity": None,
        "min_volume_velocity": None,
        "live_body_vs_breakout_threshold_pct": None,
        "min_body_above_breakout_pct": None,
        "offset": _safe_finite_float(offset),
        "min_offset": None,
        "live_green_breakout_ok": None,
        "live_body_above_threshold": None,
        "body_acceptance_ok": None,
        "current_price_acceptance_ok": None,
        "breakout_rejection_ok": None,
        "volume_ok": None,
        "entry_allowed": None,
        "reference_selection_ok": None,
        "live_green_body_top_above_sma18_ok": None,
    }
    if not bool(status.get("enabled")):
        return status
    if bool(status.get("force_only_required")) and not bool(status.get("force_only_active")):
        status["reason"] = "PMA/GF+ breakout force BUY blocked: force-buy-only mode is not active"
        return status
    if not isinstance(breakout_snapshot, dict):
        status["reason"] = "PMA/GF+ breakout force BUY blocked: breakout snapshot unavailable"
        return status

    setup_status = breakout_snapshot.get("setup_status") if isinstance(breakout_snapshot.get("setup_status"), dict) else {}
    status["setup_eligible"] = bool(breakout_snapshot.get("setup_eligible"))
    for key in (
        "live_green_breakout_ok",
        "live_body_above_threshold",
        "body_acceptance_ok",
        "current_price_acceptance_ok",
        "breakout_rejection_ok",
        "volume_ok",
        "entry_allowed",
        "reference_selection_ok",
        "live_green_body_top_above_sma18_ok",
    ):
        value = setup_status.get(key)
        status[key] = bool(value) if value is not None else None

    # "Old breakout_debug fully true" means the legacy breakout setup would be
    # actionable from its own debug fields: entry/reference/live-body/acceptance/
    # rejection/volume gates are all true. The explicit volume/body thresholds
    # below are stronger than the legacy debug booleans.
    old_breakout_fully_true = bool(
        status.get("setup_eligible") and
        status.get("entry_allowed") is not False and
        status.get("reference_selection_ok") is not False and
        # PMA/GF+ breakout-backed force buys use the explicit body-bottom
        # pre-entry SMA18 guard, not the older live-body-top>SMA18 breakout guard.
        status.get("live_green_breakout_ok") and
        status.get("live_body_above_threshold") and
        status.get("body_acceptance_ok") and
        status.get("current_price_acceptance_ok") and
        status.get("breakout_rejection_ok") is not False and
        status.get("volume_ok") is not False
    )
    status["old_breakout_fully_true"] = old_breakout_fully_true
    if not old_breakout_fully_true:
        status["reason"] = "PMA/GF+ breakout force BUY blocked: old breakout debug is not fully true"
        return status

    volume_velocity = _safe_finite_float(breakout_snapshot.get("volume_velocity"))
    body_above_pct = _safe_finite_float(breakout_snapshot.get("live_body_vs_breakout_threshold_pct"))
    try:
        min_volume_velocity = float(globals().get("PMA_GF_PLUS_BREAKOUT_FORCE_BUY_MIN_VOLUME_VELOCITY", 5.0))
    except Exception:
        min_volume_velocity = 5.0
    try:
        min_body_above_pct = float(globals().get("PMA_GF_PLUS_BREAKOUT_FORCE_BUY_MIN_BODY_ABOVE_BREAKOUT_PCT", 2.5))
    except Exception:
        min_body_above_pct = 2.5
    try:
        min_offset = float(globals().get("PMA_GF_PLUS_BREAKOUT_FORCE_BUY_MIN_OFFSET", 0.40))
    except Exception:
        min_offset = 0.40
    status.update({
        "volume_velocity": volume_velocity,
        "min_volume_velocity": min_volume_velocity,
        "live_body_vs_breakout_threshold_pct": body_above_pct,
        "min_body_above_breakout_pct": min_body_above_pct,
        "min_offset": min_offset,
    })

    if volume_velocity is None or volume_velocity < min_volume_velocity:
        status["reason"] = (
            "PMA/GF+ breakout force BUY blocked: volume velocity "
            f"{volume_velocity if volume_velocity is not None else 'unavailable'} < required {min_volume_velocity:.2f}x"
        )
        return status
    if body_above_pct is None or body_above_pct < min_body_above_pct:
        status["reason"] = (
            "PMA/GF+ breakout force BUY blocked: live body is "
            f"{body_above_pct if body_above_pct is not None else 'unavailable'}% above breakout threshold, "
            f"below required +{min_body_above_pct:.3f}%"
        )
        return status
    current_offset = _safe_finite_float(offset)
    if current_offset is None or (current_offset + 1e-12) < min_offset:
        status["reason"] = (
            "PMA/GF+ breakout force BUY blocked: PMA/GF+ offset "
            f"{current_offset if current_offset is not None else 'unavailable'} < required +{min_offset:.3f}"
        )
        return status

    status["passed"] = True
    status["reason"] = (
        "PMA/GF+ breakout force BUY: old breakout debug fully true, "
        f"volume velocity {volume_velocity:.2f}x >= {min_volume_velocity:.2f}x, "
        f"live body +{body_above_pct:.3f}% above breakout threshold >= +{min_body_above_pct:.3f}%, "
        f"and PMA/GF+ offset {current_offset:.6f} >= +{min_offset:.3f}"
    )
    return status


def pma_gf_plus_force_buy_full_scan_isolation_status():
    """Non-mutating PMA/GF+ debug placeholder for FULL-5M scans.

    v43 rule: BUY-1M is the only owner of PMA/GF+ force-buy setup/history,
    elapsed timers, direct-buy activation, and PMA/GF+ lifecycle sell timing.
    FULL-5M uses this placeholder so log/debug fields remain present without
    sampling price/OMA history or resetting setup state.
    """
    return {
        "enabled": bool(ENABLE_PMA_GF_PLUS_FORCE_BUY),
        "ready": False,
        "reason": "PMA/GF+ force-buy tracking is BUY-1M-owned; FULL-5M skipped without mutating setup/history/elapsed state",
        "trigger": "full_scan_isolated",
        "elapsed_seconds": None,
        "above_since_ts": None,
        "gf_plus_since_ts": None,
        "offset": None,
        "pma": None,
        "gf_plus": None,
        "quality_gate_enabled": bool(globals().get("PMA_GF_PLUS_FORCE_BUY_REQUIRE_PRICE_POSITIVE_RATIO", True)),
        "quality_gate_passed": None,
        "quality_gate_reason": "FULL-5M does not sample PMA/GF+ price history",
        "oma_filter_enabled": bool(globals().get("ENABLE_PMA_GF_PLUS_OMA_FILTER", True)),
        "oma_filter_passed": None,
        "oma_filter_reason": "FULL-5M does not sample PMA/GF+ OMA history",
        "final_survival_gate_enabled": bool(globals().get("PMA_GF_PLUS_FORCE_BUY_FINAL_SURVIVAL_ENABLED", False)),
        "final_survival_gate_passed": None,
        "final_survival_gate_reason": "FULL-5M does not update PMA/GF+ final-survival timing",
        "history_sampling_lane": "full_scan_isolated",
        "decision_lane_for_gates": "full_scan_isolated",
    }


