def update_active_buy_pma_gf_plus_tracking(state, pine_30m_status, scan_dt):
    status = {
        "updated_peak": False,
        "pma": None,
        "closed_pma": None,
        "gf_plus": None,
        "df0": None,
        "offset": None,
        "closed_offset": None,
        "peak_offset": None,
        "seen_above": False,
        "closed_above_gf_plus": False,
        "closed_below_gf_plus": False,
        "qualified_since_buy": False,
        "qualification_trigger": None,
    }
    if not isinstance(state, dict):
        return status
    ensure_active_buy_state_defaults(state)
    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    pine_30m_status = pine_30m_status if isinstance(pine_30m_status, dict) else {}
    pma, gf_plus, offset = pma_gf_plus_values(pine_30m_status)
    closed_pma_raw = _safe_finite_float(pine_30m_status.get("prev_pma"))
    closed_pma_flat_neutral_raw = bool(pine_30m_status.get("prev_pma_flat_neutral"))
    closed_pma_raw_above_gf_plus = bool(closed_pma_raw is not None and gf_plus is not None and closed_pma_raw > gf_plus)
    # A flat-neutral CLOSED PMA (commonly 0.000000 from flat/stale OHLC) is not
    # structural proof.  But if the raw CLOSED PMA is actually above GF+, it is
    # the latest closed-PMA proof and must not be invalidated by the flat flag.
    closed_pma_flat_neutral = bool(closed_pma_flat_neutral_raw and not closed_pma_raw_above_gf_plus)
    closed_pma_flat_neutral_ignored_for_proof = bool(closed_pma_flat_neutral_raw and closed_pma_raw_above_gf_plus)
    closed_pma = None if closed_pma_flat_neutral else closed_pma_raw
    closed_pma_candle_close_ts = ts_to_int(pine_30m_status.get("prev_pma_candle_close_ts"))
    df0 = _safe_finite_float(pine_30m_status.get("DF0"))
    closed_offset = (closed_pma - gf_plus) if closed_pma is not None and gf_plus is not None else None
    status.update({
        "pma": pma,
        "closed_pma": closed_pma,
        "closed_pma_raw": closed_pma_raw,
        "closed_pma_flat_neutral": closed_pma_flat_neutral,
        "closed_pma_flat_neutral_raw": closed_pma_flat_neutral_raw,
        "closed_pma_flat_neutral_ignored_for_proof": closed_pma_flat_neutral_ignored_for_proof,
        "closed_pma_candle_close_ts": closed_pma_candle_close_ts,
        "gf_plus": gf_plus,
        "df0": df0,
        "offset": offset,
        "closed_offset": closed_offset,
    })
    if pma is None or gf_plus is None or offset is None:
        return status

    first_buy_ts = active_buy_first_buy_ts(state)
    first_buy_ts_int = int(first_buy_ts) if first_buy_ts is not None else None
    closed_pma_in_active_buy_window = True
    if closed_pma_candle_close_ts is not None and first_buy_ts_int is not None:
        closed_pma_in_active_buy_window = bool(closed_pma_candle_close_ts > first_buy_ts_int)
    state["active_buy_pma_gf_plus_last_closed_pma_candle_close_ts"] = closed_pma_candle_close_ts
    tracked_buy_ts = ts_to_int(state.get("active_buy_pma_gf_plus_buy_ts"))
    if first_buy_ts is not None and tracked_buy_ts != int(first_buy_ts):
        reset_active_buy_pma_gf_plus_tracking(state)
        state["active_buy_pma_gf_plus_buy_ts"] = int(first_buy_ts)

    state["active_buy_pma_gf_plus_last_offset"] = offset
    state["active_buy_pma_gf_plus_last_pma"] = pma
    state["active_buy_pma_gf_plus_last_gf_plus"] = gf_plus
    state["active_buy_pma_gf_plus_last_scan_ts"] = current_scan_ts

    # Track live time above GF+ from the real BUY. This is the same GF+ proof
    # as the entry bypass: +2 offset immediately, or continuously above GF+
    # for PMA_GF_PLUS_FORCE_BUY_HOLD_SECONDS.
    try:
        hold_seconds = max(0, int(float(PMA_GF_PLUS_FORCE_BUY_HOLD_SECONDS)))
    except Exception:
        hold_seconds = 30
    try:
        hold_min_offset = float(globals().get("PMA_GF_PLUS_FORCE_BUY_HOLD_MIN_OFFSET", 1.00))
    except Exception:
        hold_min_offset = 1.00
    try:
        instant_offset = float(globals().get("PMA_GF_PLUS_FORCE_BUY_INSTANT_OFFSET", 0.06))
    except Exception:
        instant_offset = 0.06

    if offset > 0:
        if not bool(state.get("active_buy_pma_gf_plus_seen_above")):
            state["active_buy_pma_gf_plus_seen_above_ts"] = current_scan_ts
        state["active_buy_pma_gf_plus_seen_above"] = True
        above_since_ts = ts_to_int(state.get("active_buy_pma_gf_plus_above_since_ts"))
        if above_since_ts is None:
            above_since_ts = current_scan_ts
            state["active_buy_pma_gf_plus_above_since_ts"] = above_since_ts
        above_elapsed = max(0, int((current_scan_ts or above_since_ts) - above_since_ts)) if above_since_ts is not None else 0
        state["active_buy_pma_gf_plus_above_elapsed_seconds"] = above_elapsed
    else:
        state["active_buy_pma_gf_plus_above_since_ts"] = None
        state["active_buy_pma_gf_plus_above_elapsed_seconds"] = None
        above_elapsed = 0

    if not bool(state.get("active_buy_pma_gf_plus_qualified_since_buy")):
        qualification_trigger = None
        hold_trigger_enabled = bool(globals().get("PMA_GF_PLUS_FORCE_BUY_ENABLE_HOLD_SECONDS_TRIGGER", False))
        if offset >= instant_offset:
            qualification_trigger = "instant_offset"
        elif hold_trigger_enabled and offset >= hold_min_offset and above_elapsed >= hold_seconds:
            qualification_trigger = "hold_seconds"
        if qualification_trigger:
            state["active_buy_pma_gf_plus_qualified_since_buy"] = True
            state["active_buy_pma_gf_plus_qualified_ts"] = current_scan_ts
            state["active_buy_pma_gf_plus_qualified_trigger"] = qualification_trigger
            state["active_buy_pma_gf_plus_qualified_offset"] = offset
            state["active_buy_pma_gf_plus_qualified_hold_min_offset"] = hold_min_offset

    # Closed PMA above GF+ is structural proof; for DF0 exits specifically the
    # proof line is GF+ normally, but if DF0 is above GF+ then closed PMA must
    # close above DF0. This is intentionally based on the latest CLOSED PMA, not
    # the live PMA, so a one-scan/live spike cannot arm DF0 selling.
    closed_above_gf_plus = bool(closed_offset is not None and closed_offset > 0 and closed_pma_in_active_buy_window)
    if closed_above_gf_plus:
        if not bool(state.get("active_buy_pma_gf_plus_closed_above_since_buy")):
            state["active_buy_pma_gf_plus_closed_above_since_buy"] = True
            state["active_buy_pma_gf_plus_closed_above_ts"] = current_scan_ts
            state["active_buy_pma_gf_plus_closed_above_pma"] = closed_pma
            state["active_buy_pma_gf_plus_closed_above_gf_plus"] = gf_plus
        # V29: always keep the latest CLOSED PMA proof above GF+ after the real
        # BUY.  The weak-live-PMA 3-minute sell and its reset line use this
        # latest proof, not the first proof from earlier in the lifecycle.
        state["active_buy_pma_gf_plus_latest_closed_above_gf_plus_ts"] = current_scan_ts
        state["active_buy_pma_gf_plus_latest_closed_above_gf_plus_pma"] = closed_pma
        state["active_buy_pma_gf_plus_latest_closed_above_gf_plus_gf_plus"] = gf_plus
        state["active_buy_pma_gf_plus_latest_closed_above_gf_plus_candle_close_ts"] = closed_pma_candle_close_ts

    df0_arm_line_value = gf_plus
    df0_arm_line_kind = "GF+"
    try:
        use_max_arm_line = bool(PMA_GF_PLUS_BELOW_DF0_ARM_ABOVE_MAX_GF_PLUS_DF0)
    except Exception:
        use_max_arm_line = True
    if use_max_arm_line and df0 is not None and gf_plus is not None and df0 > gf_plus:
        df0_arm_line_value = df0
        df0_arm_line_kind = "DF0"
    closed_above_df0_arm_line = bool(
        closed_pma is not None and
        df0_arm_line_value is not None and
        closed_pma > df0_arm_line_value and
        closed_pma_in_active_buy_window
    )
    if closed_above_df0_arm_line and not bool(state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line")):
        state["active_buy_pma_gf_plus_df0_seen_closed_above_arm_line"] = True
        state["active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_ts"] = current_scan_ts
        state["active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_pma"] = closed_pma
        state["active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_value"] = df0_arm_line_value
        state["active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_kind"] = df0_arm_line_kind
        state["active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_gf_plus"] = gf_plus
        state["active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_df0"] = df0
        state["active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_candle_close_ts"] = closed_pma_candle_close_ts

    # Closed PMA below GF+ means the GF+ structure has been lost. From that
    # point, do not extend the highest PMA/GF+ peak for this real BUY.
    closed_below_gf_plus = bool(closed_offset is not None and closed_offset <= 0)
    if closed_below_gf_plus and not bool(state.get("active_buy_pma_gf_plus_closed_below_since_buy")):
        state["active_buy_pma_gf_plus_closed_below_since_buy"] = True
        state["active_buy_pma_gf_plus_closed_below_ts"] = current_scan_ts
        state["active_buy_pma_gf_plus_closed_below_pma"] = closed_pma
        state["active_buy_pma_gf_plus_closed_below_gf_plus"] = gf_plus

    may_extend_peak = bool(offset > 0)
    if bool(PMA_GF_PLUS_PEAK_TRACK_ONLY_WHILE_CLOSED_NOT_BELOW_GF_PLUS):
        may_extend_peak = bool(may_extend_peak and not state.get("active_buy_pma_gf_plus_closed_below_since_buy"))

    previous_peak = _safe_finite_float(state.get("active_buy_pma_gf_plus_peak_offset"))
    if may_extend_peak and (previous_peak is None or offset > previous_peak):
        state["active_buy_pma_gf_plus_peak_offset"] = offset
        state["active_buy_pma_gf_plus_peak_pma"] = pma
        state["active_buy_pma_gf_plus_peak_gf_plus"] = gf_plus
        state["active_buy_pma_gf_plus_peak_scan_ts"] = current_scan_ts
        status["updated_peak"] = True

    status["peak_offset"] = state.get("active_buy_pma_gf_plus_peak_offset")
    status["seen_above"] = bool(state.get("active_buy_pma_gf_plus_seen_above"))
    status["closed_above_gf_plus"] = bool(state.get("active_buy_pma_gf_plus_closed_above_since_buy"))
    status["df0_seen_closed_above_arm_line"] = bool(state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line"))
    status["df0_seen_closed_above_arm_line_ts"] = state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_ts")
    status["df0_seen_closed_above_arm_line_pma"] = state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_pma")
    status["df0_seen_closed_above_arm_line_value"] = state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_value")
    status["df0_seen_closed_above_arm_line_kind"] = state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_kind")
    status["df0_seen_closed_above_arm_line_gf_plus"] = state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_gf_plus")
    status["df0_seen_closed_above_arm_line_df0"] = state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_df0")
    status["df0_seen_closed_above_arm_line_candle_close_ts"] = state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_candle_close_ts")
    status["last_closed_pma_candle_close_ts"] = state.get("active_buy_pma_gf_plus_last_closed_pma_candle_close_ts")
    status["latest_closed_above_gf_plus_pma"] = state.get("active_buy_pma_gf_plus_latest_closed_above_gf_plus_pma")
    status["latest_closed_above_gf_plus_gf_plus"] = state.get("active_buy_pma_gf_plus_latest_closed_above_gf_plus_gf_plus")
    status["latest_closed_above_gf_plus_ts"] = state.get("active_buy_pma_gf_plus_latest_closed_above_gf_plus_ts")
    status["latest_closed_above_gf_plus_candle_close_ts"] = state.get("active_buy_pma_gf_plus_latest_closed_above_gf_plus_candle_close_ts")
    status["closed_below_gf_plus"] = bool(state.get("active_buy_pma_gf_plus_closed_below_since_buy"))
    status["qualified_since_buy"] = bool(state.get("active_buy_pma_gf_plus_qualified_since_buy"))
    status["qualification_trigger"] = state.get("active_buy_pma_gf_plus_qualified_trigger")
    return status



def _active_buy_live_candle_rollover_grace_status(current_forming_candle=None, scan_dt=None):
    """Return whether live-PMA active sell rules should ignore the new live candle.

    Around xx:00/xx:30 the newly-forming 30m candle can make live PMA collapse
    or print zero-like values before enough live volume exists.  These values
    should not trigger PMA/GF+ exits; closed-PMA exits remain available.
    """
    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    live_ts = ts_to_int((current_forming_candle or {}).get("t")) if isinstance(current_forming_candle, dict) else None
    try:
        grace_seconds = max(0, int(float(globals().get("PMA_GF_PLUS_ACTIVE_SELL_LIVE_PMA_ROLLOVER_GRACE_SECONDS", 70))))
    except Exception:
        grace_seconds = 70
    age_seconds = None
    in_grace = False
    if scan_ts is not None and live_ts is not None:
        age_seconds = int(scan_ts - live_ts)
        in_grace = bool(0 <= age_seconds <= grace_seconds)
    return {
        "enabled": grace_seconds > 0,
        "in_grace": bool(in_grace),
        "scan_ts": scan_ts,
        "live_candle_ts": live_ts,
        "live_candle_age_seconds": age_seconds,
        "grace_seconds": grace_seconds,
    }


def _pma_gf_plus_fib_timer_should_defer_live_pma_sell(state, current_price=None, scan_dt=None):
    """Defer live-PMA exits while an actual fib sell-zone is managing profit.

    This does not create a cooldown and does not block closed-PMA exits.  It only
    prevents a live-PMA boundary/DF0/GF-minus/peak-drop sell from overriding a
    valid fib sell-zone timer when price is in the actual fib sell zone, or when
    a previously armed timer has not had a clear exit above the sell-zone line.
    """
    if not isinstance(state, dict):
        return {"defer": False, "reason": "no state"}
    price = _safe_positive_float(current_price)
    if price in (None, 0, 0.0):
        return {"defer": False, "reason": "no current price"}
    fib_bottom = _safe_positive_float(state.get("fib_bottom"))
    fib_top = _safe_positive_float(state.get("fib_top"))
    fib_zone = fib_sell_zone_status(fib_bottom, fib_top, price)
    pending_since_ts = ts_to_int(state.get("sell_zone_pending_since_ts"))
    stored_clear_threshold = _safe_positive_float(state.get("sell_zone_clear_exit_threshold_price"))
    in_actual_zone = bool(fib_zone.get("valid") and fib_zone.get("in_sell_zone"))
    below_fib_floor = bool(fib_zone.get("valid") and (fib_zone.get("below_floor") or fib_zone.get("below_fib_bottom")))
    pending_without_clear_exit = False
    if pending_since_ts is not None:
        if stored_clear_threshold is None:
            pending_without_clear_exit = True
        else:
            pending_without_clear_exit = bool(price <= stored_clear_threshold)
    defer = bool(in_actual_zone or below_fib_floor or pending_without_clear_exit)
    return {
        "defer": defer,
        "reason": "active fib sell-zone timer/profit management" if defer else "fib sell-zone not active",
        "fib_bottom": fib_bottom,
        "fib_top": fib_top,
        "current_price": price,
        "fib_valid": bool(fib_zone.get("valid")),
        "fib_in_sell_zone": bool(fib_zone.get("in_sell_zone")),
        "fib_below_floor": bool(fib_zone.get("below_floor")),
        "fib_below_bottom": bool(fib_zone.get("below_fib_bottom")),
        "fib_ratio": fib_zone.get("ratio"),
        "fib_threshold_price": fib_zone.get("threshold_price"),
        "fib_zone_range_pct": fib_zone.get("zone_range_pct"),
        "sell_zone_pending_since_ts": pending_since_ts,
        "sell_zone_clear_exit_threshold_price": stored_clear_threshold,
        "pending_without_clear_exit": pending_without_clear_exit,
    }

def _pma_gf_plus_live_pma_sell_validity_status(pma, closed_pma, gf_plus=None, df0=None, current_price=None, entry_price=None, live_candle=None, scan_dt=None, live_pma_flat_neutral=False):
    """Guard active PMA/GF+ live-PMA sells from zero/immature/weird PMA prints.

    This does not block closed-PMA exits.  It only suppresses live-PMA sell
    triggers when the live PMA value is obviously immature, zero-like, or
    dramatically disconnected from the latest closed PMA without price weakness
    confirmation.
    """
    enabled = bool(globals().get("PMA_GF_PLUS_ACTIVE_SELL_SUPPRESS_ZERO_OR_WEIRD_LIVE_PMA", True))
    suppress_flat_neutral = bool(globals().get("PMA_GF_PLUS_ACTIVE_SELL_SUPPRESS_FLAT_NEUTRAL_LIVE_PMA", True))
    pma = _safe_finite_float(pma)
    closed_pma = _safe_finite_float(closed_pma)
    current_price = _safe_positive_float(current_price)
    entry_price = _safe_positive_float(entry_price)
    try:
        eps = abs(float(globals().get("PMA_GF_PLUS_ACTIVE_SELL_ZERO_LIVE_PMA_EPS", 1e-9)))
    except Exception:
        eps = 1e-9
    try:
        max_delta = abs(float(globals().get("PMA_GF_PLUS_ACTIVE_SELL_MAX_LIVE_CLOSED_PMA_DELTA_WITHOUT_PRICE_CONFIRM", 3.82)))
    except Exception:
        max_delta = 3.82
    try:
        weakness_pct = float(globals().get("PMA_GF_PLUS_ACTIVE_SELL_PRICE_WEAKNESS_CONFIRM_PCT", -1.00))
    except Exception:
        weakness_pct = -1.00

    entry_pnl_pct = pct_change(entry_price, current_price) if entry_price not in (None, 0, 0.0) and current_price not in (None, 0, 0.0) else None
    price_confirms_weakness = bool(entry_pnl_pct is not None and entry_pnl_pct <= weakness_pct)
    flat_neutral = bool(live_pma_flat_neutral and suppress_flat_neutral)
    zero_like = bool(pma is None or (abs(pma) <= eps and closed_pma is not None and abs(closed_pma) > eps))
    pma_delta = (pma - closed_pma) if pma is not None and closed_pma is not None else None
    weird_delta = bool(pma_delta is not None and abs(pma_delta) > max_delta and not price_confirms_weakness)
    valid = bool((not enabled) or (not flat_neutral and not zero_like and not weird_delta))
    reason = "valid_live_pma"
    if flat_neutral:
        reason = "flat_neutral_live_pma"
    elif zero_like:
        reason = "zero_or_missing_live_pma"
    elif weird_delta:
        reason = "live_pma_far_from_closed_without_price_weakness"
    elif not enabled:
        reason = "validity_guard_disabled"
    return {
        "enabled": enabled,
        "suppress_flat_neutral": suppress_flat_neutral,
        "valid": valid,
        "reason": reason,
        "pma": pma,
        "closed_pma": closed_pma,
        "pma_delta": pma_delta,
        "max_delta_without_price_confirm": max_delta,
        "flat_neutral": flat_neutral,
        "zero_like": zero_like,
        "weird_delta": weird_delta,
        "current_price": current_price,
        "entry_price": entry_price,
        "entry_pnl_pct": entry_pnl_pct,
        "price_weakness_confirm_pct": weakness_pct,
        "price_confirms_weakness": price_confirms_weakness,
    }


def maybe_force_sell_active_buy_on_pma_gf_plus_rules(state, candidate, latest_closed_candle, current_forming_candle, scan_dt, pine_30m_status):
    if not isinstance(state, dict):
        return None
    ensure_active_buy_state_defaults(state)
    stage = normalize_strategy_stage_value(state.get("stage"))
    if stage not in {"buy", "pumped"}:
        reset_active_buy_pma_gf_plus_tracking(state)
        return None

    tracking_status = update_active_buy_pma_gf_plus_tracking(state, pine_30m_status, scan_dt)
    pma = _safe_finite_float(tracking_status.get("pma"))
    closed_pma = _safe_finite_float(tracking_status.get("closed_pma"))
    gf_plus = _safe_finite_float(tracking_status.get("gf_plus"))
    df0 = _safe_finite_float(tracking_status.get("df0"))
    offset = _safe_finite_float(tracking_status.get("offset"))
    sell_environment = pma_gf_plus_active_sell_environment(state, pine_30m_status, gf_plus=gf_plus, df0=df0)
    df0_sell_line = _safe_finite_float(sell_environment.get("df0_sell_line"))
    df0_sell_line_label = str(sell_environment.get("df0_sell_line_label") or "DF0")
    gf_minus_base_line = _safe_finite_float(sell_environment.get("gf_minus_base_line"))
    gf_minus_base_line_label = str(sell_environment.get("gf_minus_base_line_label") or "GF+")
    if pma is None or gf_plus is None or offset is None:
        return None

    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    live_reference_candle = current_forming_candle if isinstance(current_forming_candle, dict) else latest_closed_candle
    live_current_price = None
    if isinstance(candidate, dict):
        live_current_price = resolve_current_market_price(candidate.get("latest_price"), live_reference_candle, prefer_candle=False, context=candidate)
    if live_current_price in (None, 0, 0.0):
        live_current_price = _safe_positive_float((live_reference_candle or {}).get("c"))

    entry_price_for_pma_validity = active_buy_live_entry_price(state)
    live_pma_validity_status = _pma_gf_plus_live_pma_sell_validity_status(
        pma,
        closed_pma,
        gf_plus=gf_plus,
        df0=df0,
        current_price=live_current_price,
        entry_price=entry_price_for_pma_validity,
        live_candle=current_forming_candle,
        scan_dt=scan_dt,
        live_pma_flat_neutral=bool(pine_30m_status.get("pma_flat_neutral")),
    )
    live_pma_sell_suppressed_by_invalid = bool(not live_pma_validity_status.get("valid"))

    live_pma_rollover_grace = _active_buy_live_candle_rollover_grace_status(
        current_forming_candle,
        scan_dt=scan_dt,
    )
    live_pma_sell_suppressed_by_rollover = bool(live_pma_rollover_grace.get("in_grace"))
    fib_live_pma_defer_status = _pma_gf_plus_fib_timer_should_defer_live_pma_sell(
        state,
        current_price=live_current_price,
        scan_dt=scan_dt,
    )
    live_pma_sell_suppressed_by_fib = bool(fib_live_pma_defer_status.get("defer"))
    live_pma_sell_suppressed = bool(live_pma_sell_suppressed_by_rollover or live_pma_sell_suppressed_by_fib or live_pma_sell_suppressed_by_invalid)

    def build_pma_rule_sell(reason, flags, trigger):
        sell_candle = build_live_price_sell_candle(live_reference_candle, scan_dt=scan_dt, live_price=live_current_price)
        if not isinstance(sell_candle, dict):
            return None
        entry_price = active_buy_live_entry_price(state)
        entry_pnl_pct = pct_change(entry_price, live_current_price) if entry_price not in (None, 0, 0.0) and live_current_price not in (None, 0, 0.0) else None
        sell_event = finalize_sell_transition(
            state,
            sell_candle,
            scan_dt,
            reason,
            {
                "pine_30m_pma": pma,
                "pine_30m_closed_pma": closed_pma,
                "pine_30m_GF_pos": gf_plus,
                "pine_30m_DF0": df0,
                "pine_30m_effective_DF0_sell_line": df0_sell_line,
                "pine_30m_pma_above_gf_plus_offset": offset,
                "pma_gf_plus_sell_environment": sell_environment,
                "entry_price": entry_price,
                "entry_pnl_pct": entry_pnl_pct,
                "current_price": live_current_price,
                "buy_style": infer_buy_style(state),
                "live_force_sell": True,
                "pma_gf_plus_live_pma_sell_suppressed": live_pma_sell_suppressed,
                "pma_gf_plus_live_pma_sell_suppressed_by_rollover": live_pma_sell_suppressed_by_rollover,
                "pma_gf_plus_live_pma_rollover_grace": live_pma_rollover_grace,
                "pma_gf_plus_live_pma_sell_suppressed_by_fib": live_pma_sell_suppressed_by_fib,
                "pma_gf_plus_live_pma_sell_suppressed_by_invalid": live_pma_sell_suppressed_by_invalid,
                "pma_gf_plus_live_pma_validity_status": live_pma_validity_status,
                "pma_gf_plus_fib_live_pma_defer_status": fib_live_pma_defer_status,
                **(flags or {}),
            },
        )
        return {
            "event": sell_event,
            "trigger": trigger,
            "pma": pma,
            "closed_pma": closed_pma,
            "gf_plus": gf_plus,
            "df0": df0,
            "offset": offset,
            "current_price": live_current_price,
            "entry_pnl_pct": entry_pnl_pct,
        }

    # V28: after the real BUY has a CLOSED PMA above GF+, do not let the live
    # PMA sit below GF+ for more than 3 minutes without exiting.  This is a
    # GF+ structure-loss timer, separate from the deeper DF0 collapse exit.
    if bool(globals().get("ENABLE_PMA_GF_PLUS_CLOSED_ABOVE_GF_PLUS_LIVE_LOSS_FORCE_SELL", True)) and gf_plus is not None:
        try:
            closed_gf_loss_seconds = max(1, int(float(globals().get("PMA_GF_PLUS_CLOSED_ABOVE_GF_PLUS_LIVE_LOSS_FORCE_SELL_SECONDS", 3 * 60))))
        except Exception:
            closed_gf_loss_seconds = 3 * 60
        try:
            closed_gf_loss_margin = float(globals().get("PMA_GF_PLUS_CLOSED_ABOVE_GF_PLUS_LIVE_LOSS_MARGIN", 0.0))
        except Exception:
            closed_gf_loss_margin = 0.0
        closed_above_gf_since_buy = bool(state.get("active_buy_pma_gf_plus_closed_above_since_buy"))
        latest_closed_above_gf_pma = _safe_finite_float(state.get("active_buy_pma_gf_plus_latest_closed_above_gf_plus_pma"))
        latest_closed_above_gf_line = _safe_finite_float(state.get("active_buy_pma_gf_plus_latest_closed_above_gf_plus_gf_plus")) or gf_plus
        latest_closed_above_gf_candle_ts = ts_to_int(state.get("active_buy_pma_gf_plus_latest_closed_above_gf_plus_candle_close_ts"))
        closed_above_gf_pma = latest_closed_above_gf_pma if latest_closed_above_gf_pma is not None else state.get("active_buy_pma_gf_plus_closed_above_pma")
        closed_above_gf_line = latest_closed_above_gf_line if latest_closed_above_gf_line is not None else (state.get("active_buy_pma_gf_plus_closed_above_gf_plus") or gf_plus)
        # V31: this sell is not about being below GF+ itself.  It is about live
        # PMA failing to reclaim/hold the latest CLOSED PMA proof above GF+.
        # Example: if the latest closed PMA proof is 5.30, sell only if mature
        # live PMA stays below 5.30 for the configured 3 minutes.
        live_loss_line = latest_closed_above_gf_pma if latest_closed_above_gf_pma is not None else closed_above_gf_pma
        if live_loss_line is None:
            live_loss_line = gf_plus
        live_loss_line = live_loss_line - closed_gf_loss_margin
        reclaim_reset_line = latest_closed_above_gf_pma if (
            bool(globals().get("PMA_GF_PLUS_CLOSED_ABOVE_GF_PLUS_LIVE_LOSS_RESET_ON_LATEST_CLOSED_PMA_RECLAIM", True))
            and latest_closed_above_gf_pma is not None
        ) else live_loss_line
        try:
            min_live_pma_age_seconds = max(0, int(float(globals().get("PMA_GF_PLUS_CLOSED_ABOVE_GF_PLUS_LIVE_LOSS_MIN_LIVE_PMA_AGE_SECONDS", 5 * 60))))
        except Exception:
            min_live_pma_age_seconds = 5 * 60
        live_pma_age_seconds = ts_to_int((live_pma_rollover_grace or {}).get("live_candle_age_seconds"))
        live_pma_age_ok_for_loss = bool(live_pma_age_seconds is not None and live_pma_age_seconds >= min_live_pma_age_seconds)
        active_force_buy_trigger_for_live_loss = (
            state.get("pma_gf_plus_force_buy_trigger") or
            state.get("active_buy_pma_gf_plus_entry_trigger") or
            state.get("active_buy_pma_gf_plus_qualified_trigger")
        )
        direct_force_buy_live_loss_skip = bool(
            pma_gf_plus_force_buy_trigger_is_direct(active_force_buy_trigger_for_live_loss)
        )
        state["active_buy_pma_gf_plus_closed_above_live_loss_entry_trigger"] = active_force_buy_trigger_for_live_loss
        state["active_buy_pma_gf_plus_closed_above_live_loss_skipped_for_direct_force_buy"] = bool(direct_force_buy_live_loss_skip)
        # Timer starts when latest CLOSED PMA has proved GF+ after the real BUY
        # and mature live PMA stays below that latest closed-proof PMA.  It resets
        # only when live PMA reclaims the latest closed-proof PMA.
        live_gf_loss_active = bool(
            closed_above_gf_since_buy and
            pma is not None and
            pma < live_loss_line and
            current_scan_ts is not None and
            not live_pma_sell_suppressed and
            live_pma_age_ok_for_loss and
            not direct_force_buy_live_loss_skip
        )
        live_gf_loss_reclaimed = bool(pma is not None and reclaim_reset_line is not None and pma >= reclaim_reset_line)
        state["active_buy_pma_gf_plus_closed_above_live_below_gf_loss_line"] = live_loss_line
        state["active_buy_pma_gf_plus_closed_above_live_below_gf_min_live_pma_age_seconds"] = min_live_pma_age_seconds
        state["active_buy_pma_gf_plus_closed_above_live_below_gf_live_pma_age_seconds"] = live_pma_age_seconds
        state["active_buy_pma_gf_plus_closed_above_live_below_gf_live_pma_age_ok"] = live_pma_age_ok_for_loss
        if pma is not None and live_loss_line is not None and pma < live_loss_line and not live_pma_age_ok_for_loss:
            state["active_buy_pma_gf_plus_closed_above_live_below_gf_waiting_for_live_pma_age"] = True

        if live_gf_loss_active:
            live_gf_loss_since_ts = ts_to_int(state.get("active_buy_pma_gf_plus_closed_above_live_below_gf_since_ts"))
            if live_gf_loss_since_ts is None:
                live_gf_loss_since_ts = current_scan_ts
                state["active_buy_pma_gf_plus_closed_above_live_below_gf_since_ts"] = live_gf_loss_since_ts
            live_gf_loss_elapsed_seconds = max(0, int(current_scan_ts - live_gf_loss_since_ts))
            state["active_buy_pma_gf_plus_closed_above_live_below_gf_elapsed_seconds"] = live_gf_loss_elapsed_seconds
            state["active_buy_pma_gf_plus_closed_above_live_below_gf_line"] = live_loss_line
            state["active_buy_pma_gf_plus_closed_above_live_below_gf_reclaim_reset_line"] = reclaim_reset_line
            state["active_buy_pma_gf_plus_closed_above_live_below_gf_latest_closed_pma"] = latest_closed_above_gf_pma
            state["active_buy_pma_gf_plus_closed_above_live_below_gf_latest_closed_candle_close_ts"] = latest_closed_above_gf_candle_ts
            state["active_buy_pma_gf_plus_closed_above_live_below_gf_margin"] = closed_gf_loss_margin
            if live_gf_loss_elapsed_seconds >= closed_gf_loss_seconds:
                reason = (
                    f"PMA/GF+ closed-above-GF+ live loss force sell: after latest CLOSED PMA proof above GF+ "
                    f"(closed PMA {closed_above_gf_pma if closed_above_gf_pma is not None else '-'} > GF+ "
                    f"{closed_above_gf_line if closed_above_gf_line is not None else gf_plus}), mature live PMA stayed below "
                    f"latest closed-proof PMA for {format_duration_compact(live_gf_loss_elapsed_seconds)} "
                    f"(PMA {pma:.6f} < latest closed-proof line {live_loss_line:.6f}; "
                    f"live age {format_duration_compact(live_pma_age_seconds or 0)} >= {format_duration_compact(min_live_pma_age_seconds)}; "
                    f"required {format_duration_compact(closed_gf_loss_seconds)})"
                )
                return build_pma_rule_sell(
                    reason,
                    {
                        "pma_gf_plus_closed_above_gf_plus_live_loss_force_sell": True,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_seconds_required": closed_gf_loss_seconds,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_elapsed_seconds": live_gf_loss_elapsed_seconds,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_since_ts": live_gf_loss_since_ts,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_margin": closed_gf_loss_margin,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_line": live_loss_line,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_reclaim_reset_line": reclaim_reset_line,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_min_live_pma_age_seconds": min_live_pma_age_seconds,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_live_pma_age_seconds": live_pma_age_seconds,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_live_pma_age_ok": live_pma_age_ok_for_loss,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_latest_closed_pma": latest_closed_above_gf_pma,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_latest_closed_candle_close_ts": latest_closed_above_gf_candle_ts,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_pma": pma,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_gf_plus": gf_plus,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_closed_pma": closed_above_gf_pma,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_closed_gf_plus": closed_above_gf_line,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_live_pma_sell_suppressed": live_pma_sell_suppressed,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_validity_status": live_pma_validity_status,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_fib_defer_status": fib_live_pma_defer_status,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_entry_trigger": active_force_buy_trigger_for_live_loss,
                        "pma_gf_plus_closed_above_gf_plus_live_loss_skipped_for_direct_force_buy": bool(direct_force_buy_live_loss_skip),
                    },
                    "pma_gf_plus_closed_above_gf_plus_live_loss",
                )
        else:
            # Reset the 3-minute weak-PMA timer only on a true reclaim of the
            # latest closed-PMA proof level, or when there is no valid PMA/proof
            # to evaluate.  Do not reset merely because live PMA is between GF+
            # and the latest closed-proof PMA.
            if live_gf_loss_reclaimed or pma is None or reclaim_reset_line is None:
                state["active_buy_pma_gf_plus_closed_above_live_below_gf_since_ts"] = None
                state["active_buy_pma_gf_plus_closed_above_live_below_gf_elapsed_seconds"] = None
                state["active_buy_pma_gf_plus_closed_above_live_below_gf_reclaimed"] = bool(live_gf_loss_reclaimed)
            elif live_pma_sell_suppressed:
                # Do not sell while PMA is suppressed/invalid/fib-managed, but also
                # do not erase the elapsed timer.  The timer resets only on a true
                # reclaim of the latest closed-proof PMA.
                state["active_buy_pma_gf_plus_closed_above_live_below_gf_suppressed_without_reset"] = True
                state["active_buy_pma_gf_plus_closed_above_live_below_gf_reclaim_reset_line"] = reclaim_reset_line
            else:
                state["active_buy_pma_gf_plus_closed_above_live_below_gf_reclaim_waiting"] = True
                state["active_buy_pma_gf_plus_closed_above_live_below_gf_reclaim_reset_line"] = reclaim_reset_line

    # V56: DF0 loss for PMA/GF+ force-buy lifecycles is no longer an
    # immediate safety sell. It has two elapsed requirements:
    #   1) the real BUY must be mature for PMA_GF_PLUS_BELOW_DF0_MIN_ELAPSED_SECONDS
    #   2) PMA must remain below DF0 for PMA_GF_PLUS_BELOW_DF0_CONFIRM_SECONDS
    # Fib sell-zone management has priority: if the actual fib sell-zone timer
    # is active/armed, DF0 may keep its elapsed state but cannot emit a sell.
    if bool(ENABLE_PMA_GF_PLUS_BELOW_DF0_FORCE_SELL) and df0_sell_line is not None:
        first_buy_ts = active_buy_first_buy_ts(state)
        try:
            min_elapsed_seconds = max(0, int(float(PMA_GF_PLUS_BELOW_DF0_MIN_ELAPSED_SECONDS)))
        except Exception:
            min_elapsed_seconds = 5 * 60
        try:
            below_df0_required_seconds = max(1, int(float(globals().get("PMA_GF_PLUS_BELOW_DF0_CONFIRM_SECONDS", 3 * 60))))
        except Exception:
            below_df0_required_seconds = 3 * 60

        elapsed_from_buy_seconds = None
        if first_buy_ts is not None and current_scan_ts is not None:
            elapsed_from_buy_seconds = max(0, int(current_scan_ts) - int(first_buy_ts))

        df0_arm_ready = True
        if bool(PMA_GF_PLUS_BELOW_DF0_REQUIRE_CLOSED_PMA_ABOVE_GF_PLUS):
            df0_arm_ready = bool(state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line"))

        if elapsed_from_buy_seconds is not None:
            state["active_buy_pma_gf_plus_below_df0_elapsed_from_buy_seconds"] = elapsed_from_buy_seconds
            state["active_buy_pma_gf_plus_below_df0_min_elapsed_seconds"] = min_elapsed_seconds
        if elapsed_from_buy_seconds is not None and elapsed_from_buy_seconds < min_elapsed_seconds:
            state["active_buy_pma_gf_plus_below_df0_wait_seconds"] = min_elapsed_seconds - elapsed_from_buy_seconds
            state["active_buy_pma_gf_plus_below_df0_maturity_ready"] = False
            # Do not let a pre-maturity below-DF0 sample count toward the
            # required below-DF0 confirmation window.
            state["active_buy_pma_gf_plus_below_df0_since_ts"] = None
            state["active_buy_pma_gf_plus_below_df0_elapsed_seconds"] = None
        elif df0_arm_ready:
            state["active_buy_pma_gf_plus_below_df0_maturity_ready"] = True
            live_below_df0_raw = bool(PMA_GF_PLUS_BELOW_DF0_USE_LIVE_PMA and pma < df0_sell_line)
            # Count below-DF0 elapsed time while fib management is active, but
            # do not allow DF0 to sell during that fib-priority window. Invalid
            # PMA and live-candle rollover grace still block live-PMA DF0 timing.
            live_below_df0_for_timer = bool(
                live_below_df0_raw and
                not live_pma_sell_suppressed_by_invalid and
                not live_pma_sell_suppressed_by_rollover
            )
            live_below_df0 = bool(live_below_df0_for_timer and not live_pma_sell_suppressed_by_fib)
            if live_below_df0_raw and live_pma_sell_suppressed:
                state["active_buy_pma_gf_plus_live_df0_blocked_by_rollover_or_fib"] = True
                state["active_buy_pma_gf_plus_live_df0_blocked_scan_ts"] = current_scan_ts
                state["active_buy_pma_gf_plus_live_df0_blocked_pma"] = pma
                state["active_buy_pma_gf_plus_live_df0_blocked_df0"] = df0
            require_new_closed_after_buy = bool(globals().get("PMA_GF_PLUS_BELOW_DF0_REQUIRE_NEW_CLOSED_CANDLE_AFTER_BUY", True))
            closed_pma_candle_close_ts = ts_to_int(tracking_status.get("closed_pma_candle_close_ts"))
            first_buy_ts_int = ts_to_int(first_buy_ts)
            closed_df0_has_new_candle_after_buy = True
            if require_new_closed_after_buy:
                closed_df0_has_new_candle_after_buy = bool(
                    closed_pma_candle_close_ts is not None and
                    first_buy_ts_int is not None and
                    int(closed_pma_candle_close_ts) > int(first_buy_ts_int)
                )
            raw_closed_below_df0 = bool(PMA_GF_PLUS_BELOW_DF0_USE_CLOSED_PMA and closed_pma is not None and closed_pma < df0_sell_line)
            closed_below_df0 = bool(raw_closed_below_df0 and closed_df0_has_new_candle_after_buy)
            if raw_closed_below_df0 and not closed_df0_has_new_candle_after_buy:
                state["active_buy_pma_gf_plus_closed_df0_blocked_waiting_new_closed_candle"] = True
                state["active_buy_pma_gf_plus_closed_df0_blocked_candle_close_ts"] = closed_pma_candle_close_ts
                state["active_buy_pma_gf_plus_closed_df0_blocked_first_buy_ts"] = first_buy_ts_int

            below_df0_active = bool(live_below_df0_for_timer or closed_below_df0)
            df0_fib_priority_defer = bool(fib_live_pma_defer_status.get("defer"))
            if below_df0_active:
                trigger_mode = "live_below_df0" if live_below_df0_for_timer else "closed_below_df0"
                value = pma if live_below_df0_for_timer else closed_pma
                below_df0_since_ts = ts_to_int(state.get("active_buy_pma_gf_plus_below_df0_since_ts"))
                if below_df0_since_ts is None:
                    below_df0_since_ts = current_scan_ts
                    state["active_buy_pma_gf_plus_below_df0_since_ts"] = below_df0_since_ts
                below_df0_elapsed_seconds = max(0, int(current_scan_ts) - int(below_df0_since_ts)) if current_scan_ts is not None and below_df0_since_ts is not None else 0
                state["active_buy_pma_gf_plus_below_df0_elapsed_seconds"] = below_df0_elapsed_seconds
                state["active_buy_pma_gf_plus_below_df0_required_seconds"] = below_df0_required_seconds
                state["active_buy_pma_gf_plus_below_df0_trigger_mode"] = trigger_mode
                state["active_buy_pma_gf_plus_below_df0_raw_closed_below_df0"] = raw_closed_below_df0
                state["active_buy_pma_gf_plus_below_df0_raw_live_below_df0"] = live_below_df0_raw
                state["active_buy_pma_gf_plus_below_df0_live_below_df0_for_timer"] = live_below_df0_for_timer
                state["active_buy_pma_gf_plus_below_df0_live_pma_sell_suppressed"] = live_pma_sell_suppressed
                state["active_buy_pma_gf_plus_below_df0_fib_priority_defer"] = df0_fib_priority_defer
                state["active_buy_pma_gf_plus_below_df0_fib_defer_status"] = fib_live_pma_defer_status

                if below_df0_elapsed_seconds < below_df0_required_seconds:
                    state["active_buy_pma_gf_plus_below_df0_wait_below_seconds"] = below_df0_required_seconds - below_df0_elapsed_seconds
                    state["active_buy_pma_gf_plus_below_df0_elapsed_confirmed"] = False
                elif df0_fib_priority_defer:
                    # Fib sell-zone must remain the highest-priority exit.  A mature
                    # DF0 timer can be recorded for debug, but it must not preempt a
                    # pending/armed fib sell-zone decision.
                    state["active_buy_pma_gf_plus_below_df0_elapsed_confirmed"] = True
                    state["active_buy_pma_gf_plus_below_df0_ready_but_deferred_to_fib"] = True
                    state["active_buy_pma_gf_plus_below_df0_deferred_to_fib_ts"] = current_scan_ts
                else:
                    state["active_buy_pma_gf_plus_below_df0_elapsed_confirmed"] = True
                    arm_pma = state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_pma")
                    arm_value = state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_value")
                    arm_kind = state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_kind") or "GF+/DF0 proof line"
                    arm_gf_plus = state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_gf_plus")
                    arm_df0 = state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_df0")
                    arm_seen = bool(state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line"))
                    if arm_seen and arm_pma is not None and arm_value is not None:
                        reason = (
                            f"PMA/GF+ DF0 elapsed force sell: after {format_duration_compact(elapsed_from_buy_seconds or 0)} from real BUY, "
                            f"PMA had CLOSED above {arm_kind} during active BUY "
                            f"(closed PMA {arm_pma:.6f} > {arm_kind} {arm_value:.6f}; GF+ {arm_gf_plus if arm_gf_plus is not None else '-'}, DF0 {arm_df0 if arm_df0 is not None else '-'}) "
                            f"and then stayed below DF0 for {below_df0_elapsed_seconds}s/{below_df0_required_seconds}s "
                            f"({trigger_mode}; PMA {value:.6f} < {df0_sell_line_label} {df0_sell_line:.6f})"
                        )
                    else:
                        reason = (
                            f"PMA/GF+ DF0 elapsed force sell: after {format_duration_compact(elapsed_from_buy_seconds or 0)} from real force BUY, "
                            f"PMA stayed below DF0 for {below_df0_elapsed_seconds}s/{below_df0_required_seconds}s "
                            f"({trigger_mode}; PMA {value:.6f} < {df0_sell_line_label} {df0_sell_line:.6f})"
                        )
                    return build_pma_rule_sell(
                        reason,
                        {
                            "pma_gf_plus_below_df0_force_sell": True,
                            "pma_gf_plus_below_df0_elapsed_force_sell": True,
                            "pma_gf_plus_below_df0_trigger_mode": trigger_mode,
                            "pma_gf_plus_below_df0_min_elapsed_seconds": min_elapsed_seconds,
                            "pma_gf_plus_below_df0_elapsed_from_buy_seconds": elapsed_from_buy_seconds,
                            "pma_gf_plus_below_df0_since_real_force_buy": True,
                            "pma_gf_plus_below_df0_since_ts": below_df0_since_ts,
                            "pma_gf_plus_below_df0_elapsed_seconds": below_df0_elapsed_seconds,
                            "pma_gf_plus_below_df0_required_seconds": below_df0_required_seconds,
                            "pma_gf_plus_below_df0_seen_closed_above_arm_line": arm_seen,
                            "pma_gf_plus_below_df0_seen_closed_above_arm_line_pma": arm_pma,
                            "pma_gf_plus_below_df0_seen_closed_above_arm_line_value": arm_value,
                            "pma_gf_plus_below_df0_seen_closed_above_arm_line_kind": arm_kind,
                            "pma_gf_plus_below_df0_seen_closed_above_arm_line_gf_plus": arm_gf_plus,
                            "pma_gf_plus_below_df0_seen_closed_above_arm_line_df0": arm_df0,
                            "pma_gf_plus_below_df0_effective_df0_sell_line": df0_sell_line,
                            "pma_gf_plus_below_df0_effective_df0_sell_line_label": df0_sell_line_label,
                            "pma_gf_plus_below_df0_sell_environment": sell_environment,
                            "pma_gf_plus_below_df0_seen_closed_above_arm_line_candle_close_ts": state.get("active_buy_pma_gf_plus_df0_seen_closed_above_arm_line_candle_close_ts"),
                            "pma_gf_plus_below_df0_require_new_closed_candle_after_buy": require_new_closed_after_buy,
                            "pma_gf_plus_below_df0_closed_pma_candle_close_ts": closed_pma_candle_close_ts,
                            "pma_gf_plus_below_df0_first_buy_ts": first_buy_ts_int,
                            "pma_gf_plus_below_df0_closed_has_new_candle_after_buy": closed_df0_has_new_candle_after_buy,
                            "pma_gf_plus_below_df0_raw_closed_below_df0": raw_closed_below_df0,
                            "pma_gf_plus_below_df0_raw_live_below_df0": live_below_df0_raw,
                            "pma_gf_plus_below_df0_live_below_df0_for_timer": live_below_df0_for_timer,
                            "pma_gf_plus_below_df0_live_pma_sell_suppressed": live_pma_sell_suppressed,
                            "pma_gf_plus_below_df0_live_pma_rollover_grace": live_pma_rollover_grace,
                            "pma_gf_plus_below_df0_live_pma_validity_status": live_pma_validity_status,
                            "pma_gf_plus_below_df0_fib_defer_status": fib_live_pma_defer_status,
                            "pma_gf_plus_below_df0_fib_priority_defer": df0_fib_priority_defer,
                        },
                        "pma_gf_plus_below_df0",
                    )
            else:
                state["active_buy_pma_gf_plus_below_df0_since_ts"] = None
                state["active_buy_pma_gf_plus_below_df0_elapsed_seconds"] = None
                state["active_buy_pma_gf_plus_below_df0_elapsed_confirmed"] = False
                state["active_buy_pma_gf_plus_below_df0_ready_but_deferred_to_fib"] = False
                state["active_buy_pma_gf_plus_below_df0_trigger_mode"] = None
        else:
            state["active_buy_pma_gf_plus_below_df0_arm_ready"] = False
            state["active_buy_pma_gf_plus_below_df0_since_ts"] = None
            state["active_buy_pma_gf_plus_below_df0_elapsed_seconds"] = None

    # V11.6 PMA-only elapsed force sell: if live PMA falls below GF+ minus
    # the configured margin and remains there for more than 2 minutes, exit the
    # PMA/GF+ lifecycle. This replaced the v11.5 midpoint(Predict Upper, GF+)
    # elapsed sell.
    if bool(globals().get("ENABLE_PMA_GF_PLUS_GF_MINUS_ELAPSED_FORCE_SELL", True)):
        try:
            gf_minus_required_seconds = max(1, int(float(globals().get("PMA_GF_PLUS_GF_MINUS_ELAPSED_FORCE_SELL_SECONDS", 2 * 60))))
        except Exception:
            gf_minus_required_seconds = 2 * 60
        try:
            gf_minus_margin = float(globals().get("PMA_GF_PLUS_GF_MINUS_ELAPSED_FORCE_SELL_MARGIN", 1.40))
        except Exception:
            gf_minus_margin = 1.40
        gf_minus_line = (gf_minus_base_line - gf_minus_margin) if gf_minus_base_line is not None else None
        gf_minus_since_ts = None
        gf_minus_elapsed_seconds = None
        if gf_minus_line is not None and pma < gf_minus_line and current_scan_ts is not None and not live_pma_sell_suppressed:
            gf_minus_since_ts = ts_to_int(state.get("active_buy_pma_gf_plus_gf_minus_below_since_ts"))
            if gf_minus_since_ts is None:
                gf_minus_since_ts = current_scan_ts
                state["active_buy_pma_gf_plus_gf_minus_below_since_ts"] = gf_minus_since_ts
            gf_minus_elapsed_seconds = max(0, int(current_scan_ts - gf_minus_since_ts))
            state["active_buy_pma_gf_plus_gf_minus_below_elapsed_seconds"] = gf_minus_elapsed_seconds
            state["active_buy_pma_gf_plus_gf_minus_line"] = gf_minus_line
            state["active_buy_pma_gf_plus_gf_minus_margin"] = gf_minus_margin
            state["active_buy_pma_gf_plus_gf_minus_gf_plus"] = gf_plus
            state["active_buy_pma_gf_plus_gf_minus_base_line"] = gf_minus_base_line
            state["active_buy_pma_gf_plus_gf_minus_base_line_label"] = gf_minus_base_line_label
            if gf_minus_elapsed_seconds >= gf_minus_required_seconds:
                reason = (
                    f"PMA/GF+ {gf_minus_base_line_label}-minus elapsed force sell: live PMA stayed below {gf_minus_base_line_label} - "
                    f"{gf_minus_margin:.3f} for {gf_minus_elapsed_seconds}s/{gf_minus_required_seconds}s "
                    f"(PMA {pma:.6f} < line {gf_minus_line:.6f}; {gf_minus_base_line_label} {gf_minus_base_line:.6f})"
                )
                return build_pma_rule_sell(
                    reason,
                    {
                        "pma_gf_plus_gf_minus_elapsed_force_sell": True,
                        "pma_gf_plus_gf_minus_elapsed_seconds": gf_minus_elapsed_seconds,
                        "pma_gf_plus_gf_minus_required_seconds": gf_minus_required_seconds,
                        "pma_gf_plus_gf_minus_below_since_ts": gf_minus_since_ts,
                        "pma_gf_plus_gf_minus_line": gf_minus_line,
                        "pma_gf_plus_gf_minus_margin": gf_minus_margin,
                        "pma_gf_plus_gf_minus_gf_plus": gf_plus,
                        "pma_gf_plus_gf_minus_base_line": gf_minus_base_line,
                        "pma_gf_plus_gf_minus_base_line_label": gf_minus_base_line_label,
                        "pma_gf_plus_gf_minus_sell_environment": sell_environment,
                    },
                    "pma_gf_plus_gf_minus_elapsed",
                )
        else:
            state["active_buy_pma_gf_plus_gf_minus_below_since_ts"] = None
            state["active_buy_pma_gf_plus_gf_minus_below_elapsed_seconds"] = None
            state["active_buy_pma_gf_plus_gf_minus_line"] = gf_minus_line
            state["active_buy_pma_gf_plus_gf_minus_margin"] = globals().get("PMA_GF_PLUS_GF_MINUS_ELAPSED_FORCE_SELL_MARGIN", 1.40)
            state["active_buy_pma_gf_plus_gf_minus_gf_plus"] = gf_plus

    peak_offset = _safe_finite_float(state.get("active_buy_pma_gf_plus_peak_offset"))
    peak_pma = _safe_finite_float(state.get("active_buy_pma_gf_plus_peak_pma"))
    peak_gf_plus = _safe_finite_float(state.get("active_buy_pma_gf_plus_peak_gf_plus"))
    peak_scan_ts = ts_to_int(state.get("active_buy_pma_gf_plus_peak_scan_ts"))
    try:
        arm_offset = float(PMA_GF_PLUS_PEAK_DROP_ARM_OFFSET)
    except Exception:
        arm_offset = 6.47
    try:
        min_drop = float(PMA_GF_PLUS_PEAK_DROP_MIN_DROP)
    except Exception:
        min_drop = 3.82
    try:
        exit_offset = float(PMA_GF_PLUS_PEAK_DROP_EXIT_OFFSET)
    except Exception:
        exit_offset = 2.0

    if bool(ENABLE_PMA_GF_PLUS_PEAK_DROP_FORCE_SELL) and peak_offset is not None:
        drop_from_peak = peak_offset - offset
        peak_drop_sell = bool(
            peak_offset >= arm_offset and
            drop_from_peak >= min_drop and
            offset <= exit_offset and
            (peak_pma is None or pma < peak_pma)
        )
        if peak_drop_sell:
            reason = (
                "PMA/GF+ peak-drop force sell: exact PMA-GF+ offset peaked at "
                f"+{peak_offset:.6f} while closed PMA had not lost GF+, armed above +{arm_offset:.3f}, "
                f"then dropped {drop_from_peak:.6f} to +{offset:.6f} (<= +{exit_offset:.3f})"
            )
            result = build_pma_rule_sell(
                reason,
                {
                    "pma_gf_plus_peak_drop_force_sell": True,
                    "pine_30m_pma_gf_plus_peak_offset": peak_offset,
                    "pine_30m_pma_gf_plus_peak_pma": peak_pma,
                    "pine_30m_pma_gf_plus_peak_gf_plus": peak_gf_plus,
                    "pine_30m_pma_gf_plus_peak_scan_ts": peak_scan_ts,
                    "pine_30m_pma_gf_plus_drop_from_peak": drop_from_peak,
                    "pine_30m_pma_gf_plus_arm_offset": arm_offset,
                    "pine_30m_pma_gf_plus_exit_offset": exit_offset,
                    "pma_gf_plus_closed_below_since_buy": bool(state.get("active_buy_pma_gf_plus_closed_below_since_buy")),
                },
                "pma_gf_plus_peak_drop",
            )
            if isinstance(result, dict):
                result["peak_offset"] = peak_offset
                result["drop_from_peak"] = drop_from_peak
            return result

    # V4 corrected 360s rule: this is NOT a GF+ reclaim rule. It only applies
    # to normal/non-GF+ buys. Track the highest CLOSED PMA since the latest
    # CLOSED PMA above Predict Upper. If live PMA stays below that closed peak
    # and the trade never qualifies as a GF+ buy (+2 offset or 20s above GF+ with the configured hold offset),
    # force sell after the configured timer.
    if not bool(ENABLE_NON_GF_PLUS_FAILED_UPPER_PREDICT_FORCE_SELL):
        return None

    if bool(state.get("buy_from_pma_gf_plus_force")) or bool(state.get("active_buy_pma_gf_plus_qualified_since_buy")):
        reset_active_buy_non_gf_upper_predict_tracking(state)
        return None

    predict_upper = _safe_finite_float((pine_30m_status or {}).get("predict_upper") if isinstance(pine_30m_status, dict) else None)
    if predict_upper is None:
        predict_upper = _safe_finite_float((pine_30m_status or {}).get("pma_required_line") if isinstance(pine_30m_status, dict) else None)
    if predict_upper is None or closed_pma is None:
        return None

    # Closed PMA above Predict Upper starts/refreshes the normal upper-predict
    # segment and updates the highest closed-PMA peak inside that segment.
    if closed_pma > predict_upper:
        previous_peak = _safe_finite_float(state.get("active_buy_non_gf_upper_predict_closed_peak_pma"))
        if previous_peak is None or closed_pma >= previous_peak:
            state["active_buy_non_gf_upper_predict_closed_peak_pma"] = closed_pma
            state["active_buy_non_gf_upper_predict_closed_peak_ts"] = current_scan_ts
            state["active_buy_non_gf_upper_predict_closed_peak_predict_upper"] = predict_upper
            state["active_buy_non_gf_upper_predict_closed_peak_gf_plus"] = gf_plus
        state["active_buy_non_gf_upper_predict_latest_closed_above_ts"] = current_scan_ts
        state["active_buy_non_gf_upper_predict_latest_closed_above_pma"] = closed_pma

    closed_peak = _safe_finite_float(state.get("active_buy_non_gf_upper_predict_closed_peak_pma"))
    state["active_buy_non_gf_upper_predict_last_pma"] = pma
    state["active_buy_non_gf_upper_predict_last_closed_pma"] = closed_pma
    state["active_buy_non_gf_upper_predict_last_predict_upper"] = predict_upper
    state["active_buy_non_gf_upper_predict_last_gf_plus"] = gf_plus

    if closed_peak is None:
        return None

    below_peak = bool(pma < closed_peak)
    if below_peak:
        started_ts = ts_to_int(state.get("active_buy_non_gf_upper_predict_below_peak_since_ts"))
        if started_ts is None:
            started_ts = current_scan_ts
            state["active_buy_non_gf_upper_predict_below_peak_since_ts"] = started_ts
        elapsed_seconds = max(0, int((current_scan_ts or started_ts) - started_ts)) if started_ts is not None else 0
        state["active_buy_non_gf_upper_predict_below_peak_elapsed_seconds"] = elapsed_seconds
        try:
            required_seconds = max(1, int(float(NON_GF_PLUS_FAILED_UPPER_PREDICT_FORCE_SELL_SECONDS)))
        except Exception:
            required_seconds = 360
        if elapsed_seconds >= required_seconds:
            reason = (
                "non-GF+ failed upper-predict force sell: normal active BUY never qualified as GF+ "
                f"(+{PMA_GF_PLUS_FORCE_BUY_INSTANT_OFFSET:.3f} PMA-GF+ offset or "
                f"{PMA_GF_PLUS_FORCE_BUY_HOLD_SECONDS}s above GF+), and PMA stayed below the highest "
                f"closed PMA peak since latest closed above Predict Upper for {elapsed_seconds}s/{required_seconds}s "
                f"(PMA {pma:.6f} < closed peak {closed_peak:.6f}; Predict Upper {predict_upper:.6f}; GF+ {gf_plus:.6f})"
            )
            return build_pma_rule_sell(
                reason,
                {
                    "non_gf_plus_failed_upper_predict_force_sell": True,
                    "non_gf_plus_failed_upper_predict_closed_peak_pma": closed_peak,
                    "non_gf_plus_failed_upper_predict_closed_peak_ts": state.get("active_buy_non_gf_upper_predict_closed_peak_ts"),
                    "non_gf_plus_failed_upper_predict_latest_closed_above_ts": state.get("active_buy_non_gf_upper_predict_latest_closed_above_ts"),
                    "non_gf_plus_failed_upper_predict_below_peak_started_ts": started_ts,
                    "non_gf_plus_failed_upper_predict_elapsed_seconds": elapsed_seconds,
                    "non_gf_plus_failed_upper_predict_required_seconds": required_seconds,
                    "pine_30m_predict_upper": predict_upper,
                },
                "non_gf_plus_failed_upper_predict",
            )
    else:
        state["active_buy_non_gf_upper_predict_below_peak_since_ts"] = None
        state["active_buy_non_gf_upper_predict_below_peak_elapsed_seconds"] = None

    return None


def active_buy_green_streak_count(state):
    if not isinstance(state, dict):
        return 0
    return _safe_non_negative_int(state.get("active_buy_green_count"), default=0)


def active_buy_max_green_streak_count(state):
    if not isinstance(state, dict):
        return 0
    current_count = _safe_non_negative_int(state.get("active_buy_green_count"), default=0)
    max_count = _safe_non_negative_int(state.get("active_buy_max_green_count"), default=0)
    return max(current_count, max_count)


def update_active_buy_max_green_streak_state(state, current_price, entry_price, scan_dt=None, source="live"):
    """Record the maximum active-BUY green streak reached since the real BUY.

    This state is intentionally monotonic during a real BUY.  It avoids using a
    display-only/live recalculation as a sell gate, while still preserving the
    highest x1/x2/... streak reached from the real active-BUY entry up to now.
    """
    if not isinstance(state, dict):
        return {"updated": False, "current_streaks": 0, "max_streaks": 0, "latest_green_price": None}

    ensure_active_buy_state_defaults(state)
    live_streaks, latest_green_price = active_buy_current_streak(current_price, entry_price)
    try:
        live_streaks = max(0, int(live_streaks or 0))
    except Exception:
        live_streaks = 0

    previous_max = active_buy_max_green_streak_count(state)
    updated = False
    if live_streaks > previous_max:
        state["active_buy_max_green_count"] = live_streaks
        state["active_buy_max_green_price"] = latest_green_price
        state["active_buy_max_green_scan_ts"] = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
        state["active_buy_max_green_source"] = str(source or "live")
        updated = True
    elif previous_max > _safe_non_negative_int(state.get("active_buy_max_green_count"), default=0):
        # Backfill max storage when only the legacy current counter exists.
        state["active_buy_max_green_count"] = previous_max
        updated = True

    return {
        "updated": updated,
        "current_streaks": live_streaks,
        "max_streaks": active_buy_max_green_streak_count(state),
        "latest_green_price": latest_green_price,
    }


def active_buy_streak_threshold_pct(streak_count):
    """Return the PnL percent required to have reached active-BUY xN."""
    try:
        streak_count = max(1, int(streak_count or 1))
    except Exception:
        streak_count = 1

    try:
        trigger_pct = float(ACTIVE_BUY_GREEN_TRIGGER_PCT)
    except Exception:
        trigger_pct = 1.618
    try:
        step_pct = float(ACTIVE_BUY_GREEN_STEP_PCT)
    except Exception:
        step_pct = trigger_pct

    multiplier = 1.0 + (trigger_pct / 100.0)
    step_multiplier = 1.0 + (step_pct / 100.0)
    for _ in range(max(0, streak_count - 1)):
        multiplier *= step_multiplier
    return (multiplier - 1.0) * 100.0



def _active_buy_peak_valid_pnl_bounds():
    try:
        max_valid = float(ACTIVE_BUY_PEAK_MAX_VALID_PNL_PCT)
    except Exception:
        max_valid = 100.0
    try:
        min_valid = float(ACTIVE_BUY_PEAK_MIN_VALID_PNL_PCT)
    except Exception:
        min_valid = -99.0

    if max_valid <= 0:
        max_valid = 100.0
    if min_valid >= 0:
        min_valid = -99.0
    return min_valid, max_valid


def active_buy_peak_candidate_pnl_valid(entry_price, candidate_price):
    """Backward-compatible validity check for active-BUY peak candidates."""
    normalized = normalize_active_buy_peak_candidate_price(entry_price, candidate_price)
    return bool(normalized.get("valid")), normalized.get("pnl_pct"), normalized.get("reason")


def normalize_active_buy_peak_candidate_price(entry_price, candidate_price, previous_peak_price=None):
    """Return a price-scale-normalized active-BUY peak candidate.

    The goal is to repair obvious decimal / legacy quote scale slips instead of
    dropping them.  If DOGS-like prices appear 10x/100x/... larger or smaller
    than the active BUY price / previous high-watermark, try power-of-ten scale
    repairs and keep the best valid candidate.  Unchanged candidates still pass
    normally when they are already on the right scale.
    """
    entry_price = _safe_positive_float(entry_price)
    raw_price = _safe_positive_float(candidate_price)
    previous_peak_price = _safe_positive_float(previous_peak_price)
    previous_peak_pnl = pct_change(entry_price, previous_peak_price) if previous_peak_price not in (None, 0, 0.0) and entry_price not in (None, 0, 0.0) else None
    try:
        min_previous_pnl_for_repair = float(ACTIVE_BUY_PEAK_SCALE_REPAIR_MIN_PREVIOUS_PNL_PCT)
    except Exception:
        min_previous_pnl_for_repair = 10.0
    if min_previous_pnl_for_repair < 0:
        min_previous_pnl_for_repair = 10.0
    previous_peak_allows_scale_repair = bool(
        previous_peak_pnl is not None and
        math.isfinite(previous_peak_pnl) and
        previous_peak_pnl >= min_previous_pnl_for_repair
    )
    min_valid, max_valid = _active_buy_peak_valid_pnl_bounds()

    if entry_price in (None, 0, 0.0) or raw_price is None:
        return {
            "valid": False,
            "price": raw_price,
            "raw_price": raw_price,
            "pnl_pct": None,
            "raw_pnl_pct": None,
            "scale_factor": 1.0,
            "repaired": False,
            "reason": "missing entry/candidate price",
        }

    raw_pnl = pct_change(entry_price, raw_price)
    if raw_pnl is None or not math.isfinite(raw_pnl):
        return {
            "valid": False,
            "price": raw_price,
            "raw_price": raw_price,
            "pnl_pct": raw_pnl,
            "raw_pnl_pct": raw_pnl,
            "scale_factor": 1.0,
            "repaired": False,
            "reason": "non-finite candidate PnL",
        }

    def pnl_valid(value):
        return value is not None and math.isfinite(value) and min_valid <= value <= max_valid

    # Normal case: already valid and not a clear power-of-ten scale mismatch.
    reference_price = previous_peak_price if previous_peak_price not in (None, 0, 0.0) else entry_price
    ratio_to_reference = None
    try:
        if reference_price not in (None, 0, 0.0):
            ratio_to_reference = raw_price / reference_price
    except Exception:
        ratio_to_reference = None

    try:
        ratio_threshold = float(ACTIVE_BUY_PEAK_SCALE_REPAIR_RATIO_THRESHOLD)
    except Exception:
        ratio_threshold = 5.0
    if ratio_threshold <= 1.0:
        ratio_threshold = 5.0

    clear_scale_mismatch = bool(
        ratio_to_reference is not None and
        math.isfinite(ratio_to_reference) and
        (ratio_to_reference >= ratio_threshold or ratio_to_reference <= (1.0 / ratio_threshold))
    )

    if pnl_valid(raw_pnl) and not clear_scale_mismatch:
        return {
            "valid": True,
            "price": raw_price,
            "raw_price": raw_price,
            "pnl_pct": raw_pnl,
            "raw_pnl_pct": raw_pnl,
            "scale_factor": 1.0,
            "repaired": False,
            "reason": None,
        }

    if not bool(globals().get("ACTIVE_BUY_PEAK_SCALE_REPAIR_ENABLED", True)):
        return {
            "valid": False,
            "price": raw_price,
            "raw_price": raw_price,
            "pnl_pct": raw_pnl,
            "raw_pnl_pct": raw_pnl,
            "scale_factor": 1.0,
            "repaired": False,
            "reason": f"candidate peak PnL {raw_pnl:.6f}% outside valid range {min_valid:.6f}%..{max_valid:.6f}%",
        }

    if not previous_peak_allows_scale_repair:
        previous_text = "none" if previous_peak_pnl is None else f"{previous_peak_pnl:.6f}%"
        return {
            "valid": False,
            "price": raw_price,
            "raw_price": raw_price,
            "pnl_pct": raw_pnl,
            "raw_pnl_pct": raw_pnl,
            "scale_factor": 1.0,
            "repaired": False,
            "reason": (
                f"candidate peak PnL {raw_pnl:.6f}% outside valid range {min_valid:.6f}%..{max_valid:.6f}%; "
                f"scale repair not allowed until previous peak PnL >= {min_previous_pnl_for_repair:.6f}% "
                f"(current previous peak PnL: {previous_text})"
            ),
        }

    try:
        repair_factors = tuple(float(x) for x in ACTIVE_BUY_PEAK_SCALE_REPAIR_FACTORS)
    except Exception:
        repair_factors = (1.0, 0.1, 0.01, 0.001, 0.0001)

    valid_scaled = []
    for factor in repair_factors:
        if factor in (None, 0, 0.0) or not math.isfinite(factor):
            continue
        scaled_price = _safe_positive_float(raw_price * factor)
        if scaled_price is None:
            continue
        scaled_pnl = pct_change(entry_price, scaled_price)
        if not pnl_valid(scaled_pnl):
            continue

        # Prefer the candidate that best matches the active lifecycle price
        # scale.  If there is a previous peak, that is the strongest reference;
        # otherwise the BUY entry is the safest anchor.
        score_reference = previous_peak_price if previous_peak_price not in (None, 0, 0.0) else entry_price
        try:
            scale_distance = abs(math.log(scaled_price / score_reference)) if score_reference not in (None, 0, 0.0) else abs(float(scaled_pnl or 0.0))
        except Exception:
            scale_distance = abs(float(scaled_pnl or 0.0))

        # Tie-break toward candidates that keep/enhance the high-watermark, then
        # toward the smallest scale change.  This handles "previous peak was 10x
        # lower than current" by selecting /10 when it restores the known scale.
        highwater_bonus = 0.0
        if previous_peak_price not in (None, 0, 0.0) and scaled_price >= previous_peak_price:
            highwater_bonus = -0.000001
        factor_penalty = 0.0 if math.isclose(factor, 1.0, rel_tol=0.0, abs_tol=0.0) else abs(math.log10(abs(factor))) * 0.00001
        valid_scaled.append((scale_distance + factor_penalty + highwater_bonus, scaled_price, scaled_pnl, factor))

    if valid_scaled:
        valid_scaled.sort(key=lambda item: item[0])
        _, repaired_price, repaired_pnl, factor = valid_scaled[0]
        repaired = not math.isclose(float(factor), 1.0, rel_tol=0.0, abs_tol=0.0)
        reason = None
        if repaired:
            reason = (
                f"candidate peak price scale repaired by factor {factor:g}: "
                f"raw={raw_price:g}, repaired={repaired_price:g}, raw_pnl={raw_pnl:.6f}%, repaired_pnl={repaired_pnl:.6f}%"
            )
        return {
            "valid": True,
            "price": repaired_price,
            "raw_price": raw_price,
            "pnl_pct": repaired_pnl,
            "raw_pnl_pct": raw_pnl,
            "scale_factor": factor,
            "repaired": repaired,
            "reason": reason,
        }

    return {
        "valid": False,
        "price": raw_price,
        "raw_price": raw_price,
        "pnl_pct": raw_pnl,
        "raw_pnl_pct": raw_pnl,
        "scale_factor": 1.0,
        "repaired": False,
        "reason": f"candidate peak PnL {raw_pnl:.6f}% could not be scale-repaired into valid range {min_valid:.6f}%..{max_valid:.6f}%",
    }


def record_repaired_active_buy_peak_candidate(state, entry_price, raw_candidate_price, repaired_candidate_price, source=None, scan_dt=None, reason=None, scale_factor=None, raw_pnl=None, repaired_pnl=None):
    if not isinstance(state, dict):
        return
    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    state["active_buy_peak_scale_repaired_candidate_raw_price"] = _safe_positive_float(raw_candidate_price)
    state["active_buy_peak_scale_repaired_candidate_price"] = _safe_positive_float(repaired_candidate_price)
    state["active_buy_peak_scale_repaired_candidate_entry_price"] = _safe_positive_float(entry_price)
    state["active_buy_peak_scale_repaired_candidate_factor"] = scale_factor
    state["active_buy_peak_scale_repaired_candidate_raw_pnl_pct"] = raw_pnl
    state["active_buy_peak_scale_repaired_candidate_pnl_pct"] = repaired_pnl
    state["active_buy_peak_scale_repaired_candidate_source"] = str(source or "unknown")
    state["active_buy_peak_scale_repaired_candidate_scan_ts"] = scan_ts
    state["active_buy_peak_scale_repaired_candidate_reason"] = str(reason or "active-BUY peak candidate scale repaired")


def record_rejected_active_buy_peak_candidate(state, entry_price, candidate_price, source=None, scan_dt=None, reason=None):
    if not isinstance(state, dict):
        return
    candidate_pnl = pct_change(_safe_positive_float(entry_price), _safe_positive_float(candidate_price))
    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    state["active_buy_peak_rejected_candidate_price"] = _safe_positive_float(candidate_price)
    state["active_buy_peak_rejected_candidate_pnl_pct"] = candidate_pnl
    state["active_buy_peak_rejected_candidate_entry_price"] = _safe_positive_float(entry_price)
    state["active_buy_peak_rejected_candidate_source"] = str(source or "unknown")
    state["active_buy_peak_rejected_candidate_scan_ts"] = scan_ts
    state["active_buy_peak_rejected_candidate_reason"] = str(reason or "invalid active-BUY peak candidate")

def reset_active_buy_peak_pnl_tracking(state):
    if not isinstance(state, dict):
        return
    state["active_buy_peak_price"] = None
    state["active_buy_peak_pnl_pct"] = None
    state["active_buy_peak_scan_ts"] = None
    state["active_buy_peak_source"] = None
    state["active_buy_peak_entry_price"] = None
    state["active_buy_peak_entry_ts"] = None
    state["active_buy_highest_wick_high_price"] = None
    state["active_buy_highest_wick_high_pnl_pct"] = None
    state["active_buy_highest_wick_high_scan_ts"] = None
    state["active_buy_highest_wick_high_candle_ts"] = None
    state["active_buy_highest_wick_high_source"] = None
    state["active_buy_highest_wick_high_entry_price"] = None
    state["active_buy_highest_wick_high_entry_ts"] = None
    state["active_buy_peak_rejected_candidate_price"] = None
    state["active_buy_peak_rejected_candidate_pnl_pct"] = None
    state["active_buy_peak_rejected_candidate_entry_price"] = None
    state["active_buy_peak_rejected_candidate_source"] = None
    state["active_buy_peak_rejected_candidate_scan_ts"] = None
    state["active_buy_peak_rejected_candidate_reason"] = None
    state["active_buy_peak_scale_repaired_candidate_raw_price"] = None
    state["active_buy_peak_scale_repaired_candidate_price"] = None
    state["active_buy_peak_scale_repaired_candidate_entry_price"] = None
    state["active_buy_peak_scale_repaired_candidate_factor"] = None
    state["active_buy_peak_scale_repaired_candidate_raw_pnl_pct"] = None
    state["active_buy_peak_scale_repaired_candidate_pnl_pct"] = None
    state["active_buy_peak_scale_repaired_candidate_source"] = None
    state["active_buy_peak_scale_repaired_candidate_scan_ts"] = None
    state["active_buy_peak_scale_repaired_candidate_reason"] = None


def active_buy_peak_pnl_pct(state):
    if not isinstance(state, dict):
        return None
    try:
        value = state.get("active_buy_peak_pnl_pct")
        return float(value) if value is not None else None
    except Exception:
        return None


def resolve_active_buy_real_entry_anchor(state, fallback_entry_price=None):
    if not isinstance(state, dict):
        return _safe_positive_float(fallback_entry_price), None
    entry_price = _safe_positive_float(state.get("active_buy_entry_price"))
    if entry_price is None:
        entry_price = _safe_positive_float(state.get("entry_price"))
    if entry_price is None:
        entry_price = _safe_positive_float(fallback_entry_price)
    entry_ts = ts_to_int(state.get("active_buy_entry_ts"))
    if entry_ts is None:
        entry_ts = ts_to_int(state.get("buy_event_ts") or state.get("buy_ts"))
    return entry_price, entry_ts


def active_buy_identity_event_extra(state, fallback_entry_price=None, fallback_entry_ts=None):
    """Return canonical real BUY identity fields for BUY/SELL event payloads."""
    if not isinstance(state, dict):
        entry_price = _safe_positive_float(fallback_entry_price)
        entry_ts = ts_to_int(fallback_entry_ts)
    else:
        entry_price, entry_ts = resolve_active_buy_real_entry_anchor(state, fallback_entry_price=fallback_entry_price)
        if entry_ts is None:
            entry_ts = ts_to_int(fallback_entry_ts)

    return {
        "entry_price": entry_price,
        "entry_ts": entry_ts,
        "entry_unix_ts": entry_ts,
        "buy_event_ts": entry_ts,
        "buy_event_unix_ts": entry_ts,
        "active_buy_entry_price": entry_price,
        "active_buy_entry_ts": entry_ts,
    }


def update_active_buy_peak_pnl_state(state, current_price, entry_price=None, scan_dt=None, source="live", live_candle=None):
    """Record the highest wick/price/PnL seen since the real active BUY entry.

    The high-watermark is monotonic for the active BUY lifecycle.  In addition
    to the live/current price, this now records the current live candle wick
    high after the real BUY scan even when that live candle opened before the
    real BUY timestamp.  That is necessary for mid-candle BUYs: otherwise a
    later scan inside the same 30m candle can show a +7% wick but the fib peak
    gate still reads +0.00% because live_candle.t < active_buy_entry_ts.
    """
    if not isinstance(state, dict):
        return {"updated": False, "peak_price": None, "peak_pnl_pct": None}

    ensure_active_buy_state_defaults(state)
    entry_price, entry_ts = resolve_active_buy_real_entry_anchor(state, fallback_entry_price=entry_price)
    entry_price = _safe_positive_float(entry_price)
    if entry_price in (None, 0, 0.0):
        return {
            "updated": False,
            "peak_price": _safe_positive_float(state.get("active_buy_peak_price")),
            "peak_pnl_pct": active_buy_peak_pnl_pct(state),
            "highest_wick_high_price": _safe_positive_float(state.get("active_buy_highest_wick_high_price")),
            "highest_wick_high_pnl_pct": state.get("active_buy_highest_wick_high_pnl_pct"),
        }

    existing_entry = _safe_positive_float(state.get("active_buy_peak_entry_price"))
    existing_entry_ts = ts_to_int(state.get("active_buy_peak_entry_ts"))
    if existing_entry is not None and not math.isclose(existing_entry, entry_price, rel_tol=1e-12, abs_tol=1e-12):
        reset_active_buy_peak_pnl_tracking(state)
    elif existing_entry_ts is not None and entry_ts is not None and existing_entry_ts != entry_ts:
        reset_active_buy_peak_pnl_tracking(state)

    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    previous_peak_price_for_scale = _safe_positive_float(state.get("active_buy_peak_price"))
    candidates = []

    def add_candidate(value, candidate_source, candle_ts=None, is_wick_high=False):
        raw_value = _safe_positive_float(value)
        if raw_value is None:
            return
        candidate_source = str(candidate_source or "live")
        normalized = normalize_active_buy_peak_candidate_price(
            entry_price,
            raw_value,
            previous_peak_price=previous_peak_price_for_scale,
        )
        if not bool(normalized.get("valid")):
            record_rejected_active_buy_peak_candidate(
                state,
                entry_price,
                raw_value,
                source=candidate_source,
                scan_dt=scan_dt,
                reason=normalized.get("reason"),
            )
            return

        value = _safe_positive_float(normalized.get("price"))
        candidate_pnl = normalized.get("pnl_pct")
        if bool(normalized.get("repaired")):
            record_repaired_active_buy_peak_candidate(
                state,
                entry_price,
                raw_value,
                value,
                source=candidate_source,
                scan_dt=scan_dt,
                reason=normalized.get("reason"),
                scale_factor=normalized.get("scale_factor"),
                raw_pnl=normalized.get("raw_pnl_pct"),
                repaired_pnl=candidate_pnl,
            )
            candidate_source = f"{candidate_source}_scale_repaired_x{normalized.get('scale_factor'):g}"

        candidates.append({
            "price": value,
            "pnl_pct": candidate_pnl,
            "raw_price": raw_value,
            "scale_factor": normalized.get("scale_factor"),
            "scale_repaired": bool(normalized.get("repaired")),
            "source": candidate_source,
            "candle_ts": ts_to_int(candle_ts),
            "is_wick_high": bool(is_wick_high),
        })

    add_candidate(current_price, str(source or "live"), is_wick_high=False)

    if isinstance(live_candle, dict):
        live_candle_ts = ts_to_int(live_candle.get("t"))
        add_candidate(live_candle.get("c"), "live_candle_c", candle_ts=live_candle_ts, is_wick_high=False)

        # Use wick/body extremes when the candle belongs to/comes after the real
        # BUY lifecycle.  For mid-candle BUYs, live_candle.t can be older than
        # entry_ts, so allow the current scan after entry to advance the peak.
        allow_live_candle_extremes = bool(
            (entry_ts is not None and live_candle_ts is not None and live_candle_ts >= entry_ts) or
            (
                bool(ACTIVE_BUY_PEAK_TRACK_LIVE_WICK_HIGH_AFTER_BUY_SCAN) and
                entry_ts is not None and
                current_scan_ts is not None and
                current_scan_ts >= entry_ts
            ) or
            entry_ts is None
        )
        if allow_live_candle_extremes:
            body_top_source = (
                "live_candle_body_top_after_real_buy_scan"
                if live_candle_ts is not None and entry_ts is not None and live_candle_ts < entry_ts
                else "live_candle_body_top"
            )
            high_source = (
                "live_candle_h_after_real_buy_scan"
                if live_candle_ts is not None and entry_ts is not None and live_candle_ts < entry_ts
                else "live_candle_h"
            )
            add_candidate(live_candle.get("body_top"), body_top_source, candle_ts=live_candle_ts, is_wick_high=False)
            add_candidate(live_candle.get("h"), high_source, candle_ts=live_candle_ts, is_wick_high=True)

    if not candidates:
        return {
            "updated": False,
            "peak_price": _safe_positive_float(state.get("active_buy_peak_price")),
            "peak_pnl_pct": active_buy_peak_pnl_pct(state),
            "highest_wick_high_price": _safe_positive_float(state.get("active_buy_highest_wick_high_price")),
            "highest_wick_high_pnl_pct": state.get("active_buy_highest_wick_high_pnl_pct"),
        }

    best = max(candidates, key=lambda item: item["price"])
    candidate_price = best["price"]
    candidate_source = best["source"]
    candidate_pnl = pct_change(entry_price, candidate_price)
    previous_peak_price = _safe_positive_float(state.get("active_buy_peak_price"))
    previous_peak_pnl = active_buy_peak_pnl_pct(state)

    updated = False
    if previous_peak_price is None or candidate_price > previous_peak_price or previous_peak_pnl is None or candidate_pnl > previous_peak_pnl:
        state["active_buy_peak_price"] = candidate_price
        state["active_buy_peak_pnl_pct"] = candidate_pnl
        state["active_buy_peak_scan_ts"] = current_scan_ts
        state["active_buy_peak_source"] = candidate_source
        state["active_buy_peak_entry_price"] = entry_price
        state["active_buy_peak_entry_ts"] = entry_ts
        updated = True

    # Keep an explicit wick high-watermark for debugging and fib top locking.
    highest_wick_price = _safe_positive_float(state.get("active_buy_highest_wick_high_price"))
    wick_candidates = [item for item in candidates if item.get("is_wick_high")]
    if not wick_candidates:
        wick_candidates = [best]
    best_wick = max(wick_candidates, key=lambda item: item["price"])
    best_wick_price = best_wick["price"]
    best_wick_pnl = best_wick.get("pnl_pct")
    if best_wick_pnl is None:
        best_wick_pnl = pct_change(entry_price, best_wick_price)
    if highest_wick_price is None or best_wick_price > highest_wick_price:
        state["active_buy_highest_wick_high_price"] = best_wick_price
        state["active_buy_highest_wick_high_pnl_pct"] = best_wick_pnl
        state["active_buy_highest_wick_high_scan_ts"] = current_scan_ts
        state["active_buy_highest_wick_high_candle_ts"] = best_wick.get("candle_ts")
        state["active_buy_highest_wick_high_source"] = best_wick.get("source")
        state["active_buy_highest_wick_high_entry_price"] = entry_price
        state["active_buy_highest_wick_high_entry_ts"] = entry_ts
        if best_wick_price > (_safe_positive_float(state.get("active_buy_peak_price")) or 0):
            state["active_buy_peak_price"] = best_wick_price
            state["active_buy_peak_pnl_pct"] = best_wick_pnl
            state["active_buy_peak_scan_ts"] = current_scan_ts
            state["active_buy_peak_source"] = best_wick.get("source")
            state["active_buy_peak_entry_price"] = entry_price
            state["active_buy_peak_entry_ts"] = entry_ts
        updated = True

    if bool(ACTIVE_BUY_FIB_TOP_LOCK_TO_HIGHEST_WICK_HIGH):
        sync_active_buy_fib_top_to_highest_wick(state, scan_dt=scan_dt)

    return {
        "updated": updated,
        "peak_price": _safe_positive_float(state.get("active_buy_peak_price")),
        "peak_pnl_pct": active_buy_peak_pnl_pct(state),
        "peak_scan_ts": ts_to_int(state.get("active_buy_peak_scan_ts")),
        "source": state.get("active_buy_peak_source"),
        "highest_wick_high_price": _safe_positive_float(state.get("active_buy_highest_wick_high_price")),
        "highest_wick_high_pnl_pct": state.get("active_buy_highest_wick_high_pnl_pct"),
        "highest_wick_high_scan_ts": ts_to_int(state.get("active_buy_highest_wick_high_scan_ts")),
        "highest_wick_high_candle_ts": ts_to_int(state.get("active_buy_highest_wick_high_candle_ts")),
        "highest_wick_high_source": state.get("active_buy_highest_wick_high_source"),
    }


def sync_active_buy_fib_top_to_highest_wick(state, scan_dt=None):
    """Make fib_top monotonic to the highest wick high seen in the active BUY."""
    if not isinstance(state, dict):
        return False
    if str(state.get("stage") or "idle").strip().lower() not in {"buy", "pumped"}:
        return False

    highest_wick = _safe_positive_float(state.get("active_buy_highest_wick_high_price") or state.get("active_buy_peak_price"))
    if highest_wick is None:
        return False

    fib_top = _safe_positive_float(state.get("fib_top"))
    if fib_top is not None and highest_wick <= fib_top:
        return False

    state["fib_top"] = highest_wick
    state["fib_top_updated_scan_ts"] = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    state["fib_top_source"] = state.get("active_buy_highest_wick_high_source") or state.get("active_buy_peak_source") or "active_buy_highest_wick_high"
    state["fib_top_locked_to_active_buy_highest_wick"] = True
    return True


def sync_pma_gf_plus_fib_bottom_to_latest_closed_body_top(state, latest_closed_candle, current_live_candle=None, scan_dt=None):
    """Conditionally readjust PMA/GF+ fib_bottom to latest closed body-top.

    v66 keeps the original real-BUY fib bottom active until the candidate
    latest-closed-body-top range is wide enough to be a real fib zone.  The
    candidate bottom is still stored separately every time a new closed candle
    is available, so the bot can inspect the would-be range, but the live
    fib_bottom is only committed when:

      candidate range = latest closed body_top -> highest wick since real BUY
      candidate zone_pct >= FIB_SELL_MIN_ZONE_PCT / PMA_GF_PLUS_FORCE_BUY_FIB_MIN_ZONE_PCT

    This prevents a tiny rollover/body-top range from replacing the buy fib
    bottom and accidentally invalidating fib management before a real 1%+ range
    exists.
    """
    if not isinstance(state, dict) or not isinstance(latest_closed_candle, dict):
        return {"updated": False, "reason": "missing state/latest closed candle"}
    if str(state.get("stage") or "idle").strip().lower() not in {"buy", "pumped"}:
        return {"updated": False, "reason": "not in active BUY stage"}
    if not active_buy_is_pma_gf_plus_lifecycle(state):
        return {"updated": False, "reason": "not a PMA/GF+ lifecycle"}

    latest_closed_ts = ts_to_int(latest_closed_candle.get("t"))
    current_live_ts = ts_to_int((current_live_candle or {}).get("t")) if isinstance(current_live_candle, dict) else None
    buy_live_ts = ts_to_int(state.get("buy_reference_candle_ts") or state.get("fib_live_candle_ts"))

    # Do not readjust inside the original buy live candle.  The first candidate
    # can only be considered once at least one candle has closed after the BUY
    # candle and a newer live candle exists.
    if buy_live_ts is not None and current_live_ts is not None and current_live_ts <= buy_live_ts:
        return {"updated": False, "reason": "still inside original buy live candle"}
    if current_live_ts is not None and latest_closed_ts is not None and latest_closed_ts >= current_live_ts:
        return {"updated": False, "reason": "latest closed candle is not before current live candle"}

    body_top = _safe_positive_float(latest_closed_candle.get("body_top"))
    if body_top is None:
        o = _safe_positive_float(latest_closed_candle.get("o"))
        c = _safe_positive_float(latest_closed_candle.get("c"))
        if o is not None and c is not None:
            body_top = max(o, c)
    if body_top is None:
        return {"updated": False, "reason": "latest closed body_top unavailable"}

    # Keep fib_top monotonic to the highest wick/high since real BUY.  This can
    # update even while fib_bottom remains the original buy fib bottom.
    sync_active_buy_fib_top_to_highest_wick(state, scan_dt=scan_dt)
    fib_top = _safe_positive_float(state.get("fib_top") or state.get("active_buy_highest_wick_high_price") or state.get("active_buy_peak_price"))
    if fib_top is None:
        return {"updated": False, "reason": "fib_top/highest wick unavailable"}

    low, high = normalized_fib_bounds(body_top, fib_top)
    candidate_zone_pct = pct_change(low, high) if low not in (None, 0, 0.0) and high not in (None, 0, 0.0) else None
    try:
        min_zone_pct = float(globals().get("PMA_GF_PLUS_FORCE_BUY_FIB_MIN_ZONE_PCT", globals().get("FIB_SELL_MIN_ZONE_PCT", 1.0)))
    except Exception:
        min_zone_pct = 1.0
    candidate_valid = bool(candidate_zone_pct is not None and candidate_zone_pct >= min_zone_pct)

    current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    previous_bottom = _safe_positive_float(state.get("fib_bottom"))
    previous_bottom_ts = ts_to_int(state.get("fib_bottom_latest_closed_ts"))

    # Always store the latest candidate separately for debug/decision visibility.
    state["pma_gf_plus_waiting_fib_bottom"] = body_top
    state["pma_gf_plus_waiting_fib_top"] = fib_top
    state["pma_gf_plus_waiting_fib_low"] = low
    state["pma_gf_plus_waiting_fib_high"] = high
    state["pma_gf_plus_waiting_fib_zone_pct"] = candidate_zone_pct
    state["pma_gf_plus_waiting_fib_min_zone_pct"] = min_zone_pct
    state["pma_gf_plus_waiting_fib_latest_closed_ts"] = latest_closed_ts
    state["pma_gf_plus_waiting_fib_current_live_ts"] = current_live_ts
    state["pma_gf_plus_waiting_fib_scan_ts"] = current_scan_ts
    state["pma_gf_plus_waiting_fib_ready"] = candidate_valid
    state["pma_gf_plus_waiting_fib_reason"] = (
        "candidate latest-closed-body-top fib range is ready"
        if candidate_valid
        else f"candidate latest-closed-body-top fib range {candidate_zone_pct if candidate_zone_pct is not None else '-'}% is below min {min_zone_pct}%"
    )

    if not candidate_valid:
        return {
            "updated": False,
            "waiting_candidate_stored": True,
            "previous_fib_bottom": previous_bottom,
            "fib_bottom": state.get("fib_bottom"),
            "fib_top": state.get("fib_top"),
            "waiting_fib_bottom": body_top,
            "waiting_fib_top": fib_top,
            "waiting_zone_pct": candidate_zone_pct,
            "min_zone_pct": min_zone_pct,
            "latest_closed_ts": latest_closed_ts,
            "reason": "candidate latest-closed-body-top range below minimum; kept existing/buy fib_bottom active",
        }

    if previous_bottom_ts == latest_closed_ts and previous_bottom is not None and math.isclose(previous_bottom, body_top, rel_tol=1e-12, abs_tol=1e-12):
        return {
            "updated": False,
            "waiting_candidate_stored": True,
            "fib_bottom": state.get("fib_bottom"),
            "fib_top": state.get("fib_top"),
            "waiting_fib_bottom": body_top,
            "waiting_fib_top": fib_top,
            "waiting_zone_pct": candidate_zone_pct,
            "min_zone_pct": min_zone_pct,
            "latest_closed_ts": latest_closed_ts,
            "reason": "fib_bottom already matches latest closed body_top",
        }

    set_state_fib_bounds(
        state,
        body_top,
        fib_top,
        bottom_source="pma_gf_plus_latest_closed_body_top_after_real_buy_validated_1pct_range",
    )
    state["fib_bottom_updated_scan_ts"] = current_scan_ts
    state["fib_bottom_latest_closed_ts"] = latest_closed_ts
    state["fib_bottom_locked_to_latest_closed_body_top"] = True
    state["fib_bottom_previous_value"] = previous_bottom
    state["pma_gf_plus_waiting_fib_committed_ts"] = current_scan_ts
    return {
        "updated": True,
        "waiting_candidate_stored": True,
        "previous_fib_bottom": previous_bottom,
        "fib_bottom": state.get("fib_bottom"),
        "fib_top": state.get("fib_top"),
        "waiting_fib_bottom": body_top,
        "waiting_fib_top": fib_top,
        "waiting_zone_pct": candidate_zone_pct,
        "min_zone_pct": min_zone_pct,
        "latest_closed_ts": latest_closed_ts,
        "reason": "fib_bottom synced to latest closed body_top after candidate range reached minimum zone width",
    }

def fib_sell_zone_peak_gate_status(state):
    """Return whether fib-zone timing may start from real active-BUY peak PnL."""
    try:
        required_peak_pct = float(FIB_SELL_ZONE_PEAK_PNL_ARM_PCT)
    except Exception:
        required_peak_pct = float(ACTIVE_BUY_GREEN_TRIGGER_PCT)

    peak_pct = active_buy_peak_pnl_pct(state)
    requires_peak = bool(
        FIB_SELL_ZONE_USE_ACTIVE_BUY_PEAK_PNL_GATE and
        FIB_SELL_ZONE_REQUIRE_GREEN_STREAK_FOR_PUMPING and
        is_pumping_style_buy(state)
    )
    allowed = (not requires_peak) or (peak_pct is not None and peak_pct >= required_peak_pct)
    return {
        "allowed": allowed,
        "requires_peak": requires_peak,
        "peak_pnl_pct": peak_pct,
        "required_peak_pct": required_peak_pct,
        "peak_price": _safe_positive_float(state.get("active_buy_peak_price")) if isinstance(state, dict) else None,
        "peak_scan_ts": ts_to_int(state.get("active_buy_peak_scan_ts")) if isinstance(state, dict) else None,
        "peak_source": state.get("active_buy_peak_source") if isinstance(state, dict) else None,
        "highest_wick_high_price": _safe_positive_float(state.get("active_buy_highest_wick_high_price")) if isinstance(state, dict) else None,
        "highest_wick_high_pnl_pct": state.get("active_buy_highest_wick_high_pnl_pct") if isinstance(state, dict) else None,
        "highest_wick_high_scan_ts": ts_to_int(state.get("active_buy_highest_wick_high_scan_ts")) if isinstance(state, dict) else None,
        "highest_wick_high_candle_ts": ts_to_int(state.get("active_buy_highest_wick_high_candle_ts")) if isinstance(state, dict) else None,
        "highest_wick_high_source": state.get("active_buy_highest_wick_high_source") if isinstance(state, dict) else None,
    }


def clear_fib_sell_zone_elapsed_tracking(state, reason=None):
    if not isinstance(state, dict):
        return
    state["sell_zone_scan_count"] = 0
    state["sell_zone_pending_since_ts"] = None
    state["sell_zone_armed"] = False
    state["sell_zone_last_seen_in_zone_ts"] = None
    state["sell_zone_last_seen_in_zone_price"] = None
    state["sell_zone_clear_exit_threshold_price"] = None
    state["sell_zone_enter_threshold_price"] = None
    state["sell_zone_enter_fib_low"] = None
    state["sell_zone_enter_fib_high"] = None
    state["sell_zone_timer_bucket"] = None
    state["sell_zone_timer_required_seconds"] = None
    state["sell_zone_last_ratio"] = None
    state["sell_zone_high_gain_confirm_active"] = False
    state["sell_zone_high_gain_peak_pct"] = None
    state["fib_retracement_warning_active"] = False
    state["fib_retracement_warning_started_ts"] = None
    state["fib_retracement_warning_last_ts"] = None
    state["fib_retracement_warning_last_price"] = None
    state["fib_retracement_live_pma_weak_since_ts"] = None
    state["fib_retracement_live_pma_weak_elapsed_seconds"] = None
    state["fib_retracement_last_status"] = None
    if reason is not None:
        state["sell_zone_clear_reason"] = str(reason)


def fib_sell_zone_clear_exit_status(state, fib_zone, current_price, scan_dt=None, current_scan_ts=None):
    """Clear armed sell-zone time only after a confirmed recovery above the zone."""
    current_price = _safe_positive_float(current_price)
    if current_scan_ts is None:
        current_scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if current_price is None:
        return {"clear_exit": False, "raw_clear_exit": False, "reason": "missing_current_price", "threshold": None}

    thresholds = []
    stored_threshold = _safe_positive_float((state or {}).get("sell_zone_clear_exit_threshold_price")) if isinstance(state, dict) else None
    if stored_threshold is not None:
        thresholds.append(stored_threshold)
    current_threshold = _safe_positive_float((fib_zone or {}).get("threshold_price")) if isinstance(fib_zone, dict) else None
    if current_threshold is not None:
        thresholds.append(current_threshold)

    if not thresholds:
        return {"clear_exit": False, "raw_clear_exit": False, "reason": "missing_threshold", "threshold": None}

    threshold = max(thresholds)
    try:
        buffer_pct = max(0.0, float(FIB_SELL_ZONE_CLEAR_EXIT_PRICE_BUFFER_PCT))
    except Exception:
        buffer_pct = 0.0
    try:
        confirm_seconds = max(0, int(round(float(FIB_SELL_ZONE_CLEAR_EXIT_CONFIRM_SECONDS))))
    except Exception:
        confirm_seconds = 10

    clear_price = threshold * (1.0 + (buffer_pct / 100.0))
    raw_clear_exit = current_price > clear_price
    above_since_ts = ts_to_int((state or {}).get("sell_zone_clear_exit_above_since_ts")) if isinstance(state, dict) else None
    elapsed_seconds = None
    clear_exit = False

    if raw_clear_exit:
        if above_since_ts is None and isinstance(state, dict):
            above_since_ts = current_scan_ts
            state["sell_zone_clear_exit_above_since_ts"] = above_since_ts
        if current_scan_ts is not None and above_since_ts is not None:
            elapsed_seconds = max(0, int(current_scan_ts - above_since_ts))
        if isinstance(state, dict):
            state["sell_zone_clear_exit_elapsed_seconds"] = elapsed_seconds
        clear_exit = bool(confirm_seconds <= 0 or (elapsed_seconds is not None and elapsed_seconds >= confirm_seconds))
        reason = "price_above_clear_exit_confirmed" if clear_exit else "price_above_clear_exit_waiting_confirmation"
    else:
        if isinstance(state, dict):
            state["sell_zone_clear_exit_above_since_ts"] = None
            state["sell_zone_clear_exit_elapsed_seconds"] = None
        reason = "still_at_or_below_clear_exit_threshold"

    return {
        "clear_exit": clear_exit,
        "raw_clear_exit": raw_clear_exit,
        "reason": reason,
        "threshold": threshold,
        "clear_price": clear_price,
        "current_price": current_price,
        "stored_threshold": stored_threshold,
        "current_threshold": current_threshold,
        "above_since_ts": above_since_ts,
        "elapsed_seconds": elapsed_seconds,
        "confirm_seconds": confirm_seconds,
    }


def fib_sell_zone_streak_gate_status(state):
    """
    Returns whether fib-zone selling may count for the current active position.

    V2 uses the maximum green streak recorded since the real BUY moment, not
    the mutable current/display streak.  This prevents a later price drop from
    hiding the fact that x1/x2 was already reached earlier in the same trade.
    """
    try:
        required_streaks = max(0, int(FIB_SELL_ZONE_MIN_GREEN_STREAK_COUNT))
    except Exception:
        required_streaks = 1

    current_streaks = active_buy_green_streak_count(state)
    max_streaks = active_buy_max_green_streak_count(state)
    requires_streak = bool(
        FIB_SELL_ZONE_REQUIRE_GREEN_STREAK_FOR_PUMPING and
        is_pumping_style_buy(state) and
        required_streaks > 0
    )
    allowed = (not requires_streak) or max_streaks >= required_streaks
    return {
        "allowed": allowed,
        "requires_streak": requires_streak,
        "current_streaks": max_streaks,
        "stored_current_streaks": current_streaks,
        "max_streaks": max_streaks,
        "required_streaks": required_streaks,
    }


def fib_sell_zone_confirmation_policy(state, fib_zone, current_scan_ts=None):
    """Return V2 real-time confirmation policy for the active fib sell zone."""
    ratio = None
    try:
        ratio = float((fib_zone or {}).get("ratio"))
    except Exception:
        ratio = None

    in_sell_zone = bool((fib_zone or {}).get("in_sell_zone"))
    # Existing terminology calls the deeper floor/bottom break the severe
    # retracement bucket.  This is the user-requested "below 0.382" fast path:
    # it applies after the normal fib sell range has been fully broken.
    below_0382_bucket = bool(
        in_sell_zone and (
            (fib_zone or {}).get("below_floor") or
            (fib_zone or {}).get("below_fib_bottom") or
            (ratio is not None and ratio >= 1.0)
        )
    )

    max_streaks = active_buy_max_green_streak_count(state)
    peak_pnl_pct = active_buy_peak_pnl_pct(state)
    try:
        fast_streaks = max(1, int(FIB_SELL_ZONE_FAST_CONFIRM_STREAK_COUNT))
    except Exception:
        fast_streaks = 2
    fast_peak_pct = active_buy_streak_threshold_pct(fast_streaks)
    peak_reached_fast_tier = bool(peak_pnl_pct is not None and peak_pnl_pct >= fast_peak_pct)

    if below_0382_bucket:
        bucket = "below_0382"
        minutes = float(FIB_SELL_ZONE_CONFIRM_MINUTES_BELOW_0382)
        reason = "below_0382_fast_confirm"
    elif peak_reached_fast_tier:
        bucket = "sell_zone_x2"
        minutes = float(FIB_SELL_ZONE_CONFIRM_MINUTES_AT_TWO_STREAKS)
        reason = "active_buy_peak_pnl_at_or_above_x2"
    else:
        bucket = "sell_zone_below_x2"
        minutes = float(FIB_SELL_ZONE_CONFIRM_MINUTES_BELOW_TWO_STREAKS)
        reason = "active_buy_peak_pnl_below_x2"

    confirm_seconds = max(1, int(round(minutes * 60.0)))
    previous_pending_ts = ts_to_int((state or {}).get("sell_zone_pending_since_ts")) if isinstance(state, dict) else None
    previous_bucket = str((state or {}).get("sell_zone_timer_bucket") or "") if isinstance(state, dict) else ""
    previous_elapsed_seconds = None
    if current_scan_ts is not None and previous_pending_ts is not None:
        previous_elapsed_seconds = max(0, int(current_scan_ts - previous_pending_ts))

    # V4 robustness: once the sell-zone elapsed timer has started, bucket
    # changes (normal -> below_0382, below_0382 -> normal, x1 -> x2) must not
    # cancel or restart elapsed time.  The required confirmation duration may
    # change by bucket, but elapsed time stays anchored to the first sell-zone
    # entry until a clear sell-zone exit or an actual sell/reset.
    reset_pending = previous_pending_ts is None
    bucket_changed = bool(previous_bucket and previous_bucket != bucket)

    return {
        "bucket": bucket,
        "reason": reason,
        "confirm_seconds": confirm_seconds,
        "confirm_minutes": confirm_seconds / 60.0,
        "confirm_units": confirm_seconds / 60.0,
        "below_0382_bucket": below_0382_bucket,
        "max_green_streaks": max_streaks,
        "peak_pnl_pct": peak_pnl_pct,
        "fast_peak_pct": fast_peak_pct,
        "peak_reached_fast_tier": peak_reached_fast_tier,
        "fast_confirm_streaks": fast_streaks,
        "previous_bucket": previous_bucket or None,
        "previous_pending_since_ts": previous_pending_ts,
        "previous_elapsed_seconds": previous_elapsed_seconds,
        "bucket_changed": bucket_changed,
        "reset_pending": reset_pending,
    }


def infer_closed_candle_seconds(candles, default_seconds=1800):
    if not candles or len(candles) < 2:
        return int(default_seconds)
    timestamps = []
    for candle in candles[-10:]:
        ts = ts_to_int((candle or {}).get("t")) if isinstance(candle, dict) else None
        if ts is not None:
            timestamps.append(ts)
    diffs = []
    for left, right in zip(timestamps, timestamps[1:]):
        diff = right - left
        if 60 <= diff <= 86400:
            diffs.append(diff)
    if not diffs:
        return int(default_seconds)
    try:
        return int(statistics.median(diffs))
    except Exception:
        return int(default_seconds)


def closed_candles_finished_after_ts(candles, start_ts, candle_seconds=None):
    """Count closed candles whose close time is strictly after start_ts."""
    start_ts = ts_to_int(start_ts)
    if start_ts is None or not candles:
        return None
    if candle_seconds is None:
        candle_seconds = infer_closed_candle_seconds(candles, default_seconds=1800)
    try:
        candle_seconds = max(60, int(candle_seconds or 1800))
    except Exception:
        candle_seconds = 1800
    count = 0
    for candle in candles:
        if not isinstance(candle, dict):
            continue
        candle_open_ts = ts_to_int(candle.get("t"))
        if candle_open_ts is None:
            continue
        candle_close_ts = candle_open_ts + candle_seconds
        if candle_close_ts > start_ts:
            count += 1
    return count


def pumping_buy_actual_start_ts(state):
    """Return the first real BUY timestamp for a pumping position.

    For positions that begin as legacy/sandbox BUYs and later become pumping
    through shadow pending-buy, active_buy_entry_ts/buy_event_ts carry the first
    real BUY moment. pumping_buy_started_ts may be a later promotion timestamp,
    so it must not be preferred for no-streak age exits. buy_ts is only a
    fallback because some legacy paths store a candle timestamp there.
    """
    if not isinstance(state, dict):
        return None

    primary_timestamps = []
    for key in ("active_buy_entry_ts", "buy_event_ts"):
        ts = ts_to_int(state.get(key))
        if ts is not None:
            primary_timestamps.append(ts)
    if primary_timestamps:
        return min(primary_timestamps)

    for key in ("pumping_buy_started_ts", "buy_ts"):
        ts = ts_to_int(state.get(key))
        if ts is not None:
            return ts
    return None


def pumping_no_green_streak_exit_status(state, candles, scan_dt, current_price=None):
    first_buy_ts = pumping_buy_actual_start_ts(state)
    raw_pumping_started_ts = ts_to_int((state or {}).get("pumping_buy_started_ts")) if isinstance(state, dict) else None
    inferred_buy_style = infer_buy_style(state) if isinstance(state, dict) else "legacy"
    is_pumping = bool(is_pumping_style_buy(state)) if isinstance(state, dict) else False
    is_legacy = not is_pumping

    if bool(ACTIVE_BUY_SECOND_STREAK_TIMEOUT_ENABLED):
        enabled = True
        max_age_default = ACTIVE_BUY_SECOND_STREAK_TIMEOUT_MINUTES
        required_streaks_default = ACTIVE_BUY_SECOND_STREAK_TIMEOUT_REQUIRED_STREAKS
        timeout_label = "pumping" if is_pumping else "legacy"
    elif is_pumping:
        enabled = bool(PUMPING_NO_STREAK_AGE_EXIT_ENABLED)
        max_age_default = PUMPING_NO_STREAK_AGE_EXIT_MAX_MINUTES
        required_streaks_default = PUMPING_NO_STREAK_AGE_EXIT_MIN_GREEN_STREAKS
        timeout_label = "pumping"
    else:
        enabled = bool(LEGACY_NO_STREAK_AGE_EXIT_ENABLED)
        max_age_default = LEGACY_NO_STREAK_AGE_EXIT_MAX_MINUTES
        required_streaks_default = LEGACY_NO_STREAK_AGE_EXIT_MIN_GREEN_STREAKS
        timeout_label = "legacy"

    status = {
        "enabled": enabled,
        "applies": False,
        "should_sell": False,
        "buy_style": inferred_buy_style,
        "timeout_label": timeout_label,
        "is_pumping_style_buy": is_pumping,
        "is_legacy_buy": is_legacy,
        "age_minutes_since_first_buy": None,
        "max_age_minutes": max_age_default,
        "closed_candles_since_pumping_buy": None,
        "required_closed_candles": None,
        "current_streaks": active_buy_green_streak_count(state),
        "required_streaks": required_streaks_default,
        "first_buy_ts": first_buy_ts,
        "pumping_buy_started_ts": first_buy_ts,
        "raw_pumping_buy_started_ts": raw_pumping_started_ts,
    }
    if not status["enabled"]:
        return status
    if not isinstance(state, dict):
        return status
    if str(state.get("stage") or "idle").strip().lower() not in {"buy", "pumped"}:
        return status

    status["applies"] = True
    try:
        required_streaks = max(1, int(required_streaks_default))
    except Exception:
        required_streaks = 1
    status["required_streaks"] = required_streaks

    stored_streaks = active_buy_green_streak_count(state)
    entry_price = _safe_positive_float(state.get("active_buy_entry_price")) or _safe_positive_float(state.get("entry_price"))
    live_streaks = 0
    if current_price not in (None, 0, 0.0) and entry_price not in (None, 0, 0.0):
        try:
            live_streaks, _ = active_buy_current_streak(current_price, entry_price)
        except Exception:
            live_streaks = 0
    effective_streaks = max(stored_streaks, int(live_streaks or 0))
    status["current_streaks"] = effective_streaks
    status["stored_streaks"] = stored_streaks
    status["live_streaks"] = live_streaks
    if effective_streaks >= required_streaks:
        return status

    try:
        max_age_minutes = max(1.0, float(status.get("max_age_minutes")))
    except Exception:
        max_age_minutes = 25.0
    status["max_age_minutes"] = max_age_minutes

    current_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if first_buy_ts is None or current_ts is None:
        return status

    age_minutes = max(0.0, (current_ts - int(first_buy_ts)) / 60.0)
    status["age_minutes_since_first_buy"] = age_minutes
    status["should_sell"] = age_minutes >= max_age_minutes
    return status

def maybe_sell_pumping_no_green_streak_after_age_window(state, candles, live_candle, scan_dt, current_price=None):
    if should_skip_non_pma_sell_for_pma_gf_plus_lifecycle(
        state,
        "pumping_or_legacy_no_green_streak_age_exit",
        scan_dt=scan_dt,
        reason="skipped no-green-streak age sell because PMA/GF+ lifecycle is PMA-only",
    ):
        return None
    status = pumping_no_green_streak_exit_status(state, candles, scan_dt, current_price=current_price)
    if not bool(status.get("should_sell")):
        return None

    if current_price in (None, 0, 0.0):
        current_price = _safe_positive_float((live_candle or {}).get("c"))
    sell_candle = build_live_price_sell_candle(live_candle, scan_dt=scan_dt, live_price=current_price)
    if not isinstance(sell_candle, dict):
        return None

    entry_price = _safe_positive_float(state.get("active_buy_entry_price")) or _safe_positive_float(state.get("entry_price"))
    entry_pnl_pct = (
        pct_change(entry_price, current_price)
        if entry_price not in (None, 0, 0.0) and current_price not in (None, 0, 0.0)
        else None
    )
    max_age_minutes = status.get("max_age_minutes")
    try:
        max_age_float = float(max_age_minutes)
        max_age_text = f"{max_age_float:.0f}" if max_age_float.is_integer() else f"{max_age_float:.1f}"
    except Exception:
        max_age_text = str(max_age_minutes or status.get("max_age_minutes") or PUMPING_NO_STREAK_AGE_EXIT_MAX_MINUTES)
    timeout_label = str(status.get("timeout_label") or "active").strip().lower()
    reason_buy_style_text = "pumping BUY" if timeout_label == "pumping" else "legacy BUY"
    sell_event = finalize_sell_transition(
        state,
        sell_candle,
        scan_dt,
        f"{reason_buy_style_text} had no active-buy green streak survival after {max_age_text} minutes from its first BUY start",
        {
            "entry_pnl_pct": entry_pnl_pct,
            "current_price": current_price,
            "buy_style": status.get("buy_style"),
            "no_green_streak_exit": True,
            "no_green_streak_age_exit": True,
            "pumping_no_green_streak_exit": bool(status.get("is_pumping_style_buy")),
            "pumping_no_green_streak_age_exit": bool(status.get("is_pumping_style_buy")),
            "legacy_no_green_streak_exit": bool(status.get("is_legacy_buy")),
            "legacy_no_green_streak_age_exit": bool(status.get("is_legacy_buy")),
            "first_buy_ts": status.get("first_buy_ts"),
            "pumping_buy_started_ts": status.get("pumping_buy_started_ts"),
            "raw_pumping_buy_started_ts": status.get("raw_pumping_buy_started_ts"),
            "age_minutes_since_first_buy": status.get("age_minutes_since_first_buy"),
            "max_age_minutes": status.get("max_age_minutes"),
            "current_streaks": status.get("current_streaks"),
            "stored_streaks": status.get("stored_streaks"),
            "live_streaks": status.get("live_streaks"),
            "required_streaks": status.get("required_streaks"),
        },
    )
    status["event"] = sell_event
    status["pnl_pct"] = entry_pnl_pct
    return status


def maybe_sell_pumping_no_green_streak_after_second_closed_candle(state, candles, live_candle, scan_dt, current_price=None):
    # Backward-compatible wrapper. V2.15 logic is age-based, not candle-count based.
    return maybe_sell_pumping_no_green_streak_after_age_window(
        state, candles, live_candle, scan_dt, current_price=current_price
    )

def maybe_force_sell_legacy_buy_on_buy_signal_scan(state, candidate, latest_closed_candle, current_forming_candle, scan_dt):
    """
    BUY-1M safety net for legacy BUY positions.

    The normal 1m strategy evaluator can already exit active positions, but this
    outer scan-level guard makes legacy BUY force-sell detection independent of
    the pending-buy setup path, so a legacy BUY cannot wait for the next FULL scan
    when live price has already crossed the force-sell percentage.
    """
    if not isinstance(state, dict):
        return None

    stage = str(state.get("stage") or "idle").strip().lower()
    if stage not in {"buy", "pumped"}:
        return None

    if should_skip_non_pma_sell_for_pma_gf_plus_lifecycle(
        state,
        "buy_1m_legacy_force_sell",
        scan_dt=scan_dt,
        reason="skipped legacy force sell because PMA/GF+ lifecycle is PMA-only",
    ):
        return None

    if infer_buy_style(state) == "pumping":
        return None

    live_reference_candle = current_forming_candle if isinstance(current_forming_candle, dict) else latest_closed_candle
    live_current_price = None
    if isinstance(candidate, dict):
        live_current_price = resolve_current_market_price(
            candidate.get("latest_price"),
            live_reference_candle,
            prefer_candle=False,
            context=candidate,
        )
    if live_current_price in (None, 0, 0.0):
        live_current_price = _safe_positive_float((live_reference_candle or {}).get("c"))

    live_force_sell_reference_price, live_force_sell_reference_label, live_force_sell_reference_kind = get_live_force_sell_reference(state)
    live_pnl_pct_from_force_sell_reference = (
        pct_change(live_force_sell_reference_price, live_current_price)
        if live_force_sell_reference_price not in (None, 0, 0.0) and live_current_price not in (None, 0, 0.0)
        else None
    )

    if live_pnl_pct_from_force_sell_reference is None:
        return None

    force_sell_hold_ok = (
        live_force_sell_reference_kind == "rollover_body_top" or
        buy_min_hold_elapsed(state, scan_dt, minutes=FORCE_SELL_MIN_HOLD_MINUTES)
    )
    if not force_sell_hold_ok:
        return None

    if live_pnl_pct_from_force_sell_reference > FORCE_SELL_FROM_BUY_SIGNAL_PCT:
        return None

    sell_candle = build_live_price_sell_candle(
        live_reference_candle,
        scan_dt=scan_dt,
        live_price=live_current_price,
    )
    if not isinstance(sell_candle, dict):
        return None

    entry_price = _safe_positive_float(state.get("entry_price"))
    live_pnl_pct_from_entry = (
        pct_change(entry_price, live_current_price)
        if entry_price not in (None, 0, 0.0) and live_current_price not in (None, 0, 0.0)
        else None
    )

    sell_event = finalize_sell_transition(
        state,
        sell_candle,
        scan_dt,
        f"BUY-1M legacy force sell hit: current price reached {FORCE_SELL_FROM_BUY_SIGNAL_PCT:+.3f}% or lower from {live_force_sell_reference_label}",
        {
            "entry_pnl_pct": live_pnl_pct_from_entry,
            "force_sell_reference_pnl_pct": live_pnl_pct_from_force_sell_reference,
            "current_price": live_current_price,
            "buy_signal_price": entry_price,
            "force_sell_reference_price": live_force_sell_reference_price,
            "force_sell_reference_kind": live_force_sell_reference_kind,
            "live_force_sell": True,
            "buy_1m_legacy_force_sell": True,
        },
    )

    return {
        "event": sell_event,
        "pnl_pct": live_pnl_pct_from_force_sell_reference,
        "reference_label": live_force_sell_reference_label,
        "reference_price": live_force_sell_reference_price,
        "current_price": live_current_price,
    }



def mark_buy_style(state, buy_style):
    if not isinstance(state, dict):
        return
    normalized = normalize_buy_style(buy_style)
    state["buy_style"] = normalized
    state["buy_from_pending_buy"] = normalized == "pumping"



def is_strategy_version_current(state):
    if not isinstance(state, dict):
        return False
    try:
        version = int(state.get("strategy_logic_version", 0) or 0)
    except Exception:
        version = 0
    return version == STRATEGY_LOGIC_VERSION


