def clear_active_buy_open_green_reversal_state(state):
    if not isinstance(state, dict):
        return
    ensure_active_buy_state_defaults(state)
    state["active_buy_open_green_candle_ts"] = None
    state["active_buy_open_green_pending_drop_ts"] = None


def reset_active_buy_anchor_to_real_buy_price(state, real_buy_price, scan_dt=None):
    """Reset all active-BUY PnL/streak anchors to the actual real BUY fill price."""
    if not isinstance(state, dict):
        return False

    price = _safe_positive_float(real_buy_price)
    if price is None:
        return False

    scan_ts = ts_to_int(scan_dt.timestamp() if isinstance(scan_dt, datetime) else scan_dt)
    if scan_ts is None:
        scan_ts = ts_to_int(state.get("buy_event_ts") or state.get("buy_ts") or state.get("active_buy_entry_ts"))

    ensure_active_buy_state_defaults(state)
    state["entry_price"] = price
    state["active_buy_entry_price"] = price
    if scan_ts is not None:
        state["active_buy_entry_ts"] = scan_ts
        state["active_buy_anchor_reset_ts"] = scan_ts
    state["active_buy_force_sell_reference_price"] = price

    # A real BUY starts a fresh active-BUY PnL lifecycle. Never carry over
    # pumpbox/sandbox/pending calculations, streaks, pullback memory, or
    # open-green reversal state into the newly bought position.
    state["active_buy_green_count"] = 0
    state["active_buy_max_green_count"] = 0
    state["active_buy_max_green_price"] = None
    state["active_buy_max_green_scan_ts"] = None
    state["active_buy_max_green_source"] = None
    state["active_buy_last_green_price"] = None
    state["active_buy_red_sent"] = False
    reset_active_buy_peak_pnl_tracking(state)
    state["recovered_buy_delivery_entry_ts"] = None
    state["recovered_buy_delivery_scan_ts"] = None
    state["recovered_buy_delivery_reason"] = None
    clear_fib_sell_zone_elapsed_tracking(state, reason="fresh active BUY")
    reset_active_buy_profit_pullback_tracking(state)
    reset_active_buy_elapsed_drawdown_tracking(state)
    reset_global_active_buy_peak_drawdown_tracking(state)
    reset_active_buy_min_progress_tracking(state)
    reset_active_buy_pine_df0_tracking(state)
    reset_active_buy_pma_gf_plus_tracking(state)
    state["active_buy_pine_df0_buy_ts"] = scan_ts
    clear_active_buy_open_green_reversal_state(state)

    state["active_buy_anchor_reset_to_real_buy_price"] = True
    state["active_buy_anchor_reset_price"] = price
    return True


