    result["pma_gf_plus_force_buy_reason"] = pma_gf_plus_force_buy_status_debug.get("reason")
    result["pma_gf_plus_force_buy_elapsed_seconds"] = pma_gf_plus_force_buy_status_debug.get("elapsed_seconds")
    result["pma_gf_plus_force_buy_offset"] = pma_gf_plus_force_buy_status_debug.get("offset")
    result["pma_gf_plus_force_buy_trigger"] = pma_gf_plus_force_buy_status_debug.get("trigger")
    result["pma_gf_plus_force_buy_setup_source"] = pma_gf_plus_force_buy_status_debug.get("setup_source")
    result["pma_gf_plus_force_buy_setup_reason"] = pma_gf_plus_force_buy_status_debug.get("setup_reason")
    result["pma_gf_plus_force_buy_gf_plus_since_ts"] = pma_gf_plus_force_buy_status_debug.get("gf_plus_since_ts")
    result["pma_gf_plus_force_buy_entry_pma_flat_neutral"] = pma_gf_plus_force_buy_status_debug.get("entry_pma_flat_neutral")
    result["pma_gf_plus_force_buy_entry_pma_flat_neutral_reason"] = pma_gf_plus_force_buy_status_debug.get("entry_pma_flat_neutral_reason")
