    result["pma_gf_plus_force_buy_latest_closed_flat_candle_gate_reason"] = pma_gf_plus_force_buy_status_debug.get("latest_closed_flat_candle_gate_reason")
    result["pma_gf_plus_force_buy_latest_closed_candle_body_pct"] = pma_gf_plus_force_buy_status_debug.get("latest_closed_candle_body_pct")
