def pma_gf_plus_scan_debug_fields_from_strategy_result(strategy_result):
    """Expose computed PMA/GF+ force-buy diagnostics on final scan rows.

    analyze_candidate builds a compact final result dict at the end.  The
    force-buy status is computed earlier inside strategy_result; without copying
    these keys, BUY_1M_PMA_GF_* log lines show '-' even when the strategy note
    already contains the exact blocker.
    """
    if not isinstance(strategy_result, dict):
        return {}
    prefixes = (
        "pma_gf_plus_force_buy_",
        "pma_gf_plus_breakout_force_buy_",
    )
    exact_keys = {
        "pma_gf_plus_breakout_force_buy_enabled",
        "pma_gf_plus_breakout_force_buy_passed",
        "pma_gf_plus_breakout_force_buy_triggered",
        "pma_gf_plus_breakout_force_buy_reason",
        "pma_gf_plus_breakout_force_buy_volume_velocity",
        "pma_gf_plus_breakout_force_buy_body_above_breakout_pct",
        "pma_gf_plus_breakout_force_buy_requires_price_quality",
    }
    copied = {}
    for key, value in strategy_result.items():
        key_text = str(key)
        if key_text.startswith(prefixes) or key_text in exact_keys:
            copied[key_text] = value
    # Preserve flat-neutral PMA metadata for the Pine debug line too.
    for key in (
        "pine_30m_pma_flat_neutral",
        "pine_30m_pma_flat_neutral_reason",
        "pine_30m_pma_flat_neutral_status",
        "pine_30m_prev_pma_flat_neutral",
        "pine_30m_prev_pma_flat_neutral_reason",
    ):
        if key in strategy_result:
            copied[key] = strategy_result.get(key)
    return copied

def fmt_num(value, decimals=4):
    try:
        return f"{float(value):.{decimals}f}"
    except Exception:
        return "-"


def _format_number_keep_nonzero_decimals(value, max_decimals=12):
    try:
        numeric_value = float(value)
    except Exception:
        return "-"

    if not math.isfinite(numeric_value):
        return "-"

    # Strip decimals only when the fractional part is effectively .000000...
    # Otherwise preserve the meaningful decimal part and only trim trailing zeros.
    rounded_integer = round(numeric_value)
    zero_fraction_tolerance = 1e-12 * max(1.0, abs(numeric_value))
    if abs(numeric_value - rounded_integer) <= zero_fraction_tolerance:
        return f"{int(rounded_integer):,d}"

    max_decimals = max(0, int(max_decimals))
    text = f"{numeric_value:,.{max_decimals}f}".rstrip("0").rstrip(".")
    if text == "-0":
        return "0"
    return text


def fmt_price_auto(value, context=None, quote_currency=None, market_type=None, symbol=None):
    display_quote_currency = resolve_display_quote_currency(
        context=context,
        quote_currency=quote_currency,
        market_type=market_type,
        symbol=symbol,
    )

    display_value = price_value_for_display(
        value,
        context=context,
        quote_currency=quote_currency,
        market_type=market_type,
        symbol=symbol,
    )
    if display_value is None:
        return "-"

    if display_quote_currency == "IRT":
        return _format_number_keep_nonzero_decimals(display_value, max_decimals=12)

    value = float(display_value)
    if value >= 1000:
        return f"{value:,.2f}"
    if value >= 1:
        return f"{value:,.4f}"
    if value >= 0.01:
        return f"{value:,.6f}"
    return f"{value:,.8f}"



def normalize_live_market_price_value(latest_price=None, candle=None, context=None, quote_currency=None, market_type=None, symbol=None):
    latest_numeric = _safe_positive_float(latest_price)
    if latest_numeric is None:
        return None

    # LBank ticker, kline, and strategy prices are all USDT-denominated.
    return latest_numeric



def resolve_current_market_price(latest_price=None, candle=None, prefer_candle=True, context=None, quote_currency=None, market_type=None, symbol=None):
    candle_price = None
    if isinstance(candle, dict):
        candle_price = candle.get("c")

    normalized_latest_price = normalize_live_market_price_value(
        latest_price,
        candle=candle,
        context=context,
        quote_currency=quote_currency,
        market_type=market_type,
        symbol=symbol,
    )

    candidates = (candle_price, normalized_latest_price) if prefer_candle else (normalized_latest_price, candle_price)
    for value in candidates:
        numeric_value = _safe_positive_float(value)
        if numeric_value is not None:
            return numeric_value

    return None


def candle_time_str(ts):
    try:
        return datetime.fromtimestamp(int(ts)).strftime("%Y-%m-%d %H:%M")
    except Exception:
        return "-"


