def _payload_buy_style(payload):
    if not isinstance(payload, dict):
        return None
    text = str(payload.get("buy_style") or "").strip().lower()
    if text in {"legacy", "pumping"}:
        return text
    if bool(payload.get("buy_from_pending_buy")):
        return "pumping"
    if payload.get("pending_buy_price") not in (None, 0, 0.0) or payload.get("pending_buy_ts"):
        return "pumping"
    return None


def signal_emoji_for_display(stage, payload=None):
    if is_pumping_mark_event(payload):
        return pumping_mark_emoji()
    normalized_stage = display_stage_for_payload(stage, payload)
    if normalized_stage == "buy":
        buy_style = _payload_buy_style(payload)
        if buy_style == "legacy":
            return "🟢"
        if buy_style == "pumping":
            if not bool(ENABLE_LEGACY_BUY_FLOW):
                return "🟢"
            return "✴️"
    return signal_emoji(normalized_stage)


