                        f"rejection_wick={plain_pct(pending_debug.get('rejection_wick_pct'))} "
                        f"max_rejection={plain_pct(pending_debug.get('max_rejection_wick_pct'))} | "
                        f"breakout_ok={pending_debug.get('live_green_breakout_ok')} | "
                        f"body_threshold_ok={pending_debug.get('live_body_above_threshold')} | "
                        f"body_acceptance_ok={pending_debug.get('body_acceptance_ok')} | "
                        f"rejection_ok={pending_debug.get('breakout_rejection_ok')} | "
                        f"volume_ok={pending_debug.get('volume_ok')} | "
